#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1500

typedef struct NetworkPacket {
    uint16_t header;
    uint16_t payload_length;
    char *payload;
    uint16_t checksum;
    struct NetworkPacket *next;
} NetworkPacket;

uint16_t calculate_checksum(NetworkPacket *packet) {
    // Implement a simple checksum calculation
    return packet->header + packet->payload_length + packet->checksum;
}

NetworkPacket* process_packet_stream(const char *data, size_t length) {
    NetworkPacket dummy_head = {0};
    NetworkPacket *tail = &dummy_head;

    for (size_t i = 0; i < length;) {
        NetworkPacket *new_packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
        if (!new_packet) {
            fprintf(stderr, "Memory allocation failed\n");
            // Handle memory allocation failure
            return dummy_head.next;
        }

        new_packet->header = ntohs(*(uint16_t *)(data + i));
        new_packet->payload_length = ntohs(*(uint16_t *)(data + i + 2));

        if (new_packet->payload_length > MAX_PACKET_SIZE) {
            fprintf(stderr, "Invalid payload size\n");
            free(new_packet);
            continue;
        }

        new_packet->payload = (char *)malloc(new_packet->payload_length * sizeof(char));
        if (!new_packet->payload) {
            fprintf(stderr, "Memory allocation failed for payload\n");
            free(new_packet);
            continue;
        }

        memcpy(new_packet->payload, data + i + 4, new_packet->payload_length);

        new_packet->checksum = ntohs(*(uint16_t *)(data + i + 4 + new_packet->payload_length));
        uint16_t calculated_checksum = calculate_checksum(new_packet);

        if (new_packet->checksum != calculated_checksum) {
            fprintf(stderr, "Checksum mismatch\n");
            free(new_packet->payload);
            free(new_packet);
            continue;
        }

        new_packet->next = NULL;
        tail->next = new_packet;
        tail = new_packet;

        i += 4 + new_packet->payload_length + 2; // Move past header, payload, and checksum
    }

    return dummy_head.next;
}

// Example usage:
int main() {
    const char *data = "..."; // Assume this is your network packet stream
    size_t length = strlen(data);

    NetworkPacket *packet_list = process_packet_stream(data, length);
    // Process the packet list...

    return 0;
}
