#define BUFFER_SIZE 4096

void print_usage() {
    printf("Usage: program_name [-cs] -o output_file input_file\n");
    printf("Options:\n");
    printf("  --help      Display detailed usage information.\n");
    printf("  -cs         Enable case-sensitive mode (default is case-insensitive).\n");
    printf("  -o file     Write results to a specified file.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    char *input_file = NULL;
    char *output_file = NULL;
    int case_sensitive = 0;
    int log_errors = 1;

    while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
        switch (opt) {
            case 'c':
                if (!strcmp(optarg, "s"))
                    case_sensitive = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            case '?':
                if (optopt == 'o')
                    fprintf(stderr, "Option -%c requires an argument.\n", optopt);
                else
                    fprintf(stderr, "Unknown option: %s\n", argv[optind]);
                print_usage();
                return 1;
            default:
                abort();
        }
    }

    if (argc != optind + 1) {
        print_usage();
        return 1;
    }

    input_file = argv[optind];

    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    ssize_t bytes_read;
    char buffer[BUFFER_SIZE];
    size_t line_count = 0;
    size_t total_chars = 0;

    while ((bytes_read = read(fd, buffer, BUFFER_SIZE)) > 0) {
        for (ssize_t i = 0; i < bytes_read; i++) {
            if (buffer[i] == '\n') {
                line_count++;
                total_chars += i + 1;
            }
        }
    }

    close(fd);

    printf("Lines: %zu\n", line_count);
    printf("Total Characters: %zu\n", total_chars);

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (out) {
            fprintf(out, "Lines: %zu\n", line_count);
            fprintf(out, "Total Characters: %zu\n", total_chars);
            fclose(out);
        } else {
            perror("Error opening output file");
        }
    }

    return 0;
}
