void* process_file(void *arg) {
    Config config;
    parse_config(argc, argv, &config);

    FILE *input = fopen(config.input_file, "rb");
    if (!input) {
        perror("Failed to open input file");
        return NULL;
    }

    fseek(input, 0, SEEK_END);
    size_t file_size = ftell(input);
    fseek(input, 0, SEEK_SET);

    unsigned char *buffer = malloc(file_size);
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        fclose(input);
        return NULL;
    }

    fread(buffer, 1, file_size, input);
    fclose(input);

    TransformationRule rules[MAX_RULES];
    int rule_count = parse_rules(config.rules, rules);

    unsigned char *output_buffer = malloc(file_size);
    if (!output_buffer) {
        perror("Failed to allocate memory for output buffer");
        free(buffer);
        return NULL;
    }

    memcpy(output_buffer, buffer, file_size);

    apply_transformation(output_buffer, file_size, rules, rule_count);

    FILE *output = fopen(config.output_file, "wb");
    if (!output) {
        perror("Failed to open output file");
        free(buffer);
        free(output_buffer);
        return NULL;
    }

    fwrite(output_buffer, 1, file_size, output);
    fclose(output);

    free(buffer);
    free(output_buffer);

    return NULL;
}

int main(int argc, char **argv) {
    pthread_t thread;
    pthread_create(&thread, NULL, process_file, (void *)argv);

    // Wait for thread completion
    pthread_join(thread, NULL);

    return 0;
}
