#define MAX_LINE_LENGTH 256

// Function to perform DNS resolution
int resolve_dns(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return status;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // Get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // Convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s\n", ipstr);
    }

    freeaddrinfo(res); // Free the linked list
    return 0;
}

// Function to read CSV file and calculate average of specific fields
double calculate_average(const char *filename, int field_index) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    double sum = 0.0;
    int count = 0;
    char *line = NULL;
    size_t len = 0;

    while ((len = getline(&line, &len, file)) != -1) {
        // Skip empty lines or comments
        if (line[0] == '\0' || line[0] == '#') continue;

        char *token = strtok(line, ",");
        int current_field = 0;

        while (token != NULL) {
            if (current_field == field_index) {
                sum += atof(token);
                count++;
            }
            token = strtok(NULL, ",");
            current_field++;
        }
    }

    free(line);
    fclose(file);

    if (count == 0) {
        fprintf(stderr, "No data in the specified column\n");
        return -1;
    }

    return sum / count;
}

int main() {
    // Example usage of DNS resolution
    resolve_dns("example.com");

    // Example usage of CSV processing
    double average = calculate_average("data.csv", 2); // Assuming we want to calculate the average of the third field
    if (average != -1) {
        printf("Average: %f\n", average);
    }

    return 0;
}
