#include <stdio.h>
#include <stdlib.h>

#define MAX_CAPACITY 10000

int* readIntegersFromFile(const char* filePath, int* count) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", filePath);
        exit(EXIT_FAILURE);
    }

    int* integers = (int*)malloc(MAX_CAPACITY * sizeof(int));
    if (integers == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    *count = 0;
    int num;
    while (*count < MAX_CAPACITY && fscanf(file, "%d", &num) == 1) {
        integers[*count] = num;
        if (num < -2147483648 || num > 2147483647) {
            fprintf(stderr, "Integer out of range: %d\n", num);
            free(integers);
            fclose(file);
            exit(EXIT_FAILURE);
        }
        (*count)++;
    }

    if (ferror(file)) {
        fprintf(stderr, "Error reading from file.\n");
        free(integers);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
    return integers;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int count;
    int* integers = readIntegersFromFile(argv[1], &count);

    // Process the integers as needed
    for (int i = 0; i < count; i++) {
        printf("%d\n", integers[i]);
    }

    free(integers);
    return EXIT_SUCCESS;
}
