#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

#define INITIAL_CAPACITY 10
#define MAX_STRINGS 1000

typedef struct {
    char **strings;
    size_t count;
    size_t capacity;
} StringList;

StringList *create_string_list() {
    StringList *list = (StringList *)malloc(sizeof(StringList));
    if (!list) {
        perror("Failed to allocate memory for StringList");
        return NULL;
    }
    list->strings = (char **)calloc(INITIAL_CAPACITY, sizeof(char *));
    if (!list->strings) {
        free(list);
        perror("Failed to allocate memory for strings array");
        return NULL;
    }
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    return list;
}

void destroy_string_list(StringList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->strings[i]);
    }
    free(list->strings);
    free(list);
}

int insert_string(StringList *list, const char *source, va_list args) {
    if (list->count >= MAX_STRINGS) {
        fprintf(stderr, "StringList reached maximum capacity\n");
        return -1;
    }

    size_t len = vsnprintf(NULL, 0, source, args);
    char *new_str = (char *)malloc(len + 1);
    if (!new_str) {
        perror("Failed to allocate memory for new string");
        return -1;
    }
    vsnprintf(new_str, len + 1, source, args);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        char **new_strings = (char **)realloc(list->strings, new_capacity * sizeof(char *));
        if (!new_strings) {
            perror("Failed to reallocate memory for strings array");
            free(new_str);
            return -1;
        }
        list->strings = new_strings;
        list->capacity = new_capacity;
    }

    list->strings[list->count++] = new_str;

    printf("String inserted successfully\n");
    return 0;
}

int main() {
    StringList *list = create_string_list();
    if (!list) {
        return EXIT_FAILURE;
    }

    va_list args1, args2;
    va_start(args1, "%s %d", "Hello", 42);
    insert_string(list, "%s %d", args1);
    va_end(args1);

    va_start(args2, "%s %.2f", "World", 3.14);
    insert_string(list, "%s %.2f", args2);
    va_end(args2);

    destroy_string_list(list);
    return EXIT_SUCCESS;
}
