#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

typedef enum {
    AES_GCM,
    AES_CFB,
    NULL_DECRYPTION
} DecryptionMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} CryptoLibrary;

void init_crypto_library(CryptoLibrary *lib, const unsigned char *key) {
    memset(lib, 0, sizeof(*lib));
    memcpy(lib->key, key, sizeof(lib->key));
}

int encrypt_aes_gcm(const CryptoLibrary *lib, const unsigned char *plaintext, size_t plaintext_len,
                   unsigned char *ciphertext, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx = lib->ctx;
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, lib->key, lib->iv)) return -1;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) return -1;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len)) return -1;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) return -1;
    return 0;
}

int decrypt_aes_gcm(const CryptoLibrary *lib, const unsigned char *ciphertext, size_t ciphertext_len,
                   const unsigned char *tag, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = lib->ctx;
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, lib->key, lib->iv)) return -1;
    if (!EVP_DecryptUpdate(ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len)) return -1;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, (unsigned char *)tag)) return -1;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + ciphertext_len, &ciphertext_len)) {
        memset(plaintext, 0, ciphertext_len);
        return -1;
    }
    return 0;
}

int decrypt_aes_cfb(const CryptoLibrary *lib, const unsigned char *ciphertext, size_t ciphertext_len,
                   unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = lib->ctx;
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, lib->key, lib->iv)) return -1;
    if (!EVP_DecryptUpdate(ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len)) {
        memset(plaintext, 0, ciphertext_len);
        return -1;
    }
    if (!EVP_DecryptFinal_ex(ctx, plaintext + ciphertext_len, &ciphertext_len)) {
        memset(plaintext, 0, ciphertext_len);
        return -1;
    }
    return 0;
}

void *null_decryption(void *arg) {
    // Null decryption logic here
    return NULL;
}

int main() {
    CryptoLibrary lib;
    unsigned char key[32], iv[16];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128], tag[16];

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    lib.ctx = ctx;
    init_crypto_library(&lib, key);
    RAND_bytes(iv, sizeof(iv));

    // Encrypt with AES-GCM
    encrypt_aes_gcm(&lib, plaintext, strlen((char *)plaintext), ciphertext, tag);

    // Decrypt with AES-GCM
    unsigned char decrypted_text[128];
    decrypt_aes_gcm(&lib, ciphertext, strlen((char *)ciphertext), tag, decrypted_text);
    printf("Decrypted text: %s\n", decrypted_text);

    // Decrypt with AES-CFB
    decrypt_aes_cfb(&lib, ciphertext, strlen((char *)ciphertext), decrypted_text);
    printf("Decrypted text: %s\n", decrypted_text);

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
