    print(f"Applying new config: {new_config}")

def fetch_current_config():
    try:
        response = requests.get(API_URL, headers=AUTH_HEADERS)
        response.raise_for_status()
        return validate_config(response.json())
    except requests.exceptions.RequestException as e:
        print(f"Error fetching current config: {e}")
        return None

def update_config(new_config):
    original_path = '/path/to/original/script.txt'
    backup_path = backup_script(original_path, BACKUP_DIR)
    try:
        apply_config(new_config)
        print(f"Configuration updated successfully. Backup saved at {backup_path}")
