        return EVP_aes_128_cbc();
    else if (strcmp(name, "AES-256-CFB") == 0)
        return EVP_aes_256_cfb();
    // Add more mappings as needed
    return NULL;
}

static void* generate_unique_nonce(size_t size) {
    static unsigned char nonce[16];
    static size_t nonce_index = 0;

    if (RAND_bytes(nonce + nonce_index, size - nonce_index) != 1) {
        fprintf(stderr, "Error generating nonce\n");
        return NULL;
    }
    nonce_index += size;

    // Reset nonce index when it reaches the buffer size
    if (nonce_index >= sizeof(nonce)) {
        nonce_index = 0;
        memset(nonce, 0, sizeof(nonce));
    }

    return nonce + (nonce_index - size);
}

CryptoFunction* get_available_crypto_functions(size_t* count) {
    static CryptoFunction functions[] = {
        {"SHA-256", EVP_sha256},
        {"MD5", EVP_md5},
        {"AES-128-CBC", NULL},
        {"AES-256-CFB", NULL}
        // Add more functions as needed
    };

    *count = sizeof(functions) / sizeof(functions[0]);

    for (size_t i = 0; i < *count; i++) {
        if (functions[i].function == NULL) {
            functions[i].function = get_cipher_by_name(functions[i].name);
        }
    }

    return functions;
}
