['```cpp
#include <iostream>
#include <vector>
#include <list>

class DataManager {
public:
    struct Node {
        int value;
        Node* next;
        Node(int val) : value(val), next(nullptr) {}
    };

    DataManager() : arraySize(0) {}

    ~DataManager() {
        clearArray();
        clearList();
    }

    void insertToArray(int value) {
        array.push_back(value);
        arraySize++;
    }

    bool removeFromArray(int value) {
        auto it = std::find(array.begin(), array.end(), value);
        if (it != array.end()) {
            array.erase(it);
            arraySize--;
            return true;
        }
        return false;
    }

    void insertAfterFirstOccurrenceInList(int arrayValue, int newValue) {
        Node* newNode = new Node(newValue);
        bool inserted = false;

        for (Node* current = head; current != nullptr; current = current->next) {
            if (current->value == arrayValue) {
                newNode->next = current->next;
                current->next = newNode;
                inserted = true;
                break;
            }
        }

        if (!inserted && head != nullptr) {
            Node* temp = head;
            while (temp->next != nullptr) {
                temp = temp->next;
            }
            temp->next = newNode;
        } else if (!inserted) {
            head = newNode;
        }
    }

    void removeFromList(int value) {
        Node** current = &head;
        while (*current != nullptr) {
            if ((*current)->value == value) {
                Node* temp = *current;
                *current = (*current)->next;
                delete temp;
                break;
            } else {
                current = &(*current)->next;
            }
        }
    }

    void clearArray() {
        array.clear();
        arraySize = 0;
    }

    void clearList() {
        while (head != nullptr) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

private:
    std::vector<int> array;
    int arraySize;
    Node* head = nullptr;
};
```

This code block defines a `DataManager` class that manages a dynamically allocated array of integers and a linked list of integer nodes. It provides methods for inserting and removing elements from both data structures, ensuring efficient memory management and preventing use-after-free errors. The class also includes constructors and destructors to manage the lifecycle of the data structures.']

