public class UserQueryBuilder
{
    public string BuildUserQuery(string connectionString, List<string> usernames, List<string> emails, List<string> roles, int pageNumber, int pageSize)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();

            var queryParts = new List<string>
            {
                "SELECT * FROM Users"
            };

            if (usernames.Any())
            {
                queryParts.Add($"WHERE Username IN ({string.Join(", ", usernames.Select(username => $"'{username}'"))})");
            }

            if (emails.Any())
            {
                if (!queryParts.Contains("WHERE"))
                {
                    queryParts.Add("WHERE");
                }
                else
                {
                    queryParts.Add("AND");
                }
                queryParts.Add($"Email IN ({string.Join(", ", emails.Select(email => $"'{email}'"))})");
            }

            if (roles.Any())
            {
                if (!queryParts.Contains("WHERE"))
                {
                    queryParts.Add("WHERE");
                }
                else
                {
                    queryParts.Add("AND");
                }
                queryParts.Add($"Role IN ({string.Join(", ", roles.Select(role => $"'{role}'"))})");
            }

            var query = string.Join(" ", queryParts);

            if (pageNumber > 0 && pageSize > 0)
            {
                query += $" OFFSET {(pageNumber - 1) * pageSize} ROWS FETCH NEXT {pageSize} ROWS ONLY";
            }

            return query;
        }
    }
}
