using System;
using System.IO;
using System.Xml.XPath;

public class XmlDocumentProcessor
{
    private static string cachedDirectoryPath = null;

    public static string ProcessXmlDocument(string xmlDocument, string elementName, string baseDirectory)
    {
        if (!IsValidBaseDirectory(baseDirectory))
        {
            return string.Empty;
        }

        if (string.IsNullOrEmpty(cachedDirectoryPath) || cachedDirectoryPath != baseDirectory)
        {
            UpdateEnvironmentVariable(xmlDocument, elementName, baseDirectory);
            cachedDirectoryPath = baseDirectory;
        }

        XPathDocument doc = new XPathDocument(new StringReader(xmlDocument));
        XPathNavigator navigator = doc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select($"//{elementName}");

        if (nodes.Count == 0)
        {
            Console.WriteLine("Warning: No element found with the provided name.");
            return string.Empty;
        }
        else if (nodes.Count > 1)
        {
            Console.WriteLine("Info: Multiple elements found with the provided name. Only the first will be processed.");
        }

        navigator.MoveToFirst();
        XPathNodeIterator selectedNode = nodes.Current.SelectDescendants(XPathNodeType.Text, false);
        return selectedNode.Current.Value;
    }

    private static bool IsValidBaseDirectory(string baseDirectory)
    {
        if (string.IsNullOrEmpty(baseDirectory))
        {
            Console.WriteLine("Warning: Base directory is empty.");
            return false;
        }

        if (!Directory.Exists(baseDirectory))
        {
            Console.WriteLine("Error: Base directory does not exist.");
            return false;
        }

        if (!Directory.GetCurrentDirectory().Equals(baseDirectory))
        {
            Console.WriteLine("Error: Current working directory is different from the base directory.");
            return false;
        }

        return true;
    }

    private static void UpdateEnvironmentVariable(string xmlDocument, string elementName, string baseDirectory)
    {
        XPathDocument doc = new XPathDocument(new StringReader(xmlDocument));
        XPathNavigator navigator = doc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select($"//{elementName}");

        if (nodes.Count > 0)
        {
            Environment.SetEnvironmentVariable("XML_DIR", Path.GetFullPath(baseDirectory), EnvironmentVariableTarget.Process);
        }
    }
}
