using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json.Linq;
using FluentValidation;
using Polly;

[ApiController]
[Route("api/[controller]")]
public class HtmlUpdateController : ControllerBase
{
    private readonly IHtmlRenderingService _htmlRenderingService;
    private readonly ICachingService _cachingService;
    private readonly IValidator<UpdateRequest> _validator;
    private readonly AsyncPolicy _retryPolicy;

    public HtmlUpdateController(IHtmlRenderingService htmlRenderingService, 
                                ICachingService cachingService,
                                IValidator<UpdateRequest> validator)
    {
        _htmlRenderingService = htmlRenderingService;
        _cachingService = cachingService;
        _validator = validator;
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .Or<ServiceUnavailableException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    [HttpPost]
    public async Task<IActionResult> UpdateContent([FromBody] JObject request)
    {
        var updateRequest = request.ToObject<UpdateRequest>();

        var validationResult = await _validator.ValidateAsync(updateRequest);
        if (!validationResult.IsValid)
            return BadRequest(validationResult.Errors);

        try
        {
            var updatedHtml = await _retryPolicy.ExecuteAsync(async () =>
                await _htmlRenderingService.UpdateElementContent(updateRequest.SectionId, updateRequest.ElementId, updateRequest.NewContent));

            await _cachingService.CacheUpdatedContent(updatedHtml);

            var response = new UpdateResponse { RefreshPage = true, StatusMessage = "Content updated successfully." };
            return Ok(response);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating HTML content");
            return StatusCode(500, "Internal server error");
        }
    }

    public class UpdateRequest
    {
        public string SectionId { get; set; }
        public string ElementId { get; set; }
        public string NewContent { get; set; }
    }

    public class UpdateResponse
    {
        public bool RefreshPage { get; set; }
        public string StatusMessage { get; set; }
    }
}

public interface IHtmlRenderingService
{
    Task<string> UpdateElementContent(string sectionId, string elementId, string newContent);
}

public interface ICachingService
{
    Task CacheUpdatedContent(string updatedHtml);
}
