public class CustomUserManager : UserManager<ApplicationUser>
{
    private readonly IFailedLoginAttemptsLogger _failedLoginAttemptsLogger;
    private readonly IUserAlertService _userAlertService;

    public CustomUserManager(IUserStore<ApplicationUser> store, 
                              IOptions<IdentityOptions> optionsAccessor,
                              IPasswordHasher<ApplicationUser> passwordHasher,
                              IEnumerable<IUserValidator<ApplicationUser>> userValidators,
                              IEnumerable<IPasswordValidator<ApplicationUser>> passwordValidators,
                              ILogger<UserManager<ApplicationUser>> logger,
                              IFailedLoginAttemptsLogger failedLoginAttemptsLogger,
                              IUserAlertService userAlertService)
        : base(store, optionsAccessor, passwordHasher, userValidators, passwordValidators, logger)
    {
        _failedLoginAttemptsLogger = failedLoginAttemptsLogger;
        _userAlertService = userAlertService;
    }

    public async Task<IdentityResult> CreateUserAsync(ApplicationUser user, string password)
    {
        if (!IsValidPassword(password))
        {
            return IdentityResult.Failed(new IdentityError { Description = "Invalid password. Please ensure it meets the policy requirements." });
        }

        return await base.CreateUserAsync(user, password);
    }

    public async Task<SignInResult> PasswordSignInAsync(string userName, string password, bool isPersistent, bool lockoutOnFailure)
    {
        var result = await base.PasswordSignInAsync(userName, password, isPersistent, lockoutOnFailure);

        if (result.IsLockedOut)
        {
            _failedLoginAttemptsLogger.LogFailedAttempt(userName);
            await _userAlertService.SendAccountLockedAlert(userName);
        }

        return result;
    }

    private bool IsValidPassword(string password)
    {
        var regex = new Regex(@"^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{12,}$");
