import os

def read_config_file(directory_path, file_name):
    # Construct the full path to the file
    file_path = os.path.join(directory_path, file_name)

    # Check if the file exists in the specified directory
    if not os.path.exists(file_path) or not file_name.startswith('.'):
        raise FileNotFoundError(f"File '{file_name}' does not exist in directory '{directory_path}'.")

    # Ensure we do not allow directory traversal attacks
    if not file_path.startswith(directory_path):
        raise ValueError("Directory traversal attack detected.")

    try:
        with open(file_path, 'rb') as file:
            content = file.read()
            return content.decode('utf-8', errors='ignore')
    except IOError as e:
        raise IOError(f"Failed to read file '{file_name}': {e}")

# Example usage
directory_path = '/safe/directory'
file_name = 'config.txt'
try:
    config_content = read_config_file(directory_path, file_name)
    print(config_content)
except (FileNotFoundError, ValueError, IOError) as e:
    print(e)
