// Custom function to sanitize the module path
function sanitizeModulePath(modulePath) {
    return path.resolve(__dirname, '..', 'modules', modulePath);
}

// Function to execute tests for a given module
async function runTestsForModule(modulePath, testFunction) {
    try {
        // Sanitize and validate the module path
        const sanitizedPath = sanitizeModulePath(modulePath);

        // Check if the file exists to prevent unexpected behavior
        if (!fs.existsSync(sanitizedPath)) {
            console.error(`Module not found at ${sanitizedPath}`);
            return;
        }

        // Load the module dynamically
        const module = require(sanitizedPath);

        // Get all test functions from the module
        const tests = Object.keys(module).filter(key => typeof module[key] === 'function');

        // Log the module being tested
        console.log(`Testing module: ${modulePath}`);

        for (const testName of tests) {
            console.log(`Running test: ${testName}`);

            // Start performance logging
            const startTime = process.hrtime();

            try {
                // Execute each test function
                await testFunction(module[testName]);

                // Reset blueslip after each test
                blueslip.reset();
            } catch (error) {
                console.error(`Test failed for: ${testName}`);
                console.error(error);
            }

            // End performance logging and log execution time
            const endTime = process.hrtime(startTime);
            console.log(`${testName} took ${endTime[0]}s and ${endTime[1] / 1e6}ms`);
        }
    } catch (error) {
        console.error('Error in runTestsForModule:', error);
    }
}

// Example usage
