function refreshDialogFields(resourceId, url, fieldNames) {
    const MAX_RETRIES = 3;
    let forwardList = [];

    function fetchFieldData(fieldName) {
        return $http.get(`${url}/${fieldName}`, { params: { resourceId } })
            .then(response => response.data)
            .catch(() => null);
    }

    function updateDialogField(fieldName, data) {
        if (data && validateData(data)) {
            forwardList.push({ fieldName, data });
        } else {
            forwardList.push({ fieldName });
        }
    }

    function retryFetch(field, attempt = 0) {
        return fetchFieldData(field).then(data => {
            if (data || attempt >= MAX_RETRIES - 1) {
                updateDialogField(field, data);
            } else {
                setTimeout(() => retryFetch(field, attempt + 1), 500);
            }
        });
    }

    function batchUpdateFields(fields) {
        fields.forEach(field => retryFetch(field));
    }

    function validateData(data) {
        // Implement your validation logic here
        return true;
    }

    batchUpdateFields(fieldNames);

    return forwardList;
}
