class DataProcessor {
  constructor(dataSources, dbClient, messageBroker) {
    this.dataSources = dataSources;
    this.dbClient = dbClient;
    this.messageBroker = messageBroker;
    this.isProcessing = false;
    this.bufferedWrites = [];
    this.writeThrottle = null;
    this.reconnectInterval = 5000; // milliseconds
  }

  async start() {
    this.isProcessing = true;
    while (this.isProcessing) {
      try {
        await this.collectAndProcessData();
        if (this.bufferedWrites.length > 0) {
          await this.flushBufferedWrites();
        }
      } catch (error) {
        console.error('Error processing data:', error);
        await this.handleReconnection();
      }
    }
  }

  async collectAndProcessData() {
    const promises = this.dataSources.map(async source => {
      try {
        return await source.fetchData();
      } catch (error) {
        console.error(`Failed to fetch data from ${source.id}:`, error);
        return null;
      }
    });

    const dataChunks = await Promise.all(promises);
    dataChunks.forEach(chunk => {
      if (chunk) {
        this.processChunk(chunk);
      }
    });
  }

  processChunk(chunk) {
    // Process the chunk of data
    console.log('Processing chunk:', chunk);

    // Buffer writes to the database
    this.bufferedWrites.push(chunk);
    this.scheduleWriteThrottle();
  }

  async flushBufferedWrites() {
    while (this.bufferedWrites.length > 0) {
      try {
        const chunk = this.bufferedWrites.shift();
        await this.dbClient.write(chunk);
        console.log('Wrote chunk to database:', chunk);
      } catch (error) {
        console.error('Failed to write chunk to database:', error);
        // Requeue the failed chunk
        this.bufferedWrites.unshift(chunk);
        break;
      }
    }
  }

  scheduleWriteThrottle() {
    if (!this.writeThrottle) {
      this.writeThrottle = setTimeout(() => {
        this.flushBufferedWrites();
        this.writeThrottle = null;
      }, 100); // Throttle writes to once every 100ms
    }
  }

  async handleReconnection() {
    console.log('Attempting reconnection...');
    await new Promise(resolve => setTimeout(resolve, this.reconnectInterval));
    try {
      await this.dbClient.connect();
      await this.messageBroker.connect();
      console.log('Reconnected successfully.');
    } catch (error) {
      console.error('Failed to reconnect:', error);
      // Retry reconnection
      this.handleReconnection();
    }
  }

  pause() {
    this.isProcessing = false;
  }

  resume() {
    if (!this.isProcessing) {
      this.isProcessing = true;
      this.start();
    }
  }
}
