function traverseDOM(ancestorNode, selector, callback) {
  const filter = (node) => node.matches(selector);

  function traverse(node) {
    if (!node || !node.isConnected) return;

    if (filter(node)) {
      callback(node);
    }

    for (let child of node.childNodes) {
      traverse(child);
    }
  }

  traverse(ancestorNode);
}

// Example usage:
document.addEventListener('DOMContentLoaded', () => {
  const ancestor = document.getElementById('root');
  traverseDOM(ancestor, '.example-class', (node) => {
    console.log(node);
  });
});
```

This code snippet defines a `traverseDOM` function that takes three parameters: an ancestor node, a selector string, and a callback function. It uses the `matches` method to filter nodes based on the provided selector and recursively traverses through child nodes while skipping descendants of the ancestor node. The traversal is designed to be efficient and non-blocking, suitable for high-load conditions."]

