public final class SessionIdGenerator {
    private static final Logger LOGGER = LoggerFactory.getLogger(SessionIdGenerator.class);
    private static final SecureRandom RANDOM = getSecureRandomInstance();
    private static final long ENTROPY_CHECK_INTERVAL = 60 * 1000; // 1 minute
    private static long lastEntropyCheckTime = System.currentTimeMillis();

    private SessionIdGenerator() {}

    public static String generateSessionId() {
        return UUID.randomUUID().toString(); // Using UUID for simplicity and uniqueness
    }

    private static SecureRandom getSecureRandomInstance() {
        try {
            return SecureRandom.getInstance("SHA1PRNG");
        } catch (NoSuchAlgorithmException e) {
            LOGGER.error("Failed to initialize secure random instance", e);
            throw new RuntimeException(e);
        }
    }

    public static void checkEntropySource() {
        if (System.currentTimeMillis() - lastEntropyCheckTime >= ENTROPY_CHECK_INTERVAL) {
            try {
                RANDOM.nextBytes(new byte[1024]);
                lastEntropyCheckTime = System.currentTimeMillis();
                LOGGER.info("Entropy source verified successfully.");
            } catch (Exception e) {
                LOGGER.error("Failed to verify entropy source", e);
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        String sessionId = generateSessionId();
        LOGGER.info("Generated session ID: {}", sessionId);

        // Periodically check the entropy source
        while (true) {
            checkEntropySource();
            try {
                Thread.sleep(10 * 1000); // Check every 10 seconds
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}
