import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class URLFetcher {

    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final List<String> ALLOWED_DOMAINS = List.of("example.com", "test.com");

    public CompletableFuture<String> fetchURL(String url) {
        try {
            URI uri = new URI(url);
            String domain = uri.getHost();

            if (!ALLOWED_DOMAINS.contains(domain)) {
                throw new SecurityException("Domain not allowed: " + domain);
            }

            HttpRequest request = HttpRequest.newBuilder()
                    .uri(uri)
                    .GET()
                    .build();

            return httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                             .thenApply(HttpResponse::body)
                             .exceptionally(ex -> {
                                 System.err.println("Failed to fetch URL: " + ex.getMessage());
                                 return null;
                             });
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid URL format: " + url, e);
        }
    }

    public static void main(String[] args) {
        URLFetcher fetcher = new URLFetcher();
        CompletableFuture<String> result = fetcher.fetchURL("http://example.com");

        result.thenAccept(System.out::println)
              .join();
    }
}
```

This code snippet provides a basic implementation of the `fetchURL` method, which takes a URL as input and fetches its content using Java's `HttpClient`. It includes domain validation against an allowed list and logs any exceptions that occur during the request. The use of `CompletableFuture` allows for asynchronous execution and non-blocking handling of HTTP requests.

Please note that this code is a starting point and may need to be adapted to fit your specific requirements. Additionally, you should consider implementing more advanced logging and monitoring mechanisms as well as optimizing resource usage and concurrency as needed.']

