        if (!themeDir.exists()) {
            themeDir.mkdirs();
            themeDir.setReadable(true);
            themeDir.setWritable(true);
        }
    }

    public void recycleBitmap(Bitmap bitmap) {
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    public Bitmap getTheme(String themeName) {
        if (themeCache.containsKey(themeName)) {
            return themeCache.get(themeName);
        } else {
            try {
                Bitmap newBitmap = BitmapFactory.decodeFile(new File(themeDir, themeName).getAbsolutePath());
                if (newBitmap != null && calculateCacheSize() + newBitmap.getByteCount() <= MAX_CACHE_SIZE) {
                    themeCache.put(themeName, newBitmap);
                    return newBitmap;
                } else {
                    throw new IOException("Theme exceeds cache size limit");
                }
            } catch (IOException e) {
                Log.e("ThemeCacheManager", "Error loading theme: " + e.getMessage());
                return null;
            }
        }
    }

    private int calculateCacheSize() {
        int totalSize = 0;
        for (Bitmap bitmap : themeCache.values()) {
            totalSize += bitmap.getByteCount();
        }
        return totalSize;
    }

    public void downloadThemeFromService(String themeName) {
        try {
            // Simulate network request
            Thread.sleep(1000);
            Bitmap newBitmap = BitmapFactory.decodeStream(new URL("http://example.com/themes/" + themeName).openStream());
            if (newBitmap != null && calculateCacheSize() + newBitmap.getByteCount() <= MAX_CACHE_SIZE) {
                themeCache.put(themeName, newBitmap);
            } else {
                throw new IOException("Theme exceeds cache size limit");
            }
        } catch (IOException | InterruptedException e) {
            Log.e("ThemeCacheManager", "Error downloading theme: " + e.getMessage());
        }
    }

    public void updateTheme(String oldThemeName, String newThemeName) {
        Bitmap oldBitmap = getTheme(oldThemeName);
        if (oldBitmap != null) {
            recycleBitmap(oldBitmap);
            themeCache.remove(oldThemeName);
        }
        Bitmap newBitmap = getTheme(newThemeName);
        if (newBitmap == null) {
            downloadThemeFromService(newThemeName);
        }
    }

    public List<String> listCachedThemes() {
        List<String> themes = new ArrayList<>();
        for (String theme : themeCache.keySet()) {
            themes.add(theme);
        }
        return themes;
    }
}
