const fetch = require('node-fetch');
const fs = require('fs');

async function generatePemFile(oauthRequest) {
  const { privateKeyUrl, certificateUrl } = oauthRequest;
  let privateKey, certificate;

  try {
    // Fetch private key and certificate securely
    privateKey = await fetch(privateKeyUrl, { method: 'GET', headers: { Authorization: `Bearer ${oauthRequest.accessToken}` } }).then(res => res.text());
    certificate = await fetch(certificateUrl, { method: 'GET', headers: { Authorization: `Bearer ${oauthRequest.accessToken}` } }).then(res => res.text());
  } catch (error) {
    console.error('Failed to fetch private key or certificate:', error);
    throw error;
  }

  // Combine into a single PEM file
  const pemFile = `-----BEGIN PRIVATE KEY-----
${privateKey}
-----END PRIVATE KEY-----
-----BEGIN CERTIFICATE-----
${certificate}
-----END CERTIFICATE-----`;

  return pemFile;
}

// Example usage:
const oauthRequest = {
  privateKeyUrl: 'https://api.example.com/private-key',
  certificateUrl: 'https://api.example.com/certificate',
  accessToken: 'your-access-token'
};

generatePemFile(oauthRequest).then(pemFile => {
  fs.writeFileSync('combined.pem', pemFile);
  console.log('PEM file generated successfully');
}).catch(error => {
  console.error('Error generating PEM file:', error);
});
```

This code snippet defines an asynchronous function `generatePemFile` that takes an OAuth request object as input and generates a combined PEM certificate file. It uses the `fetch` library to securely retrieve the private key and certificate from external API endpoints using bearer tokens. The function then combines these into a single PEM file and returns it. Error handling is implemented for fetching operations, and the resulting PEM file is saved to disk."]

['### C Function: Resolve Hostname to IP Address

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_IP_LENGTH 16

int resolveHostname(const char *hostname, char *ipAddress) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(ipAddress, ipstr);
        freeaddrinfo(res); // free the linked list
        return 0;
    }
    freeaddrinfo(res); // free the linked list if we didn't find an address
    fprintf(stderr, "No addresses found\n");
    return -1;
}
```

