    int featureSize, numLeafNodes, maxDepth;
    OctreeNode* root;

    OctreeNode* allocateNode(int depth) {
        if (depth == maxDepth || numLeafNodes <= 0) {
            return nullptr; // Reached maximum depth or no more leaf nodes
        }
        OctTreeNode* node = new (std::align_val_t(64)) OctreeNode;
        if (!node) {
            return nullptr; // Memory allocation failed
        }
        node->children.resize(8, nullptr);
        node->data = allocateData(featureSize); // Allocate data for this node
        if (!node->data) {
            delete node;
            return nullptr;
        }
        numLeafNodes--;
        return node;
    }

    void* allocateData(int size) {
        // Implement memory allocation with cache line alignment and checks for integer overflows
        // Return a pointer to the allocated data or nullptr if allocation fails
        return new (std::align_val_t(64)) char[size];
    }

    void deallocateTree(OctreeNode* node) {
        if (!node) {
            return;
        }
        for (auto& child : node->children) {
            deallocateTree(child);
        }
        delete[] static_cast<char*>(node->data); // Deallocate data
        node->data = nullptr;
        node->~OctreeNode(); // Explicitly call destructor
        free(node); // Free memory, assuming custom alignment is handled correctly
    }

    // Additional methods for inserting data and resizing the octree can be added here
};
