// Pseudo-random number generator (PRNG) implementation using the Mersenne Twister algorithm
unsigned int mt[624]; // state vector
int index = 624;      // current index in state vector

void init_prng() {
    srand(PRNG_SEED);
    for(int i = 0; i < 624; ++i) {
        mt[i] = rand();
    }
}

unsigned int prng() {
    if(index == 624) {
        index = 0;
        // Twister algorithm to generate new numbers
        unsigned int x, y;
        for(int i = 0; i < 624; ++i) {
            x = (mt[i] & 0x80000000) + (mt[(i+1)%624] & 0x7FFFFFFF);
            y = mt[(i+397)%624];
            mt[i] = y ^ (x >> 1) ^ ((x & 1) ? 0x9908B0DF : 0x0);
        }
    }
    unsigned int r = mt[index++];
    // Tempering step
    r ^= r >> 11;
    r ^= (r << 7) & 0x9D2C5680;
    r ^= (r << 15) & 0xEFC60000;
    r ^= r >> 18;
    return r;
}

