class CombatAbilityManager {
public:
    CombatAbilityManager() : lastAttackTime(std::chrono::high_resolution_clock::now()) {}

    void selectRandomAttack() {
        if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - lastAttackTime) < cooldown) {
            return;
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);

        int attack = dis(gen);
        if (attack == 0) {
            performAttack("Fireball");
        } else {
            performAttack("Ice Lance");
        }

        lastAttackTime = std::chrono::high_resolution_clock::now();
    }

    void resetAttackStats() {
        attackStats.clear();
    }

private:
    void performAttack(const std::string& attackType) {
        if (attackStats.find(attackType) == attackStats.end()) {
            attackStats[attackType] = 0;
        }
        attackStats[attackType]++;
        std::cout << "Selected " << attackType << std::endl;
    }

    std::chrono::milliseconds cooldown = std::chrono::milliseconds(1000);
    std::atomic<std::chrono::time_point<std::chrono::high_resolution_clock>> lastAttackTime;
    std::unordered_map<std::string, int> attackStats;
};

int main() {
    CombatAbilityManager manager;

    // Simulate concurrent attacks
    std::thread t1([&manager]() { for (int i = 0; i < 10; ++i) manager.selectRandomAttack(); });
    std::thread t2([&manager]() { for (int i = 0; i < 10; ++i) manager.selectRandomAttack(); });

    t1.join();
    t2.join();

    // Reset attack stats and simulate further actions
    manager.resetAttackStats();
    manager.selectRandomAttack();

    return 0;
}
