public class RandomNumberGenerator
{
    private int _intMin;
    private int _intMax;
    private float _floatMin;
    private float _floatMax;
    private RNGCryptoServiceProvider _rng;

    public RandomNumberGenerator(int intMin, int intMax, float floatMin, float floatMax)
    {
        if (intMin > intMax || floatMin > floatMax)
            throw new ArgumentException("Invalid range values.");

        _intMin = intMin;
        _intMax = intMax;
        _floatMin = floatMin;
        _floatMax = floatMax;
        _rng = new RNGCryptoServiceProvider();
    }

    public void Seed(int seedValue)
    {
        if (seedValue < 0)
            throw new ArgumentException("Seed value must be non-negative.");

        byte[] seedBytes = BitConverter.GetBytes(seedValue);
        _rng = new RNGCryptoServiceProvider();
        _rng.SeedData(seedBytes);
    }

    public int GetRandomInt()
    {
        byte[] bytes = new byte[4];
        _rng.GetBytes(bytes);
        return BitConverter.ToInt32(bytes, 0) % (_intMax - _intMin + 1) + _intMin;
    }

    public float GetRandomFloat()
    {
        byte[] bytes = new byte[4];
        _rng.GetBytes(bytes);
        uint value = BitConverter.ToUInt32(bytes, 0);
        return _floatMin + (value / (float)uint.MaxValue * (_floatMax - _floatMin));
    }

    public override string ToString()
    {
        return $"Int Range: {_intMin}-{_intMax}, Float Range: {_floatMin}-{_floatMax}";
    }
}
