// Function signature for validateElement callback
typedef int (*ValidateFunc)(const char*);

// C function to process string with limit and validate using callback
char* processStringWithLimit(char* inputStr, int sizeLimit, ValidateFunc validateElement) {
    if (inputStr == NULL || strlen(inputStr) > sizeLimit) {
        return NULL;
    }

    if (!validateElement(inputStr)) {
        return NULL;
    }

    int len = strlen(inputStr);
    if (len + 1 <= sizeLimit) {
        inputStr[len] = '/';
        inputStr[len + 1] = '\0';
        return inputStr;
    } else {
        char* truncatedStr = (char*)malloc(sizeLimit * sizeof(char));
        strncpy(truncatedStr, inputStr, sizeLimit - 1);
        truncatedStr[sizeLimit - 1] = '\0';
        return truncatedStr;
    }
}
