// JavaScript function to get elements matching selector and filter using callback
function getElementMatches(rootNode, selector, callback) {
    let result = [];

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE) {
            if (callback(node)) {
                let matches = node.querySelectorAll(selector);
                result.push(...matches);
            }
            for (let child of node.children) {
                traverse(child);
            }
        }
    }

    traverse(rootNode);
    return result;
}
