using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Security.Cryptography;

public class ImageDetails
{
    public int BitsPerPixel { get; set; }
    public int SamplesPerPixel { get; set; }
    public int ExtraSamples { get; set; }
    public string SampleInfo { get; set; }
}

public class TiffProcessor
{
    public (ImageDetails, byte[]) ProcessTiffImage(string filePath)
    {
        try
        {
            using (var image = Image.FromFile(filePath))
            {
                var details = ExtractImageDetails(image);
                var hash = ComputeMd5Hash(image);

                return (details, hash);
            }
        }
        catch (Exception ex)
        {
            // Log the exception details for debugging and monitoring
            Console.WriteLine($"Error processing TIFF image: {ex.Message}");
            throw;
        }
    }

    private ImageDetails ExtractImageDetails(Image image)
    {
        var details = new ImageDetails();
        using (var bitmap = new Bitmap(image))
        {
            details.BitsPerPixel = bitmap.PixelFormat == PixelFormat.Format1bppIndexed ? 1 : bitmap.PixelFormat == PixelFormat.Format24bppRgb ? 24 : bitmap.PixelFormat == PixelFormat.Format32bppArgb ? 32 : bitmap.PixelFormat == PixelFormat.Format64bppPbgra ? 64 : -1;
            details.SamplesPerPixel = details.BitsPerPixel / 8;
            details.ExtraSamples = image.PropertyIdList.Contains(ExtraSampleTag) ? image.GetPropertyItem(ExtraSampleTag).Value.Length : 0;
            details.SampleInfo = "No extra samples.";

            if (!SupportedBitsPerSample(details.BitsPerPixel))
            {
                throw new ArgumentException("Unsupported bits per sample value.");
            }
        }

        return details;
    }

    private byte[] ComputeMd5Hash(Image image)
    {
        using (var memoryStream = new MemoryStream())
        {
            image.Save(memoryStream, ImageFormat.Tiff);
            using (var md5 = MD5.Create())
            {
                return md5.ComputeHash(memoryStream.ToArray());
            }
        }
    }

    private bool SupportedBitsPerSample(int bitsPerPixel)
    {
        return bitsPerPixel == 1 || bitsPerPixel == 2 || bitsPerPixel == 4 || bitsPerPixel == 8 || bitsPerPixel == 16;
    }
}
