#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 128
#define MAX_EXTENSION_LENGTH 10

int generate_random_string(char *str, int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < length; ++i) {
        str[i] = charset[rand() % strlen(charset)];
    }
    str[length] = '\0';
    return 0;
}

int rename_file(const char *old_filename, const char *directory, const char *file_extension, char **new_filename) {
    struct dirent *entry;
    DIR *dir;
    int counter = 1;

    if ((dir = opendir(directory)) == NULL) {
        perror("Error opening directory");
        return -1;
    }

    // Generate random string and check for conflicts
    while (counter < 10000) { // Arbitrary limit to avoid infinite loops
        char new_extension[MAX_EXTENSION_LENGTH + 2]; // Extra space for '.' and null terminator
        generate_random_string(new_extension, MAX_EXTENSION_LENGTH);
        snprintf(*new_filename, MAX_FILENAME_LENGTH, "%s/%.*s.%s",
                 directory, strlen(old_filename) - strlen(strrchr(old_filename, '.')), old_filename, new_extension);

        if (opendir(directory) != NULL) {
            closedir(dir);
            dir = opendir(directory);
        }

        int found_conflict = 0;
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, (*new_filename) + strlen(directory) + 1) == 0) {
                found_conflict = 1;
                break;
            }
        }
        closedir(dir);

        if (!found_conflict) {
            return 0; // New filename is unique
        }

        counter++;
    }

    fprintf(stderr, "Failed to find a unique new filename after %d attempts\n", counter);
    free(*new_filename);
    *new_filename = NULL;
    return -1;
}

int main() {
    srand(time(NULL));

    const char *directory = "/path/to/directory";
    const char *old_filename = "example.txt";
    const char *file_extension = ".txt";

    char *new_filename = malloc(MAX_FILENAME_LENGTH);
    if (rename_file(old_filename, directory, file_extension, &new_filename) == 0) {
        printf("New filename: %s\n", new_filename);
    } else {
        printf("Failed to rename file\n");
    }

    free(new_filename);
    return 0;
}
```

