int execute_command_in_background(const char *command, const char *env_var) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        setsid(); // Detach from the parent session

        // Sanitize the environment variable string
        char *sanitized_env = strdup(env_var);
        for (char *p = sanitized_env; *p != '\0'; p++) {
            if (*p == '&' || *p == ';' || *p == '>' || *p == '<') {
                *p = '\0';
                break;
            }
        }

        // Execute the command with a sanitized environment
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        free(sanitized_env);
        _exit(1);
    } else {
        // Parent process
        return 1;
    }
}

int main() {
    const char *command = "ls -l /root";
    const char *env_var = "HOME=/tmp;PATH=/bin";

    if (execute_command_in_background(command, env_var)) {
        printf("Command executed successfully.\n");
    } else {
        printf("Failed to execute command.\n");
    }

    return 0;
}
```

This code defines a function `execute_command_in_background` that takes a command and an environment variable string as inputs. It uses `fork()` to create a child process, `setsid()` to detach the child from the parent session, sanitizes the environment variable string, and then executes the command using `execl()`. The function returns 1 if the command is successfully executed in the background, and 0 otherwise.']

