using System;
using System.Diagnostics;
using System.IO;
using System.Text.RegularExpressions;

public class WebsiteIntegrationManager
{
    private static readonly string SafeDirectoryStructure = @"^[a-zA-Z0-9_]+$";
    private static readonly string LogFilePath = "integration.log";

    public Process IntegrateAndStartSite(string directoryPath, string siteName)
    {
        try
        {
            // Validate directory path
            if (!Regex.IsMatch(directoryPath, SafeDirectoryStructure))
            {
                Log("Invalid directory path: " + directoryPath);
                return null;
            }

            // Sanitize site name
            string sanitizedSiteName = Regex.Replace(siteName, @"[^a-zA-Z0-9_]", "_");

            // Check for web.config file
            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                Log("No web.config file found in: " + directoryPath);
                return null;
            }

            // Create process information
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = "path_to_website_management_tool",
                Arguments = $"{directoryPath} {sanitizedSiteName}",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            // Start process
            Process process = new Process { StartInfo = startInfo };
            process.Start();

            // Log start
            Log($"Started website integration for {sanitizedSiteName} at {directoryPath}");

            return process;
        }
        catch (Exception ex)
        {
            Log("Error during website integration: " + ex.Message);
            return null;
        }
    }

    private void Log(string message)
    {
        string logMessage = $"{DateTime.Now}: {message}";
        File.AppendAllText(LogFilePath, logMessage + Environment.NewLine);
    }
}
