import java.io.*;
import java.nio.file.*;
import java.util.*;

public class DirectoryProcessor {

    private static final String DEFAULT_FILE_NAME = "config.txt";

    public static void main(String[] args) {
        List<String> directoryPaths = getUserInput();
        for (String path : directoryPaths) {
            processDirectory(path, DEFAULT_FILE_NAME);
        }
    }

    private static List<String> getUserInput() {
        List<String> paths = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter directory paths separated by commas:");
        String input = scanner.nextLine();
        Collections.addAll(paths, input.split(",\\s*"));
        return paths;
    }

    private static void processDirectory(String path, String fileName) {
        try (Stream<Path> stream = Files.walk(Paths.get(path))) {
            Path targetFile = stream
                    .filter(Files::isRegularFile)
                    .filter(p -> p.getFileName().toString().equals(fileName))
                    .findFirst()
                    .orElse(null);

            if (targetFile != null) {
                deleteFile(targetFile);
            } else {
                System.out.println("No " + fileName + " found in: " + path);
            }
        } catch (IOException e) {
            System.err.println("Error processing directory: " + path + ", " + e.getMessage());
        }
    }

    private static void deleteFile(Path file) {
        try {
            Files.delete(file);
            System.out.println("Deleted: " + file.getFileName());
        } catch (IOException e) {
            System.err.println("Failed to delete file: " + file.getFileName() + ", " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        List<String> directoryPaths = getUserInput();
        for (String path : directoryPaths) {
            processDirectory(path, DEFAULT_FILE_NAME);
        }
    }
}
