#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libpq-fe.h>

typedef struct {
    const char *host;
    int port;
    const char *username;
    const char *password;
} ConnectionParams;

bool connectToDatabase(const char *configFilePath, ConnectionParams *params) {
    FILE *configFile = fopen(configFilePath, "r");
    if (!configFile) {
        fprintf(stderr, "Failed to open configuration file: %s\n", configFilePath);
        return false;
    }

    // Parse the configuration file to retrieve connection parameters
    char line[256];
    while (fgets(line, sizeof(line), configFile)) {
        char *key = strtok(line, "=");
        if (!key) continue;
        key[strcspn(key, "\r\n")] = 0; // Remove trailing newline

        char *value = strtok(NULL, "=\n");
        if (!value) continue;

        value[strcspn(value, "\r\n")] = 0; // Remove trailing newline

        if (strcmp(key, "host") == 0) {
            params->host = strdup(value);
        } else if (strcmp(key, "port") == 0) {
            params->port = atoi(value);
        } else if (strcmp(key, "username") == 0) {
            params->username = strdup(value);
        } else if (strcmp(key, "password") == 0) {
            params->password = strdup(value);
        }
    }

    fclose(configFile);

    // Validate the connection parameters
    if (!params->host || !params->username || !params->password) {
        fprintf(stderr, "Missing required configuration parameters\n");
        return false;
    }

    // Establish the database connection
    char connInfo[256];
    snprintf(connInfo, sizeof(connInfo), "host=%s port=%d user=%s password=%s", 
             params->host, params->port, params->username, params->password);

    PGconn *conn = PQconnectdb(connInfo);
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s\n", PQerrorMessage(conn));
        PQfinish(conn);
        free((void*)params->host);
        free((void*)params->username);
        free((void*)params->password);
        return false;
    }

    // Execute a simple query to verify the connection
    PGresult *res = PQexec(conn, "SELECT NOW()");
    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Query failed: %s\n", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        free((void*)params->host);
        free((void*)params->username);
        free((void*)params->password);
        return false;
    }

    PQclear(res);
    PQfinish(conn);

    // Clean up allocated memory
    free((void*)params->host);
    free((void*)params->username);
    free((void*)params->password);

    return true;
}

int main() {
    ConnectionParams params = {0};
    if (connectToDatabase("config.ini", &params)) {
        printf("Successfully connected to the database\n");
    } else {
        printf("Failed to connect to the database\n");
    }
    return 0;
}
```

