using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDesDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly CipherMode _cipherMode;

    public TripleDesDecryptor(byte[] key, byte[] iv, CipherMode cipherMode)
    {
        if (key == null || key.Length != 24)
            throw new ArgumentException("Invalid key length. It must be 24 bytes for Triple DES.");

        if (iv == null || iv.Length != 8)
            throw new ArgumentException("Invalid IV length. It must be 8 bytes for Triple DES.");

        _key = key;
        _iv = iv;
        _cipherMode = cipherMode;
    }

    public string Decrypt(string base64EncryptedMessage, byte[] macKey)
    {
        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
            using (TripleDES tripleDes = TripleDES.Create())
            {
                tripleDes.Key = _key;
                tripleDes.IV = _iv;
                tripleDes.Mode = _cipherMode;

                using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tripleDes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[encryptedBytes.Length];
                    int bytesRead = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                    Array.Resize(ref decryptedBytes, bytesRead);

                    if (!VerifyMac(decryptedBytes, macKey))
                        throw new InvalidOperationException("Message authentication failed.");

                    return Encoding.UTF8.GetString(decryptedBytes);
                }
            }
        }
        catch (Exception ex)
        {
            // Log the error and rethrow or handle gracefully
            Console.WriteLine($"Decryption error: {ex.Message}");
            throw;
        }
    }

    private bool VerifyMac(byte[] data, byte[] macKey)
    {
        using (HMACSHA256 hmac = new HMACSHA256(macKey))
        {
            byte[] computedMac = hmac.ComputeHash(data);
            // Compare MACs securely
            return ConstantTimeComparison.Equals(computedMac, data.Skip(data.Length - computedMac.Length).ToArray());
        }
    }
}
```

