using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TextIntegrityVerifier
{
    private readonly byte[] _secretKey;
    private static readonly HMAC MD5Hmac = new HMACMD5();

    public TextIntegrityVerifier(string secretKey)
    {
        _secretKey = Encoding.UTF8.GetBytes(secretKey);
    }

    public bool VerifyText(Stream inputStream, out string hashResult)
    {
        using (var md5Hash = MD5.Create())
        using (var reader = new StreamReader(inputStream))
        {
            var messageBytes = Encoding.UTF8.GetBytes(reader.ReadToEnd());
            var computedHash = md5Hash.ComputeHash(messageBytes);
            hashResult = BitConverter.ToString(computedHash).Replace("-", "").ToLower();

            var hmacResult = HMACSHA256(messageBytes, _secretKey);
            return hashResult == hmacResult;
        }
    }

    private static string HMACSHA256(byte[] message, byte[] key)
    {
        using (var hmacsha256 = new HMACSHA256(key))
        {
            var hashValue = hmacsha256.ComputeHash(message);
            return BitConverter.ToString(hashValue).Replace("-", "").ToLower();
        }
    }

    public void LogMessage(string rawInput, bool isVerified)
    {
        // Implement logging here
        Console.WriteLine($"Raw Input: {rawInput}, Verified: {isVerified}");
    }
}
