public class AESGCMDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly byte[] _aad;

    public AESGCMDecryptor(byte[] key, byte[] iv, byte[] aad)
    {
        if (key.Length != 16 && key.Length != 32) throw new ArgumentException("Key must be 16 or 32 bytes.");
        if (iv.Length != 12) throw new ArgumentException("IV must be 12 bytes.");
        _key = key;
        _iv = iv;
        _aad = aad;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] tag)
    {
        try
        {
            using (AesGcm aesGcm = AesGcm.Create())
            {
                aesGcm.Key = _key;
                aesGcm.IV = _iv;
                aesGcm.AddAdditionalAuthenticatedData(_aad);

                byte[] plaintext = new byte[ciphertext.Length];
                aesGcm.Decrypt(tag, ciphertext, plaintext);
                return plaintext;
            }
        }
        catch (CryptographicException ex)
        {
            LogError("Decryption failed: " + ex.Message);
            return null;
        }
    }

    private void LogError(string message)
    {
        // Implement logging mechanism here
        Console.WriteLine(message); // Example placeholder for logging
    }
}
