public class ObjectFileReader {

    public static <T> T readObjectFromFile(String filePath, Class<T> clazz) throws IOException, ClassNotFoundException {
        FileInputStream fis = new FileInputStream(filePath);
        GZIPInputStream gzipIn = new GZIPInputStream(fis);
        ObjectInputStream ois = new ObjectInputStream(gzipIn);

        try {
            return clazz.cast(ois.readObject());
        } catch (IOException e) {
            System.out.println("Failed to read object from file: " + filePath);
            throw e;
        } catch (ClassNotFoundException e) {
            System.out.println("Class not found while deserializing object from file: " + filePath);
            throw e;
        } finally {
            ois.close();
            gzipIn.close();
            fis.close();
        }
    }

    public static void main(String[] args) {
        try {
            // Example usage
            MyClass myObject = readObjectFromFile("path/to/your/file.gz", MyClass.class);
            System.out.println("Object deserialized successfully: " + myObject.toString());
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

