import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ObjectDeserializer {
    private static final Logger logger = Logger.getLogger(ObjectDeserializer.class.getName());

    public static List<Object> deserializeObjects(byte[] data) throws RuntimeException {
        List<Object> objects = new ArrayList<>();
        ByteArrayInputStream bis = null;
        ObjectInputStream ois = null;

        try {
            bis = new ByteArrayInputStream(data);
            ois = new ObjectInputStream(bis);

            while (true) {
                try {
                    objects.add(ois.readObject());
                } catch (ClassNotFoundException e) {
                    logger.log(Level.SEVERE, "Class not found during deserialization", e);
                    throw new RuntimeException("Failed to deserialize object: " + e.getMessage(), e);
                }
            }
        } catch (IOException e) {
            if (e instanceof java.io.EOFException) {
                // End of stream reached
                return objects;
            } else {
                logger.log(Level.SEVERE, "IO error during deserialization", e);
                throw new RuntimeException("I/O error occurred during deserialization: " + e.getMessage(), e);
            }
        } finally {
            try {
                if (ois != null) ois.close();
                if (bis != null) bis.close();
            } catch (IOException ex) {
                logger.log(Level.SEVERE, "Error closing streams", ex);
                throw new RuntimeException("Failed to close streams during deserialization: " + ex.getMessage(), ex);
            }
        }
    }
}
