use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::task;

const MAX_RETRIES: usize = 3;
const BACKOFF_INTERVAL: Duration = Duration::from_millis(100);

fn create_directory_and_set_env_var(env_key: &str, dir_name: &str) -> Result<(), String> {
    let env_var_path = env::var(env_key).unwrap_or_else(|_| "".to_string());
    let mut env_var_path = PathBuf::new();

    if !env_var_path.as_os_str().is_empty() && Path::new(&env_var_path).exists() {
        if fs::metadata(&env_var_path)?.is_dir() {
            return Ok(());
        }
    }

    for _ in 0..MAX_RETRIES {
        env_var_path = get_unique_directory_path(dir_name);
        if !Path::new(&env_var_path).exists() {
            match fs::create_dir_all(&env_var_path) {
                Ok(_) => {
                    env::set_var(env_key, env_var_path.clone());
                    return Ok(());
                }
                Err(e) => {
                    tokio::time::sleep(BACKOFF_INTERVAL).await;
                }
            }
        } else {
            // Handle concurrent directory creation
            continue;
        }
    }

    Err(format!("Failed to create directory after {} retries", MAX_RETRIES))
}

fn get_unique_directory_path(dir_name: &str) -> PathBuf {
    let mut path = std::env::temp_dir();
    path.push(dir_name);
    path.set_extension("dir");
    path
}

#[tokio::main]
async fn main() {
    let env_key = "MY_DIRECTORY_ENV_VAR";
    let dir_name = "my_directory";

    match create_directory_and_set_env_var(env_key, dir_name) {
        Ok(_) => println!("Directory created and environment variable set successfully"),
        Err(e) => eprintln!("Failed to create directory or set environment variable: {}", e),
    }
}
