typedef struct {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

Record* init_records(int count, unsigned long seed) {
    srand(seed);
    Record* records = (Record*)safe_malloc(count * sizeof(Record));
    for (int i = 0; i < count; ++i) {
        records[i].value = rand();
    }
    return records;
}

void free_records(Record* records, int count) {
    free(records);
}

int find_largest(int* array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size\n");
        exit(1);
    }
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void read_integers(int** array, int* count) {
    *count = 0;
    while (1) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        *array = (int*)realloc(*array, (*count + 1) * sizeof(int));
        if (!*array) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        (*array)[(*count)++] = value;
    }
}

void print_largest(int max_value) {
    printf("Largest integer: %d\n", max_value);
}

int main() {
    int count;
    int* integers = NULL;

    read_integers(&integers, &count);

    if (count > 0) {
        int max_value = find_largest(integers, count);
        print_largest(max_value);

        free(integers);
    } else {
        printf("No integers entered.\n");
    }

    return 0;
}
