} Data;

void manage_memory_allocation(long *timestamps, int *indices, Data **data, int count, unsigned int seed) {
    srand(seed);

    timestamps = (long *)malloc(count * sizeof(long));
    indices = (int *)malloc(count * sizeof(int));
    data = (Data **)malloc(count * sizeof(Data *));

    if (!timestamps || !indices || !data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; i++) {
        timestamps[i] = time(NULL);
        indices[i] = rand() % 1000;
        data[i] = (Data *)malloc(sizeof(Data));
        if (!data[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        data[i]->value = ((double)rand()) / RAND_MAX;
        snprintf(data[i]->buffer, sizeof(data[i]->buffer), "Entry %d", i);
    }

    // Further processing...

    for (int i = 0; i < count; i++) {
        free(data[i]);
    }
    free(data);
    free(indices);
    free(timestamps);
}

int main() {
    unsigned int seed = 12345;
    int count = 100;

    manage_memory_allocation(NULL, NULL, NULL, count, seed);

