namespace RecordManagement {
    struct record {
        int value;
    };

    class DynamicRecordManager {
    public:
        static std::mt19937 generator;

        DynamicRecordManager() {
            seedGenerator();
            allocateRecords();
        }

        ~DynamicRecordManager() {
            deallocateRecords();
        }

        void addRecord(int key, int value) {
            if (key >= 1 && key <= 1000) {
                record* newRecord = &records[key - 1];
                newRecord->value = value;
            }
        }

        record* queryRecord(int key) {
            if (key >= 1 && key <= 1000) {
                return &records[key - 1];
            }
            return nullptr;
        }

    private:
        static void seedGenerator() {
            generator.seed(static_cast<unsigned int>(std::time(nullptr)));
        }

        void allocateRecords() {
            offsets = new long[1000];
            keys = new int[1000];
            records = new record[1000];

            for (int i = 0; i < 1000; ++i) {
                offsets[i] = generator();
                keys[i] = generator() % 1000 + 1;
                records[i].value = generator() % 1000;
            }
        }

        void deallocateRecords() {
            delete[] offsets;
            delete[] keys;
            delete[] records;
        }

        long* offsets;
        int* keys;
        record* records;
    };

    std::mt19937 DynamicRecordManager::generator;
}

int main() {
    RecordManagement::DynamicRecordManager manager;

