#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_PACKET_SIZE 1024 * 1024 // Example maximum packet size

typedef struct Packet {
    uint32_t header;
    uint32_t payloadLength;
    char* payload;
} Packet;

typedef struct ThreadData {
    pthread_mutex_t* queueMutex;
    pthread_cond_t* notEmpty;
    Packet** queue;
    int front, rear, capacity;
    int count;
} ThreadData;

void initThreadData(ThreadData* td, int size) {
    td->queue = (Packet**)malloc(size * sizeof(Packet*));
    td->capacity = size;
    td->front = 0;
    td->rear = -1;
    td->count = 0;
    pthread_mutex_init(&(td->queueMutex), NULL);
    pthread_cond_init(&(td->notEmpty), NULL);
}

void enqueue(ThreadData* td, Packet* packet) {
    pthread_mutex_lock(&(td->queueMutex));
    while (td->count == td->capacity) {
        pthread_cond_wait(&(td->notEmpty), &(td->queueMutex));
    }
    td->rear = (td->rear + 1) % td->capacity;
    td->queue[td->rear] = packet;
    td->count++;
    pthread_mutex_unlock(&(td->queueMutex));
}

Packet* dequeue(ThreadData* td) {
    pthread_mutex_lock(&(td->queueMutex));
    while (td->count == 0) {
        pthread_cond_wait(&(td->notEmpty), &(td->queueMutex));
    }
    Packet* packet = td->queue[td->front];
    td->front = (td->front + 1) % td->capacity;
    td->count--;
    pthread_mutex_unlock(&(td->queueMutex));
    return packet;
}

void freePacket(Packet* packet) {
    if (packet->payload != NULL) {
        free(packet->payload);
    }
    free(packet);
}

void processNetworkPackets(ThreadData* td, int numThreads) {
    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, packetProcessorThread, td);
    }

    // Simulate incoming packets
