#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct Transaction {
    int id;
    int userId;
    long timestamp;
    double amount;
} Transaction;

typedef struct UserSummary {
    int userId;
    double totalAmount;
    int processed;
    pthread_mutex_t lock;
} UserSummary;

UserSummary *userSummaries[MAX_RECORDS];
int userCount = 0;
pthread_mutex_t globalLock;

void parseCsv(const char *filename, long startDate, long endDate) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Transaction transaction;
        // Parse CSV fields into transaction structure
        sscanf(line, "%d,%d,%ld,%lf", &transaction.id, &transaction.userId, &transaction.timestamp, &transaction.amount);

        if (transaction.timestamp >= startDate && transaction.timestamp <= endDate) {
            pthread_mutex_lock(&globalLock);
            int userId = transaction.userId;
            if (userSummaries[userId] == NULL) {
                userSummaries[userId] = malloc(sizeof(UserSummary));
                userSummaries[userId]->userId = userId;
                userSummaries[userId]->totalAmount = 0.0;
                userSummaries[userId]->processed = 1;
                pthread_mutex_init(&userSummaries[userId]->lock, NULL);
            } else {
                pthread_mutex_lock(&userSummaries[userId]->lock);
                if (userSummaries[userId]->processed == 1) {
                    userSummaries[userId]->totalAmount += transaction.amount;
                    userSummaries[userId]->processed = 0;
                }
                pthread_mutex_unlock(&userSummaries[userId]->lock);
            }
            pthread_mutex_unlock(&globalLock);
        }
    }

    fclose(file);
}

void summarizeResults() {
    for (int i = 0; i < userCount; i++) {
        if (userSummaries[i] != NULL) {
            printf("User ID: %d, Total Amount: %.2f\n", userSummaries[i]->userId, userSummaries[i]->totalAmount);
            free(userSummaries[i]);
            pthread_mutex_destroy(&userSummaries[i]->lock);
        }
    }
}

int main() {
    long startDate = 1609459200; // Example start date
    long endDate = 1672531200;   // Example end date

    parseCsv("transactions.csv", startDate, endDate);
    summarizeResults();

    return 0;
}
