import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class CommandExecutor {
    private static final Map<String, String> statusCache = new HashMap<>();
    private static final Map<String, String> hashCache = new HashMap<>();

    public static String executeBackgroundCommand(String command) {
        if (command == null || command.isEmpty()) {
            return "INVALID_COMMAND";
        }

        try {
            String md5Hash = getMd5Hash(command);
            if (statusCache.containsKey(md5Hash)) {
                return statusCache.get(md5Hash);
            }

            Process process = Runtime.getRuntime().exec(command + " &");
            int exitCode = process.waitFor();

            String status = exitCode == 0 ? "EXECUTION_SUCCESS" : "EXECUTION_FAILURE";
            statusCache.put(md5Hash, status);
            limitCacheSize(statusCache);

            return status;
        } catch (Exception e) {
            // Log error and return failure
            System.err.println("Error executing command: " + e.getMessage());
            return "EXECUTION_FAILURE";
        }
    }

    private static String getMd5Hash(String input) throws NoSuchAlgorithmException {
        if (!hashCache.containsKey(input)) {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            hashCache.put(input, hexString.toString());
            limitCacheSize(hashCache);
        }

        return hashCache.get(input);
    }

    private static void limitCacheSize(Map<String, String> cache) {
        while (cache.size() > 256) {
            cache.remove(cache.keySet().iterator().next());
        }
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(executeBackgroundCommand("ls -la"));
    }
}
