using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Caching.Distributed;
using StackExchange.Redis;

public class PageUpdater
{
    private readonly IDistributedCache _cache;
    private readonly IConnectionMultiplexer _redis;

    public PageUpdater(IDistributedCache cache, IConnectionMultiplexer redis)
    {
        _cache = cache;
        _redis = redis;
    }

    [HttpPost]
    public async Task<IActionResult> UpdatePageSection(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            if (!IsValidInput(pageSectionId, elementId, htmlContent))
                return BadRequest("Invalid input");

            var userId = GetUserIdFromRequest(); // Assume this method retrieves the authenticated user ID

            if (await IsRateLimitExceeded(userId))
                return StatusCode(StatusCodes.Status429TooManyRequests, "Rate limit exceeded. Please try again later.");

            var cacheKey = $"{pageSectionId}:{elementId}";
            await _cache.SetStringAsync(cacheKey, htmlContent);

            var jobQueueKey = $"JobQueue:{pageSectionId}";
            var jobId = Guid.NewGuid().ToString();
            await _redis.GetDatabase().ListRightPushAsync(jobQueueKey, jobId);

            // Enqueue background job to update cache and render page section
            BackgroundJobs.Enqueue(async () =>
            {
                try
                {
                    await UpdateCacheAndRender(pageSectionId, elementId, htmlContent);
                }
                catch (Exception ex)
                {
                    LogError(ex);
                }
            });

            return Ok("Update enqueued successfully");
        }
        catch (Exception ex)
        {
            LogError(ex);
            return StatusCode(StatusCodes.Status500InternalServerError, "An error occurred while processing your request.");
        }
    }

    private bool IsValidInput(string pageSectionId, string elementId, string htmlContent)
    {
        // Validate input schema
        return !string.IsNullOrEmpty(pageSectionId) && !string.IsNullOrEmpty(elementId) && !string.IsNullOrEmpty(htmlContent);
    }

    private string GetUserIdFromRequest()
    {
        // Assume this method retrieves the authenticated user ID from the request
        return "userId";
    }

    private async Task<bool> IsRateLimitExceeded(string userId)
    {
        var rateLimitKey = $"RateLimit:{userId}";
        var currentCount = await _redis.GetDatabase().StringIncrementAsync(rateLimitKey);
        if (currentCount == 1) // Start counting from the first request
            await _redis.GetDatabase().ExpireAsync(rateLimitKey, TimeSpan.FromHours(1));

        return currentCount > 5;
    }

    private async Task UpdateCacheAndRender(string pageSectionId, string elementId, string htmlContent)
    {
        var cacheKey = $"{pageSectionId}:{elementId}";
        await _cache.SetStringAsync(cacheKey, htmlContent);
        // Implement rendering logic here
    }

    private void LogError(Exception ex)
    {
        // Log the error without exposing internal details
        Console.WriteLine($"Error: {ex.Message}");
    }
}
