record* allocate_and_init_records(int num_records, unsigned seed) {
    if (num_records <= 0) return NULL;

    srand(seed);

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int key = 1;
    for (int i = 0; i < num_records; ++i, ++key) {
        records[i].value = rand() % INT_MAX;
        records[i].offset = ((long)rand()) << 32 | rand();
        records[i].key = key;
        records[i].measurement = (double(rand()) / RAND_MAX) * 100.0; // Simulate temperature
    }

    return records;
}

void free_records(record *records, int num_records) {
    if (records) {
        free(records);
    }
}

int find_largest_integer(int* arr, int size) {
    if (size <= 0 || !arr) return INT_MIN;

    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

int main() {
    int num_records, num_integers;
    printf("Enter number of records: ");
    scanf("%d", &num_records);

    record *records = allocate_and_init_records(num_records, time(NULL));
    if (!records) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    int *integers = malloc(num_integers * sizeof(int));
    if (!integers) {
        perror("Failed to allocate memory for integers");
        free_records(records, num_records);
        return EXIT_FAILURE;
    }

    printf("Enter number of integers: ");
    scanf("%d", &num_integers);

    printf("Enter %d integers:\n", num_integers);
    for (int i = 0; i < num_integers; ++i) {
        scanf("%d", &integers[i]);
    }

    int largest_integer = find_largest_integer(integers, num_integers);
    if (largest_integer != INT_MIN) {
        printf("Largest integer: %d\n", largest_integer);
    } else {
        fprintf(stderr, "Failed to find the largest integer\n");
    }

    free_records(records, num_records);
    free(integers);

    return EXIT_SUCCESS;
}
