void* allocate_from_pool(size_t size) {
    if (used_memory + size > pool_size) {
        custom_memory_pool = realloc(custom_memory_pool, pool_size + pool_increment);
        pool_size += pool_increment;
    }
    void* mem = (char*)custom_memory_pool + used_memory;
    used_memory += size;
    return mem;
}

void initialize_records(int seed, int range_min, int range_max, size_t num_records) {
    srand(seed);

    long* offsets = (long*)allocate_from_pool(num_records * sizeof(long));
    int* keys = (int*)allocate_from_pool(num_records * sizeof(int));
    record* records = (record*)allocate_from_pool(num_records * sizeof(record));

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i;
        keys[i] = rand() % (range_max - range_min + 1) + range_min;
        records[i].value = keys[i];
    }

    // Integrate with external data processing library
