    // Free allocated memory when done
    used_memory -= num_records * sizeof(long);
    used_memory -= num_records * sizeof(int);
    used_memory -= num_records * sizeof(record);
    if (used_memory == 0) {
        free(custom_memory_pool);
        custom_memory_pool = NULL;
        pool_size = 0;
    }
}

