    int *keys = malloc(numRecords * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    record *records = malloc(numRecords * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    // Initialize and fill records with random values
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

void findAndPrintLargest(int *array, int size) {
    if (size <= 0) {
        printf("Array is empty\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
