void processAndTestModule(char* label, void (*f)()) {
    // Initialize semaphore
    sem_t* sem = sem_open("/my_semaphore", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return;
