    srand(time(NULL));

    // Read integers from standard input and store in an array
    int* numbers = NULL;
    size_t count = 0;
    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;
        numbers = realloc(numbers, (count + 1) * sizeof(int));
        numbers[count++] = num;
