#define POOL_SIZE 1024

typedef struct {
    int value;
    time_t timestamp;
    char status;
} record;

typedef struct memory_pool {
    void *pool;
    size_t size;
    size_t used;
    size_t block_size;
} memory_pool;

memory_pool pool_init(size_t block_size) {
    memory_pool p;
    p.pool = malloc(POOL_SIZE * block_size);
    if (!p.pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    p.size = POOL_SIZE * block_size;
    p.used = 0;
    p.block_size = block_size;
    return p;
}

void *pool_alloc(memory_pool *p) {
    if (p->used + p->block_size > p->size) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    void *block = ((char *)p->pool) + p->used;
    p->used += p->block_size;
    return block;
}

void pool_free(memory_pool *p) {
    // No-op for this example
}

record* init_arrays(size_t size, memory_pool *long_pool, memory_pool *int_pool, memory_pool *record_pool) {
    long *offsets = (long *)pool_alloc(long_pool);
    int *keys = (int *)pool_alloc(int_pool);
    record *records = (record *)pool_alloc(record_pool);

    // Initialize arrays
    for (size_t i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        records[i].value = rand() % 256;
        records[i].timestamp = time(NULL);
        records[i].status = 'A';
    }

    return records;
}

int main() {
    srand(time(NULL));
    memory_pool long_pool = pool_init(sizeof(long));
    memory_pool int_pool = pool_init(sizeof(int));
    memory_pool record_pool = pool_init(sizeof(record));

    size_t array_size = 1000;
    record *records = init_arrays(array_size, &long_pool, &int_pool, &record_pool);

    // Process records...

    pool_free(&long_pool);
    pool_free(&int_pool);
    pool_free(&record_pool);

    return 0;
}
