        (*records)[i].identifier = 'A' + (rand() % 26); // Random char identifier
        (*records)[i].timestamp = ((double)rand() / RAND_MAX) * time(NULL); // Random timestamp
    }
}

void clean_up(long *offsets, int *keys, Record **records, int size) {
    free(offsets);
    free(keys);
    if (records != NULL && *records != NULL) {
        free(*records);
    }
}

