SessionRecord* create_session_records(int num_sessions, size_t *allocation_size, void (*cleanup_callback)(void)) {
    if (num_sessions <= 0 || allocation_size == NULL || cleanup_callback == NULL) {
        return NULL; // Invalid input
    }

    SessionRecord *sessions = NULL;
    size_t current_size = MIN_ALLOCATION_SIZE;

    while (current_size < num_sessions * sizeof(SessionRecord)) {
        sessions = realloc(sessions, current_size);
        if (sessions != NULL) {
            *allocation_size = current_size;
            break;
        }
        current_size *= 2; // Double the size for next attempt
    }

    if (sessions == NULL) {
        cleanup_callback(); // Call user's callback on failure
        return NULL; // Memory allocation failed
    }

    // Initialize session records using CSPRNG
    unsigned char seed[16];
    if (!RAND_bytes(seed, sizeof(seed))) {
        cleanup_callback();
        free(sessions);
        return NULL; // Failed to get random seed
    }

    srand48((long)time(NULL));
    for (int i = 0; i < num_sessions; i++) {
        sessions[i].session_id = lrand48(); // Use a fast PRNG for simplicity
