#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_LOG_ENTRIES 100
#define BUFFER_SIZE 256

typedef struct {
    char logEntries[MAX_LOG_ENTRIES][BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

void initializeLog(CircularBuffer *cb) {
    cb->head = cb->tail = 0;
}

void addToLog(CircularBuffer *cb, const char *message) {
    snprintf(cb->logEntries[cb->head], BUFFER_SIZE, "%s", message);
    cb->head = (cb->head + 1) % MAX_LOG_ENTRIES;
}

void executeCommandWithLoggingAndCleanup(const char *command, int seed, int timeout, long* offsets, int* keys, int keyCount, CircularBuffer *logBuffer) {
    // Initialize pseudo-random number generator
    srand(seed);

    // Dynamically allocate memory for arrays
    offsets = (long*)malloc(keyCount * sizeof(long));
    keys = (int*)malloc(keyCount * sizeof(int));

    if (!offsets || !keys) {
        addToLog(logBuffer, "Error: Memory allocation failed");
        return;
    }

    // Initialize arrays with random numbers and long values
    for (int i = 0; i < keyCount; i++) {
        keys[i] = rand() % 1000; // Range for non-security-critical needs
        offsets[i] = i * sizeof(long); // Example initialization
    }

    // Read integers from standard input and calculate average
    int numbers[keyCount];
    printf("Enter %d integers:\n", keyCount);
    for (int i = 0; i < keyCount; i++) {
        scanf("%d", &numbers[i]);
    }
    double sum = 0;
    for (int i = 0; i < keyCount; i++) {
        sum += numbers[i];
    }
    double average = sum / keyCount;

    // Execute command and handle output/error streams
    FILE *fp = popen(command, "r");
    if (!fp) {
        addToLog(logBuffer, "Error: Command execution failed");
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, fp) != NULL) {
        printf("%s", buffer);
    }
    int status = pclose(fp);

    // Log command execution result
    snprintf(buffer, BUFFER_SIZE, "Command executed with status %d\n", status);
    addToLog(logBuffer, buffer);

    // Clean up resources
    free(offsets);
    free(keys);

    printf("Average: %.2f\n", average);
}
