TransactionArray* create_transaction_array() {
    TransactionArray *array = malloc(sizeof(TransactionArray));
    if (array == NULL) {
        return NULL; // Handle memory allocation failure
    }
    array->timestamps = malloc(INITIAL_CAPACITY * sizeof(long));
    array->amounts = malloc(INITIAL_CAPACITY * sizeof(double));
    if (array->timestamps == NULL || array->amounts == NULL) {
        free(array);
        return NULL; // Handle memory allocation failure
    }
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    return array;
}

void destroy_transaction_array(TransactionArray *array) {
    free(array->timestamps);
    free(array->amounts);
    free(array);
}

void add_transaction(TransactionArray *array, long timestamp, double amount) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        long *new_timestamps = realloc(array->timestamps, new_capacity * sizeof(long));
        double *new_amounts = realloc(array->amounts, new_capacity * sizeof(double));
        if (new_timestamps == NULL || new_amounts == NULL) {
            // Handle memory allocation failure
            return;
        }
        array->timestamps = new_timestamps;
        array->amounts = new_amounts;
        array->capacity = new_capacity;
    }
    array->timestamps[array->count] = timestamp;
    array->amounts[array->count] = amount;
    array->count++;
}

void initialize_timestamps(TransactionArray *array, long seed) {
    srand(seed);
    for (size_t i = 0; i < array->count; i++) {
        array->timestamps[i] = time(NULL) + rand();
    }
}
