    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void free_all_memory(offset_t* offsets, key_t* keys, record_t* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
