    key_t* keys = allocate_key_array(array_size);
    record_t* records = allocate_record_array(array_size, min_value, max_value);

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Use the allocated arrays...

    free_all_memory(offsets, keys, records);

    return 0;
}
