long allocateMemoryAndFill(int range, int count) {
    long total = 0;
    for (int i = 0; i < count; ++i) {
        total += rand() % range + 1;
    }
    return total;
}

void* processChunk(void* arg) {
    // Simulate processing a chunk of data
    pthread_exit(NULL);
}

void logEvent(const char* message) {
    static char buffer[BUFFER_SIZE];
    time_t now = time(NULL);
    snprintf(buffer, BUFFER_SIZE, "[%ld] %s\n", now, message);
    // Implement circular buffer for logging
    printf("%s", buffer);
}

int main() {
    int seed = 42;
    int range = 100;
    int count = 1000000;

    seedRandom(seed);

    long total = allocateMemoryAndFill(range, count);
    if (total > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Error: Memory usage exceeds limit.\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    sem_t sem;

    // Initialize semaphore
    sem_init(&sem, 0, 1);

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, processChunk, &sem)) {
            fprintf(stderr, "Error: Failed to create thread.\n");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&sem);

    printf("Average: %ld\n", total / count);

    return EXIT_SUCCESS;
}
