typedef struct {
    char* str;
    int id;
    double value;
} Data;

typedef struct {
    time_t timestamp;
    char message[256];
} LogEntry;

LogEntry logBuffer[MAX_LOG_SIZE];
int logIndex = 0;

void logEvent(const char* message) {
    time_t now = time(NULL);
    snprintf(logBuffer[logIndex].message, sizeof(logBuffer[logIndex].message), "%s: %s", ctime(&now), message);
    logBuffer[logIndex].timestamp = now;
    logIndex = (logIndex + 1) % MAX_LOG_SIZE;
}

int findLongestString(char* strings[], int count) {
    int maxLength = 0;
    for (int i = 0; i < count; i++) {
        if (strlen(strings[i]) > maxLength) {
            maxLength = strlen(strings[i]);
        }
    }
    return maxLength;
}

void processAndLogData(int seed, char* strings[], int count) {
    srand(seed);
    time_t start = time(NULL);

    // Allocate and initialize arrays
    long* timestamps = malloc(count * sizeof(long));
    int* identifiers = malloc(count * sizeof(int));
    double* values = malloc(count * sizeof(double));
    Data** dataStructures = malloc(count * sizeof(Data*));

    if (!timestamps || !identifiers || !values || !dataStructures) {
        logEvent("Memory allocation failed");
        return;
    }

    // Initialize arrays using PRNG
    for (int i = 0; i < count; i++) {
        timestamps[i] = rand();
        identifiers[i] = rand() % 1000;
        values[i] = ((double)rand() / RAND_MAX) * 100.0;
        dataStructures[i] = malloc(sizeof(Data));
        dataStructures[i]->str = strdup(strings[i]);
        dataStructures[i]->id = identifiers[i];
        dataStructures[i]->value = values[i];

        logEvent("Data structure initialized: str=%s, id=%d, value=%.2f", strings[i], identifiers[i], values[i]);
    }

    int longestLength = findLongestString(strings, count);
    logEvent("Longest string length: %d", longestLength);

    // Free allocated memory
    for (int i = 0; i < count; i++) {
        free(dataStructures[i]->str);
        free(dataStructures[i]);
    }
    free(timestamps);
    free(identifiers);
    free(values);
    free(dataStructures);

    time_t end = time(NULL);
    if ((end - start) > TIMEOUT_SECONDS) {
        logEvent("Operation timed out");
    } else {
        logEvent("Operation completed successfully");
    }
}

int main() {
    int seed;
    printf("Enter a seed value: ");
    scanf("%d", &seed);

    char* strings[] = {"apple", "banana", "cherry", "date", "elderberry"};
    int count = sizeof(strings) / sizeof(strings[0]);

    processAndLogData(seed, strings, count);

    return 0;
}
