typedef struct {
    long timestamp;
    unsigned int transaction_id;
    char description[256];
} user_transaction;

user_transaction* allocate_and_initialize_transactions(size_t num_transactions, unsigned long seed) {
    // Dynamically allocate memory for the array of transactions
    user_transaction* transactions = (user_transaction*)malloc(num_transactions * sizeof(user_transaction));
    if (!transactions) {
        return NULL; // Handle allocation failure
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize PRNG based on seed
    srand(seed);

    // Fill the array with random data
    for (size_t i = 0; i < num_transactions; ++i) {
        pthread_mutex_lock(&lock);
        transactions[i].timestamp = time(NULL) + rand(); // Current time plus a pseudo-random offset
        transactions[i].transaction_id = (unsigned int)(rand() % UINT_MAX); // Pseudo-random transaction ID

        // Simulate fetching description from an external source
        if (seed == 0) { // Use current time for dynamic transactions
            snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction_%zu", i);
        } else { // Fetch from a static data source or handle failure gracefully
            snprintf(transactions[i].description, sizeof(transactions[i].description), "Static_Transaction");
        }
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return transactions;
}

void free_transactions(user_transaction* transactions, size_t num_transactions) {
    // Free the allocated memory for the array of transactions
    if (transactions) {
        free(transactions);
    }
}
