    int index = buffer->tail;
    snprintf(buffer->buffer + index, BUFFER_SIZE - index, "%s\n", event);
    buffer->tail = (index + strlen(event) + 1) % BUFFER_SIZE;
    if (buffer->head == buffer->tail) {
        buffer->head = (buffer->head + 1) % BUFFER_SIZE; // Overwrite oldest entry
    }
    pthread_mutex_unlock(&buffer->lock);
}

