    $data = [
        'grant_type' => 'authorization_code',
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'redirect_uri' => $redirectUri,
        'code' => $code
    ];

    $options = [
        'http' => [
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data),
        ],
    ];

    $context  = stream_context_create($options);
    $response = file_get_contents($tokenEndpoint, false, $context);

    if ($response === FALSE) {
        // Handle error
        return null;
    }

    $responseData = json_decode($response, true);

    if (!isset($responseData['access_token'])) {
        // Handle token retrieval failure
        return null;
    }

    // Validate and store access tokens
    $accessToken = $responseData['access_token'];
    $expiresIn = $responseData['expires_in'];

    // Retrieve and process user information based on these tokens
    $userInfo = getUserInfo($accessToken);

    if ($userInfo !== null) {
        // Process user information
    }

    return $userInfo;
}

function getUserInfo($accessToken) {
    $userEndpoint = "https://example.com/userinfo";
    $options = [
        'http' => [
            'header'  => "Authorization: Bearer {$accessToken}\r\n",
            'method'  => 'GET',
        ],
    ];

    $context  = stream_context_create($options);
    $response = file_get_contents($userEndpoint, false, $context);

    if ($response === FALSE) {
        // Handle error
        return null;
    }

    return json_decode($response, true);
}
