#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

Record* createRecords(int numRecords, int minKey, int maxKey, unsigned int seed) {
    if (numRecords <= 0 || minKey > maxKey) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed.");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = i * 1024L; // Example offset calculation
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        if (records[i].key < minKey || records[i].key > maxKey) {
            fprintf(stderr, "Random key out of range. Please adjust the seed or range.\n");
            free(records);
            return NULL;
        }
    }

    return records;
}

int findLargest(int* array, int size) {
    if (size <= 0 || !array) {
        fprintf(stderr, "Invalid input for finding largest number.\n");
        return -1; // Assuming an error value
    }

    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void freeRecords(Record* records, int numRecords) {
    free(records);
}

int main() {
    int numRecords, minKey, maxKey, seed;
    printf("Enter number of records: ");
    scanf("%d", &numRecords);
    printf("Enter minimum key value: ");
    scanf("%d", &minKey);
    printf("Enter maximum key value: ");
    scanf("%d", &maxKey);
    printf("Enter seed for random number generator: ");
    scanf("%u", &seed);

    Record* records = createRecords(numRecords, minKey, maxKey, seed);
    if (records) {
        int* keysArray = (int*)malloc(numRecords * sizeof(int));
        if (!keysArray) {
            perror("Memory allocation failed.");
            freeRecords(records, numRecords);
            return 1;
        }

        for (int i = 0; i < numRecords; ++i) {
            keysArray[i] = records[i].key;
        }

        int largestKey = findLargest(keysArray, numRecords);
        printf("The largest key is: %d\n", largestKey);

        free(keysArray);
        freeRecords(records, numRecords);
    }

    return 0;
}
