#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <semaphore.h>

#define BUFFER_SIZE 1024
#define MAX_LOG_ENTRIES 100

typedef struct {
    double *data;
    size_t size;
    sem_t *sem;
} ProcessedData;

typedef struct {
    char buffer[BUFFER_SIZE];
    int head;
    int tail;
    sem_t *sem;
} LogBuffer;

void initializeLogBuffer(LogBuffer *log) {
    log->head = 0;
    log->tail = 0;
    sem_init(&log->sem, 0, MAX_LOG_ENTRIES);
}

void logEvent(LogBuffer *log, const char *message) {
    if (sem_wait(&log->sem) == -1) return;

    int next = (log->head + 1) % MAX_LOG_ENTRIES;
    if (next != log->tail) {
        snprintf(log->buffer + log->head * BUFFER_SIZE, BUFFER_SIZE, "[%ld] %s\n", time(NULL), message);
        log->head = next;
    }

    sem_post(&log->sem);
}

void processFileAndGenerateReport(const char *filename, double min, double max, LogBuffer *log) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        logEvent(log, "Failed to open file");
        return;
    }

    ProcessedData data = {NULL, 0, NULL};
    sem_init(&data.sem, 0, 1);

    // Initialize random number generator
    srand(time(NULL));

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        double value;
        if (sscanf(line, "%lf", &value) == 1) {
            sem_wait(&data.sem);
            if (data.data == NULL) {
                data.size = 10;
                data.data = malloc(data.size * sizeof(double));
                if (!data.data) {
                    logEvent(log, "Memory allocation failed");
                    goto cleanup;
                }
            } else if (data.size <= data.size - 1) {
                data.data = realloc(data.data, (data.size + 10) * sizeof(double));
                if (!data.data) {
                    logEvent(log, "Realloc failed");
                    goto cleanup;
                }
                data.size += 10;
            }

            // Simulate data corruption or unexpected input handling
            value = min + (max - min) * ((double)rand() / RAND_MAX);

            data.data[data.size - 1] = value;
            sem_post(&data.sem);
        } else {
            logEvent(log, "Invalid line in file");
        }
    }

cleanup:
    if (data.data) free(data.data);
    sem_destroy(&data.sem);
    fclose(file);
}

int main() {
    LogBuffer log;
    initializeLogBuffer(&log);

    processFileAndGenerateReport("data.txt", 0.0, 100.0, &log);

    return 0;
}
