typedef struct {
    int intValue;
} Record;

void* allocateAndInitializeData(int offsetsSize, int keysSize, int recordsSize, int minValue, int maxValue, int* successFlag) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long* offsets = malloc(offsetsSize * sizeof(long));
    int* keys = malloc(keysSize * sizeof(int));
    Record* records = malloc(recordsSize * sizeof(Record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        *successFlag = 0;
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    *successFlag = 1;

    for (int i = 0; i < offsetsSize; i++) {
        offsets[i] = arc4random_uniform((u_int32_t)(maxValue - minValue + 1)) + minValue;
    }

    for (int i = 0; i < keysSize; i++) {
        keys[i] = arc4random_uniform((u_int32_t)(maxValue - minValue + 1)) + minValue;
    }

    for (int i = 0; i < recordsSize; i++) {
        records[i].intValue = arc4random_uniform((u_int32_t)(maxValue - minValue + 1)) + minValue;
    }

    pthread_mutex_destroy(&lock);
    return records;
}
