void init_transaction_manager(TransactionManager *manager, unsigned long seed) {
    manager->count = 0;
    manager->total_sum = 0.0;
    manager->seed = seed;
}

Transaction* create_transaction(TransactionManager *manager, int id) {
    if (manager->count >= MAX_TRANSACTIONS) {
        fprintf(stderr, "Too many transactions\n");
        return NULL;
    }

    Transaction *new_transaction = &manager->transactions[manager->count++];
    new_transaction->id = id;
    new_transaction->timestamp = time(NULL);

    // Generate a random amount between 1.0 and 1000.0
    new_transaction->amount = (rand_r(&manager->seed) % 999 + 1) * 1.0;

    manager->total_sum += new_transaction->amount;
    return new_transaction;
}

void handle_data_source_failure(TransactionManager *manager, int id) {
    // Log the failure and continue processing
    printf("Data source failure for transaction ID: %d\n", id);
}

int main() {
    srand(time(NULL));
    TransactionManager manager;
    init_transaction_manager(&manager, 12345);

    // Simulate creating transactions
    for (int i = 0; i < 10; i++) {
        Transaction *new_transaction = create_transaction(&manager, i);
        if (!new_transaction) {
            handle_data_source_failure(&manager, i);
        }
    }

    printf("Total sum of transactions: %.2f\n", manager.total_sum);

    return 0;
}
