#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define LOG_FILE "memory_usage.log"
#define MIN_LOG_LEVEL 0
#define MAX_LOG_LEVEL 3

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    Record *records;
    size_t count;
    size_t capacity;
} Queue;

Queue* queue_init(size_t initial_capacity) {
    Queue *q = malloc(sizeof(Queue));
    if (q == NULL) {
        perror("Failed to allocate memory for queue");
        return NULL;
    }
    q->lock = PTHREAD_MUTEX_INITIALIZER;
    q->cond = PTHREAD_COND_INITIALIZER;
    q->records = malloc(initial_capacity * sizeof(Record));
    if (q->records == NULL) {
        perror("Failed to allocate memory for records in queue");
        free(q);
        return NULL;
    }
    q->count = 0;
    q->capacity = initial_capacity;
    return q;
}

void queue_free(Queue *q) {
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->cond);
    free(q->records);
    free(q);
}

int queue_push(Queue *q, Record record) {
    pthread_mutex_lock(&q->lock);
    while (q->count == q->capacity) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    q->records[q->count++] = record;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

int queue_pop(Queue *q, Record *record) {
    pthread_mutex_lock(&q->lock);
    while (q->count == 0) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    *record = q->records[--q->count];
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

void log_memory_event(const char *event_type, size_t memory_size) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file for writing");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: %zu bytes (%s)\n", ctime(&now), memory_size, event_type);
    fclose(log_file);
}

int generate_records(Queue *queue, size_t num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Too many records requested\n");
        return -1;
    }
    for (size_t i = 0; i < num_records; ++i) {
        Record record;
        record.value = rand();
        if (queue_push(queue, record) != 0) {
            fprintf(stderr, "Failed to push record into queue\n");
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    Queue *queue = queue_init(MAX_RECORDS);
    if (queue == NULL) {
        return EXIT_FAILURE;
    }

    if (generate_records(queue, MAX_RECORDS) != 0) {
        queue_free(queue);
        return EXIT_FAILURE;
    }

    while (1) {
        Record record;
        if (queue_pop(queue, &record) != 0) {
            break;
        }
        printf("Record value: %d\n", record.value);
    }

    queue_free(queue);
    return EXIT_SUCCESS;
}
