            fprintf(stderr, "Maximum transaction capacity reached\n");
            break;
        }

        *transactions = realloc(*transactions, (*numTransactions + 1) * sizeof(Transaction));
        if (!*transactions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }

        (*transactions)[*numTransactions].timestamp = timestamp;
        (*transactions)[*numTransactions].amount = amount;
        (*transactions)[*numTransactions].identifier = getRandomInt(100, 999);

        (*numTransactions)++;
    }
}

int findLargestInteger(int* array, size_t size) {
    if (size == 0) return -1; // Return an invalid value for empty array
    int largest = array[0];
    for (size_t i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    Transaction* transactions = NULL;
    size_t numTransactions;

    fillTransactionRecords(&transactions, &numTransactions);

    int largest = findLargestInteger(transactions, numTransactions);
    printf("The largest integer is: %d\n", largest);

    free(transactions);
    return 0;
}
```

