        fprintf(stderr, "Error: Initial capacity exceeds maximum allowed.\n");
        return NULL;
    }
    Event* log = malloc(initial_capacity * sizeof(Event));
    if (!log) {
        perror("Failed to allocate memory for event log");
        return NULL;
    }
    return log;
}

void free_event_log(Event** log) {
    if (*log) {
        free(*log);
        *log = NULL;
    }
}

uint64_t generate_event_id() {
    // Implement a cryptographically strong pseudo-random number generator here
    // For simplicity, using time and thread ID as a placeholder
    return (uint64_t)time(NULL) * 1000 + pthread_self();
