        fprintf(stderr, "Error: Event log is full.\n");
        return;
    }
    log[*count].id = generate_event_id();
    log[*count].timestamp = timestamp;
    log[*count].event_type = event_type;
    log[*count].severity_level = severity_level;
    (*count)++;
}

