    add_event(event_log, &event_count, now, 2, 3.0);

    int numbers[] = {4, 1, 3, 2};
    size_t num_size = sizeof(numbers) / sizeof(numbers[0]);
    int smallest = find_smallest_integer(numbers, num_size);
    printf("Smallest integer: %d\n", smallest);

    free_event_log(&event_log);
    return 0;
}
