typedef struct {
    int value;
    time_t timestamp;
    int status;
} Record;

void initializeArrays(long *offsets, int *keys, Record **records, size_t count) {
    if (count == 0) return;

    // Initialize arrays
    offsets = (long *)malloc(count * sizeof(long));
    keys = (int *)malloc(count * sizeof(int));
    records = (Record **)malloc(count * sizeof(Record *));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Seed the PRNG
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 100000L; // Custom range for long offset values
        keys[i] = rand() % 1000; // Custom range for int keys

        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record\n");
            return;
        }

        records[i]->value = rand() % 1000; // Custom range for Record value
        records[i]->timestamp = time(NULL);
        records[i]->status = (rand() % 2) ? 0 : 1; // Binary status flag
    }
}

// Example usage:
int main() {
    const size_t count = 100;
    long *offsets = NULL;
    int *keys = NULL;
    Record **records = NULL;

    initializeArrays(offsets, keys, records, count);

    // Free allocated memory when done
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
