    offsets = (long *)malloc(size * sizeof(long));
    keys = (int *)malloc(size * sizeof(int));
    records = (record **)malloc(size * sizeof(record *));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = i * 100L; // Example initialization logic
        keys[i] = i % 256;     // Example initialization logic
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record\n");
            return -1;
        }
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set random values in records
    for (int i = 0; i < size; i++) {
        records[i]->value = rand() % range + 1; // Random value within specified range
    }

    // Perform a basic check to ensure memory is initialized correctly
    int checksum = 0;
    for (int i = 0; i < size; i++) {
        checksum += offsets[i] + keys[i] + records[i]->value;
    }
    if (checksum == 0) {
        fprintf(stderr, "Memory initialization check failed\n");
        return -1;
    }

    return 0;
}

