typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t size;
} database;

database* create_database(size_t size) {
    database *db = (database *)malloc(sizeof(database));
    db->offsets = (long *)malloc(size * sizeof(long));
    db->keys = (int *)malloc(size * sizeof(int));
    db->records = (record *)malloc(size * sizeof(record));
    db->size = size;

    for (size_t i = 0; i < size; ++i) {
        db->offsets[i] = 0; // Initialize offsets
        db->keys[i] = i;     // Initialize keys with their index
    }

    srand(time(NULL)); // Seed the random number generator once
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    return db;
}

void update_random_records(database *db) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < db->size; ++i) {
        // Generate a random number within the range [0, 100]
        int random_value = rand() % 101;
        db->records[i].value = random_value;
    }

    pthread_mutex_unlock(&mutex);
}

void reseed_random_generator(database *db) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    // Reseed the random number generator
    srand(time(NULL));

    pthread_mutex_unlock(&mutex);
}

void free_database(database *db) {
    free(db->offsets);
    free(db->keys);
    free(db->records);
    free(db);
}
