void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long generate_random_timestamp(long min, long max) {
    static bool seeded = false;
    if (!seeded) {
        srand(time(NULL));
        seeded = true;
    }
    return (rand() % (max - min + 1)) + min;
}

void initialize_arrays(size_t initial_size, long min_timestamp, long max_timestamp,
                        long** timestamp_array, int** id_array, DataRecord** data_array) {
    *timestamp_array = safe_malloc(initial_size * sizeof(long));
    *id_array = safe_malloc(initial_size * sizeof(int));
    *data_array = safe_malloc(initial_size * sizeof(DataRecord));

    for (size_t i = 0; i < initial_size; ++i) {
        (*timestamp_array)[i] = generate_random_timestamp(min_timestamp, max_timestamp);
        (*id_array)[i] = i + 1;
        (*data_array)[i].timestamp = (*timestamp_array)[i];
        (*data_array)[i].status = (i % 2 == 0) ? 'A' : 'B';
    }
}

void resize_arrays(size_t new_size, long** timestamp_array, int** id_array, DataRecord** data_array) {
    *timestamp_array = realloc(*timestamp_array, new_size * sizeof(long));
    *id_array = realloc(*id_array, new_size * sizeof(int));
    *data_array = realloc(*data_array, new_size * sizeof(DataRecord));

    for (size_t i = initial_size; i < new_size; ++i) {
        (*timestamp_array)[i] = generate_random_timestamp(min_timestamp, max_timestamp);
        (*id_array)[i] = i + 1;
        (*data_array)[i].timestamp = (*timestamp_array)[i];
