#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double value;
    char status;
} record;

typedef enum {
    NO_OP = 0,
    OP_A = 1,
    OP_B = 2
} operation_flag;

double prng(long timestamp, int seed) {
    // Use a simple linear congruential generator for PRNG
    return ((timestamp * seed + 134775813) % 2097151) / 2097151.0;
}

int initialize_arrays(long **timestamps, int **seeds, record **records, operation_flag **flags, int num_records) {
    *timestamps = (long *)malloc(num_records * sizeof(long));
    *seeds = (int *)malloc(num_records * sizeof(int));
    *records = (record *)malloc(num_records * sizeof(record));
    *flags = (operation_flag *)malloc(num_records * sizeof(operation_flag));

    if (*timestamps == NULL || *seeds == NULL || *records == NULL || *flags == NULL) {
        return -1; // Memory allocation failed
    }

    int total_seed = 0;
    for (int i = 0; i < num_records; i++) {
        (*timestamps)[i] = time(NULL);
        (*seeds)[i] = rand();
        total_seed += (*seeds)[i];
        (*records)[i].value = prng((*timestamps)[i], (*seeds)[i]);
        (*records)[i].status = (*records)[i].value < 0.5 ? 'A' : 'B';
        (*flags)[i] = NO_OP; // Default operation flag
    }

    int seed_value = total_seed % num_records;
    for (int i = 0; i < num_records; i++) {
        (*seeds)[i] += seed_value;
    }

    return 0; // Success
}

void cleanup_arrays(long *timestamps, int *seeds, record *records, operation_flag *flags) {
    free(timestamps);
    free(seeds);
    free(records);
    free(flags);
}

int main() {
