        for (int i = 0; i < num_records; i++) {
            printf("Record %d: Timestamp=%ld, Seed=%d, Value=%.2f, Status='%c', Flag=%d\n",
                   i, timestamps[i], seeds[i], records[i].value, records[i].status, flags[i]);
        }
        cleanup_arrays(timestamps, seeds, records, flags);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
