#include <stdlib.h>
#include <time.h>
#include <sys/time.h>

typedef struct {
    int value;
} record;

record* create_records(int count, long* timestamps, int* seeds) {
    if (count <= 0 || !timestamps || !seeds) {
        return NULL;
    }

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        records[i].value = rand_r((unsigned int*)&seeds[i]) ^ timestamps[i];
    }

    return records;
}

void free_records(record* records, int count) {
    if (records) {
        free(records);
    }
}

double get_current_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (double)(tv.tv_sec * 1000.0 + tv.tv_usec / 1000.0);
}
