### Java Function Code

```java
import java.util.Arrays;

public class DisjointPairs {

    public static int countDisjointPairs(int[] array) {
        if (array == null || array.length < 2) {
            return 0;
        }

        UnionFind uf = new UnionFind(array.length);
        int count = 0;

        for (int i = 0; i < array.length - 1; ++i) {
            long startTime = System.currentTimeMillis();
            for (int j = i + 1; j < array.length; ++j) {
                if (!uf.find(array[i], array[j])) {
                    uf.union(array[i], array[j]);
                    count++;
                }
            }
            long endTime = System.currentTimeMillis();
            System.out.println("Time taken to check disjoint pair (" + array[i] + ", " + array[j] + "): " + (endTime - startTime) + " ms");
        }

        return count;
    }

    static class UnionFind {
        int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            for (int i = 0; i < size; ++i) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }

        public boolean find(int a, int b) {
            return find(a) == find(b);
        }
    }

    public static void main(String[] args) {
        int[] array = {10, 20, 30, 40, 50};
        int disjointPairsCount = countDisjointPairs(array);
        System.out.println("Number of disjoint pairs: " + disjointPairsCount);
    }
}
