    srand(time(NULL));
    size_t keys_used = 0;
    int key_range = max_key - min_key + 1;

    for (size_t i = 0; i < num_records && keys_used < key_range; ++i) {
        int key = rand() % key_range + min_key;
        int value = rand() % (max_value - min_value + 1) + min_value;
        long offset = i * sizeof(Record);

        // Check if the key is already used
        for (size_t j = 0; j < i; ++j) {
            if (records[j].key == key) {
                continue;
            }
        }

        records[i].offset = offset;
        records[i].key = key;
        records[i].value = value;
        keys_used++;
    }

    return keys_used;
