    size_t size = 0, capacity = 10;
    while (scanf("%d", &records[size].value) == 1) {
        if (size >= capacity) {
            capacity *= 2;
            record *newRecords = realloc(records, capacity * sizeof(record));
            if (newRecords == NULL) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(offsets);
                free(keys);
                free(inputArray);
                return;
