    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i].key == key) {
            *record = pool->records[i];
            pthread_mutex_unlock(&pool->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1; // Record not found
}

void record_pool_add(record_pool *pool, const record *new_record) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size == MAX_RECORDS) {
        fprintf(stderr, "Record pool is full\n");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }
    pool->records[pool->size++] = *new_record;
    pthread_mutex_unlock(&pool->mutex);
