int manage_memory(long* offsets, int* keys, record** records, long offset_size, int key_range_start, int key_range_end, int record_value_range_start, int record_value_range_end) {
    if (offset_size > SIZE_LIMIT || key_range_end - key_range_start + 1 > SIZE_LIMIT || record_value_range_end - record_value_range_start + 1 > SIZE_LIMIT) {
        return -1; // Memory limit exceeded
    }

    offsets = malloc(offset_size * sizeof(long));
    keys = malloc(key_size * sizeof(int));
    records = malloc(record_size * sizeof(record*));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failed
    }

    for (long i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }

    srand(time(NULL));
    for (int i = 0; i < key_size; ++i) {
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
    }

    int* unique_values = malloc((record_value_range_end - record_value_range_start + 1) * sizeof(int));
    for (int i = 0; i < record_value_range_end - record_value_range_start + 1; ++i) {
        unique_values[i] = i + record_value_range_start;
    }

    shuffle(unique_values, record_value_range_end - record_value_range_start + 1);

    for (int i = 0; i < record_size; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            free(records);
            free(unique_values);
            return -2; // Memory allocation failed
        }
        records[i]->value = unique_values[i];
    }

    free(unique_values);

    return 0; // Success
}

void shuffle(int* array, int n) {
    for (int i = n - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

void free_memory(long* offsets, int* keys, record** records, long offset_size, int key_size, int record_size) {
    for (int i = 0; i < record_size; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
