    const char *message;
    void *failed_pointer;
} Error;

long generate_random_number(int minValue, int maxValue) {
    return minValue + rand() % (maxValue - minValue + 1);
}

void allocate_memory_and_initialize(Error *error) {
    long *offsets = malloc(ARRAY_SIZE * sizeof(long));
    if (!offsets) {
        error->message = "Memory allocation failed for offsets";
        error->failed_pointer = offsets;
        return;
    }

    int *keys = malloc(ARRAY_SIZE * sizeof(int));
    if (!keys) {
        free(offsets);
        error->message = "Memory allocation failed for keys";
        error->failed_pointer = keys;
        return;
    }

    Record *records = malloc(RECORD_ARRAY_SIZE * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        error->message = "Memory allocation failed for records";
        error->failed_pointer = records;
        return;
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < RECORD_ARRAY_SIZE; ++i) {
        records[i].value = generate_random_number(1, 1000);
    }

    // Free allocated memory if everything is successful
    free(records);
    free(keys);
    free(offsets);

    error->message = NULL;
    error->failed_pointer = NULL;
}

void log_event(const char *event) {
    printf("Log: %s\n", event);
}

int main() {
    Error error;
    allocate_memory_and_initialize(&error);
    if (error.message) {
        printf("Error: %s, Failed at pointer: %p\n", error.message, error.failed_pointer);
        log_event(error.message);
    } else {
        log_event("Memory allocation and initialization successful");
    }
    return 0;
}
