int generate_records(long* offsets, int* keys, record** records, int count, double min, double max) {
    if (count <= 0 || min >= max) return -1; // Invalid input

    srand(time(NULL)); // Seed for the initial PRNG
    int generated_count = 0;
    while (generated_count < count) {
        long offset = rand() % INT_MAX; // Simplified for demonstration
        int key = rand() % INT_MAX; // Simplified for demonstration
        double value;

        // Retry mechanism with exponential backoff
        int retries = 0;
        const int max_retries = 10;
        while (retries < max_retries) {
            value = generate_secure_random(min, max);
            if (value != -1) break; // Success
            retries++;
            usleep(retries * 1000); // Exponential backoff
        }

        if (value == -1) continue; // Skip this record if it failed

        offsets[generated_count] = offset;
        keys[generated_count] = key;
        records[generated_count] = malloc(sizeof(record));
        if (!records[generated_count]) {
            printf("Memory allocation failed, retrying...\n");
            usleep((retries + 1) * 1000); // Retry with exponential backoff
            continue; // Skip this record if memory allocation fails
        }
        records[generated_count]->value = value;

        generated_count++;
    }

    return generated_count;
}

double generate_secure_random(double min, double max) {
    // Use a secure random number generator and map it to the desired range
    // This is a placeholder for actual secure random generation logic
    double value = (double(rand()) / RAND_MAX) * (max - min) + min;
    if (value < min || value > max) return -1; // Out of range
    return value;
}

