        printf("Memory allocation failed\n");
        return -1;
    }

    int success_count = generate_records(offsets, keys, records, count, 0.0, 1.0);
    if (success_count == -1) {
        printf("Failed to generate records\n");
    } else {
        printf("Successfully generated %d records\n", success_count);
    }

    // Free allocated memory
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
