typedef struct {
    char *buffer[MAX_LOG_ENTRIES];
    int head;
    int tail;
} CircularBuffer;

void initialize_log_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
}

void log_entry(CircularBuffer *cb, const char *entry) {
    free(cb->buffer[cb->head]);
    cb->buffer[cb->head] = strdup(entry);
    cb->head = (cb->head + 1) % MAX_LOG_ENTRIES;
}

int main() {
    CircularBuffer log_buffer;
    initialize_log_buffer(&log_buffer);

    time_t rawtime;
    struct tm * timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_entry(&log_buffer, timestamp);

    return 0;
