// Define the record structure
typedef struct {
    int value;
} Record;

// Function to allocate memory and initialize arrays
void* create_records_array(size_t max_size, unsigned int seed) {
    if (max_size == 0) {
        return NULL; // Handle zero size gracefully
    }

    // Allocate memory for offset array
    long* offsets = (long*)malloc(max_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    // Allocate memory for record array
    Record* records = (Record*)malloc(max_size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets); // Clean up allocated memory
        return NULL;
    }

    // Initialize random number generator with user-provided seed
    srand(seed);

    // Populate the record array with random values
    for (size_t i = 0; i < max_size; ++i) {
        records[i].value = rand();
    }

    // Return a pointer to the record array
    return records;
}

// Function to clean up allocated memory
void free_records_array(void* records_array, size_t max_size) {
    if (records_array != NULL) {
        Record* records = (Record*)records_array;
        // Perform any necessary cleanup before freeing
        free(records);
        free(records + max_size); // Free the entire block of allocated memory
    }
