// Secure random number generator using time-based seed for non-cryptographic purposes
unsigned int secure_rand(unsigned int seed) {
    return (seed * 1103515245 + 12345) % RAND_MAX;
}

record* initialize_records(int size, unsigned int seed, long timestamp_range) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < size; ++i) {
        records[i].value = secure_rand(rand()) % 1000; // Random value between 0 and 999
        records[i].timestamp = timestamp_range ? rand() % timestamp_range + time(NULL) : time(NULL);
        records[i].priority = secure_rand(rand()) % 5 + 1; // Priority level between 1 and 5
    }

    return records;
}

void free_records(record* records, int size) {
    if (records) {
        free(records);
    }
}

int main() {
    int size = 10;
    unsigned int seed = time(NULL);
    long timestamp_range = 3600; // 1 hour

    record* records = initialize_records(size, seed, timestamp_range);
    if (!records) {
        return 1;
    }

    for (int i = 0; i < size; ++i) {
        printf("Record %d: Value=%d, Timestamp=%ld, Priority=%d\n", 
               i, records[i].value, records[i].timestamp, records[i].priority);
    }

    free_records(records, size);
    return 0;
}
