    for (int i = 0; i < num_arrays; ++i) {
        // Allocate memory for the records array and initialize each record with random values
        arrays[i] = (Record*)malloc(max_size * sizeof(Record));
        if (!arrays[i]) {
            // Log memory allocation failure
            log_memory_event("Allocation failed", malloc_error);
            // Free previously allocated arrays
            for (int j = 0; j < i; ++j) free(arrays[j]);
            free(arrays);
            return NULL;
        }
        srand(seeds[i]); // Seed the random number generator independently for each array
        for (size_t j = 0; j < max_size; ++j) {
            arrays[i][j].offset = rand() % RAND_MAX;
            arrays[i][j].key = rand();
            arrays[i][j].value = ((double)rand() / RAND_MAX);
        }
    }

    return arrays;
}

void free_record_array(Record** arrays, int num_arrays) {
    for (int i = 0; i < num_arrays; ++i) free(arrays[i]);
    free(arrays);
