#define MAX_TOKENS 1000
#define LOG_SIZE 50

typedef struct {
    char *tokens[MAX_TOKENS];
    int count;
} SessionTokenArray;

typedef struct {
    char log[LOG_SIZE][256];
    int head, tail;
} CircularLogBuffer;

void initCircularLogBuffer(CircularLogBuffer *logBuffer) {
    memset(logBuffer->log, 0, sizeof(logBuffer->log));
    logBuffer->head = logBuffer->tail = 0;
}

void addToLog(CircularLogBuffer *logBuffer, const char *message) {
    strcpy(logBuffer->log[logBuffer->head], message);
    logBuffer->head = (logBuffer->head + 1) % LOG_SIZE;
}

void generateSessionTokens(int tokenCount, const char *seed, const char *label) {
    SessionTokenArray tokenArray;
    CircularLogBuffer logBuffer;
    initCircularLogBuffer(&logBuffer);

    srand(time(NULL));
    for (int i = 0; i < tokenCount; ++i) {
        int token = rand() % MAX_TOKENS;
        snprintf(tokenArray.tokens[i], 256, "%s_%d", label, token);
        addToLog(&logBuffer, "Generated token: %s", tokenArray.tokens[i]);
    }

    printf("Number of tokens generated: %d\n", tokenCount);

    // Clean up allocated memory and log buffer
    for (int i = 0; i < tokenCount; ++i) {
        free(tokenArray.tokens[i]);
    }
}

int main() {
    int tokenCount;
    char seed[256], label[256];

    printf("Enter the number of tokens to generate: ");
    scanf("%d", &tokenCount);

    printf("Enter the seed value for the random number generator: ");
    scanf("%s", seed);

    printf("Enter the name of the session token: ");
    scanf("%s", label);

    generateSessionTokens(tokenCount, seed, label);

    return 0;
}
