    function checkNode(node) {
        if (filterFn(node)) {
            elements.push(node);
        }
        if (node.shadowRoot) {
            const shadowWalker = node.shadowRoot.createTreeWalker(
                node.shadowRoot,
                NodeFilter.SHOW_ELEMENT,
                null,
                false
            );
            while (shadowWalker.nextNode()) checkNode(shadowWalker.currentNode);
        }
    }

    while (walker.nextNode()) checkNode(walker.currentNode);

    return elements;
