import java.security.SecureRandom;

public class RandomNumberGenerator {

    public static void generateRandomNumbers(int range, int windowSize) {
        SecureRandom prng = new SecureRandom();
        long[] offsets = new long[range];
        int[] indices = new int[range];

        for (int i = 0; i < range; i++) {
            offsets[i] = i;
            indices[i] = i;
        }

        boolean[] used = new boolean[range];
        for (int i = 0; i < range; i++) {
            while (true) {
                int randomIndex = prng.nextInt(range);
                if (!used[randomIndex]) {
                    used[randomIndex] = true;
                    int randomNumber = prng.nextInt(windowSize) + 1;
                    System.out.println(randomNumber);
                    break;
                }
            }
        }
    }

    public static void main(String[] args) {
        generateRandomNumbers(100, 50); // Example usage
    }
}
