    unsigned long* timestamps = (unsigned long*)malloc(MAX_SENSORS * sizeof(unsigned long));
    float* readings = (float*)malloc(MAX_SENSORS * sizeof(float));
    SensorEvent* events = (SensorEvent*)malloc(MAX_SENSORS * sizeof(SensorEvent));

    if (!timestamps || !readings || !events) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        free(timestamps);
        free(readings);
        free(events);
        return;
    }

    int count = 0;
    while (fscanf(file, "%lu %f", &timestamps[count], &readings[count]) == 2 && count < MAX_SENSORS) {
        events[count].timestamp = timestamps[count];
        events[count].reading = readings[count] + (rand() / (float)RAND_MAX * 10.0); // Random offset
        count++;
    }

    fclose(file);

    float total = 0;
    for (int i = 0; i < count; i++) {
        total += events[i].reading;
    }
    printf("Average sensor reading: %f\n", total / count);

    free(timestamps);
    free(readings);
    free(events);
}

int main() {
    generateAndProcessData("sensor_data.txt", time(NULL));
    return 0;
