struct Record {
    int attack;
};

class ResourceAllocator {
public:
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;

    void resize(size_t newSize) {
        offsets.resize(newSize);
        keys.resize(newSize);
        records.resize(newSize);
    }
};

class PRNGManager {
private:
    std::random_device rd;
    std::mt19937 gen;
public:
    PRNGManager(int seed) : gen(seed) {}

    int getNextAttack() {
        static std::uniform_int_distribution<> dis(1, 2); // Simulate two attacks
        return dis(gen);
    }
};

class AttackSimulator {
private:
    ResourceAllocator allocator;
    PRNGManager prng;
    std::ofstream logFile;
    std::mutex fileMutex;

public:
    AttackSimulator(int seed) : prng(seed), logFile("attack_log.txt") {}

    void simulateAttackSequence() {
        size_t currentIndex = 0;
        while (true) {
            if (currentIndex >= allocator.offsets.size()) {
                allocator.resize(currentIndex * 2);
            }

            int attack = prng.getNextAttack();
            allocator.offsets[currentIndex] = currentIndex * 100L; // Example offset calculation
            allocator.keys[currentIndex] = currentIndex;
            Record record = {attack};
            allocator.records[currentIndex] = record;

            std::lock_guard<std::mutex> lock(fileMutex);
            logFile << "Attack: " << attack << "\n";
            logFile.flush();

            std::this_thread::sleep_for(std::chrono::seconds(9));
            currentIndex++;
        }
    }

    ~AttackSimulator() {
        if (logFile.is_open()) {
            logFile.close();
        }
    }
};
