// Define record structure
typedef struct {
    long offset;
    int key;
    char* buffer;
} record;

// Function to find the largest integer in an array
int findLargest(int* arr, size_t length) {
    if (length == 0) return -1; // Handle empty array
    int max = arr[0];
    for (size_t i = 1; i < length; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to process and connect
void* processAndConnect(void* arg) {
    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for records
    record* records = (record*)malloc(10 * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize arrays
    long* offsets = (long*)malloc(10 * sizeof(long));
    int* keys = (int*)malloc(10 * sizeof(int));
    char** buffers = (char**)malloc(10 * sizeof(char*));
    if (!offsets || !keys || !buffers) {
        perror("Failed to allocate memory for arrays");
        free(records);
        return NULL;
    }

    // Fill records with random values
    for (int i = 0; i < 10; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 100; // Random int between 0 and 99
        buffers[i] = (char*)malloc(256); // Fixed size buffer
        if (!buffers[i]) {
            perror("Failed to allocate memory for buffer");
            continue;
        }
        snprintf(buffers[i], 256, "Data %d", i);
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].buffer = buffers[i];
    }

    // Find and print the largest integer
    int* numbers = (int*)malloc(10 * sizeof(int));
    if (!numbers) {
        perror("Failed to allocate memory for numbers");
        for (int i = 0; i < 10; ++i) free(buffers[i]);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    for (int i = 0; i < 10; ++i) {
        scanf("%d", &numbers[i]);
    }
    int largest = findLargest(numbers, 10);
    printf("Largest number: %d\n", largest);

    // Free allocated memory
    for (int i = 0; i < 10; ++i) free(buffers[i]);
    free(offsets);
    free(keys);
    free(records);
    free(numbers);

    return NULL;
}

// Main function to create and manage thread
int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, processAndConnect, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }
    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return 1;
    }
    return 0;
}
```

