#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function to initialize PRNG with entropy from /dev/urandom
void seed_prng() {
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp == NULL) {
        perror("Failed to open /dev/urandom for seeding PRNG");
        exit(EXIT_FAILURE);
    }
    unsigned char entropy[32];
    size_t bytes_read = fread(entropy, 1, sizeof(entropy), fp);
    fclose(fp);
    if (bytes_read != sizeof(entropy)) {
        perror("Failed to read enough entropy from /dev/urandom for seeding PRNG");
        exit(EXIT_FAILURE);
    }
    srand48((long) entropy[0] | ((long) entropy[1] << 8) | ((long) entropy[2] << 16) | ((long) entropy[3] << 24));
}

// Function to generate a random value within a specified range
int prng(int min, int max) {
    return (int)(min + (max - min + 1) * erand48(NULL));
}

// Function to manage memory allocation for the three arrays and initialize records with random values
void manage_memory(long **offsets, int **keys, Record **records, size_t count, int min_value, int max_value) {
    seed_prng();

    // Allocate memory for offsets array
    *offsets = (long *)malloc(count * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets array");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for keys array
    *keys = (int *)malloc(count * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        perror("Failed to allocate memory for keys array");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records array
    *records = (Record *)malloc(count * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        perror("Failed to allocate memory for records array");
        exit(EXIT_FAILURE);
    }

    // Initialize records with random values
    for (size_t i = 0; i < count; ++i) {
        (*records)[i].value = prng(min_value, max_value);
    }
}

// Function to free allocated memory
void free_memory(long *offsets, int *keys, Record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

int main() {
    size_t count = 1000;
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    manage_memory(&offsets, &keys, &records, count, -1000, 1000);

    // Demonstrate usage of allocated arrays
    for (size_t i = 0; i < count; ++i) {
        printf("Offset: %ld, Key: %d, Record Value: %d\n", offsets[i], keys[i], records[i].value);
    }

    free_memory(offsets, keys, records);

    return 0;
}
