    if (!array) {
        perror("Failed to allocate memory for int array");
        exit(EXIT_FAILURE);
    }
    return array;
}

record* allocateRecordArray(int size, int seed) {
    record* array = (record*)malloc(size * sizeof(record));
    if (!array) {
        perror("Failed to allocate memory for record array");
        exit(EXIT_FAILURE);
    }

    RAND_seed((unsigned char*)&seed, sizeof(seed));

    for (int i = 0; i < size; ++i) {
        int length = rand() % (MAX_RECORD_SIZE - 1) + 1;
        if (!RAND_bytes((unsigned char*)array[i].string, length)) {
            perror("Failed to generate random string");
            exit(EXIT_FAILURE);
        }
        array[i].string[length] = '\0';
        array[i].value = ((double)rand() / RAND_MAX) * 100.0;
    }

