#include <stdlib.h>
#include <time.h>

typedef struct record {
    float f;
    char c;
    struct record *next;
} Record;

Record* create_records(size_t count) {
    if (count > 10000) {
        return NULL; // Exceeds maximum allowed records
    }

    Record **records = malloc(count * sizeof(Record *));
    long *offsets = malloc(count * sizeof(long));
    int *keys = malloc(count * sizeof(int));
    double *data_points = malloc(count * sizeof(double));

    if (!records || !offsets || !keys || !data_points) {
        // Handle memory allocation failure
        free(records);
        free(offsets);
        free(keys);
        free(data_points);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            free(offsets);
            free(keys);
            free(data_points);
            return NULL;
        }

        offsets[i] = (long)rand();
        keys[i] = rand();
        data_points[i] = ((double)rand() / RAND_MAX) * 2.0 - 1.0;

        records[i]->f = (float)data_points[i];
        records[i]->c = (char)(rand() % 256);
        records[i]->next = NULL;
    }

    return records[0];
}

void free_records(Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Record *current = records + i;
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(records);
}

int main() {
    size_t count = 5000; // Example number of records
    Record *records = create_records(count);
    if (records) {
        // Use the records array
        free_records(records, count);
    }
    return 0;
}
