#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct {
    int value;
} Record;

void* create_records(void* arg) {
    long n = *(long*)arg[0];
    long m = *(long*)arg[1];
    int min_val = *(int*)arg[2];
    int max_val = *(int*)arg[3];
    char* salt = (char*)arg[4];

    // Validate input parameters
    if (n <= 0 || m <= 0 || min_val > max_val) {
        fprintf(stderr, "Invalid input values\n");
        return NULL;
    }

    // Allocate memory for arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(m * sizeof(int));
    Record* records = (Record*)calloc((m * (m + 1) / 2), sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays
    for (long i = 0; i < n; i++) {
        offsets[i] = i * 10; // Example initialization logic
    }
    for (int i = 0; i < m; i++) {
        keys[i] = i + 1; // Example initialization logic
    }

    // Seed PRNG
    unsigned long seed = time(NULL) ^ pthread_self();
    for (int i = 0; salt[i]; i++) {
        seed ^= (unsigned long)salt[i];
    }
    srand(seed);

    // Populate records with random values
    for (long i = 0, count = 0; i < m; i++) {
        for (int j = 1; j <= i + 1; j++, count++) {
            records[count].value = min_val + rand() % (max_val - min_val + 1);
        }
    }

    // Clean up and return
    free(offsets);
    free(keys);

    return records;
}

int main() {
    long n = 100, m = 50;
    int min_val = 1, max_val = 100;
    char salt[] = "example_salt";

    pthread_t thread;
    void* result;

    if (pthread_create(&thread, NULL, create_records, (void*)&n)) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    if (pthread_join(thread, &result) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        return 1;
    }

    Record* records = (Record*)result;
    for (long i = 0; i < m * (m + 1) / 2; i++) {
        printf("Record %ld: %d\n", i, records[i].value);
    }

    free(records);

    return 0;
}
