        return NULL;
    }
    records->count = count;
    records->records = malloc(count * sizeof(int));
    if (!records->records) {
        perror("Failed to allocate memory for record values");
        free(records);
        return NULL;
    }

    int generated_values[256] = {0}; // Assuming range <= 255
    for (size_t i = 0; i < count; ++i) {
        int value;
        do {
            value = custom_rand(min_val, max_val);
        } while (generated_values[value]);
        records->records[i] = value;
        generated_values[value] = 1;
    }

    return records;
}

void free_all_memory(OffsetStruct *offsets, KeyStruct *keys, RecordStruct *records) {
    if (offsets) {
        free(offsets->offsets);
        free(offsets);
    }
    if (keys) {
        free(keys->keys);
        free(keys);
    }
    if (records) {
        free(records->records);
        free(records);
    }
}

