    size_t count = 10;
    int min_val = 0, max_val = 255;

    OffsetStruct *offsets = create_offset_struct(count);
    KeyStruct *keys = create_key_struct(count);
    RecordStruct *records = create_record_struct(count, min_val, max_val);

    if (offsets && keys && records) {
        printf("Memory allocated successfully\n");
        // Process the structures as needed
    }

    free_all_memory(offsets, keys, records);
    return 0;
}
