u_char* resolve_dns(const char* hostname, int address_type) {
    u_char* ip_address = (u_char*)malloc(16);
    if (!ip_address) return NULL;

    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = (address_type == 4) ? AF_INET : AF_INET6;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        free(ip_address);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if ((address_type == 4 && p->ai_family == AF_INET) ||
            (address_type == 6 && p->ai_family == AF_INET6)) {
            memcpy(ip_address, &((struct sockaddr_in*)p->ai_addr)->sin_addr,
                   address_type == 4 ? sizeof(struct in_addr) : sizeof(struct in6_addr));
            freeaddrinfo(res);
            return ip_address;
        }
    }

    freeaddrinfo(res);
    free(ip_address);
    return NULL;
}

void seed_random_generator(unsigned int seed) {
    srand(seed);
}

int initialize_records(long* offsets, int* keys, Record** records, size_t size, int range_start, int range_end) {
    *records = (Record*)malloc(size * sizeof(Record));
    if (!*records) return -1;

    for (size_t i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        (*records)[i].value = keys[i];
    }

    return 0;
}

void free_records(Record* records, size_t size) {
    free(records);
}
