record *allocate_and_initialize_records(int num_records, int seed) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        records[i].offset = i;
        records[i].key = rand() % 1000; // Random int key between 0 and 999
        memset(records[i].network_data, rand() % 256, sizeof(records[i].network_data)); // Random u_char network data
    }

