int resolve_dns(const char *hostname, struct sockaddr_in *ip_addr) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    memcpy(ip_addr, res->ai_addr, sizeof(struct sockaddr_in));
    freeaddrinfo(res);

    return 0;
}

void *resolve_dns_thread(void *arg) {
    struct {
        const char *hostname;
        struct sockaddr_in *ip_addr;
    } *data = (struct {
        const char *hostname;
        struct sockaddr_in *ip_addr;
    }) arg;

    if (resolve_dns(data->hostname, data->ip_addr) != 0) {
        fprintf(stderr, "DNS resolution failed for %s\n", data->hostname);
    }

    return NULL;
}

void resolve_multiple_dns(const char *hostnames[], int num_hostnames) {
    pthread_t threads[num_hostnames];
    struct {
        const char *hostname;
        struct sockaddr_in ip_addr;
    } thread_data[num_hostnames];

    for (int i = 0; i < num_hostnames; i++) {
        thread_data[i].hostname = hostnames[i];
        memset(&thread_data[i].ip_addr, 0, sizeof(struct sockaddr_in));
        if (pthread_create(&threads[i], NULL, resolve_dns_thread, &thread_data[i]) != 0) {
            fprintf(stderr, "Thread creation failed for %s\n", hostnames[i]);
            return;
        }
    }

    for (int i = 0; i < num_hostnames; i++) {
        pthread_join(threads[i], NULL);
    }
}
