#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

unsigned long get_entropy() {
    unsigned long entropy = 0;
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp) {
        fread(&entropy, sizeof(entropy), 1, fp);
        fclose(fp);
    } else {
        entropy = time(NULL) ^ getpid();
    }
    return entropy;
}

unsigned long xorshift(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    *state = x;
    return x;
}

double populate_records(int range, int count, record **records, long **offsets, int **keys) {
    unsigned long state = get_entropy();
    double total_sum = 0;

    if ((*records = malloc(count * sizeof(record))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    if (($offsets = malloc(count * sizeof(long))) == NULL) {
        free(*records);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    if ((*keys = malloc(count * sizeof(int))) == NULL) {
        free(*records);
        free(*offsets);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < count; i++) {
        (*records)[i].value = xorshift(&state) % range + range / 2;
        total_sum += (*records)[i].value;
        (*offsets)[i] = i * sizeof(record);
        (*keys)[i] = i;
    }

    return total_sum / count;
}

int main() {
    int range = 100;
    int count = 1000;
    record *records;
    long *offsets;
    int *keys;

    double average = populate_records(range, count, &records, &offsets, &keys);
    if (average != -1) {
        printf("Average value: %f\n", average);
        free(records);
        free(offsets);
        free(keys);
    }

    return 0;
}
```

