#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint64_t id;
} Key;

typedef struct Node {
    Key key;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
} HashTable;

HashTable* createHashTable(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->capacity = capacity;
    table->size = 0;
    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

size_t hashFunction(HashTable* table, uint64_t key) {
    return key % table->capacity;
}

void insertKey(HashTable* table, Key key) {
    size_t index = hashFunction(table, key.id);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure
    newNode->key = key;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->size;
}

void generateUniqueKeys(size_t numKeys, uint64_t seed, HashTable* table) {
    srand(seed);
    for (size_t i = 0; i < numKeys; ++i) {
        Key key = {rand() % UINT64_MAX};
        insertKey(table, key);
    }
}
