#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define MAX_PACKET_SIZE 1024

typedef struct dataPacket {
    time_t timestamp;
    int priority;
    char payload[MAX_PACKET_SIZE];
} dataPacket;

void seedPRNG(int seed) {
    srand(seed);
}

dataPacket* generateDataPacket() {
    dataPacket* packet = malloc(sizeof(dataPacket));
    if (packet == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    packet->timestamp = time(NULL);
    packet->priority = rand() % 10; // Simulate priority
    for (int i = 0; i < MAX_PACKET_SIZE; i++) {
        packet->payload[i] = (char)rand();
    }
    return packet;
}

void freeDataPacket(dataPacket* packet) {
    free(packet);
}

int comparePackets(const void* a, const void* b) {
    dataPacket** pa = (dataPacket**)a;
    dataPacket** pb = (dataPacket**)b;
    return (*pb)->priority - (*pa)->priority; // Sort in descending order
}

void transmitData(dataPacket* packet, int sockfd) {
    send(sockfd, &packet->timestamp, sizeof(time_t), 0);
    send(sockfd, &packet->priority, sizeof(int), 0);
    send(sockfd, packet->payload, MAX_PACKET_SIZE, 0);
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serverAddr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    seedPRNG(time(NULL));

    dataPacket** packetList = malloc(10 * sizeof(dataPacket*));
    for (int i = 0; i < 10; i++) {
        packetList[i] = generateDataPacket();
    }

    qsort(packetList, 10, sizeof(dataPacket*), comparePackets);

    for (int i = 0; i < 10; i++) {
        transmitData(packetList[i], sockfd);
        freeDataPacket(packetList[i]);
    }

    free(packetList);
    close(sockfd);

    return 0;
}
```

