# Cache for resource data with TTL
@lru_cache(maxsize=1024)
def get_resource(resource_id):
    # Simulate fetching resource from database or external system
    return {"id": resource_id, "data": "sample_data"}

@app.route('/api/v1/resources/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    try:
        data = request.get_json()
        # Update the resource in database or external system
        # For simplicity, we just replace the cached data with new data
        get_resource.cache_clear()  # Clear cache to invalidate stale data
        return jsonify(data), 200
    except Exception as e:
        abort(500)

@app.route('/api/v1/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    try:
        # Delete the resource from database or external system
        # For simplicity, we just clear the cached data
        get_resource.cache_clear()
        return jsonify({"message": "Resource deleted"}), 204
    except Exception as e:
        abort(500)

@app.route('/api/v1/resources/<int:resource_id>', methods=['GET'])
def get_resource_by_id(resource_id):
    resource = get_resource(resource_id)
    if not resource:
