public class RemoteConnectionManager
{
    private readonly HttpClient _httpClient;
    private ConcurrentQueue<string> _logBuffer;

    public RemoteConnectionManager()
    {
        _httpClient = new HttpClient();
        _logBuffer = new ConcurrentQueue<string>();
    }

    public async Task ConnectAndTransferDataAsync(string remoteAddress, string data)
    {
        try
        {
            using (var response = await _httpClient.PostAsync(remoteAddress, new StringContent(data)))
            {
                if (response.IsSuccessStatusCode)
                {
                    Log("Success: Data transferred to " + remoteAddress);
                }
                else
                {
                    Log("Error: Failed to transfer data to " + remoteAddress);
                }
            }
        }
        catch (Exception ex)
