#define MAX_RECORDS 1000

typedef struct {
    int id;
} record;

int loadAndInitializeData(const char *filePath, record **bundle, long **offsets, int **keys) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *bundle = (record *)malloc(fileSize / sizeof(record));
    if (!*bundle) {
        fclose(file);
        perror("Failed to allocate memory for bundle");
        return -2; // Memory allocation failed
    }

    size_t recordsRead = fread(*bundle, sizeof(record), fileSize / sizeof(record), file);
    fclose(file);

    *offsets = (long *)malloc(recordsRead * sizeof(long));
    *keys = (int *)malloc(recordsRead * sizeof(int));

    if (!*offsets || !*keys) {
        free(*bundle);
        perror("Failed to allocate memory for offsets and keys");
        return -3; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < recordsRead; ++i) {
        (*offsets)[i] = rand() % 1000L; // Generate a random offset
        (*keys)[i] = rand() % 1000; // Generate a random key
        (*bundle)[i].id = rand() % 1000; // Initialize record ID with a random value
    }

    return recordsRead;
}
