#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    long timestamp;
    int key_id;
    char session_id[256];
} SessionRecord;

typedef struct {
    SessionRecord *records;
    pthread_mutex_t lock;
} SessionManager;

SessionManager session_manager;

void init_session_manager() {
    pthread_mutex_init(&session_manager.lock, NULL);
    session_manager.records = (SessionRecord *)malloc(MAX_SESSIONS * sizeof(SessionRecord));
    if (!session_manager.records) {
        fprintf(stderr, "Failed to allocate memory for session records\n");
        exit(1);
    }
}

void cleanup_session_manager() {
    pthread_mutex_lock(&session_manager.lock);
    free(session_manager.records);
    pthread_mutex_unlock(&session_manager.lock);
    pthread_mutex_destroy(&session_manager.lock);
}

void fill_session_record(SessionRecord *record) {
    record->timestamp = rand();
    record->key_id = rand();
    snprintf(record->session_id, 256, "Session-%d", record->key_id);
}

void *generate_sessions(void *arg) {
    int seed = *(int *)arg;
    srand(seed);

    pthread_mutex_lock(&session_manager.lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        fill_session_record(session_manager.records + i);
    }
    pthread_mutex_unlock(&session_manager.lock);

    return NULL;
}

int main() {
    init_session_manager();

    int seeds[MAX_SESSIONS];
    pthread_t threads[MAX_SESSIONS];

    for (int i = 0; i < MAX_SESSIONS; i++) {
        seeds[i] = time(NULL) + i;
        pthread_create(&threads[i], NULL, generate_sessions, &seeds[i]);
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_session_manager();

    return 0;
}
