#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define RECORD_SIZE 1024

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t size;
    pthread_mutex_t mutex;
} data_structure;

data_structure* create_data_structure(size_t size, unsigned long seed, int secure) {
    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) {
        perror("Failed to allocate memory for data structure");
        return NULL;
    }

    ds->size = size;
    ds->offsets = malloc(size * sizeof(long));
    ds->keys = malloc(size * sizeof(int));
    ds->records = malloc(size * RECORD_SIZE * sizeof(record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Failed to allocate memory for arrays");
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    srand(secure ? time(NULL) : seed);
    for (size_t i = 0; i < size; ++i) {
        ds->offsets[i] = i * sizeof(record);
        ds->keys[i] = rand() % size;
        for (int j = 0; j < RECORD_SIZE; ++j) {
            ds->records[i * RECORD_SIZE + j].value = rand() % size;
        }
    }

    qsort(ds->records, size * RECORD_SIZE, sizeof(record), 
          [](const void *a, const void *b) {
              return ((record *)a)->value - ((record *)b)->value;
          });

    printf("Data structure initialized successfully\n");
    return ds;
}

void free_data_structure(data_structure *ds) {
    if (ds) {
        pthread_mutex_destroy(&ds->mutex);
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
    }
}

// Example usage
int main() {
    data_structure *ds = create_data_structure(1000, 12345, 0); // Non-secure PRNG with seed
    if (ds) {
        // Use ds for your operations
        free_data_structure(ds);
    }
    return 0;
}
```

