typedef struct {
    int id;
    double value;
} record;

int loadAndInitializeData(const char* filePath, record** records) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        // Log error: Unable to open file
        return -1;
    }

    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0L, SEEK_SET);

    int numRecords = fileSize / sizeof(record);
    *records = malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        // Log error: Memory allocation failed
        fclose(file);
        return -2;
    }

    for (int i = 0; i < numRecords; ++i) {
        (*records)[i].id = i;
        (*records)[i].value = ((double)rand() / RAND_MAX) * 100.0;
    }

    fclose(file);
    return numRecords;
}
