using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Tasks;

public class GameConfigManager
{
    private readonly string _configPath = "config.json";
    private dynamic _configSettings;

    public GameConfigManager()
    {
        LoadConfig();
    }

    private void LoadConfig()
    {
        using (var reader = new StreamReader(_configPath))
        {
            _configSettings = JsonSerializer.Deserialize<dynamic>(reader.ReadToEnd());
        }
    }

    public int GetTileSize() => _configSettings.tileSize;
    public (int width, int height) GetWorldDimensions() => (_configSettings.worldWidth, _configSettings.worldHeight);
    public float GetCameraSpeed() => _configSettings.cameraSpeed;
}

public class EncryptionManager
{
    private readonly AesGcm _aesGcm;
    private readonly AesCryptoServiceProvider _aesCfb;

    public EncryptionManager()
    {
        _aesGcm = new AesGcm(Aes.Create());
        _aesCfb = new AesCryptoServiceProvider();
    }

    public byte[] Encrypt(byte[] data, byte[] key, byte[] iv)
    {
        return _aesGcm.EncryptDeterministically(data, key, iv);
    }

    public byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv, bool verifySignature = true)
    {
        try
        {
            return _aesGcm.DecryptAndVerifyDeterministic(encryptedData, key, iv);
        }
        catch (CryptographicException)
        {
            if (!verifySignature) return null;
            throw;
        }
    }

    public byte[] EncryptWithAesCfb(byte[] data, byte[] key, byte[] iv)
    {
        _aesCfb.Key = key;
        _aesCfb.IV = iv;
        var encryptor = _aesCfb.CreateEncryptor();
        using (var ms = new MemoryStream())
        using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
        {
            cs.Write(data, 0, data.Length);
            return ms.ToArray();
        }
    }

    public byte[] DecryptWithAesCfb(byte[] encryptedData, byte[] key, byte[] iv)
    {
        _aesCfb.Key = key;
        _aesCfb.IV = iv;
        var decryptor = _aesCfb.CreateDecryptor();
        using (var ms = new MemoryStream(encryptedData))
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        {
            var decryptedData = new byte[encryptedData.Length];
            cs.Read(decryptedData, 0, decryptedData.Length);
            return decryptedData;
        }
    }
}

public class RemoteApiManager
{
    private readonly HttpClient _httpClient;

    public RemoteApiManager()
    {
        _httpClient = new HttpClient();
    }

    public async Task<T> FetchConfigAsync<T>(string url)
    {
        int retries = 3;
        while (retries > 0)
        {
            try
            {
                var response = await _httpClient.GetAsync(url);
                response.EnsureSuccessStatusCode();
                var content = await response.Content.ReadAsStringAsync();
                return JsonSerializer.Deserialize<T>(content);
            }
            catch (HttpRequestException)
            {
                retries--;
                if (retries == 0) throw;
                await Task.Delay(100); // Exponential backoff
            }
        }
        throw new HttpRequestException("Failed to fetch config after multiple attempts");
    }
}

