typedef struct {
    char data[10];
    int value;
    unsigned char flag;
} Record;

// Non-cryptographic PRNG function
unsigned int myPRNG(unsigned int seed, unsigned int max_value) {
    seed = seed * 214013 + 2531011; // LCG constants
    return (seed % max_value);
}

void initializeArrays(size_t offsetSize, size_t keySize, size_t recordSize, unsigned int seed, Record **recordArray, long **offsetArray, int **keyArray) {
    *recordArray = malloc(recordSize * sizeof(Record));
    *offsetArray = malloc(offsetSize * sizeof(long));
    *keyArray = malloc(keySize * sizeof(int));

    srand(seed);

    for (size_t i = 0; i < recordSize; ++i) {
        (*recordArray)[i].value = myPRNG(rand(), INT_MAX);
        // Chi-squared test can be implemented here to check uniformity
        snprintf((*recordArray)[i].data, sizeof((*recordArray)[i].data), "Record%zu", i);
        (*recordArray)[i].flag = (unsigned char)myPRNG(rand(), 256);
    }

    for (size_t i = 0; i < offsetSize; ++i) {
        (*offsetArray)[i] = myPRNG(rand(), LLONG_MAX);
    }

    for (size_t i = 0; i < keySize; ++i) {
        (*keyArray)[i] = myPRNG(rand(), INT_MAX);
    }
}

void freeArrays(Record *recordArray, long *offsetArray, int *keyArray) {
    if (recordArray != NULL) free(recordArray);
    if (offsetArray != NULL) free(offsetArray);
    if (keyArray != NULL) free(keyArray);
}
