    snprintf(logBuf->log[logBuf->tail], sizeof(logBuf->log[logBuf->tail]), "%s", message);
    logBuf->tail = (logBuf->tail + 1) % MAX_LOG_SIZE;
    pthread_mutex_unlock(&logBuf->lock);
}

// PRNG initialization
void initPRNG(unsigned long seed) {
    srand(seed);
}
