#include <stdlib.h>
#include <time.h>

#define MAX_ALLOC_SIZE 1024 * 1024 // 1MB limit

typedef struct {
    int value;
    time_t timestamp;
} Record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offset, int** key, Record** record, size_t count) {
    *offset = allocate_memory(count * sizeof(long));
    *key = allocate_memory(count * sizeof(int));
    *record = allocate_memory(count * sizeof(Record));

    if (count > MAX_ALLOC_SIZE / (sizeof(long) + sizeof(int) + sizeof(Record))) {
        fprintf(stderr, "Requested size exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator with current time

    for (size_t i = 0; i < count; ++i) {
        (*offset)[i] = i;
        (*key)[i] = i;
        (*record)[i].value = rand(); // Use simple random function
        (*record)[i].timestamp = time(NULL);
    }

    srand(1); // Reset the random number generator state for reproducibility
}

int main() {
    size_t count = 1000; // Example size
    long* offset;
    int* key;
    Record* record;

    initialize_arrays(&offset, &key, &record, count);

    free(offset);
    free(key);
    free(record);

    return 0;
}
```

### Explanation of the Code:
1. **Memory Allocation**: The `allocate_memory` function is used to handle memory allocation with error checking.
2. **Random Number Generation**: The `rand()` function is used for simplicity and is seeded with the current time using `srand(time(NULL))`. After initialization, the random number generator's state is reset to `(srand(1))` to ensure reproducibility of results across multiple runs.
3. **Memory Limit Check**: A check is performed to ensure that the requested allocation does not exceed a predefined limit (`MAX_ALLOC_SIZE`).
4. **Error Handling**: The program exits with an error message if memory allocation fails or if the requested size exceeds the maximum allowed.

This code snippet provides a basic implementation and can be further optimized based on specific requirements and performance considerations.']

