void encrypt_password(char* password) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char *)"1234567890123456", (unsigned char *)"1234567890123456");

    // Encrypt the password
    EVP_EncryptUpdate(ctx, (unsigned char *)password, &len, (unsigned char *)password, strlen(password));
    ciphertext_len = len;

    // Finalize encryption
    EVP_EncryptFinal_ex(ctx, (unsigned char *)(password + len), &len);
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
}
