#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
    int key;
    unsigned char* data;
} record;

record* initialize_records(int num_records, size_t max_data_size) {
    if (num_records <= 0 || max_data_size <= 0) {
        return NULL; // Handle invalid input
    }

    srand(time(NULL)); // Seed the random number generator

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100000; // Random value between 0 and 99999
        records[i].offset = rand() % 1000000L; // Random offset between 0 and 999999
        records[i].key = rand() % 10000; // Random key between 0 and 9999

        records[i].data = (unsigned char*)malloc(max_data_size);
        if (!records[i].data) {
            for (int j = 0; j < i; j++) {
                free(records[j].data); // Clean up previously allocated memory
            }
            free(records); // Free the main array
            return NULL; // Memory allocation failed
        }

        for (size_t j = 0; j < max_data_size; j++) {
            records[i].data[j] = rand() % 256; // Random data byte between 0 and 255
        }
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (!records || num_records <= 0) {
        return; // Handle invalid input
    }

    for (int i = 0; i < num_records; i++) {
        free(records[i].data); // Free each record's data array
    }

    free(records); // Free the main array
}
