    private static readonly ILog Log = LogManager.GetLogger(typeof(CryptoDistributedSystem));

    public byte[] Encrypt(byte[] data, string mode)
    {
        var config = ConfigurationManager.AppSettings;
        var key = Convert.FromBase64String(config["Key"]);
        var iv = Convert.FromBase64String(config["IV"]);

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = (CipherMode)Enum.Parse(typeof(CipherMode), mode);

            if (mode == "GCM")
                aes.GCMTagAuthenticationKeySize = 128;

            using (var encryptor = aes.CreateEncryptor())
            {
                return encryptor.TransformFinalBlock(data, 0, data.Length);
            }
        }
    }

    public byte[] Decrypt(byte[] encryptedData, string mode)
    {
        var config = ConfigurationManager.AppSettings;
        var key = Convert.FromBase64String(config["Key"]);
        var iv = Convert.FromBase64String(config["IV"]);

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = (CipherMode)Enum.Parse(typeof(CipherMode), mode);

            if (mode == "GCM")
                aes.GCMTag = encryptedData[0..16];
                encryptedData = encryptedData[16..];

            using (var decryptor = aes.CreateDecryptor())
            {
                return decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
