['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1000000

typedef struct {
    int value;
    long offset;
    int key;
    unsigned char *data;
} record;

typedef struct {
    pthread_mutex_t lock;
    void **pool;
    size_t pool_size;
} memory_pool;

record* create_record(memory_pool *pool) {
    record *new_record = (record *)pthread_mutex_lock(&pool->lock);
    new_record->value = rand() % 1000;
    new_record->offset = ((long)rand()) << 32 | rand();
    new_record->key = rand() % 100;
    new_record->data = (unsigned char *)malloc(rand() % 100 + 1);
    pthread_mutex_unlock(&pool->lock);
    return new_record;
}

void free_record(record *rec, memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(rec->data);
    rec->data = NULL;
    pthread_mutex_unlock(&pool->lock);
}

memory_pool* init_memory_pool(size_t initial_size) {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    pool->pool = (void **)calloc(initial_size, sizeof(void *));
    pool->pool_size = initial_size;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool *pool) {
    for (size_t i = 0; i < pool->pool_size; ++i) {
        free(pool->pool[i]);
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void* thread_func(void *arg) {
    memory_pool *pool = (memory_pool *)arg;
    record **records = (record **)calloc(MAX_RECORDS, sizeof(record *));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = create_record(pool);
    }
    // Process records
    for (int i = 0; i < MAX_RECORDS; ++i) {
        free_record(records[i], pool);
    }
    free(records);
    return NULL;
}

int main() {
    srand(time(NULL));
    memory_pool *pool = init_memory_pool(1000);

    pthread_t threads[16];
    for (int i = 0; i < 16; ++i) {
        pthread_create(&threads[i], NULL, thread_func, pool);
    }

    for (int i = 0; i < 16; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(pool);
    return 0;
}
```

This code snippet demonstrates a basic structure for a function that dynamically allocates memory for and initializes multiple components in a high-throughput data processing pipeline. It includes functions to create and free records, manage a custom memory pool, and utilize multi-threading for efficient parallel processing. The actual implementation of the pseudo-random number generator, error handling, logging, and performance monitoring mechanisms is omitted for brevity, as these would be complex tasks in themselves and are beyond the scope of this example.']

