#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int initialize_arrays(long** offset_array, int** seed_array, Record** record1, Record** record2) {
    // Allocate memory for arrays
    *offset_array = (long*)malloc(4 * sizeof(long));
    *seed_array = (int*)malloc(4 * sizeof(int));
    *record1 = (Record*)malloc(4 * sizeof(Record));
    *record2 = (Record*)malloc(4 * sizeof(Record));

    if (*offset_array == NULL || *seed_array == NULL || *record1 == NULL || *record2 == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize arrays with default values
    for (int i = 0; i < 4; i++) {
        (*offset_array)[i] = 0;
        (*seed_array)[i] = rand();
        (*record1)[i].value = 0;
        (*record2)[i].value = 0;
    }

    return 0; // Success
}

void cleanup(long* offset_array, int* seed_array, Record* record1, Record* record2) {
    free(offset_array);
    free(seed_array);
    free(record1);
    free(record2);
}

int generate_pseudo_random_values(long* offsets, int* seeds, Record* records, int num_records) {
    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; i++) {
