} Record;

int init_arrays(long** offsets, int** keys, double** data_points, Record** records, size_t num_records, unsigned long seed) {
    srand(seed);

    *offsets = (long*)malloc(num_records * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = (int*)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *data_points = (double*)malloc(num_records * sizeof(double));
    if (*data_points == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    *records = (Record*)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        free(*data_points);
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = (long)(rand() % ((long)LONG_MAX / num_records));
        (*keys)[i] = rand() % INT_MAX;
        (*data_points)[i] = (double)(rand() / (double)RAND_MAX);

        (*records)[i].f = (float)(rand() / (double)RAND_MAX);
        (*records)[i].c = (char)(rand() % 256);
        (*records)[i].next = NULL;
        (*records)[i].i = rand() % INT_MAX;
    }

    return 0;
}

void cleanup(long* offsets, int* keys, double* data_points, Record* records) {
    free(offsets);
    free(keys);
    free(data_points);
    while (records != NULL) {
        Record* next = records->next;
        free(records);
        records = next;
    }
}
