ComplexRecord* allocateAndInitializeRecords(int count) {
    size_t total_size = count * sizeof(ComplexRecord);
    if (total_size > 1024 * 1024) {
        return NULL; // Exceeds the 1MB limit
    }

    ComplexRecord* records = (ComplexRecord*)malloc(total_size);
    if (!records) {
        return NULL; // Memory allocation failed
    }

    unsigned int seed = time(NULL) ^ getpid();
    srand(seed);

    for (int i = 0; i < count; ++i) {
        records[i].offset = rand() % 1000000L;
        records[i].key = rand();

        // Allocate memory for the hex_string
        size_t hex_string_size = 33; // 16 bytes * 2 (hex) + null terminator
        records[i].record.hex_string = (char*)malloc(hex_string_size);
        if (!records[i].record.hex_string) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].record.hex_string);
            }
            free(records);
            return NULL;
        }

        // Generate a random hexadecimal string
        for (size_t j = 0; j < 16; ++j) {
            records[i].record.hex_string[2 * j] = "0123456789ABCDEF"[rand() % 16];
            records[i].record.hex_string[2 * j + 1] = "0123456789ABCDEF"[rand() % 16];
        }
        records[i].record.hex_string[32] = '\0';

        // Initialize the inner record
        records[i].record.value = rand();
    }

    return records;
}

void freeRecords(ComplexRecord* records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i].record.hex_string);
    }
    free(records);
