    *offsets = (long*)malloc(5 * sizeof(long));
    *keys = (int*)malloc(5 * sizeof(int));
    *data_points = (double*)malloc(5 * sizeof(double));
    *intermediate_results = (float*)malloc(5 * sizeof(float));

    if (*offsets == NULL || *keys == NULL || *data_points == NULL || *intermediate_results == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *records = (Record**)malloc(5 * sizeof(Record*));

    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        free(*data_points);
        free(*intermediate_results);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 5; i++) {
        (*records)[i] = NULL;
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 100;
        (*data_points)[i] = (double)rand() / RAND_MAX * 100.0;
        (*intermediate_results)[i] = (float)((double)rand() / RAND_MAX * 100.0);

        if ((*data_points)[i] > 50.0 && (*keys)[i] < 'm') {
            Record* new_record = (Record*)malloc(sizeof(Record));
            new_record->f = *intermediate_results[i];
            new_record->c = (char)(*keys)[i];
            new_record->next = (*records)[i];
            new_record->i = i;
            (*records)[i] = new_record;
        }
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    // Perform further operations with the arrays
    pthread_mutex_unlock(&mutex);
}

void clean_up(long* offsets, int* keys, double* data_points, float* intermediate_results, Record** records) {
    for (int i = 0; i < 5; i++) {
        Record* current = records[i];
        while (current != NULL) {
            Record* next = current->next;
            free(current);
            current = next;
        }
    }

    free(offsets);
    free(keys);
    free(data_points);
    free(intermediate_results);
    free(records);
}
