typedef struct {
    long timestamp;
    int type;
    double probability;
} event;

event* initialize_events(size_t num_events, int max_type, double min_prob, double max_prob) {
    if (num_events == 0 || max_type <= 0 || min_prob >= max_prob) {
        return NULL;
    }

    // Allocate memory for arrays
    long* timestamps = malloc(num_events * sizeof(long));
    int* types = malloc(num_events * sizeof(int));
    double* probabilities = malloc(num_events * sizeof(double));

    if (!timestamps || !types || !probabilities) {
        free(timestamps);
        free(types);
        free(probabilities);
        return NULL;
    }

    // Initialize arrays with non-cryptographically secure random values
    srand(time(NULL)); // Seed PRNG for non-security purposes

    event* events = malloc(num_events * sizeof(event));
    if (!events) {
        free(timestamps);
        free(types);
        free(probabilities);
        return NULL;
    }

    for (size_t i = 0; i < num_events; ++i) {
        timestamps[i] = rand(); // Non-cryptographically secure random timestamp
        types[i] = rand() % max_type + 1; // Random event type from 1 to max_type
        probabilities[i] = min_prob + (double)(rand()) / RAND_MAX * (max_prob - min_prob);
    }

    for (size_t i = 0; i < num_events; ++i) {
        events[i].timestamp = timestamps[i];
        events[i].type = types[i];
        events[i].probability = probabilities[i];
    }

    // Free temporary arrays
    free(timestamps);
    free(types);
    free(probabilities);

    return events;
}

void free_events(event* events, size_t num_events) {
    if (events) {
        free(events);
    }
}
