        data[i] = (Data*)malloc(sizeof(Data));
        if (!data[i]) {
            // Clean up previously allocated memory
            for (size_t j = 0; j < i; ++j) free(data[j]);
            free(data);
            return NULL;
        }
        data[i]->base64_string = (char*)malloc(base64_length);
        if (!data[i]->base64_string) {
            // Clean up previously allocated memory
            for (size_t j = 0; j <= i; ++j) {
                free(data[j]->base64_string);
                free(data[j]);
            }
            free(data);
            return NULL;
        }
    }

