    if (total_size > 1024 * 1024) {
        fprintf(stderr, "Requested memory exceeds 1MB limit.\n");
        return NULL;
    }

    ComplexRecord* records = malloc(total_size);
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL) ^ getpid());
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = i * sizeof(ComplexRecord);
        records[i].key = rand();

        records[i].record.value = rand();
        size_t hex_string_size = 17; // Including null terminator
        records[i].record.hex_string = malloc(hex_string_size);
        if (!records[i].record.hex_string) {
            perror("Memory allocation failed for hex string");
            free(records);
            return NULL;
        }
        snprintf(records[i].record.hex_string, hex_string_size, "%016x", rand());
    }

    return records;
}

void free_complex_records(ComplexRecord* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].record.hex_string);
    }
    free(records);
}

int main() {
    const int num_records = 1000;
    ComplexRecord* records = allocate_and_initialize_complex_records(num_records);
    if (records) {
        // Use the records array...
        free_complex_records(records, num_records);
    }
    return 0;
}
