#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 100000
#define LOG_SIZE 100

typedef struct {
    double *transactions;
    size_t count;
    pthread_mutex_t mutex;
} FinancialData;

typedef struct {
    char filename[256];
    time_t startDate, endDate;
    int transactionType;
    FinancialData *data;
} TransactionFilter;

pthread_mutex_t logMutex;
char logs[LOG_SIZE][100];

void logMessage(const char *message) {
    pthread_mutex_lock(&logMutex);
    static size_t logIndex = 0;
    time_t now = time(NULL);
    snprintf(logs[logIndex], sizeof(logs[logIndex]), "%s: %s", ctime(&now), message);
    logIndex = (logIndex + 1) % LOG_SIZE;
    pthread_mutex_unlock(&logMutex);
}

FinancialData* processFinancialData(double budget, int seed, const char *filename, time_t startDate, time_t endDate, int transactionType) {
    FinancialData *data = (FinancialData*)malloc(sizeof(FinancialData));
    data->transactions = (double*)calloc(MAX_TRANSACTIONS, sizeof(double));
    data->count = 0;
    pthread_mutex_init(&data->mutex, NULL);

    srand(seed);
    double totalAmount = 0.0;
    while (totalAmount < budget && data->count < MAX_TRANSACTIONS) {
        double amount = (double)rand() / RAND_MAX * budget;
        totalAmount += amount;
        data->transactions[data->count++] = amount;
    }

    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return data;
    }

    TransactionFilter filter = {filename, startDate, endDate, transactionType, data};
    pthread_t parserThread;
    pthread_create(&parserThread, NULL, parseTransactions, &filter);

    // Wait for the parser thread to finish
    pthread_join(parserThread, NULL);

    fclose(file);
    return data;
}

void* parseTransactions(void *arg) {
    TransactionFilter *filter = (TransactionFilter*)arg;
    FILE *file = fopen(filter->filename, "r");
    if (!file) {
        perror("Failed to open file in parser thread");
        pthread_exit(NULL);
    }

    double amount;
    while (fscanf(file, "%lf", &amount) == 1) {
        if (filter->startDate != 0 && filter->endDate != 0 &&
            ((time_t)amount < filter->startDate || (time_t)amount > filter->endDate)) {
            continue;
        }
        if (filter->transactionType != -1 && (int)amount % 2 != filter->transactionType) {
            continue;
        }

        pthread_mutex_lock(&filter->data->mutex);
        filter->data->transactions[filter->data->count++] = amount;
        pthread_mutex_unlock(&filter->data->mutex);
    }

    fclose(file);
    pthread_exit(NULL);
}

double calculateAverage(FinancialData *data) {
    if (data->count == 0) return 0.0;

    double sum = 0.0;
    for (size_t i = 0; i < data->count; i++) {
        sum += data->transactions[i];
    }
    return sum / data->count;
}

double calculateMedian(FinancialData *data) {
    if (data->count == 0) return 0.0;

    pthread_mutex_lock(&data->mutex);
    qsort(data->transactions, data->count, sizeof(double), (int (*)(const void *, const void *))strcmp);
    double median;
    if (data->count % 2 == 0) {
        median = (data->transactions[data->count / 2 - 1] + data->transactions[data->count / 2]) / 2.0;
    } else {
        median = data->transactions[data->count / 2];
    }
    pthread_mutex_unlock(&data->mutex);
    return median;
}

void freeFinancialData(FinancialData *data) {
    pthread_mutex_destroy(&data->mutex);
    free(data->transactions);
    free(data);
}
