double generateRandomDouble(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

dataRecord* createDataRecords(size_t count) {
    dataRecord *records = malloc(count * sizeof(dataRecord));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < count; ++i) {
        records[i].id = rand();
        snprintf(records[i].label, sizeof(records[i].label), "Label%d", i);
        records[i].value = generateRandomDouble(0.0, 100.0);
    }
    return records;
}

void freeDataRecords(dataRecord *records, size_t count) {
    free(records);
}

int networkClient(const char *serverIP, int port, const char *query, char *responseBuffer, size_t bufferSize) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(port);
    inet_pton(AF_INET, serverIP, &serverAddr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return -1;
    }

    send(sockfd, query, strlen(query), 0);
    ssize_t bytesReceived = recv(sockfd, responseBuffer, bufferSize - 1, 0);
    if (bytesReceived < 0) {
        perror("Receive failed");
    } else {
        responseBuffer[bytesReceived] = '\0';
    }

    close(sockfd);
    return bytesReceived;
}

void logConnectionStatus(const char *serverIP, int port, int status) {
    FILE *logFile = fopen("connection_log.txt", "a");
    if (logFile) {
        fprintf(logFile, "Server: %s:%d, Status: %s\n", serverIP, port, status ? "Connected" : "Failed to connect");
        fclose(logFile);
    }
}

void cacheDataRecords(RecordCache *cache, dataRecord *records, size_t count) {
    // Implement caching logic here
}

int exportToJSON(dataRecord *records, size_t count, const char *filename) {
    FILE *jsonFile = fopen(filename, "w");
    if (!jsonFile) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    fprintf(jsonFile, "[\n");
    for (size_t i = 0; i < count; ++i) {
        fprintf(jsonFile, "  {\n"
                         "    \"id\": %lu,\n"
                         "    \"label\": \"%s\",\n"
                         "    \"value\": %f\n"
                         "  }%s\n",
                         records[i].id, records[i].label, records[i].value, i < count - 1 ? "," : "");
    }
    fprintf(jsonFile, "]\n");

    fclose(jsonFile);
    return 0;
}

void dataGeneratorAndNetworkClient(const char *serverIP, int port, const char *query, unsigned int seed, const char *outputFile) {
    initPRNG(seed);
    dataRecord *records = createDataRecords(MAX_RECORDS);

    RecordCache cache;
    cache.records = records;
    cache.count = 0;
    cache.capacity = MAX_RECORDS;

    char responseBuffer[BUFFER_SIZE];
    int bytesReceived = networkClient(serverIP, port, query, responseBuffer, BUFFER_SIZE);
    if (bytesReceived >= 0) {
        logConnectionStatus(serverIP, port, 1);
        printf("Response: %s\n", responseBuffer);

        cacheDataRecords(&cache, records, MAX_RECORDS);
        exportToJSON(records, MAX_RECORDS, outputFile);
    } else {
        logConnectionStatus(serverIP, port, 0);
    }

    freeDataRecords(records, MAX_RECORDS);
}
