        fillRandomValues(entryArray[i]);
    }

    // Sorting the float array
    qsort(floatArray, 100, sizeof(double), (int (*)(const void *, const void *))strcmp);

    // Printing the sorted list
    for (int i = 0; i < 100; i++) {
        printf("Sorted Float: %f\n", floatArray[i]);
    }

    // Freeing all allocated memory
    free(floatArray);
    for (int i = 0; i < 100; i++) {
        free(entryArray[i]);
    }
    free(entryArray);
}

int main() {
    int seed = time(NULL);
    dataProcessingPipeline(seed, 30, 5);
    return 0;
}
