#define DEFAULT_RECORDS 1024

typedef struct {
    long offset;
    int key;
    unsigned long id;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
} RecordCollection;

// Custom PRNG function to generate unique identifiers
unsigned long custom_prng(unsigned long seed) {
    return (seed * 214013 + 2531011) % UINT_MAX;
}

// Function to initialize the record collection
RecordCollection* init_record_collection(size_t initial_capacity, const char* config_file) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    // Allocate memory for records with initial capacity
    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;

    // Load metadata from config_file and populate records
    FILE* file = fopen(config_file, "r");
    if (file) {
        long offset;
        int key;
        while (fscanf(file, "%ld %d", &offset, &key) == 2) {
            if (collection->size >= collection->capacity) {
                // Double the capacity and reallocate
                size_t new_capacity = collection->capacity * 2;
                Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
                if (!new_records) {
                    free(collection->records);
                    free(collection);
                    fclose(file);
                    return NULL;
                }
                collection->records = new_records;
                collection->capacity = new_capacity;
            }

            // Populate record with offset, key, and unique ID
            unsigned long seed = (offset * 100 + key) * time(NULL);
            Record* record = &collection->records[collection->size++];
            record->offset = offset;
            record->key = key;
            record->id = custom_prng(seed);
        }
        fclose(file);
    }

    return collection;
}

// Function to free the record collection
void free_record_collection(RecordCollection* collection) {
    if (collection) {
        free(collection->records);
        free(collection);
    }
}
