void initRecord(Record *rec, long offset, int key, unsigned long seed) {
    rec->offset = offset;
    rec->key = key;
    rec->id = customPRNG(seed);
}

Record* allocateAndInitializeRecords(int count, Record *externalRecords, int externalCount, time_t seed) {
    if (count > MAX_RECORDS || (externalCount + count) > MAX_RECORDS) {
        fprintf(stderr, "Cannot allocate more than %d records\n", MAX_RECORDS);
        return NULL;
    }

    Record *records = malloc((count + externalCount) * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    unsigned long internalSeed = seed;
    for (int i = 0; i < count; ++i) {
        initRecord(&records[i], i, rand() % 1000, internalSeed);
        internalSeed = customPRNG(internalSeed);
    }

    for (int i = 0; i < externalCount; ++i) {
        if (externalRecords[i].offset != 0 && externalRecords[i].key != 0) {
            initRecord(&records[count + i], externalRecords[i].offset, externalRecords[i].key, seed);
        }
    }

    return records;
}

void freeRecords(Record *records, int count) {
    free(records);
}

int main() {
    time_t seed = time(NULL);

    Record externalRecords[10] = {
        {123456, 789, 0},
        {0, 0, 0},
        {987654, 321, 0}
    };

    Record *records = allocateAndInitializeRecords(1000000, externalRecords, 3, seed);
    if (records) {
        // Use the records...
        freeRecords(records, 1000003); // 1 million + 3 from external
    }

    return 0;
}
