    uint8_t *memory;
    size_t size;
    size_t used;
} mem_pool;

void* custom_malloc(mem_pool *pool, size_t size) {
    if (pool->used + size > pool->size) return NULL; // Allocation failure
    void *ptr = &pool->memory[pool->used];
    pool->used += size;
    return ptr;
}

void init_mem_pool(mem_pool *pool, size_t total_size) {
    pool->memory = malloc(total_size);
    if (!pool->memory) exit(1); // Allocation failure
    pool->size = total_size;
    pool->used = 0;
}

void destroy_mem_pool(mem_pool *pool) {
    free(pool->memory);
}

// Pseudo-random number generator (Xorshift)
uint64_t xorshift64star(uint64_t *state) {
    uint64_t x = *state;
    x ^= x >> 12; 
    x ^= x << 25; 
    x ^= x >> 27;
    *state = x;
    return x * UINT64_C(0x1b3d2e8c5a97a4bd);
}

entry* init_entries(size_t num_entries, uint8_t min_val, uint8_t max_val, uint64_t seed) {
    if (num_entries > 1000000) return NULL; // Exceeds limit

    entry *entries = custom_malloc(NULL, num_entries * sizeof(entry));
    if (!entries) return NULL; // Allocation failure

    mem_pool pool;
    init_mem_pool(&pool, num_entries * sizeof(uint8_t));

    uint64_t state = seed;
    for (size_t i = 0; i < num_entries; ++i) {
        entries[i].value = min_val + (xorshift64star(&state) % (max_val - min_val + 1));
        entries[i].length = custom_malloc(&pool, xorshift64star(&state) % 100); // Random length up to 99
        if (!entries[i].length) {
            destroy_mem_pool(&pool);
            free(entries);
            return NULL; // Allocation failure
        }
    }

    destroy_mem_pool(&pool);
    return entries;
}

// Example usage:
int main() {
    srand(time(NULL)); // Seed PRNG with current time for better randomness in practice
    entry *my_entries = init_entries(1000000, 1, 255, xorshift64star((uint64_t*)&srand));
    if (!my_entries) return -1; // Allocation failure

    // Use my_entries...

    free(my_entries); // Free allocated memory
    return 0;
}
