        records[i].value = rangeMin + rand() % (rangeMax - rangeMin + 1);
    }

    // Read integers from standard input
    int* inputArray = (int*)malloc(10 * sizeof(int));
    for (int i = 0; i < 10; i++) {
        scanf("%d", &inputArray[i]);
    }

    // Find and print the largest integer in the array
    int maxInt = findMax(inputArray, 10);
    printf("Largest Integer: %d\n", maxInt);

    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(inputArray);
}

int findMax(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
