    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays_and_records(long *offsets, int *keys, double *doubles, float *floats, Record **records) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = (long)RAND_int();
        keys[i] = RAND_int();
        doubles[i] = RAND_double();
        floats[i] = (float)RAND_double();

        records[i] = allocate_memory(sizeof(Record));
        records[i]->f = (float)RAND_double();
        records[i]->c = 'a' + (char)RAND_int() % 26;
        records[i]->next = NULL;
        records[i]->i = RAND_int();
    }
}

void free_all_memory(long *offsets, int *keys, double *doubles, float *floats, Record **records) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(doubles);
    free(floats);
}

int main() {
    secure_random_init(1);

    long *offsets = allocate_memory(MAX_RECORDS * sizeof(long));
    int *keys = allocate_memory(MAX_RECORDS * sizeof(int));
    double *doubles = allocate_memory(MAX_RECORDS * sizeof(double));
    float *floats = allocate_memory(MAX_RECORDS * sizeof(float));
    Record **records = allocate_memory(MAX_RECORDS * sizeof(Record*));

    initialize_arrays_and_records(offsets, keys, doubles, floats, records);

    // Use the arrays and records as needed

    free_all_memory(offsets, keys, doubles, floats, records);

    return 0;
}
