typedef struct {
    int key;
    long offset;
    double value;
} Record;

Record* read_records(int count) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < count; ++i) {
        scanf("%d", &records[i].key);
        records[i].offset = (long)i * sizeof(Record);
        records[i].value = 1.0 * records[i].key / count;
    }
    return records;
}

void sort_records(Record* records, int count) {
    // Implement a stable O(n log n) sorting algorithm
    // Example: Merge Sort
    // For simplicity, using qsort here for demonstration
    qsort(records, count, sizeof(Record), compare_records);
}

int compare_records(const void* a, const void* b) {
    return ((Record*)a)->key - ((Record*)b)->key;
}

double find_largest_integer(Record* records, int count) {
    double largest = INT_MIN;
    for (int i = 0; i < count; ++i) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }
    return largest;
}

void print_largest_integer(double largest) {
    printf("Largest integer: %.2f\n", largest);
}

int main() {
    int count;
    printf("Enter the number of records: ");
    scanf("%d", &count);

    Record* records = read_records(count);
    sort_records(records, count);

    double largest = find_largest_integer(records, count);
    print_largest_integer(largest);

    free(records);
    return 0;
}
