typedef struct {
    int value;
    char *str;
} record;

record* create_record(int value, const char *str) {
    record *r = (record*)malloc(sizeof(record));
    if (!r) return NULL;
    r->value = value;
    r->str = strdup(str);
    if (!r->str) {
        free(r);
        return NULL;
    }
    return r;
}

void free_record(record *r) {
    if (r) {
        free(r->str);
        free(r);
    }
}

long* create_offset_array(size_t size, unsigned long seed) {
    long *offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) return NULL;
    srand(seed);
    for (size_t i = 0; i < size; i++) {
        offsets[i] = rand();
    }
    return offsets;
}

void free_offset_array(long *offsets, size_t size) {
    if (offsets) {
        free(offsets);
    }
}

int* create_key_array(size_t size, unsigned long seed) {
    int *keys = (int*)malloc(size * sizeof(int));
    if (!keys) return NULL;
    srand(seed);
    for (size_t i = 0; i < size; i++) {
        keys[i] = rand();
    }
    return keys;
}

void free_key_array(int *keys, size_t size) {
    if (keys) {
        free(keys);
    }
}

record** create_record_array(size_t size, unsigned long seed, int range_min, int range_max) {
    record **records = (record**)malloc(size * sizeof(record*));
    if (!records) return NULL;
    srand(seed);
    for (size_t i = 0; i < size; i++) {
        records[i] = create_record(rand() % (range_max - range_min + 1) + range_min, "example");
        if (!records[i]) {
            for (size_t j = 0; j < i; j++) {
                free_record(records[j]);
            }
            free(records);
            return NULL;
        }
    }
    return records;
}

void free_record_array(record **records, size_t size) {
    if (records) {
        for (size_t i = 0; i < size; i++) {
            free_record(records[i]);
        }
        free(records);
    }
}

int find_largest(int *array, size_t size) {
    if (!array || size == 0) return INT_MIN;
    int largest = array[0];
    for (size_t i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

