    unsigned long seed;
    printf("Enter a seed value: ");
    scanf("%lu", &seed);

    int num_records, range_min, range_max;
    printf("Enter the number of records and value range (min max): ");
    scanf("%d %d %d", &num_records, &range_min, &range_max);

    long *offsets = create_offset_array(num_records, seed);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return 1;
    }

    int *keys = create_key_array(num_records, seed);
    if (!keys) {
        free_offset_array(offsets, num_records);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return 1;
    }

    record **records = create_record_array(num_records, seed, range_min, range_max);
    if (!records) {
        free_offset_array(offsets, num_records);
        free_key_array(keys, num_records);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return 1;
    }

    printf("Enter the number of integers: ");
    size_t num_integers;
    scanf("%zu", &num_integers);

    int *integers = (int*)malloc(num_integers * sizeof(int));
    if (!integers) {
        free_offset_array(offsets, num_records);
        free_key_array(keys, num_records);
        free_record_array(records, num_records);
        fprintf(stderr, "Failed to allocate memory for integers\n");
        return 1;
    }

    printf("Enter the integers:\n");
    for (size_t i = 0; i < num_integers; i++) {
        scanf("%d", &integers[i]);
    }

    int largest = find_largest(integers, num_integers);
    printf("Largest integer: %d\n", largest);

    free(integers);
    free_record_array(records, num_records);
    free_key_array(keys, num_records);
    free_offset_array(offsets, num_records);

    return 0;
}
