typedef struct {
    int value;
} record;

record* manage_memory(size_t offset_size, size_t key_size, int min_value, int max_value) {
    if (offset_size == 0 || key_size == 0) {
        return NULL;
    }

    long* offsets = calloc(offset_size, sizeof(long));
    if (!offsets) {
        return NULL;
    }

    int* keys = malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = calloc(key_size, sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < key_size; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    // Simulate some operations with the allocated memory
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = rand();
    }

    // Free all allocated memory before returning
    free(offsets);
    free(keys);

    return records;
}
