void initialize_string(char **dest, const char *src) {
    if (((*dest) = strdup(src)) == NULL) {
        fprintf(stderr, "Memory allocation failed for string\n");
        exit(EXIT_FAILURE);
    }
}

int* read_integers(size_t *size) {
    int *numbers = NULL;
    size_t count = 0;

    while (1) {
        int num;
        if (scanf("%d", &num) != 1) {
            break;
        }
        count++;
        numbers = realloc(numbers, count * sizeof(int));
        if (numbers == NULL) {
            fprintf(stderr, "Memory reallocation failed for integers\n");
            exit(EXIT_FAILURE);
        }
        numbers[count - 1] = num;
    }

    *size = count;
    return numbers;
}

char** read_strings(size_t *size) {
    char **strings = NULL;
    size_t count = 0;

    while (1) {
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
            break;
        }
        buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline character
        count++;
        strings = realloc(strings, count * sizeof(char*));
        if (strings == NULL) {
            fprintf(stderr, "Memory reallocation failed for strings\n");
            exit(EXIT_FAILURE);
        }
        initialize_string(&strings[count - 1], buffer);
    }

    *size = count;
    return strings;
}

int find_largest_integer(int *numbers, size_t size) {
    if (size == 0) {
        fprintf(stderr, "Empty array for finding largest integer\n");
        exit(EXIT_FAILURE);
    }
    int max = numbers[0];
    for (size_t i = 1; i < size; ++i) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }
    return max;
}

int find_longest_string(char **strings, size_t size) {
    if (size == 0) {
        fprintf(stderr, "Empty array for finding longest string\n");
        exit(EXIT_FAILURE);
    }
    int length = strlen(strings[0]);
    for (size_t i = 1; i < size; ++i) {
        int current_length = strlen(strings[i]);
        if (current_length > length) {
            length = current_length;
        }
    }
    return length;
}

int main() {
    unsigned long seed;
    printf("Enter seed value for random number generator: ");
    scanf("%lu", &seed);
    seed_random_generator(seed);

    size_t num_records, num_ints, num_strings;

    int *numbers = read_integers(&num_ints);
    char **strings = read_strings(&num_strings);

    if (num_ints < 3 || num_strings < 3) {
        fprintf(stderr, "Not enough data to initialize records\n");
        free(numbers);
        free(strings);
        return EXIT_FAILURE;
    }

    size_t min_value = -1000; // Example minimum value for random numbers
    size_t max_value = 1000; // Example maximum value for random numbers

    record *records = initialize_records(3, min_value, max_value, seed);

    for (size_t i = 0; i < 3; ++i) {
        initialize_string(&records[i].str, strings[i]);
    }

    int largest_int = find_largest_integer(numbers, num_ints);
    printf("Largest integer: %d\n", largest_int);

    int longest_string_length = find_longest_string(strings, num_strings);
    printf("Longest string length: %d\n", longest_string_length);

    free_all_memory(records->str, numbers, records, 3);
    free(numbers);
    free(strings);

    return EXIT_SUCCESS;
}
