#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <json/json.h>
#include <semaphore.h>

struct Attack {
    int cooldown;
    int power;
    float hitProbability;
};

class GameCharacter {
private:
    std::vector<Attack> attacks;
    sem_t attackMutex;

public:
    GameCharacter() : attackMutex(1) {}

    void loadAttacks(const std::string& filename) {
        std::ifstream file(filename);
        Json::Value root;
        file >> root;
        for (const auto& attackJson : root["attacks"]) {
            Attack attack;
            attack.cooldown = attackJson["cooldown"].asInt();
            attack.power = attackJson["power"].asInt();
            attack.hitProbability = attackJson["hitProbability"].asFloat();
            attacks.push_back(attack);
        }
    }

    void selectAttack() {
        sem_wait(&attackMutex);
        if (!attacks.empty()) {
            std::srand(std::time(nullptr));
            int index = std::rand() % attacks.size();
            const Attack& selectedAttack = attacks[index];
            std::cout << "Selected Attack: " << index + 1 << "\n";
            std::cout << "Cooldown: " << selectedAttack.cooldown << "\n";
            std::cout << "Power: " << selectedAttack.power << "\n";
            std::cout << "Hit Probability: " << selectedAttack.hitProbability << "\n";
        }
        sem_post(&attackMutex);
    }

    ~GameCharacter() {
        sem_destroy(&attackMutex);
    }
};

int main() {
    GameCharacter character;
    character.loadAttacks("attacks.json");
    character.selectAttack();
    return 0;
}
