#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define NUM_RECORDS 1000
#define RECORD_SIZE sizeof(struct record)

struct record {
    int key;
    long offset;
    double value;
};

void* seed_prng(void* arg) {
    srand((unsigned int)arg);
    return NULL;
}

void initialize_arrays(long** offsets, int** keys, double** values) {
    *offsets = (long*)malloc(NUM_RECORDS * sizeof(long));
    *keys = (int*)malloc(NUM_RECORDS * sizeof(int));
    *values = (double*)malloc(NUM_RECORDS * sizeof(double));
    if (*offsets == NULL || *keys == NULL || *values == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void initialize_records(struct record* records) {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].key = rand() % 1000;
        records[i].offset = rand() % 1000000L;
        records[i].value = (double)rand() / RAND_MAX * 1000.0;
    }
}

void free_memory(long* offsets, int* keys, double* values, struct record* records) {
    free(offsets);
    free(keys);
    free(values);
    free(records);
}

int read_integers(int** integers) {
    int count = 0;
    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        int num = atoi(line);
        if (num == 0 && line[0] != '0') break; // Break on non-integer input
        *integers = realloc(*integers, (count + 1) * sizeof(int));
        (*integers)[count++] = num;
    }
    return count;
}

void print_largest_integer(int* integers, int count) {
    if (count == 0) {
        printf("No integers provided\n");
        return;
    }
    int largest = integers[0];
    for (int i = 1; i < count; ++i) {
        if (integers[i] > largest) {
            largest = integers[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void* process_records(void* arg) {
    struct record* records = (struct record*)arg;
    qsort(records, NUM_RECORDS, RECORD_SIZE, [](const void* a, const void* b) {
        return ((struct record*)a)->key - ((struct record*)b)->key;
    });
    // Filter logic here
    return NULL;
}

int main() {
    pthread_t seed_thread, process_thread;
    long* offsets = NULL;
    int* keys = NULL;
    double* values = NULL;
    struct record* records = (struct record*)malloc(NUM_RECORDS * RECORD_SIZE);
    int* integers = NULL;

    initialize_arrays(&offsets, &keys, &values);
    initialize_records(records);

    pthread_create(&seed_thread, NULL, seed_prng, time(NULL));
    pthread_join(seed_thread, NULL);

    pthread_create(&process_thread, NULL, process_records, records);
    pthread_join(process_thread, NULL);

    free_memory(offsets, keys, values, records);
    integers = (int*)malloc(sizeof(int));
    int count = read_integers(&integers);
    print_largest_integer(integers, count);

    free(integers);
    return 0;
}
