#include <mutex>

namespace RandomUtils {
    class SecureRandomGenerator {
    public:
        using result_type = std::uint32_t;

        explicit SecureRandomGenerator(std::seed_seq seq) : gen(seq), mt(seq) {}

        static auto generateSecureSeed() -> std::seed_seq {
            std::random_device rd;
            std::vector<std::uint32_t> seeds(rd(), rd());
            return std::seed_seq(seeds.begin(), seeds.end());
        }

        result_type operator()() {
            return mt();
        }

    private:
        std::mt19937_64 mt;
        std::mt19937 gen;
    };

    class RandomGenerator {
    public:
        using real_type = double;

        explicit RandomGenerator(SecureRandomGenerator& secureGen) : rng(secureGen()) {}

        template <typename IntType>
        IntType generate(IntType min, IntType max) {
            std::uniform_int_distribution<IntType> dist(min, max);
            return dist(rng);
        }

        real_type generate(real_type min, real_type max) {
            std::uniform_real_distribution<real_type> dist(min, max);
            return dist(rng);
        }

    private:
        std::mt19937 rng;
    };
}
