#define RECORD_SIZE sizeof(int) + sizeof(long) + sizeof(double)

typedef struct {
    int intValue;
    long offset;
    union {
        double doubleValue;
        char stringValue[256];
    } data;
} Record;

Record* createRecords(int numRecords, int mode, int seed, int minValue, int maxValue, int stringLength) {
    srand(seed);
    Record* records = (Record*)malloc(numRecords * RECORD_SIZE);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].intValue = rand() % (maxValue - minValue + 1) + minValue;

        if (mode == 0) {
            // Initialize double value
            records[i].data.doubleValue = (double)rand() / RAND_MAX;
        } else if (mode == 1) {
            // Initialize string value
            for (int j = 0; j < stringLength; j++) {
                records[i].data.stringValue[j] = 'a' + rand() % ('z' - 'a' + 1);
            }
            records[i].data.stringValue[stringLength] = '\0';
        }

        records[i].offset = (long)time(NULL) + rand();
    }

    return records;
}

void freeRecords(Record* records, int numRecords) {
    free(records);
}

int main() {
    int numRecords = 100;
    int mode = 1; // Mode 0 for double, Mode 1 for string
    int seed = time(NULL);
    int minValue = 0;
    int maxValue = 100;
    int stringLength = 256;

    Record* records = createRecords(numRecords, mode, seed, minValue, maxValue, stringLength);
    if (records) {
        // Process records
        freeRecords(records, numRecords);
    }

    return 0;
}
