#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_USERS 1000
#define MAX_TRANSACTIONS 100000
#define MEM_THRESHOLD 50 * 1024 * 1024 // 50MB

typedef struct {
    int id;
    long timestamp;
    double amount;
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    int user_id;
    double total_amount;
} UserSummary;

UserSummary *user_summaries = NULL;
int transaction_count = 0;
Transaction transactions[MAX_TRANSACTIONS];
pthread_mutex_t global_lock;

void* parse_transaction(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = thread_id; i < transaction_count; i += MAX_THREADS) {
        pthread_mutex_lock(&user_summaries[transactions[i].user_id].lock);
        user_summaries[transactions[i].user_id].total_amount += transactions[i].amount;
        pthread_mutex_unlock(&user_summaries[transactions[i].user_id].lock);
    }
    free(arg);
    return NULL;
}

void monitor_memory_usage() {
    // Implement memory usage monitoring logic here
    if (get_current_memory_usage() > MEM_THRESHOLD) {
        printf("Memory usage alert! Current: %ld bytes\n", get_current_memory_usage());
        // Trigger alert or handle the situation
    }
}

int main() {
    int num_threads = 4; // Number of threads for parallel processing

    // Initialize user summaries
    user_summaries = (UserSummary*)calloc(MAX_USERS, sizeof(UserSummary));
    if (!user_summaries) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Populate transactions with random data
    srand(time(NULL));
    for (int i = 0; i < MAX_TRANSACTIONS; ++i) {
        transactions[i].id = i;
        transactions[i].user_id = rand() % MAX_USERS + 1;
        transactions[i].timestamp = rand();
        transactions[i].amount = ((double)rand() / RAND_MAX) * 100.0;
    }
    transaction_count = MAX_TRANSACTIONS;

    // Monitor memory usage before processing
    monitor_memory_usage();

    // Parse transactions using multiple threads
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < num_threads; ++i) {
        int *thread_id = malloc(sizeof(int));
        if (!thread_id) {
            fprintf(stderr, "Memory allocation failed\n");
            return EXIT_FAILURE;
        }
        *thread_id = i;
        if (pthread_create(&threads[i], NULL, parse_transaction, thread_id) != 0) {
            free(thread_id);
            perror("Thread creation failed");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Output results
    for (int i = 1; i <= MAX_USERS; ++i) {
        printf("User %d: Total Amount = %.2f\n", i, user_summaries[i].total_amount);
    }

    // Clean up
    free(user_summaries);

    return EXIT_SUCCESS;
}
