#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    float value;
    char buffer[256];
} DataStructure;

typedef struct {
    time_t timestamp;
    int identifierIndex;
    DataStructure data;
    int used;
} UniqueIdentifierEntry;

UniqueIdentifierEntry* entries = NULL;
int currentSize = 0;

void initializeEntries() {
    entries = (UniqueIdentifierEntry*)malloc(MAX_ENTRIES * sizeof(UniqueIdentifierEntry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    for (int i = 0; i < MAX_ENTRIES; i++) {
        entries[i].used = 0;
    }
}

int hashFunction(int identifierIndex) {
    return identifierIndex % MAX_ENTRIES;
}

int findEmptySlot(int identifierIndex) {
    int index = hashFunction(identifierIndex);
    while (entries[index].used && entries[index].identifierIndex != identifierIndex) {
        index = (index + 1) % MAX_ENTRIES;
    }
    if (entries[index].used) {
        return -1; // No empty slot found
    }
    return index;
}

int insertEntry(int identifierIndex, time_t timestamp, float value, const char* buffer) {
    int index = findEmptySlot(identifierIndex);
    if (index == -1) {
        fprintf(stderr, "Cannot insert entry. Table is full.\n");
        return -1;
    }
    entries[index].timestamp = timestamp;
    entries[index].identifierIndex = identifierIndex;
    entries[index].data.value = value;
    strncpy(entries[index].data.buffer, buffer, sizeof(entries[index].data.buffer) - 1);
    entries[index].used = 1;
    currentSize++;
    return index;
}

void freeEntries() {
    free(entries);
}

int main() {
    srand(time(NULL));
    initializeEntries();

    time_t timestamp = time(NULL);
    float value = 3.14f;
    const char* buffer = "Data Entry";

    int identifierIndex = rand() % MAX_ENTRIES;

    insertEntry(identifierIndex, timestamp, value, buffer);

    freeEntries();
    return 0;
}
