        time_t currentTime = time(NULL);
        transactions[i].timestamp = currentTime;
        transactions[i].transactionID = rand(); // Use PRNG for transaction ID generation
        transactions[i].amount = minAmount + ((double)rand() / RAND_MAX) * (maxAmount - minAmount); // Random amount within specified range
    }

    return transactions;
}

void freeTransactions(Transaction* transactions, int numTransactions) {
    free(transactions);
}
