    if (num_records <= 0 || !offsets || !keys || !chars) {
        return NULL;
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].data = malloc(config_length + 1);
        if (!records[i].data) {
            // Cleanup allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(records[j].data);
            }
            free(records);
            return NULL;
        }

        for (int j = 0; j < config_length; j++) {
            records[i].data[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        records[i].data[config_length] = '\0';

        keys[i] = i;
        chars[i] = records[i].data;
    }

    return records;
}

void destroy_records(int num_records, record *records) {
    if (num_records <= 0 || !records) {
        return;
    }

    for (int i = 0; i < num_records; i++) {
        free(records[i].data);
    }
    free(records);
}
