int initializeArrays(long* offset, int* keys, record** records, long numElements, long seed, int minValue, int maxValue) {
    if (seed == -1) {
        srand(time(NULL));
        seed = rand();
    }

    *offset = malloc(numElements * sizeof(long));
    *keys = malloc(numElements * sizeof(int));
    *records = malloc(numElements * sizeof(record));

    if (*offset == NULL || *keys == NULL || *records == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    for (long i = 0; i < numElements; i++) {
        (*offset)[i] = customPRNG(seed);
        (*keys)[i] = rand() % (maxValue - minValue + 1) + minValue;
        (*records)[i].value = customPRNG(seed);
    }

    return 0;
}

void cleanup(long* offset, int* keys, record** records, long numElements) {
    free(offset);
    free(keys);
    free(*records);
}

