#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int id;
    time_t expiration;
    char** permissions;
    size_t num_permissions;
} UserSession;

typedef struct {
    UserSession* sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} SessionManager;

UserSession* create_session(int session_id, time_t expiration, char** permissions, size_t num_permissions) {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (session == NULL) {
        return NULL; // Handle memory allocation failure
    }
    session->id = session_id;
    session->expiration = expiration;
    session->permissions = permissions;
    session->num_permissions = num_permissions;
    return session;
}

void destroy_session(UserSession* session) {
    free(session);
}

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (manager == NULL) {
        return NULL; // Handle memory allocation failure
    }
    manager->sessions = (UserSession**)malloc(initial_capacity * sizeof(UserSession*));
    if (manager->sessions == NULL) {
        free(manager);
        return NULL; // Handle memory allocation failure
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_session_manager(SessionManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        destroy_session(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_session(SessionManager* manager, UserSession* session) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = (UserSession**)realloc(manager->sessions, manager->capacity * sizeof(UserSession*));
        if (manager->sessions == NULL) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Handle memory allocation failure
        }
    }
    manager->sessions[manager->size++] = session;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

UserSession* get_session(SessionManager* manager, int session_id) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i]->id == session_id) {
            pthread_mutex_unlock(&manager->mutex);
            return manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

int remove_session(SessionManager* manager, int session_id) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i]->id == session_id) {
            destroy_session(manager->sessions[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // Session not found
}
