int session_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void seed_cspng(int seed) {
    srand(seed);
}

int generate_session_id(char *id) {
    if (id == NULL || strlen(id) != 32) return -1;
    for (int i = 0; i < 32; i++) {
        id[i] = '0' + rand() % 10;
    }
    id[32] = '\0';
    return 0;
}

void *allocate_sessions(void *arg) {
    int target_size = *(int *)arg;
    while (target_size > MAX_SESSIONS) target_size /= 2;

    pthread_mutex_lock(&lock);
    SessionRecord *new_records = realloc(session_records, target_size * sizeof(SessionRecord));
    if (new_records == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    session_records = new_records;
    session_count = target_size;
    pthread_mutex_unlock(&lock);

    for (int i = 0; i < session_count; i++) {
        generate_session_id(session_records[i].session_id);
        time_t now = time(NULL);
        if (now != -1) session_records[i].timestamp = now;
        else return NULL;
        session_records[i].user_id = rand() % 1000;
    }

    return NULL;
}

void free_sessions() {
    pthread_mutex_lock(&lock);
    free(session_records);
    session_records = NULL;
    session_count = 0;
    pthread_mutex_unlock(&lock);
}

void log_memory_usage(int size) {
    printf("Allocated %d sessions\n", size);
}

