    while (allocate_sessions(&initial_size) == NULL) {
        if (initial_size <= MIN_SESSIONS) break;
        initial_size /= 2;
    }

    if (session_records != NULL) {
        log_memory_usage(session_count);
        // Use session records
        free_sessions();
    } else {
        printf("Failed to allocate sessions\n");
    }

    return 0;
