#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int transaction_id;
    double amount;
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    PRNG *prng;
    int seed;
    int successful_attempts;
    int failed_attempts;
} TransactionManager;

Transaction* create_transactions(int num_transactions, int seed, int *error_code) {
    Transaction *transactions = malloc(num_transactions * sizeof(Transaction));
    if (transactions == NULL) {
        *error_code = -1; // Memory allocation failure
        return NULL;
    }

    pthread_mutex_lock(&manager.lock);
    PRNG *prng = manager.prng;

    for (int i = 0; i < num_transactions; ++i) {
        time_t timestamp = time(NULL);
        int transaction_id = prng->generate(prng, seed + i); // Generate unique ID
        double amount = prng->generate(prng, seed * 100 + i) / 100.0; // Generate unique amount

        // Check for collisions and generate unique IDs if necessary
        int collision_count = 0;
        while (is_collision(transactions, num_transactions, transaction_id)) {
            transaction_id = prng->generate(prng, seed * 100 + i + collision_count);
            ++collision_count;
            ++manager.failed_attempts;
        }

        transactions[i].timestamp = timestamp;
        transactions[i].transaction_id = transaction_id;
        transactions[i].amount = amount;

        if (collision_count == 0) {
            ++manager.successful_attempts;
        }
    }

    pthread_mutex_unlock(&manager.lock);
    return transactions;
}

int is_collision(Transaction *transactions, int num_transactions, int transaction_id) {
    for (int i = 0; i < num_transactions; ++i) {
        if (transactions[i].transaction_id == transaction_id) {
            return 1;
        }
    }
    return 0;
}

void free_transactions(Transaction *transactions) {
    free(transactions);
}

void log_transaction_manager_state() {
    printf("Seed: %d, Successful Attempts: %d, Failed Attempts: %d\n",
           manager.seed, manager.successful_attempts, manager.failed_attempts);
}
