        int length = MIN_SESSION_ID_LEN + rand() % (MAX_SESSION_ID_LEN - MIN_SESSION_ID_LEN + 1);
        for (int j = 0; j < length; ++j) {
            sessions[i].id[j] = 'A' + rand() % 52;
