    if ((buffer->tail + 1) % MAX_LOG_SIZE != buffer->head) {
        snprintf(buffer->log + buffer->tail * sizeof(char), MAX_LOG_SIZE - buffer->tail * sizeof(char), "%s\n", event);
        buffer->tail = (buffer->tail + 1) % MAX_LOG_SIZE;
