// Define a simple circular buffer for logging
#define LOG_BUFFER_SIZE 1024

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    int head;
    int tail;
} LogBuffer;

void initLogBuffer(LogBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
}

void logMessage(LogBuffer *buffer, const char *message) {
    if ((buffer->tail + 1) % LOG_BUFFER_SIZE == buffer->head) {
        // Buffer is full, overwrite the oldest message
        buffer->head = (buffer->head + 1) % LOG_BUFFER_SIZE;
    }
    snprintf(buffer->buffer + buffer->tail, LOG_BUFFER_SIZE - buffer->tail, "%s\n", message);
    buffer->tail = (buffer->tail + 1) % LOG_BUFFER_SIZE;
}

void printLogBuffer(const LogBuffer *buffer) {
    for (int i = buffer->head; i != buffer->tail; i = (i + 1) % LOG_BUFFER_SIZE) {
        printf("%s", buffer->buffer + i);
    }
}

