#define MIN_SEED 1
#define MAX_SEED 10000
#define DEFAULT_BUFFER_SIZE 256
#define DEFAULT_TRANSACTION_COUNT 100
#define DEFAULT_TOTAL_MEMORY_LIMIT 10 * 1024 * 1024 // 10MB

typedef struct {
    long timestamp;
    int session_id;
    char* buffer;
} transaction;

pthread_mutex_t memory_management_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_transaction_array(int seed, int buffer_size, int transaction_count, int total_memory_limit) {
    if (seed < MIN_SEED || seed > MAX_SEED) {
        fprintf(stderr, "Invalid seed. Seed must be between %d and %d.\n", MIN_SEED, MAX_SEED);
        return NULL;
    }

    srand(seed);

    transaction* transactions = malloc(transaction_count * sizeof(transaction));
    if (!transactions) {
        fprintf(stderr, "Failed to allocate memory for transaction array.\n");
        return NULL;
    }

    int total_allocated_memory = 0;
    for (int i = 0; i < transaction_count; i++) {
        transactions[i].buffer = malloc(buffer_size);
        if (!transactions[i].buffer) {
            fprintf(stderr, "Failed to allocate memory for transaction buffer %d.\n", i);
            // Clean up previously allocated buffers
            for (int j = 0; j < i; j++) {
                free(transactions[j].buffer);
            }
            free(transactions);
            return NULL;
        }

        transactions[i].timestamp = time(NULL);
        transactions[i].session_id = rand() % MAX_SEED;

        // Simulate buffer data generation
        snprintf(transactions[i].buffer, buffer_size, "Transaction %d", i);

        total_allocated_memory += buffer_size;
        if (total_allocated_memory > total_memory_limit) {
            fprintf(stderr, "Total memory limit exceeded.\n");
            // Clean up all allocated buffers
            for (int j = 0; j <= i; j++) {
                free(transactions[j].buffer);
            }
            free(transactions);
            return NULL;
        }
    }

    return transactions;
}

// Example usage
int main() {
    int seed = 42;
    int buffer_size = DEFAULT_BUFFER_SIZE;
    int transaction_count = DEFAULT_TRANSACTION_COUNT;
    int total_memory_limit = DEFAULT_TOTAL_MEMORY_LIMIT;

    void* result = allocate_transaction_array(seed, buffer_size, transaction_count, total_memory_limit);
    if (result) {
        // Process transactions
        free(result);
    }

    return 0;
}
