typedef struct {
    long timestamp;
    int eventID;
    float dataValue;
} EventLog;

void generateEventLogs(long* timestamps, int* eventIDs, float* dataValues, int numEvents) {
    srand(time(NULL)); // Seed the PRNG for initial run
    for (int i = 0; i < numEvents; ++i) {
        timestamps[i] = rand() % 1000000; // Timestamp within [0, 999999]
        eventIDs[i] = rand() % 1000;    // Event ID within [0, 999]
        dataValues[i] = (float)(rand() % 1000) / 10.0f; // Data value within [0.0, 99.9]
    }
}

void populateEventLogSystem(EventLog* eventLogs, long* timestamps, int* eventIDs, float* dataValues, int numEvents) {
    for (int i = 0; i < numEvents; ++i) {
        eventLogs[i].timestamp = timestamps[i];
        eventLogs[i].eventID = eventIDs[i];
        eventLogs[i].dataValue = dataValues[i];
    }
}

int main() {
    const int numEvents = 1000;
    long* timestamps = (long*)malloc(numEvents * sizeof(long));
    int* eventIDs = (int*)malloc(numEvents * sizeof(int));
    float* dataValues = (float*)malloc(numEvents * sizeof(float));
    EventLog* eventLogs = (EventLog*)malloc(numEvents * sizeof(EventLog));

    if (timestamps == NULL || eventIDs == NULL || dataValues == NULL || eventLogs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    generateEventLogs(timestamps, eventIDs, dataValues, numEvents);
    populateEventLogSystem(eventLogs, timestamps, eventIDs, dataValues, numEvents);

    // Use the eventLogs for processing...

    free(timestamps);
    free(eventIDs);
    free(dataValues);
    free(eventLogs);

    return 0;
}
