#include <time.h>
#include <string.h>

#define MAX_ENTRIES 100

typedef struct {
    unsigned int key;
    char* value;
    size_t length;
    time_t timestamp;
} entry;

entry* create_entries(size_t count, unsigned int min_key, unsigned int max_key, unsigned long seed) {
    if (count > MAX_ENTRIES) return NULL; // Limit the number of entries

    entry* entries = (entry*)calloc(count, sizeof(entry));
    if (!entries) return NULL; // Check for memory allocation failure

    srand(seed); // Seed the random number generator
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts); // Get high-resolution timestamp

    for (size_t i = 0; i < count; ++i) {
        entries[i].key = min_key + rand() % (max_key - min_key + 1);
        size_t len = rand() % 256 + 1; // Random string length
        entries[i].value = (char*)malloc(len * sizeof(char));
        if (!entries[i].value) {
            for (size_t j = 0; j < i; ++j) free(entries[j].value);
            free(entries);
            return NULL;
        }
        char* chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        for (size_t j = 0; j < len - 1; ++j) {
            entries[i].value[j] = chars[rand() % strlen(chars)];
        }
        entries[i].value[len - 1] = '\0';
        entries[i].length = len;
        entries[i].timestamp = ts.tv_sec + (ts.tv_nsec / 1e9);
    }

    return entries;
}

void free_entries(entry* entries, size_t count) {
    for (size_t i = 0; i < count; ++i) free(entries[i].value);
    free(entries);
}

int main() {
    srand(time(NULL)); // Seed the random number generator with the current time
    entry* logs = create_entries(10, 1000, 9999, 42); // Create 10 entries with keys between 1000 and 9999 using seed 42

    if (logs) {
        for (size_t i = 0; i < 10; ++i) {
            printf("Key: %u, Value: %s, Length: %zu, Timestamp: %ld\n", logs[i].key, logs[i].value, logs[i].length, logs[i].timestamp);
        }
        free_entries(logs, 10); // Free the allocated memory
    }

    return 0;
}
```

