typedef struct {
    int value;
    long timestamp;
    int count;
    float weighted_sum;
} Transaction;

void process_transactions(long seed, int max_transactions) {
    srand(seed);

    // Allocate memory for arrays
    long* offsets = (long*)malloc(max_transactions * sizeof(long));
    int* keys = (int*)malloc(max_transactions * sizeof(int));
    float* weights = (float*)malloc(max_transactions * sizeof(float));

    // Allocate memory for transactions array
    Transaction* transactions = (Transaction*)malloc(max_transactions * sizeof(Transaction));

    if (!offsets || !keys || !weights || !transactions) {
        // Handle memory allocation failure
        return;
    }

    // Initialize arrays and transaction structures with random values
    for (int i = 0; i < max_transactions; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 1000; // Assuming keys are in the range [0, 999]
        weights[i] = (float)rand() / RAND_MAX * 100.0f;

        transactions[i].value = rand() % 1000; // Assuming transaction values are in the range [0, 999]
        transactions[i].timestamp = time(NULL);
        transactions[i].count = rand() % 3 + 1; // Count of transactions in the past 3 seconds
        transactions[i].weighted_sum = (float)rand() / RAND_MAX * 100.0f;
    }

    // Filter and process transactions based on criteria
    float max_weighted_sum = 0.0f;
    int max_transaction_id = -1;
    long total_weighted_sum = 0;
    for (int i = 0; i < max_transactions; ++i) {
        if (transactions[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = transactions[i].weighted_sum;
            max_transaction_id = i;
        }
        total_weighted_sum += transactions[i].weighted_sum;
    }

    // Calculate metrics
    float average_weighted_sum = (float)total_weighted_sum / max_transactions;

    // Free allocated memory
    free(offsets);
    free(keys);
    free(weights);
    free(transactions);
}

int main() {
    long seed = time(NULL); // Use current time as a seed for reproducibility
    process_transactions(seed, 10000000); // Process up to 10 million transactions per second
    return 0;
}
