#include <pthread.h>

typedef struct {
    int value;
    char flag;
    size_t length;
} record;

record* create_record_array(size_t count, size_t max_data_size, long* offsets, int* keys, unsigned char** data, size_t offset_size, size_t key_size) {
    if (count > SIZE_MAX / sizeof(record)) return NULL; // Check for overflow
    record* array = malloc(count * sizeof(record));
    if (!array) return NULL;

    unsigned char* temp_data = malloc(count * max_data_size);
    if (!temp_data) {
        free(array);
        return NULL;
    }

    if (offsets) {
        offsets[0] = 0; // Initialize offset array
        for (size_t i = 1; i < count; ++i) {
            offsets[i] = offsets[i - 1] + temp_data[i - 1].length;
        }
    }

    if (keys) keys[0] = rand(); // Seed key generation

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        array[i].value = rand_r((unsigned int*)&keys[i]) % (max_data_size - temp_data[i].length); // Random value within range
        array[i].flag = 'A' + (i % 26); // Simple flag for demonstration
        array[i].length = temp_data[i].length;

        pthread_mutex_lock(&lock);
        data[i] = malloc(temp_data[i].length);
        if (!data[i]) {
            free(array);
            free(temp_data);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        memcpy(data[i], temp_data + offsets[i], temp_data[i].length); // Copy data to allocated memory
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    free(temp_data);
    return array;
}
