record* initialize_records(long* offsets, int* keys, record** records_ptr, size_t num_records, long min_offset, long max_offset, int seed, long min_time, long max_time) {
    if (!records_ptr || !*records_ptr) {
        *records_ptr = (record*)malloc(num_records * sizeof(record));
        if (*records_ptr == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
    }

    srand(seed);
    struct timeval tv;
    gettimeofday(&tv, NULL);
    srandom(tv.tv_usec ^ tv.tv_sec);

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
        keys[i] = rand();
        (*records_ptr)[i].value = min_offset + rand() % (max_offset - min_offset + 1);
        (*records_ptr)[i].timestamp = min_time + rand() % (max_time - min_time + 1);
        (*records_ptr)[i].active = (rand() % 2 == 0) ? true : false;
    }

    return *records_ptr;
}

void free_records(record** records_ptr, size_t num_records) {
    if (*records_ptr) {
        free(*records_ptr);
        *records_ptr = NULL;
    }
}

int filter_records(record* records, size_t num_records, time_t start_time, time_t end_time) {
    int count = 0;
    clock_t start = clock();
    for (size_t i = 0; i < num_records && ((clock() - start) / CLOCKS_PER_SEC <= 1); ++i) {
        if (records[i].timestamp >= start_time && records[i].timestamp <= end_time) {
            ++count;
        }
    }
    return count;
}
