#define MAX_RECORDS 1000

typedef struct {
    int value;
    time_t timestamp;
    bool active;
} record;

void generate_data(long *offsets, int *keys, unsigned char **data_blocks, record *records) {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 1000;

        data_blocks[i] = (unsigned char *)malloc(64);
        if (!data_blocks[i]) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        memset(data_blocks[i], 0, 64);

        records[i].value = rand() % 1000;
        records[i].timestamp = time(NULL) - (rand() % (60 * 60 * 24));
        records[i].active = (rand() % 2 == 0);
    }
}

void filter_records(record *records, int start_time, int end_time, record **filtered_records, int *num_filtered) {
    clock_t start = clock();
    for (*num_filtered = 0; *num_filtered < MAX_RECORDS; (*num_filtered)++) {
        if (records[*num_filtered].timestamp >= start_time && records[*num_filtered].timestamp <= end_time) {
            filtered_records[*num_filtered] = &records[*num_filtered];
        }
        if ((clock() - start) > CLOCKS_PER_SEC * 5) {
            // Abort filtering if processing time exceeds 5 seconds
            break;
        }
    }
}

void free_memory(unsigned char **data_blocks, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(data_blocks[i]);
    }
}
