    for (size_t i = 0; i < count; ++i) {
        uint64_t id;
        do {
            id = rand() % (max_id - min_id + 1) + min_id;
        } while (used_ids[id - min_id]);
        used_ids[id - min_id] = 1;

        txns[i].id = id;
