// Custom PRNG function
unsigned long custom_prng(unsigned long *seed) {
    *seed = (*seed * 1664525 + 1013904223) % 4294967296; // LCG parameters
    return *seed;
}

double generate_random_amount(double min, double max, unsigned long *seed) {
    unsigned long random_value = custom_prng(seed);
    return min + (max - min) * ((double)random_value / 4294967295.0);
}

transaction* initialize_transactions(int num_transactions, double amount_range_min, double amount_range_max, int* error_code) {
    if (num_transactions <= 0 || amount_range_min >= amount_range_max) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    if (!transactions) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    unsigned long seed = time(NULL); // Seed for PRNG
    int next_id = 1;

    for (int i = 0; i < num_transactions; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].ID = next_id++;
        transactions[i].amount = generate_random_amount(amount_range_min, amount_range_max, &seed);
    }

    *error_code = 0; // Success
    return transactions;
}

// Example usage and error handling
int main() {
    int num_transactions = 1000;
    double min_amount = 10.0, max_amount = 100.0;
    int error_code;

    transaction* transactions = initialize_transactions(num_transactions, min_amount, max_amount, &error_code);
    if (error_code == -1) {
        printf("Error: Invalid input parameters.\n");
    } else if (error_code == -2) {
        printf("Error: Memory allocation failed.\n");
    } else {
        // Process transactions
        free(transactions); // Don't forget to free the allocated memory when done
    }

    return 0;
}
