transaction* create_transactions(int num_transactions, double avg_transaction_size, int daily_volume) {
    srand(time(NULL));
    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    if (!transactions) return NULL;

    for (int i = 0; i < num_transactions; i++) {
        transactions[i].timestamp = time(NULL);
        transactions[i].id = rand() % daily_volume;
        double uniform_random = (double)rand() / RAND_MAX;
        double transaction_amount = avg_transaction_size * (1.0 + 2.0 * uniform_random - 1.0);
        transactions[i].amount = transaction_amount;
    }

    return transactions;
}

record* create_records(int num_records, int min_value, int max_value) {
    srand(time(NULL));
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) return NULL;

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    free(offsets);
    free(keys);

    return records;
}
