void addToLog(const char* message) {
    time_t now = time(NULL);
    snprintf(logBuffer.entries[logBuffer.tail].message, sizeof(logBuffer.entries[logBuffer.tail].message), "%s", message);
    logBuffer.entries[logBuffer.tail].timestamp = now;
    logBuffer.tail = (logBuffer.tail + 1) % MAX_LOG_SIZE;

    if (logBuffer.head == logBuffer.tail) {
        logBuffer.head = (logBuffer.head + 1) % MAX_LOG_SIZE;
    }
}

void* simulateNetworkOperation(void* arg) {
    Key* key = (Key*)arg;
