        addToLog("Failed to send key over network");
        pthread_exit(NULL);
    }
    addToLog("Successfully sent key over network");
    pthread_exit(NULL);
}

void processAndGenerateKeys(long seed, size_t numKeys, long offsetRangeStart, long offsetRangeEnd, int keyRangeStart, int keyRangeEnd) {
    srand(seed);

    OffsetRecord* offsets = (OffsetRecord*)malloc(numKeys * sizeof(OffsetRecord));
    Record* records = (Record*)malloc(numKeys * sizeof(Record));
    Key* keys = (Key*)malloc(numKeys * sizeof(Key));

    for (size_t i = 0; i < numKeys; ++i) {
        offsets[i].offset = rand() % (offsetRangeEnd - offsetRangeStart + 1) + offsetRangeStart;
        records[i].key = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        records[i].data.value = records[i].key;

        keys[i].id = rand();
        keys[i].buffer = (char*)malloc(256);
        snprintf(keys[i].buffer, sizeof(keys[i].buffer), "Key%d", i);
    }

    initLogBuffer();

    pthread_t threads[numKeys];
    for (size_t i = 0; i < numKeys; ++i) {
        if (pthread_create(&threads[i], NULL, simulateNetworkOperation, &keys[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (size_t i = 0; i < numKeys; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (size_t i = 0; i < numKeys; ++i) {
        free(keys[i].buffer);
    }

    free(offsets);
    free(records);
    free(keys);
}
