#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INIT_SIZE 10

typedef struct {
    long id;
    int priority;
    char status;
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} TransactionManager;

void init_transaction_manager(TransactionManager* manager) {
    manager->transactions = malloc(INIT_SIZE * sizeof(Transaction));
    if (!manager->transactions) exit(1);
    manager->capacity = INIT_SIZE;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void add_transaction(TransactionManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Transaction* new_transactions = realloc(manager->transactions, new_capacity * sizeof(Transaction));
        if (!new_transactions) {
            pthread_mutex_unlock(&manager->mutex);
            exit(1);
        }
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }
    manager->transactions[manager->size].id = time(NULL);
    manager->transactions[manager->size].priority = rand();
    manager->transactions[manager->size].status = (char)(rand() % 26 + 'A');
    manager->size++;
    pthread_mutex_unlock(&manager->mutex);
}

void free_transaction_manager(TransactionManager* manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager->transactions);
}

int main() {
    srand(time(NULL));
    TransactionManager manager;
    init_transaction_manager(&manager);

    for (int i = 0; i < 20; i++) {
        add_transaction(&manager);
    }

    free_transaction_manager(&manager);
    return 0;
}
