        entries[i].timestamp = (long)(rand() % 86400 + time(NULL)); // Random timestamp within a day
        entries[i].eventID = rand() % 1000; // Random event ID between 0 and 999

        eventDescriptions[i] = (char*)malloc(MAX_EVENT_DESCRIPTION_LENGTH);
        if (!eventDescriptions[i]) {
            for (int j = 0; j < i; ++j) {
                free(eventDescriptions[j]);
