        fgets(eventDescriptions[i], MAX_EVENT_DESCRIPTION_LENGTH, stdin);
        eventDescriptions[i][strcspn(eventDescriptions[i], "\n")] = '\0'; // Remove newline character
        strncpy(entries[i].description, eventDescriptions[i], sizeof(entries[i].description) - 1);
    }

    for (int i = 0; i < numEvents; ++i) {
        free(eventDescriptions[i]);
    }
    free(eventDescriptions);

    return entries;
}

void printLogEntries(logEntry* entries, int numEvents) {
    qsort(entries, numEvents, sizeof(logEntry), [](const void* a, const void* b) {
        return ((logEntry*)a)->timestamp - ((logEntry*)b)->timestamp;
    });

    for (int i = 0; i < numEvents; ++i) {
        printf("Event ID: %d, Timestamp: %ld, Description: %s\n", entries[i].eventID, entries[i].timestamp, entries[i].description);
    }
}

void freeLogEntries(logEntry* entries, int numEvents) {
    for (int i = 0; i < numEvents; ++i) {
        // No need to free descriptions as they are part of the logEntry structure
    }
    free(entries);
}

int main() {
    int numEvents;
    unsigned int seed;

    printf("Enter number of events: ");
    scanf("%d", &numEvents);

    printf("Enter random seed for reproducibility: ");
    scanf("%u", &seed);

    logEntry* entries = createLogEntries(numEvents, seed);
    if (entries) {
        printLogEntries(entries, numEvents);
        freeLogEntries(entries, numEvents);
    }

    return 0;
}
