typedef struct {
    int value;
    time_t timestamp;
    bool active;
} record;

typedef struct {
    unsigned char data[64];
    int version;
    char source[32];
} metadata;

record* create_records(int count, int key_range_start, int key_range_end, double max_processing_time);
void filter_records(record** records, int* count, time_t start_time, time_t end_time);
void free_records(record** records, int* count);

int main() {
    srand(time(NULL));
    record *records = NULL;
    int count = 0;

    // Create records
    records = create_records(1000, 0, 100, 0.5);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return EXIT_FAILURE;
    }

    // Filter records
    time_t start_time = time(NULL) - 86400; // 24 hours ago
    time_t end_time = time(NULL);
    filter_records(&records, &count, start_time, end_time);

    // Free records
    free_records(&records, &count);

    return EXIT_SUCCESS;
}

record* create_records(int count, int key_range_start, int key_range_end, double max_processing_time) {
    record *new_records = malloc(count * sizeof(record));
    if (new_records == NULL) {
        return NULL;
    }

    metadata *metadata_array = malloc(count * sizeof(metadata));
    if (metadata_array == NULL) {
        free(new_records);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        new_records[i].value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        new_records[i].timestamp = time(NULL);
        new_records[i].active = (rand() % 2 == 0);

        // Initialize metadata
        memset(metadata_array[i].data, 0, sizeof(metadata_array[i].data));
        metadata_array[i].version = rand() % 100;
        snprintf(metadata_array[i].source, sizeof(metadata_array[i].source), "Source-%d", i);
    }

    // Simulate filtering based on processing time
    clock_t start_time = clock();
    for (int i = count - 1; i >= 0; i--) {
        if ((double)(clock() - start_time) / CLOCKS_PER_SEC > max_processing_time) {
            break;
        }
        if (!new_records[i].active) {
            memmove(&new_records[i], &new_records[i + 1], (count - i - 1) * sizeof(record));
            metadata_array--;
            count--;
        }
    }

    return new_records;
}

void filter_records(record** records, int* count, time_t start_time, time_t end_time) {
    record *filtered_records = malloc((*count) * sizeof(record));
    if (filtered_records == NULL) {
        fprintf(stderr, "Failed to allocate memory for filtered records.\n");
        return;
    }

    int filter_count = 0;
    for (int i = 0; i < *count; i++) {
        if ((*records)[i].timestamp >= start_time && (*records)[i].timestamp <= end_time) {
            filtered_records[filter_count++] = (*records)[i];
        }
    }

    free(*records);
    *records = filtered_records;
    *count = filter_count;
}

void free_records(record** records, int* count) {
    free(*records);
    free(metadata_array);
}
