#include <time.h>

#define MAX_KEYS 1000

typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->capacity = initial_capacity;
    pool->offsets = (long *)malloc(initial_capacity * sizeof(long));
    pool->keys = (int *)malloc(initial_capacity * sizeof(int));
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->offsets);
    free(pool->keys);
    free(pool);
}

int generate_key() {
    // Simple PRNG using time and process ID for uniqueness
    static unsigned long seed = 0;
    if (seed == 0) seed = time(NULL) ^ getpid();
    return (int)((seed++ * 2654435761U) % MAX_KEYS);
}

void initialize_pool(MemoryPool *pool, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        pool->offsets[i] = rand();
        pool->keys[i] = generate_key();
    }
}

int main() {
    MemoryPool *pool = create_memory_pool(MAX_KEYS);
    if (!pool) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_pool(pool, MAX_KEYS);

    // Simulate usage
    for (size_t i = 0; i < MAX_KEYS; ++i) {
        printf("Offset: %ld, Key: %d\n", pool->offsets[i], pool->keys[i]);
    }

    destroy_memory_pool(pool);
    return 0;
}
