// Custom PRNG function (example: Mersenne Twister)
unsigned long custom_random(unsigned long seed) {
    static unsigned long mt[624], index = 0;
    unsigned long y;

    if (index == 0) {
        for (int i = 0; i < 624; ++i) {
            mt[i] = seed;
            seed = (seed * 1965025883U + 1111111111U) & 0xFFFFFFFFUL;
        }
    }

    if (index == 624) {
        for (int i = 0; i < 624; ++i) {
            y = (mt[i] & 0x80000000UL) | (mt[(i + 1) % 624] & 0x7FFFFFFFUL);
            mt[i] = mt[(i + 397) % 624] ^ (y >> 1);
            if (y & 1) {
                mt[i] ^= 0x9908B0DFUL;
            }
        }
        index = 0;
    }

    y = mt[index++];
    y ^= y >> 11;
    y ^= (y << 7) & 0x9D2C5680UL;
    y ^= (y << 15) & 0xEFC60000UL;
    y ^= y >> 18;

    return y;
}

void allocate_and_initialize_arrays(long *offsets, int *keys, Record **records, int size, unsigned long seed) {
    offsets = malloc(size * sizeof(*offsets));
    keys = malloc(size * sizeof(*keys));
    records = malloc(size * sizeof(*records));

    for (int i = 0; i < size; ++i) {
        offsets[i] = custom_random(seed);
        keys[i] = custom_random(seed);

        records[i] = malloc(sizeof(**records));
        records[i]->value = custom_random(seed) % 1000; // Random value between 0 and 999
        records[i]->timestamp = time(NULL);
        records[i]->status_flag = (custom_random(seed) % 2) ? 1 : 0;
    }
}

void free_arrays(long *offsets, int *keys, Record **records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i]);
    }

