// Define a simple record structure
typedef struct {
    int value;
} Record;

// Function to initialize arrays with random values using a high-performance PRNG
void initArrays(long *offsets, int *keys, Record *records, size_t count) {
    // Initialize the PRNG state
    unsigned long seed = 12345; // Example seed for reproducibility
    srand(seed);

    // Fill arrays with random values
    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 1000000L; // Random offset within a range
        keys[i] = rand() % 1000000;   // Random key within a range

        // Initialize record with random value
        records[i].value = rand() % 100000;
    }
}

// Function to find and print the maximum integer in an array
void findMaxInteger(int *array, size_t count) {
    if (count == 0) {
        printf("Array is empty.\n");
        return;
    }

    int max = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Maximum integer: %d\n", max);
}

// Function to free allocated memory
void cleanup(long *offsets, int *keys, Record *records, size_t count) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    size_t count;
    printf("Enter the number of records: ");
    scanf("%zu", &count);

    // Allocate memory for arrays
    long *offsets = malloc(count * sizeof(long));
    int *keys = malloc(count * sizeof(int));
    Record *records = malloc(count * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    // Initialize arrays
    initArrays(offsets, keys, records, count);

    // Read integers from standard input and store them in an array
    int *inputArray = malloc(count * sizeof(int));
    for (size_t i = 0; i < count; ++i) {
        printf("Enter integer %zu: ", i + 1);
        scanf("%d", &inputArray[i]);
    }

    // Find and print the maximum integer
    findMaxInteger(inputArray, count);

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
    free(inputArray);

    return 0;
}
