const xml2js = require('xml2js');
const fs = require('fs').promises;
const path = require('path');

class NotFoundError extends Error {}
class MultipleMatchesError extends Error {}

let parsedXmlCache = {};

async function fetchAndProcessXmlDataAsync(xmlString, elementName, processCallback, config) {
    const { baseDir } = config;

    if (!baseDir || typeof baseDir !== 'string') {
        throw new Error('Invalid base directory path');
    }

    let xmlFilePath;
    try {
        xmlFilePath = resolvePath(baseDir, xmlString);
    } catch (error) {
        throw new Error(`Failed to resolve XML file path: ${error.message}`);
    }

    let xmlData;
    if (!parsedXmlCache[xmlFilePath]) {
        try {
            const xmlContent = await fs.readFile(xmlFilePath, 'utf-8');
            xmlData = await parseXmlString(xmlContent);
            parsedXmlCache[xmlFilePath] = xmlData;
        } catch (error) {
            throw new Error(`Failed to read or parse XML file: ${error.message}`);
        }
    } else {
        xmlData = parsedXmlCache[xmlFilePath];
    }

    const matchingElements = xmlData[elementName];
    if (!matchingElements || matchingElements.length === 0) {
        throw new NotFoundError(`No elements found with the name '${elementName}'`);
    } else if (matchingElements.length > 1) {
        throw new MultipleMatchesError(`Multiple elements found with the name '${elementName}'`);
    }

    const firstElement = matchingElements[0];
    await processCallback(firstElement);
}

function resolvePath(baseDir, xmlString) {
    try {
        const xmlDoc = new DOMParser().parseFromString(xmlString, 'application/xml');
        const rootElement = xmlDoc.documentElement;
        if (rootElement.getAttribute('base')) {
            return path.resolve(baseDir, rootElement.getAttribute('base'));
        }
        throw new Error('Base directory not specified in XML');
    } catch (error) {
        throw new Error(`Failed to resolve base directory from XML: ${error.message}`);
    }
}

async function parseXmlString(xmlString) {
    return new Promise((resolve, reject) => {
        xml2js.parseString(xmlString, (err, result) => {
            if (err) {
                reject(err);
            } else {
                resolve(result);
            }
        });
    });
}

// Unit tests
async function runTests() {
    try {
        // Test cases go here
        console.log('All tests passed!');
    } catch (error) {
        console.error(`Test failed: ${error.message}`);
    }
}

runTests();
