} record;

record* create_records(int count, int min_value, int max_value, unsigned long seed) {
    srand(seed);
    record *r = (record *)malloc(count * sizeof(record));
    if (r == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < count; ++i) {
        r[i].value = min_value + rand() % (max_value - min_value + 1);
    }
    printf("Seed: %lu\n", seed);
    printf("Total Records Generated: %d\n", count);
    return r;
}

void find_and_print_max(record *r, int count) {
    if (count == 0) {
        printf("No records to process.\n");
        return;
    }
    int max = r[0].value;
    for (int i = 1; i < count; ++i) {
        if (r[i].value > max) {
            max = r[i].value;
        }
    }
    printf("Largest Value: %d\n", max);
}

void free_records(record *r, int count) {
    free(r);
}

int main() {
    unsigned long seed = time(NULL);
    int count = 100;
    int min_value = 0;
    int max_value = 100;

    record *records = create_records(count, min_value, max_value, seed);
    if (records != NULL) {
        find_and_print_max(records, count);
