// Define the structure for sensor events
typedef struct {
    unsigned long timestamp;
    float reading;
} sensorEvent;

// Define the structure for records
typedef struct {
    int value;
} record;

// Function to initialize arrays with random data
void processSensorData(int seed, int range, FILE* file) {
    srand(seed);

    // Allocate memory for arrays
    unsigned long* timestamps = (unsigned long*)malloc(100 * sizeof(unsigned long));
    float* readings = (float*)malloc(100 * sizeof(float));
    sensorEvent* events = (sensorEvent*)malloc(100 * sizeof(sensorEvent));
    long* offsets = (long*)malloc(100 * sizeof(long));

    // Allocate memory for records
    record* records = (record*)malloc(100 * sizeof(record));

    // Initialize arrays with random data
    for (int i = 0; i < 100; i++) {
        timestamps[i] = time(NULL) + i;
        readings[i] = ((float)rand() / RAND_MAX) * range;
        events[i].timestamp = timestamps[i];
        events[i].reading = readings[i];
        offsets[i] = (long)((double)rand() / RAND_MAX) * 1000;

        records[i].value = rand() % range;
    }

    // Process sensor data from file and calculate average readings per hour
    float sum[24] = {0};
    int count[24] = {0};

    while (!feof(file)) {
        unsigned long timestamp;
        float reading;
        fscanf(file, "%lu %f", &timestamp, &reading);

        int hour = timestamp / 3600 % 24;
        sum[hour] += reading;
        count[hour]++;
    }

    for (int i = 0; i < 24; i++) {
        if (count[i] > 0) {
            printf("Average sensor reading at hour %d: %.2f\n", i, sum[i] / count[i]);
        }
    }

    // Free allocated memory
    free(timestamps);
    free(readings);
    free(events);
    free(offsets);
    free(records);

    fclose(file);
}

int main() {
    FILE* file = fopen("sensor_data.txt", "r");
    if (file == NULL) {
        perror("Failed to open sensor data file");
        return EXIT_FAILURE;
    }

    processSensorData(42, 100, file);

    fclose(file);
    return EXIT_SUCCESS;
}
