// Pseudo-random number generator using the Mersenne Twister algorithm
unsigned long mt_rand(unsigned long lower, unsigned long upper) {
    static unsigned long mt[624];
    static int index = 624;

    if (index == 624) {
        for (int i = 0; i < 624; ++i) {
            mt[i] = mt[(i + 397) % 624] ^ (mt[i] >> 1);
            if (mt[i] & 1) {
                mt[i] ^= 0x9908B0DF;
            }
        }
        index = 0;
    }

    unsigned long y = mt[index++];
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9D2C5680;
    y ^= (y << 15) & 0xEFC60000;
    y ^= (y >> 18);

    return lower + (y % (upper - lower + 1));
}

// Function to dynamically allocate memory for and initialize arrays
void dataProcessor() {
    long *offsets = malloc(100 * sizeof(long));
    char **labels = malloc(100 * sizeof(char *));
    double *values = malloc(100 * sizeof(double));
    int *integers = malloc(100 * sizeof(int));
