#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
} allocation_result;

allocation_result* allocate_records(size_t count, int min_value, int max_value, unsigned long seed) {
    allocation_result *result = (allocation_result *)malloc(sizeof(allocation_result));
    if (!result) return NULL;

    result->offsets = (long *)malloc(count * sizeof(long));
    if (!result->offsets) {
        free(result);
        return NULL;
    }

    result->keys = (int *)malloc(count * sizeof(int));
    if (!result->keys) {
        free(result->offsets);
        free(result);
        return NULL;
    }

    result->records = (record *)malloc(count * sizeof(record));
    if (!result->records) {
        free(result->keys);
        free(result->offsets);
        free(result);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        result->records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    result->count = count;

    pthread_mutex_destroy(&lock);
    return result;
}
