#define MAX_DATASETS 10

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    metadata* metadata;
} dataset;

typedef struct {
    int value;
} record;

typedef struct {
    time_t timestamp;
    int valid;
} metadata;

void initialize_dataset(dataset** datasets, int num_datasets, int* sizes, int* key_ranges, int* record_ranges) {
    for (int i = 0; i < num_datasets; i++) {
        datasets[i] = malloc(sizeof(dataset));
        if (!datasets[i]) {
            fprintf(stderr, "Memory allocation failed for dataset %d\n", i);
            exit(EXIT_FAILURE);
        }

        datasets[i]->offsets = malloc(sizes[i] * sizeof(long));
        datasets[i]->keys = malloc(sizes[i] * sizeof(int));
        datasets[i]->records = malloc(sizes[i] * sizeof(record));
        datasets[i]->metadata = malloc(sizes[i] * sizeof(metadata));

        if (!datasets[i]->offsets || !datasets[i]->keys || !datasets[i]->records || !datasets[i]->metadata) {
            fprintf(stderr, "Memory allocation failed for dataset %d\n", i);
            exit(EXIT_FAILURE);
        }

        // Initialize with pseudo-random values
        srand(time(NULL));
        for (int j = 0; j < sizes[i]; j++) {
            datasets[i]->offsets[j] = rand();
            datasets[i]->keys[j] = key_ranges[2 * i] + rand() % (key_ranges[2 * i + 1] - key_ranges[2 * i]);
            datasets[i]->records[j].value = record_ranges[2 * i] + rand() % (record_ranges[2 * i + 1] - record_ranges[2 * i]);
            datasets[i]->metadata[j].timestamp = time(NULL);
            datasets[i]->metadata[j].valid = (rand() % 2) == 0;
        }
    }
}

void free_datasets(dataset** datasets, int num_datasets) {
    for (int i = 0; i < num_datasets; i++) {
        if (datasets[i]) {
            free(datasets[i]->offsets);
            free(datasets[i]->keys);
            free(datasets[i]->records);
            free(datasets[i]->metadata);
            free(datasets[i]);
            datasets[i] = NULL;
        }
    }
}

void validate_metadata(dataset** datasets, int num_datasets) {
    for (int i = 0; i < num_datasets; i++) {
        if (datasets[i]) {
            for (int j = 0; j < sizes[i]; j++) {
                if (!datasets[i]->metadata[j].valid) {
                    fprintf(stderr, "Metadata validation failed for dataset %d, record %d\n", i, j);
                }
            }
        }
    }
}

int main() {
    int sizes[MAX_DATASETS] = {100, 200, 300}; // Example sizes
    int key_ranges[MAX_DATASETS * 2] = {0, 1000, 1001, 2000, 2001, 3000}; // Example ranges
    int record_ranges[MAX_DATASETS * 2] = {10, 50, 51, 100, 101, 500}; // Example ranges

    dataset* datasets[MAX_DATASETS];

    initialize_dataset(datasets, MAX_DATASETS, sizes, key_ranges, record_ranges);

    validate_metadata(datasets, MAX_DATASETS);

    free_datasets(datasets, MAX_DATASETS);

    return 0;
}
