long* allocate_offsets(int size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocate_keys(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocate_records(int size) {
    return (record*)calloc(size, sizeof(record));
}

void initialize_records(record* records, int size, int* keys, int key_size) {
    for (int i = 0; i < size && i < key_size; ++i) {
        records[i].identifier = 'A' + rand() % 26;
        records[i].value = keys[i];
    }
}

void fill_offsets(long* offsets, int size, record* records, int record_size) {
    for (int i = 0; i < size && i < record_size; ++i) {
        offsets[i] = (long)&records[i];
    }
}

char* generate_unique_identifier() {
    static char identifier[33]; // 32 characters + null terminator
    FILE* fp;
    fp = fopen("/dev/urandom", "r");
    if (fp != NULL) {
        fread(identifier, sizeof(char), 32, fp);
        fclose(fp);
        identifier[32] = '\0';
    } else {
        // Fallback to time-based identifier
        srand(time(NULL));
        for (int i = 0; i < 32; ++i) {
            identifier[i] = 'a' + rand() % 26;
        }
        identifier[32] = '\0';
    }
    return identifier;
}

void populate_records_with_identifiers(record* records, int size) {
    for (int i = 0; i < size; ++i) {
        records[i].identifier = *generate_unique_identifier();
    }
}

// Example usage
int main() {
    int size = 10;
    long* offsets = allocate_offsets(size);
    int* keys = allocate_keys(size);
    record* records = allocate_records(size);

    // Simulate external key retrieval with potential latency and errors
    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % 100;
        if ((i + 1) % 2 == 0) {
            // Introduce a fake missing entry for demonstration purposes
            break;
        }
    }

    initialize_records(records, size, keys, (int)(sizeof(keys) / sizeof(keys[0])));
    fill_offsets(offsets, size, records, (int)(sizeof(records) / sizeof(records[0])));

    populate_records_with_identifiers(records, size);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
