int findLargestInteger(int* array, int size) {
    if (size == 0) {
        fprintf(stderr, "Empty input\n");
        exit(1);
    }
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}
