function traverseDOM(rootNode, selectorFunction) {
    let elements = [];

    function recursiveTraverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE && selectorFunction(node)) {
            elements.push(node);
        }
        for (let child of node.childNodes) {
            recursiveTraverse(child);
        }
    }

    try {
        recursiveTraverse(rootNode);
    } catch (e) {
        console.error("Invalid DOM structure or selector function", e);
    }

    return elements;
}
