void printLogEntries(const logEntry* entries, size_t numEntries) {
    for (size_t i = 0; i < numEntries; ++i) {
        printf("Event ID: %d, Timestamp: %ld, Duration: %.2f, Description: %s\n",
               entries[i].eventID, entries[i].timestamp, entries[i].duration, entries[i].description);
    }
}

