void processFinancialTransactions(const char* transactionFile, const LogSchema* logSchema,
                                ExternalDataSource* externalDataSource, int timeoutDuration,
                                const char* logDirectory, TempDatabaseConnection* tempDatabase) {
    // Initialize CSPRG with a unique seed from the external data source
    initCSPRG(externalDataSource->getSeed());

    // Open transaction file for reading
    FILE* transactionsFile = fopen(transactionFile, "r");
    if (!transactionsFile) {
        logError("Failed to open transaction file.");
        return;
    }

    // Initialize circular buffer for logs
    LogBuffer* logBuffer = initLogBuffer(logDirectory);

    // Set up timeout mechanism
    struct timespec startTime, currentTime;
    clock_gettime(CLOCK_REALTIME, &startTime);

    while (1) {
        // Check if the processing time has exceeded the timeout duration
        clock_gettime(CLOCK_REALTIME, &currentTime);
        if ((currentTime.tv_sec - startTime.tv_sec) > timeoutDuration) {
            logError("Processing timed out.");
            break;
        }

        // Read a transaction from the file
        FinancialTransaction* transaction = readNextTransaction(transactionsFile);
        if (!transaction) {
            break; // End of file or error reading transaction
        }

        // Validate the transaction input
        if (!validateTransaction(transaction)) {
            logError("Invalid transaction input.");
            freeTransaction(transaction);
            continue;
        }

        // Generate a unique transaction ID using CSPRG
        uint64_t transactionID = generateUniqueID();

        // Store the transaction in the temporary database
        if (storeTransaction(tempDatabase, transactionID, transaction)) {
            logInfo("Transaction stored successfully.");
        } else {
            logError("Failed to store transaction.");
        }

        // Free allocated memory for the transaction
        freeTransaction(transaction);
    }

    // Close the transaction file
    fclose(transactionsFile);

    // Clean up resources
    destroyCSPRG();
    freeLogBuffer(logBuffer);
}
