#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int eventID;
    float dataValue;
} logEntry;

int initLogBuffer(long *timestamps, int *eventIDs, float *dataValues, logEntry **entries, size_t capacity) {
    srand(time(NULL));
    timestamps = (long *)malloc(capacity * sizeof(long));
    if (!timestamps) return -1;

    eventIDs = (int *)malloc(capacity * sizeof(int));
    if (!eventIDs) {
        free(timestamps);
        return -1;
    }

    dataValues = (float *)malloc(capacity * sizeof(float));
    if (!dataValues) {
        free(eventIDs);
        free(timestamps);
        return -1;
    }

    entries = (logEntry **)malloc(capacity * sizeof(logEntry *));
    if (!entries) {
        free(dataValues);
        free(eventIDs);
        free(timestamps);
        return -1;
    }

    for (size_t i = 0; i < capacity; ++i) {
        timestamps[i] = time(NULL);
        eventIDs[i] = rand() % 1000; // Random event ID between 0 and 999
        dataValues[i] = ((float)rand() / RAND_MAX) * 100.0f; // Random data value between 0 and 100

        entries[i] = (logEntry *)malloc(sizeof(logEntry));
        if (!entries[i]) {
            for (size_t j = 0; j < i; ++j) free(entries[j]);
            free(entries);
            free(dataValues);
            free(eventIDs);
            free(timestamps);
            return -1;
        }
        entries[i]->timestamp = timestamps[i];
        entries[i]->eventID = eventIDs[i];
        entries[i]->dataValue = dataValues[i];
    }

    return 0;
}

void destroyLogBuffer(long *timestamps, int *eventIDs, float *dataValues, logEntry **entries, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) free(entries[i]);
    free(entries);
    free(dataValues);
    free(eventIDs);
    free(timestamps);
}

int main() {
    long *timestamps;
    int *eventIDs;
    float *dataValues;
    logEntry **entries;
    size_t capacity = 1000;

    if (initLogBuffer(timestamps, eventIDs, dataValues, entries, capacity) == 0) {
        // Use the log buffer here
        destroyLogBuffer(timestamps, eventIDs, dataValues, entries, capacity);
    }

    return 0;
}
