// Define a structure for records
typedef struct {
    int value;
} Record;

// Function to initialize arrays and records securely
void init_arrays(int* offsets, long* keys, Record** records, int size, int seed) {
    srand(seed); // Seed the random number generator

    // Allocate memory for offsets and keys arrays
    if ((offsets = (int*)malloc(size * sizeof(int))) == NULL || 
        (keys = (long*)malloc(size * sizeof(long))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records array
    if ((*records = (Record*)malloc(size * sizeof(Record))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Fill records with random values within a specified range
    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % 1000 + 1; // Random value between 1 and 1000
    }
}

// Helper function to find the largest integer in an array
int find_largest(int* array, int size) {
    if (size == 0) return -1; // Return -1 for empty array

    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to read integers from standard input and validate them
void read_input(int* input_array, int* size) {
    printf("Enter the number of elements: ");
    if (scanf("%d", size) != 1 || *size <= 0) {
        fprintf(stderr, "Invalid input for number of elements\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the input array
    if ((input_array = (int*)malloc(*size * sizeof(int))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers:\n", *size);
    for (int i = 0; i < *size; i++) {
        if (scanf("%d", &input_array[i]) != 1) {
            fprintf(stderr, "Invalid input at index %d\n", i);
            free(input_array);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to clean up allocated memory
void cleanup(int* offsets, long* keys, Record* records, int size) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int* input_array;
    int size;
    int largest;

    // Read and validate inputs from standard input
    read_input(input_array, &size);

    // Initialize arrays and records securely
    int* offsets;
    long* keys;
    Record* records;
    init_arrays(offsets, keys, &records, size, time(NULL)); // Seed with current time

    // Copy validated integers to an array of records
    for (int i = 0; i < size; i++) {
        records[i].value = input_array[i];
    }

    // Find and print the largest integer
    largest = find_largest(input_array, size);
    printf("Largest number: %d\n", largest);

    // Clean up allocated memory
    cleanup(offsets, keys, records, size);

    return 0;
}
