#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned int id;
    char* description;
    float value;
    double weight;
    short index;
} entry;

entry* create_entries(int num_entries, float range_min, float range_max, const char* seed_str) {
    if (num_entries <= 0) {
        fprintf(stderr, "Invalid number of entries\n");
        return NULL;
    }

    entry* entries = malloc(num_entries * sizeof(entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    unsigned int seed = 0;
    if (seed_str && strlen(seed_str) > 0) {
        sscanf(seed_str, "%u", &seed);
    } else {
        seed = time(NULL);
    }
    srand(seed);

    char* descriptions[] = {"Description1", "Description2", "Description3"};
    int desc_count = sizeof(descriptions) / sizeof(descriptions[0]);

    for (int i = 0; i < num_entries; ++i) {
        entries[i].id = i;
        entries[i].description = strdup(descriptions[rand() % desc_count]);
        entries[i].value = range_min + ((float)rand()) * (range_max - range_min) / RAND_MAX;
        entries[i].weight = (double)(rand() % 10000) / 100.0; // Random weight between 0 and 100
        entries[i].index = rand() % 256; // Random index between 0 and 255
    }

    return entries;
}

void free_entries(entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].description);
    }
    free(entries);
}

// Example usage:
int main(int argc, char* argv[]) {
    int num_entries = 100;
    float range_min = 0.0f;
    float range_max = 1.0f;
    const char* seed_str = "12345";

    entry* entries = create_entries(num_entries, range_min, range_max, seed_str);
    if (entries) {
        // Process entries
        free_entries(entries, num_entries);
    }

    return 0;
}
