typedef struct {
    int type; // 0 for int, 1 for double
    union {
        int i;
        double d;
    } value;
} Record;

enum OperationFlag {
    NONE,
    PROCESS_DATA,
    SAVE_TO_DISK
};

void initializeArrays(long* offsets, long* timestamps, int* seeds, double* keys, Record** records, enum OperationFlag* flags, int numRecords, int seedValue) {
    srand(time(NULL)); // Seed PRNG with current time

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % 1000L;
        timestamps[i] = time(NULL);
        seeds[i] = rand() % 100 + seedValue;
        keys[i] = (double)rand() / RAND_MAX * 100.0;

        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            exit(1);
        }

        int choice = rand() % 2;
        records[i]->type = choice;
        if (choice == 0) {
            records[i]->value.i = rand() % 100;
        } else {
            records[i]->value.d = (double)rand() / RAND_MAX * 100.0;
        }
    }

    // Seed PRNG with a unique value
    unsigned long totalSeed = seedValue + time(NULL);
    srand(totalSeed);

    for (int i = 0; i < numRecords; i++) {
        if (flags[i] == PROCESS_DATA) {
            // Perform additional processing steps here
            printf("Processing record %d\n", i);
        }
        if (flags[i] == SAVE_TO_DISK) {
            // Save to disk logic here
            printf("Saving record %d to disk\n", i);
        }
    }

    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
}
