typedef struct Record {
    int key;
    long offset;
} Record;

Record* process_records(Record* records, int num_records, char* input, int max_size) {
    if (records == NULL || num_records <= 0 || input == NULL || max_size <= 0) {
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records - 1; i++) {
        long offset = rand() % max_size;
        for (int j = 0; j < i; j++) {
            if (records[j].offset == offset) {
                i--; // Retry generating the offset
                break;
            }
        }
        records[i].offset = offset;
    }

    if (strlen(input) < max_size) {
        input[strlen(input)] = '/';
        return input;
    } else {
        return NULL; // String is too long, cannot append '/'
    }
}

int main() {
    Record* records = malloc(3 * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    records[0].key = 1;
    records[1].key = 2;
    records[2].key = 3;

    char* input = strdup("example");
    if (input == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(records);
        return 1;
    }

    char* result = process_records(records, 3, input, 10);
    if (result != NULL) {
        printf("Processed string: %s\n", result);
    } else {
        printf("Failed to process string\n");
    }

    free(input);
    free(records);

