record* allocate_and_init_arrays(long* offset_arr, int* key_arr, int min_val, int max_val, size_t max_size) {
    srand(time(NULL)); // Seed the random number generator
    size_t total_size = sizeof(long) * 3 + sizeof(record) * MAX_RECORD_SIZE;
    if (total_size > max_size) {
        return NULL; // Not enough memory
    }

    long* offset_arr_ptr = (long*)malloc(sizeof(long) * 3);
    int* key_arr_ptr = (int*)(offset_arr_ptr + 3);
    record* records_ptr = (record*)((char*)key_arr_ptr + sizeof(int) * MAX_RECORD_SIZE);

    if (!offset_arr_ptr || !key_arr_ptr || !records_ptr) {
        return NULL; // Memory allocation failed
    }

    offset_arr[0] = 10L;
    offset_arr[1] = 20L;
    offset_arr[2] = 30L;

    for (int i = 0; i < MAX_RECORD_SIZE; ++i) {
        key_arr[i] = rand() % (max_val - min_val + 1) + min_val;
        records_ptr[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    return records_ptr;
}

void calculate_md5(const char* input, unsigned char output_buffer[MD5_DIGEST_LENGTH]) {
    MD5_CTX mdContext;
    MD5_Init(&mdContext);
    MD5_Update(&mdContext, input, strlen(input));
    MD5_Final(output_buffer, &mdContext);
