#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define NUM_THREADS 4

typedef struct {
    long offset;
    int key;
    char data[256];
} DataRecord;

DataRecord records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void* producer(void* arg) {
    srand(time(NULL));
    while (1) {
        pthread_mutex_lock(&mutex);
        if (record_count >= MAX_RECORDS) {
            pthread_cond_wait(&cond_var, &mutex);
        }
        records[record_count].offset = rand();
        records[record_count].key = rand() % 100;
        snprintf(records[record_count].data, sizeof(records[record_count].data), "Data-%d", record_count);
        record_count++;
        pthread_mutex_unlock(&mutex);
    }
}

void* consumer(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (record_count == 0) {
            pthread_cond_signal(&cond_var);
        } else {
            int index = rand() % record_count;
            printf("Consumed: Offset=%ld, Key=%d, Data=%s\n", records[index].offset, records[index].key, records[index].data);
            memmove(records + index, records + index + 1, (record_count - index - 1) * sizeof(DataRecord));
            record_count--;
        }
        pthread_mutex_unlock(&mutex);
    }
}

int main() {
    pthread_t producers[NUM_THREADS], consumers[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&producers[i], NULL, producer, NULL);
        pthread_create(&consumers[i], NULL, consumer, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(producers[i], NULL);
        pthread_join(consumers[i], NULL);
    }

    return 0;
}
