#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define LOG_FILE "events.log"

typedef struct {
    int value;
    double timestamp;
} Record;

typedef struct {
    Record record;
    char description[256];
    char type[32];
} Event;

void log_event(char* description, char* type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s - %s\n", type, description);
        fclose(fp);
    }
}

Event* create_events(int seed, int min_value, int max_value, int log_level) {
    srand(seed);
    Event* events = malloc(MAX_RECORDS * sizeof(Event));
    if (events == NULL) {
        fprintf(stderr, "Memory allocation failed for events.\n");
        return NULL;
    }

    int record_count = 0;

    while (1) {
        char input[256];
        printf("Enter an integer (or 'q' to quit): ");
        fgets(input, sizeof(input), stdin);
        if (input[0] == 'q') {
            break;
        }

        int key;
        if (sscanf(input, "%d", &key) != 1) {
            log_event("Invalid input received.", "WARNING");
            continue;
        }

        Record record;
        record.value = rand() % (max_value - min_value + 1) + min_value;
        record.timestamp = time(NULL);

        Event event;
        strcpy(event.description, "Generated record");
        strcpy(event.type, "INFO");
        event.record = record;

        events[record_count++] = event;

        if (log_level == 1) {
            log_event("Event generated", "INFO");
        }

        if (record_count >= MAX_RECORDS) {
            break;
        }
    }

    // Clean up allocated memory
    for (int i = 0; i < record_count; i++) {
        free(events[i].description);
        free(events[i].type);
    }
    free(events);

    return events;
}

int main() {
    int seed, min_value, max_value, log_level;

    printf("Enter seed value: ");
    scanf("%d", &seed);
    printf("Enter minimum value for records: ");
    scanf("%d", &min_value);
    printf("Enter maximum value for records: ");
    scanf("%d", &max_value);
    printf("Enter log level (0 for none, 1 for info): ");
    scanf("%d", &log_level);

    Event* events = create_events(seed, min_value, max_value, log_level);

    if (events != NULL) {
        printf("Events created successfully.\n");
        free(events);
    }

    return 0;
}
