import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TaskProcessor {

    public static List<String> generateUniqueIdentifiersForBatchProcessing(File taskFile, LogSchema logSchema, ExternalDataSource externalDataSource, int timeoutDuration, File outputDirectory) {
        try {
            // Read tasks from JSON file
            List<Task> tasks = readTasksFromJson(taskFile);

            // Initialize semaphore
            Semaphore semaphore = new Semaphore(5); // Example initial value

            // Prepare the circular buffer for logs
            ConcurrentLinkedQueue<String> logBuffer = new ConcurrentLinkedQueue<>();

            // Create an executor service with a fixed thread pool size
            ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

            // Use a countdown latch to wait for all tasks to complete
            CountDownLatch latch = new CountDownLatch(tasks.size());

            // Process each task in parallel
            for (Task task : tasks) {
                semaphore.acquire();
                executorService.submit(() -> {
                    try {
                        processTask(task, externalDataSource, logSchema, logBuffer, outputDirectory);
                    } catch (Exception e) {
                        handleProcessingError(e, task, logSchema, logBuffer);
                    } finally {
                        semaphore.release();
                        latch.countDown();
                    }
                });
            }

            // Wait for all tasks to complete or timeout
            if (!latch.await(timeoutDuration, TimeUnit.SECONDS)) {
                executorService.shutdownNow(); // Force shutdown if timeout occurs
                throw new TimeoutException("Processing timed out");
            }

            // Shutdown the executor service
            executorService.shutdown();

            // Save log entries to a file
            saveLogEntries(logBuffer, outputDirectory);

            return generateIdentifiersFromLog(logBuffer);
