int* find_largest(int* array, size_t size) {
    if (array == NULL || size == 0) return NULL;

    int* largest = &array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > *largest) {
            largest = &array[i];
        }
    }
    return largest;
}

void fill_records(record* records, size_t size, long offset, int key, int min_val, int max_val, unsigned seed) {
    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void process_data(size_t num_records, long* offsets, int* keys, record** records_ptr, double max_latency) {
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    *records_ptr = (record*)malloc(num_records * sizeof(record));
    if (*records_ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    fill_records(*records_ptr, num_records, 0, 0, -100, 100, time(NULL));

    int* largest = find_largest((*records_ptr)->value, num_records);
    if (largest != NULL) {
        printf("Largest value: %d\n", *largest);
    } else {
        printf("No data to process.\n");
    }

    free(*records_ptr);

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    if (elapsed_time > max_latency) {
        printf("Latency exceeded: %f seconds\n", elapsed_time);
    }
}

int main() {
    size_t num_records;
