#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <sys/types.h>

typedef int64_t offset_t;
typedef uint32_t key_t;

typedef struct {
    offset_t *offset_ptr;
    int value;
} record_t;

int allocate_and_initialize_records(size_t n, int64_t min_offset, int64_t max_offset, uint32_t min_value, uint32_t max_value) {
    pid_t pid = getpid();
    time_t current_time = time(NULL);
    srand((pid << 16) ^ (current_time & 0xFFFF));

    offset_t *offsets = malloc(n * sizeof(offset_t));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return -1;
    }

    key_t *keys = malloc(n * sizeof(key_t));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return -1;
    }

    record_t *records = malloc(n * sizeof(record_t));
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return -1;
    }

    int64_t total_memory_used = n * (sizeof(offset_t) + sizeof(key_t) + sizeof(record_t));
    // Check memory usage against threshold
    if (total_memory_used > MAX_MEMORY_THRESHOLD) {
        free(records);
        free(keys);
        free(offsets);
        fprintf(stderr, "Memory usage exceeds threshold\n");
        return -1;
    }

    // Initialize offsets with unique random values
    for (size_t i = 0; i < n; ++i) {
        do {
            offsets[i] = (offset_t)(rand() % (max_offset - min_offset + 1)) + min_offset;
        } while (i > 0 && offsets[i] == offsets[i-1]);
    }

    // Initialize keys with unique values
    for (size_t i = 0; i < n; ++i) {
        do {
            keys[i] = rand() % ((uint32_t)n);
        } while (i > 0 && keys[i] == keys[i-1]);
    }

    // Initialize records with random values and unique offsets
    for (size_t i = 0; i < n; ++i) {
        records[i].offset_ptr = &offsets[keys[i]];
        records[i].value = rand() % ((max_value - min_value + 1)) + min_value;
    }

    // Free allocated memory before returning
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
