#include <math.h>

#define MAX_MEMORY 10000

typedef struct {
    long *offset;
    int key;
} record;

// Custom PRNG function
unsigned int prng(unsigned int seed) {
    return (seed * 214013 + 2531011) % 65536;
}

int main() {
    unsigned int seed = time(NULL);
    long num_offsets, num_keys;
    record *records;

    // Input parameters
    printf("Enter number of offsets: ");
    scanf("%ld", &num_offsets);

    // Calculate number of keys (rounded up)
    num_keys = ceil(sqrt(num_offsets));

    // Allocate memory for offsets and initialize
    if ((offsets = malloc(num_offsets * sizeof(long))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }
    for (long i = 0; i < num_offsets; i++) {
        offsets[i] = prng(seed) % 1001; // Ensure offset is within range
    }

    // Allocate memory for records and initialize
    if ((records = malloc(num_keys * sizeof(record))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        return 1;
    }
    for (long i = 0; i < num_keys; i++) {
        records[i].offset = &offsets[prng(seed) % num_offsets];
        records[i].key = prng(seed) % 1001 + 1; // Ensure key is between 1 and 1000
    }

    // Print records for verification (optional)
    for (long i = 0; i < num_keys; i++) {
        printf("Record %ld: Offset = %ld, Key = %d\n", i, *records[i].offset, records[i].key);
    }

    // Free allocated memory
    free(offsets);
    free(records);

    return 0;
}
