typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct MemoryPool {
    size_t size;
    size_t block_size;
    void* blocks;
    int* free_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t total_size, size_t block_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->size = total_size;
    pool->block_size = block_size;
    pool->blocks = malloc(total_size);
    pool->free_blocks = (int*)calloc(total_size / block_size, sizeof(int));
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->blocks);
    free(pool->free_blocks);
    free(pool);
}

Record* allocate_record(MemoryPool* pool) {
    for (size_t i = 0; i < pool->size / pool->block_size; ++i) {
        if (!pool->free_blocks[i]) {
            pool->free_blocks[i] = 1;
            return (Record*)((char*)pool->blocks + i * pool->block_size);
        }
    }
    return NULL;
}

void deallocate_record(MemoryPool* pool, Record* record) {
    size_t index = ((char*)record - (char*)pool->blocks) / pool->block_size;
    pool->free_blocks[index] = 0;
}

// Customizable PRNG
unsigned long custom_prng(unsigned long seed, int range) {
    return seed * 1664525 + 1013904223 % range;
}

Record* populate_records(MemoryPool* pool, size_t count, unsigned long seed, int min_value, int max_value) {
    Record* records = allocate_record(pool);
    for (size_t i = 0; i < count; ++i) {
        records[i].offset = i * sizeof(Record);
        records[i].key = custom_prng(seed + i, RAND_MAX);
        records[i].value = min_value + custom_prng(records[i].key, max_value - min_value + 1);
    }
    return records;
}

// External data processing library integration
// (Assuming a function sort_records and filter_records are available from the library)

int main() {
    MemoryPool* pool = create_memory_pool(1024 * 1024, sizeof(Record)); // 1MB memory pool for 1024 records
    Record* records = populate_records(pool, 1024, time(NULL), 100, 1000);

    // Perform operations using external library functions
    sort_records(records, 1024);
    filter_records(records, 1024, some_condition);

    deallocate_record(pool, records);
    destroy_memory_pool(pool);

    return 0;
}
```

