#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define PRNG_REFRESH_INTERVAL 3600 // Refresh every hour

typedef struct {
    int key;
    long offset;
} record;

record* records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock;

void initialize_prng() {
    srand(time(NULL));
}

int generate_unique_key(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* create_record(long offset) {
    record* new_record = malloc(sizeof(record));
    new_record->key = generate_unique_key(1, MAX_RECORDS);
    new_record->offset = offset;
    return new_record;
}

void add_record(long offset) {
    pthread_mutex_lock(&lock);
    if (record_count < MAX_RECORDS) {
        records[record_count++] = create_record(offset);
    }
    pthread_mutex_unlock(&lock);
}

void refresh_prng() {
    initialize_prng();
}

void* manage_records(void* arg) {
    long offset;
    while (1) {
        // Simulate incoming requests
        offset = rand() % 10000; // Example: random offset
        add_record(offset);

        // Refresh PRNG periodically
        sleep(PRNG_REFRESH_INTERVAL);
        refresh_prng();
    }
    return NULL;
}

int main() {
    pthread_t threads[10];

    initialize_prng();
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, manage_records, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
```

