#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int amount;
    char status;
    time_t timestamp;
} Transaction;

Transaction* init_transactions(int max_count, int budget, unsigned long seed, FILE* log_fd) {
    if (log_fd == NULL) {
        fprintf(stderr, "Error: Invalid log file descriptor.\n");
        return NULL;
    }

    srand(seed);
    Transaction* transactions = malloc(max_count * sizeof(Transaction));
    if (transactions == NULL) {
        fprintf(log_fd, "Error: Memory allocation failed.\n");
        return NULL;
    }

    int total_amount = 0;
    for (int i = 0; i < max_count; i++) {
        int amount = rand() % budget + 1;
        if ((total_amount += amount) > budget) {
            fprintf(log_fd, "Error: Budget exceeded.\n");
            free(transactions);
            return NULL;
        }
        transactions[i].amount = amount;
        transactions[i].status = 'P'; // Pending status
        time(&transactions[i].timestamp);
    }

    return transactions;
}

void free_transactions(Transaction* transactions) {
    if (transactions != NULL) {
        free(transactions);
    }
}
