use tokio::task;
use rand::{thread_rng, Rng};
use std::collections::HashMap;
use std::env;

struct Record {
    value: i32,
}

async fn process_data(num_records: usize) {
    let mut long_offsets = vec![0; num_records];
    let mut int_keys = vec![0; num_records];
    let mut records = vec![Record { value: 0 }; num_records];

    for record in &mut records {
        record.value = thread_rng().gen_range(1..=100);
    }

    // Simulate external data source
    tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;

    for i in 0..num_records {
        long_offsets[i] = (record.value * i) as u64;
        int_keys[i] = record.value % 100;
    }
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <num_records>", args[0]);
        return;
    }

    let num_records: usize = args[1].parse().expect("Invalid number of records");

    let num_tasks: usize = std::thread::available_parallelism().unwrap().into();
    let records_per_task = (num_records + num_tasks - 1) / num_tasks;

    let mut tasks = Vec::new();

    for i in 0..num_tasks {
        let start = i * records_per_task;
        let end = if i == num_tasks - 1 { num_records } else { start + records_per_task };
        tasks.push(task::spawn(async move {
            process_data(end - start).await
        }));
    }

    for task in tasks {
        task.await.unwrap();
    }
}
