#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
} Record;

// Function to securely generate random numbers
unsigned long secure_random(unsigned long min, unsigned long max) {
    static unsigned long seed = 0;
    if (seed == 0)
        seed = time(NULL); // Seed with current time for initial run

    seed = seed * 1103515245 + 12345; // Linear congruential generator
    return min + seed % (max - min + 1);
}

// Function to dynamically allocate and initialize arrays
void initialize_arrays(int num_records, long **offsets, int **keys, Record **records) {
    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));
    *records = malloc(num_records * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = secure_random(0L, 1000000000L); // Example range
        (*keys)[i] = secure_random(-1000, 1000);
        (*records)[i].value = secure_random(0, 10000);
    }
}

// Cleanup function to release allocated memory
void cleanup(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const int num_records = 100; // Example number of records

    long *offsets;
    int *keys;
    Record *records;

    initialize_arrays(num_records, &offsets, &keys, &records);

    // Process data using offsets, keys, and records
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Offset=%ld, Key=%d, Value=%d\n", i, offsets[i], keys[i], records[i].value);
    }

    cleanup(offsets, keys, records);

    return 0;
}
```

**Explanation of the code:**

1. **Record Structure**: Defines a simple structure to hold an integer value.

2. **Secure Random Function**: Uses a linear congruential generator (LCG) seeded with the current time for initial runs. This ensures good randomness and minimizes bias. The LCG is chosen for its simplicity and speed, making it suitable for real-time applications.

3. **Initialize Arrays Function**: Dynamically allocates memory for three arrays using `malloc`. It initializes each array with random values generated by the secure random function. Error handling is included to check for memory allocation failures.

4. **Cleanup Function**: Frees all dynamically allocated memory to avoid memory leaks.

5. **Main Function**: Demonstrates how to use the `initialize_arrays` and `cleanup` functions, including a simple loop to print out each record's details for demonstration purposes.

This code provides a basic framework that can be extended with additional features such as thread safety, error handling, and integration with external data processing libraries. The secure random function is chosen for its balance between speed and accuracy, making it suitable for real-time applications with high data volumes.']

