record* create_records(int count, size_t max_buffer_size) {
    if (count <= 0 || max_buffer_size == 0) {
        return NULL;
    }

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        return NULL;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    srand((unsigned int)(ts.tv_sec * 1000 + ts.tv_nsec / 1e6));

    for (int i = 0; i < count; i++) {
        records[i].offset = rand() % 1000L;
        records[i].key = rand() % 1000;
        records[i].unique_id = (uint64_t)rand();
        records[i].timestamp = (float)(rand()) / RAND_MAX;

        size_t buffer_size = rand() % max_buffer_size;
        for (size_t j = 0; j < buffer_size; j++) {
            records[i].buffer[j] = 'a' + (rand() % ('z' - 'a' + 1));
        }
        records[i].buffer[buffer_size] = '\0';

        records[i].flag = rand();
    }

    return records;
}

void free_records(record* records, int count) {
    if (records) {
        free(records);
    }
}
