int initialize_arrays(long **offsets, int **keys, short **ids, Operation **ops,
                      size_t size, long offset_min, long offset_max, int key_range) {
    srand(time(NULL)); // Seed the random number generator

    *offsets = (long *)malloc(size * sizeof(long));
    if (*offsets == NULL) return -1; // Handle memory allocation failure

    *keys = (int *)malloc(size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *ids = (short *)malloc(size * sizeof(short));
    if (*ids == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    *ops = (Operation *)malloc(size * sizeof(Operation));
    if (*ops == NULL) {
        free(*offsets);
        free(*keys);
        free(*ids);
        return -1;
    }

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand() % (offset_max - offset_min + 1) + offset_min;
        (*keys)[i] = rand() % key_range;
        (*ids)[i] = (short)(rand() % SHRT_MAX);
        (*ops)[i].amount = rand() % key_range; // Adjust range as needed
        (*ops)[i].status = (char)(rand() % 256); // Random byte for demonstration
    }

    return 0; // Success
}

void cleanup_arrays(long *offsets, int *keys, short *ids, Operation *ops) {
    free(offsets);
    free(keys);
    free(ids);
    free(ops);
}
