#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function prototypes
void* safe_malloc(size_t size);
Record* create_records(int count, int key_range_min, int key_range_max, int random_seed);
int find_largest(int* array, int size);
int hash_function(int key, int table_size);
void insert_record(Record** hashtable, int table_size, Record* record);
Record* lookup_record(Record** hashtable, int table_size, int key);
void delete_record(Record** hashtable, int table_size, int key);
void log_operation(const char* message);

int main() {
    // Read configuration and seed the random number generator
    srand(time(NULL));

    // Create records with user-specified sizes and ranges
    Record* records = create_records(1000, 1, 1000, time(NULL));

    // Find and print the largest integer in an array of integers
    int* array = (int*)safe_malloc(50 * sizeof(int));
    for (int i = 0; i < 50; i++) {
        array[i] = rand() % 1000;
    }
    int largest = find_largest(array, 50);
    printf("Largest integer: %d\n", largest);

    // Clean up allocated memory
    free(records);
    free(array);

    return 0;
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record* create_records(int count, int key_range_min, int key_range_max, int random_seed) {
    Record* records = (Record*)safe_malloc(count * sizeof(Record));
    srand(random_seed);

    for (int i = 0; i < count; i++) {
        Record record;
        record.value = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        records[i] = record;
    }

    return records;
}

int find_largest(int* array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size\n");
        exit(EXIT_FAILURE);
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

int hash_function(int key, int table_size) {
    return abs(key % table_size);
}

void insert_record(Record** hashtable, int table_size, Record* record) {
    int index = hash_function(record->value, table_size);

    if (hashtable[index] != NULL) {
        // Handle collision using chaining
        Record* current = hashtable[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    } else {
        hashtable[index] = record;
    }
}

Record* lookup_record(Record** hashtable, int table_size, int key) {
    int index = hash_function(key, table_size);

    Record* current = hashtable[index];
    while (current != NULL) {
        if (current->value == key) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

void delete_record(Record** hashtable, int table_size, int key) {
    int index = hash_function(key, table_size);

    Record* current = hashtable[index];
    Record* prev = NULL;
    while (current != NULL) {
        if (current->value == key) {
            if (prev == NULL) {
                hashtable[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void log_operation(const char* message) {
    // Log the operation to a specified file
    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - %s\n", ctime(&now), message);
        fclose(log_file);
    }
}
