                                 const ExternalDataSource *externalDataSource, int timeoutDuration,
                                 const char *logDirectory) {
    FILE *file = fopen(transactionFile, "r");
    if (!file) {
        perror("Failed to open transaction file");
        return;
    }

    // Initialize CSPRG and log buffer
    unsigned char seed[32];
    externalDataSource->getRandomSeed(seed, sizeof(seed));
    RAND_seed(seed, sizeof(seed));

    CachedTransactionID cache[1000]; // Example size
    int cacheSize = 0;

    time_t startProcessing = time(NULL);
    while (time(NULL) - startProcessing < timeoutDuration) {
        FinancialTransaction transaction;
        // Read and parse the next transaction from the file

        if (!parseTransaction(file, &transaction)) {
            logError(logSchema, "Failed to parse transaction");
            continue;
        }

        unsigned char *transactionID = malloc(32);
        RAND_bytes(transactionID, 32);

        // Store the transaction in a temporary database
        storeTransaction(transactionID, transaction);

        // Cache the transaction ID for frequent access
        if (cacheSize < sizeof(cache) / sizeof(CachedTransactionID)) {
            cache[cacheSize].id = transactionID;
            cache[cacheSize].transaction = transaction;
            cache[cacheSize].lastAccessTime = time(NULL);
            cacheSize++;
        } else {
            // Replace the least recently used item in the cache
            int minIndex = 0;
            time_t minTime = cache[0].lastAccessTime;
            for (int i = 1; i < cacheSize; i++) {
                if (cache[i].lastAccessTime < minTime) {
                    minIndex = i;
                    minTime = cache[minIndex].lastAccessTime;
                }
            }
            free(cache[minIndex].id);
            cache[minIndex] = (CachedTransactionID){transactionID, transaction, time(NULL)};
        }

        // Log the successful processing of a transaction
        logSuccess(logSchema, "Processed transaction with ID: %s", transactionID);

        if (feof(file)) {
            break;
        }
    }

    fclose(file);
}

