import os
import asyncio
from collections import defaultdict

async def process_log_file(file_path):
    method_counts = defaultdict(int)
    status_code_categories = {'success': 0, 'redirect': 0, 'error': 0}

    with open(file_path, 'r') as file:
        async for line in aiter(file.readline, ''):
            parts = line.strip().split()
            if len(parts) < 6:
                continue

            method = parts[5].upper()
            status_code = parts[8]

            if method in ('GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'):
                method_counts[method] += 1

            if status_code.isdigit():
                status_code = int(status_code)
                if 200 <= status_code < 300:
                    status_code_categories['success'] += 1
                elif 300 <= status_code < 400:
                    status_code_categories['redirect'] += 1
                elif 400 <= status_code < 600:
                    status_code_categories['error'] += 1

    return method_counts, status_code_categories

async def process_log_files_concurrently(directory_path, max_requests):
    tasks = []
    for filename in os.listdir(directory_path):
        if filename.endswith('.log'):
            file_path = os.path.join(directory_path, filename)
            task = asyncio.create_task(process_log_file(file_path))
            tasks.append(task)
            if len(tasks) >= max_requests:
                results = await asyncio.gather(*tasks)
                tasks.clear()

    if tasks:
        results = await asyncio.gather(*tasks)

    return aggregate_results(results)

def aggregate_results(results):
    method_counts = defaultdict(int)
    status_code_categories = {'success': 0, 'redirect': 0, 'error': 0}

    for method_count, status_category in results:
        method_counts.update(method_count)
        for category, count in status_category.items():
            status_code_categories[category] += count

    return method_counts, status_code_categories

async def main(directory_path, max_requests):
    result = await process_log_files_concurrently(directory_path, max_requests)
    print("HTTP Method Counts:")
    for method, count in result[0].items():
        print(f"{method}: {count}")

    print("\nStatus Code Categories:")
    for category, count in result[1].items():
        print(f"{category.capitalize()}: {count}")

# Example usage
directory_path = 'path/to/log/files'
max_requests = 5

asyncio.run(main(directory_path, max_requests))
