void parseCSV(char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Transaction record;
        // Parse the line and populate record
        // ...

        pthread_mutex_lock(&summaries[record.userID].lock);
        summaries[record.userID].totalAmount += record.amount;
        pthread_mutex_unlock(&summaries[record.userID].lock);

        if (++recordCount % 100000 == 0) {
            monitorMemoryUsage();
        }
    }

    fclose(file);
}

void *processRecords(void *arg) {
    int startIndex = *(int *)arg;

    for (int i = startIndex; i < recordCount; ++i) {
        Transaction record;
        // Parse the line and populate record
        // ...

        pthread_mutex_lock(&summaries[record.userID].lock);
        summaries[record.userID].totalAmount += record.amount;
        pthread_mutex_unlock(&summaries[record.userID].lock);

        if (recordCount % 100000 == 0) {
            monitorMemoryUsage();
        }
    }

    return NULL;
}

void initializeSummaries() {
    for (int i = 0; i < 10000; ++i) {
        pthread_mutex_init(&summaries[i].lock, NULL);
        summaries[i].totalAmount = 0.0;
    }
}

void monitorMemoryUsage() {
    // Implement memory usage monitoring and logging
    // ...
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    initializeSummaries();

    threads = malloc(threadCount * sizeof(pthread_t));
    int *indices = malloc(threadCount * sizeof(int));

    for (int i = 0; i < threadCount; ++i) {
        indices[i] = i * (recordCount / threadCount);
        pthread_create(&threads[i], NULL, processRecords, &indices[i]);
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(indices);
    free(threads);

    // Output the summaries
    // ...

    return 0;
}
