    *timestamps = (long *)malloc(MAX_RECORDS * sizeof(long));
    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    *amounts = (float *)malloc(MAX_RECORDS * sizeof(float));
    if (*timestamps == NULL || *keys == NULL || *amounts == NULL) {
