void fill_arrays(long *timestamps, int *keys, float *amounts, unsigned long seed) {
    srand(seed);
    for (int i = 0; i < MAX_RECORDS; i++) {
        timestamps[i] = time(NULL) + rand();
        keys[i] = rand() % 1000;
        amounts[i] = ((float)rand() / RAND_MAX) * 100.0f;
    }
}

void parse_transactions(Transaction **transactions, int *record_count) {
    char line[256];
    *transactions = (Transaction *)malloc(MAX_RECORDS * sizeof(Transaction));
    if (*transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *record_count = 0;
    while (fgets(line, sizeof(line), stdin)) {
        if (*record_count >= MAX_RECORDS) break;
        sscanf(line, "%ld %d %f", &(*transactions)[*record_count].timestamp,
               &(*transactions)[*record_count].key_id,
               &(*transactions)[*record_count].amount);
        (*record_count)++;
    }
}

float calculate_total_amount(Transaction *transactions, int record_count) {
    float total = 0.0f;
    for (int i = 0; i < record_count; i++) {
        total += transactions[i].amount;
    }
    return total;
}

void cleanup(long *timestamps, int *keys, float *amounts, Transaction *transactions) {
    free(timestamps);
    free(keys);
    free(amounts);
    free(transactions);
}

