#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_USERS 1000
#define MAX_RECORDS 10000

typedef struct {
    int transactionID;
    int userID;
    long timestamp;
    double amount;
} Transaction;

typedef struct {
    int userID;
    double totalAmount;
} UserSummary;

UserSummary userSummaries[MAX_USERS];
pthread_mutex_t summaryMutex = PTHREAD_MUTEX_INITIALIZER;

void *parseAndSummarize(void *arg) {
    char *filePath = (char *)arg;
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Error opening file");
        pthread_exit(NULL);
    }

    Transaction records[MAX_RECORDS];
    int recordCount = 0;

    // Read and parse CSV file
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        records[recordCount].transactionID = atoi(token);
        token = strtok(NULL, ",");
        records[recordCount].userID = atoi(token);
        token = strtok(NULL, ",");
        records[recordCount].timestamp = atol(token);
        token = strtok(NULL, ",");
        records[recordCount].amount = atof(token);
        recordCount++;
    }

    fclose(file);

    // Summarize transactions by user
    for (int i = 0; i < recordCount; i++) {
        pthread_mutex_lock(&summaryMutex);
        int userID = records[i].userID;
        double amount = records[i].amount;

        for (int j = 0; j < MAX_USERS; j++) {
            if (userSummaries[j].userID == userID) {
                userSummaries[j].totalAmount += amount;
                pthread_mutex_unlock(&summaryMutex);
                break;
            }
        }

        if (j == MAX_USERS) {
            printf("Error: Too many users\n");
            pthread_mutex_unlock(&summaryMutex);
            continue;
        }
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_directory> <date_range>\n", argv[0]);
        return 1;
    }

    char *inputFile = argv[1];
    char *outputDirectory = argv[2];
    long dateRange = atol(argv[3]);

    pthread_t thread;
    int result = pthread_create(&thread, NULL, parseAndSummarize, inputFile);
    if (result != 0) {
        perror("Error creating thread");
        return 1;
    }

    pthread_join(thread, NULL);

    // Output summaries to file
    FILE *outputFile = fopen(outputDirectory, "w");
    if (!outputFile) {
        perror("Error opening output file");
        return 1;
    }

    for (int i = 0; i < MAX_USERS; i++) {
        fprintf(outputFile, "%d,%f\n", userSummaries[i].userID, userSummaries[i].totalAmount);
    }

    fclose(outputFile);

    return 0;
}
```

