#include <time.h>

#define MAX_SIZE 1000

typedef struct {
    int value;
} Record;

void initializeArrays(long *offsets, int *keys, Record *records, size_t size) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % MAX_SIZE;
        keys[i] = rand() % MAX_SIZE;
        records[i].value = rand() % 100; // Random temperature value between 0 and 99
    }
}

void reallocateMemory(long **offsets, int **keys, Record **records, size_t oldSize, size_t newSize) {
    *offsets = realloc(*offsets, newSize * sizeof(long));
    *keys = realloc(*keys, newSize * sizeof(int));
    *records = realloc(*records, newSize * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize new elements if necessary
    for (size_t i = oldSize; i < newSize; ++i) {
        (*offsets)[i] = rand() % MAX_SIZE;
        (*keys)[i] = rand() % MAX_SIZE;
        (*records)[i].value = rand() % 100;
    }
}

void freeMemory(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    size_t initialSize = 500;
    long *offsets = malloc(initialSize * sizeof(long));
    int *keys = malloc(initialSize * sizeof(int));
    Record *records = malloc(initialSize * sizeof(Record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    initializeArrays(offsets, keys, records, initialSize);

    // Simulate memory growth
    size_t newSize = 1000;
    reallocateMemory(&offsets, &keys, &records, initialSize, newSize);

    freeMemory(offsets, keys, records);

    return 0;
}
