#define MAX_EVENTS 10000

typedef struct {
    time_t timestamp;
    int key_index;
    double probability;
    char event_type[2];
} Event;

int compare_events(const void *a, const void *b) {
    Event *eventA = (Event *)a;
    Event *eventB = (Event *)b;

    if (eventA->probability != eventB->probability) {
        return (eventB->probability > eventA->probability) - (eventB->probability < eventA->probability);
    }
    return strcmp(eventA->event_type, eventB->event_type);
}

int main() {
    Event events[MAX_EVENTS];
    int num_events;

    // Initialize random number generator
    if (time(NULL) == -1 || srand(time(NULL)) != 0) {
        perror("Failed to initialize random number generator");
        return EXIT_FAILURE;
    }

    // Read events from standard input
    printf("Enter the number of events: ");
    scanf("%d", &num_events);

    if (num_events <= 0 || num_events > MAX_EVENTS) {
        fprintf(stderr, "Invalid number of events\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_events; ++i) {
        printf("Enter timestamp for event %d: ", i + 1);
        scanf("%ld", &events[i].timestamp);

        printf("Enter key index for event %d: ", i + 1);
        scanf("%d", &events[i].key_index);
    }

    // Populate probability and event type fields with random values
    for (int i = 0; i < num_events; ++i) {
        events[i].probability = (double)rand() / RAND_MAX;

        switch (rand() % 3) {
            case 0:
                strcpy(events[i].event_type, "A");
                break;
            case 1:
                strcpy(events[i].event_type, "B");
                break;
            default:
                strcpy(events[i].event_type, "C");
                break;
        }
    }

    // Sort events by probability and event type
    qsort(events, num_events, sizeof(Event), compare_events);

    // Output sorted list of events along with their indices
    printf("Sorted Events:\n");
    for (int i = 0; i < num_events; ++i) {
        printf("Event %d: Timestamp=%ld, Key Index=%d, Probability=%.2f, Event Type=%s\n",
               i + 1, events[i].timestamp, events[i].key_index, events[i].probability, events[i].event_type);
    }

    return EXIT_SUCCESS;
}
