Event* process_events(Event** events, int num_events, char* input, int max_size) {
    if (strlen(input) + 1 > max_size) {
        return NULL;
    }

    // Append forward slash if input length is less than max size
    if (strlen(input) < max_size) {
        strcat(input, "/");
    }

    Event* sorted_events = (Event*)malloc(num_events * sizeof(Event));
    if (!sorted_events) {
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG for reproducibility

    for (int i = 0; i < num_events; ++i) {
        events[i]->probability = ((float)rand() / RAND_MAX) * 1.0f; // Generate random probability
        sorted_events[i] = *(events[i]);
    }

    // Stable sort based on probability in descending order
    for (int i = 0; i < num_events - 1; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < num_events; ++j) {
            if (sorted_events[min_idx].probability < sorted_events[j].probability) {
                min_idx = j;
            }
        }
        Event temp = sorted_events[min_idx];
        sorted_events[min_idx] = sorted_events[i];
        sorted_events[i] = temp;
    }

    for (int i = 0; i < num_events; ++i) {
        events[i]->timestamp = sorted_events[i].timestamp;
        events[i]->key_index = sorted_events[i].key_index;
        events[i]->probability = sorted_events[i].probability;
    }

    free(sorted_events);
    return *events;
}
