    Record *records = ((struct {Record *records; size_t count;})data).records;
    size_t initial_count = ((struct {Record *records; size_t count;})data).count;

    while (1) {
        size_t current_count = records[0].value; // Simulated dynamic adjustment
        if (current_count != initial_count) {
            periodic_cleanup(records, current_count);
            log_memory_usage(current_count, current_count * sizeof(Record));
        }
        sleep(60); // Check every 1 minute
    }

    return NULL;
}

