    log_entry** new_entries = realloc(log_entries, (entry_count + 1) * sizeof(log_entry*));
    if (!new_entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    log_entries = new_entries;

    // Initialize a new log entry
    log_entries[index] = malloc(sizeof(log_entry));
    memset(log_entries[index], 0, sizeof(log_entry));
    time(&log_entries[index]->timestamp);
    snprintf(log_entries[index]->user_id, sizeof(log_entries[index]->user_id), "user%d", index % 100);
    snprintf(log_entries[index]->action_type, sizeof(log_entries[index]->action_type), "action%d", index % 50);

    // Simulate processing time
    usleep(1000); // 1 millisecond

    pthread_mutex_unlock(&log_mutex);
    return NULL;
}

void initialize_log_system() {
    log_entries = malloc(sizeof(log_entry*));
    if (!log_entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    entry_count = 0;
}

void cleanup_log_system() {
    for (int i = 0; i < entry_count; i++) {
        free(log_entries[i]);
    }
    free(log_entries);
}

int main() {
    initialize_log_system();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, process_log, NULL) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(1);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_log_system();
    return 0;
}
