#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRCFLAG; }
#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    struct Record *next;
} Record;

NFAPI_CRC_INDICATION_PDU_T nfaapi_pdu[MAX_RECORDS];
Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t records_mutex;
pthread_cond_t records_cv;
int clearing_frequency = 10; // seconds

void init_prng() {
    srand(time(NULL));
}

int prng(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

Record* create_record(long offset, int key) {
    Record *record = malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->next = NULL;
    return record;
}

void add_record(Record **head, long offset, int key) {
    pthread_mutex_lock(&records_mutex);
    Record *new_record = create_record(offset, key);
    new_record->next = *head;
    *head = new_record;
    pthread_cond_signal(&records_cv);
    pthread_mutex_unlock(&records_mutex);
}

void* periodic_clear(void *arg) {
    while (1) {
        sleep(clearing_frequency);
        pthread_mutex_lock(&records_mutex);
        Record *current = records;
        Record *prev = NULL;
        while (current != NULL) {
            if (current->key == 0) { // Assuming key 0 means the record is unused
                if (prev == NULL) {
                    records = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current);
            } else {
                prev = current;
            }
            current = current->next;
        }
        pthread_mutex_unlock(&records_mutex);
    }
}

void* populate_pdu(void *arg) {
    int n = (int)arg;
    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&records_mutex);
        while (record_count >= MAX_RECORDS) {
            pthread_cond_wait(&records_cv, &records_mutex);
        }
        Record *record = records;
        if (record == NULL) {
            record = create_record(i, prng(0, 100));
            add_record(&records, i, prng(0, 100));
            record_count++;
        } else {
            record->key = prng(0, 100);
        }
        nfaapi_pdu[i].RX_UE_INFORMATION_TAG = record->offset;
        nfaapi_pdu[i].RNTI = i;
        nfaapi_pdu[i].CRCFLAG = prng(0, 1);
        pthread_mutex_unlock(&records_mutex);
    }
}

void* log_memory(void *arg) {
    while (1) {
        sleep(5); // Log every 5 seconds
        printf("Current record count: %d\n", record_count);
    }
}

int main() {
    init_prng();
    pthread_t clear_thread, pdu_thread, log_thread;

    pthread_mutex_init(&records_mutex, NULL);
    pthread_cond_init(&records_cv, NULL);

    pthread_create(&clear_thread, NULL, periodic_clear, NULL);
    pthread_create(&pdu_thread, NULL, populate_pdu, (void*)MAX_RECORDS);
    pthread_create(&log_thread, NULL, log_memory, NULL);

    pthread_join(clear_thread, NULL);
    pthread_join(pdu_thread, NULL);
    pthread_join(log_thread, NULL);

    return 0;
}
