void initRecordArray(RecordArray* recordArray, size_t count, int dataRange) {
    recordArray->count = count;
    recordArray->records = (Record*)malloc(count * sizeof(Record));
    if (recordArray->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < count; ++i) {
        recordArray->records[i].data = customPRNG(dataRange);
    }
}

