        transactions[i].timestamp = time(NULL);
    }

    // Set the array size
    *arraySize = numTransactions;

    return transactions;
}

void freeTransactions(Transaction **transactions, size_t *arraySize) {
    if (transactions && *transactions) {
        free(*transactions);
        *transactions = NULL;
        *arraySize = 0;
    }
}
```

