#include <stdlib.h>
#include <pthread.h>

#define NUM_RECORDS 1000
#define RECORD_CACHE_SIZE 100

typedef struct {
    int value;
} Record;

Record records[NUM_RECORDS];
Record record_cache[RECORD_CACHE_SIZE];
int cache_count = 0;

pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(int min_val, int max_val) {
    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    pthread_mutex_unlock(&records_lock);
}

void* thread_writer(void* arg) {
    int start = *(int*)arg * (NUM_RECORDS / 4);
    for (int i = start; i < start + (NUM_RECORDS / 4); i++) {
        pthread_mutex_lock(&records_lock);
        records[i].value += rand() % 10;
        pthread_mutex_unlock(&records_lock);
    }
    free(arg);
    return NULL;
}

void* thread_reader(void* arg) {
    int count = *(int*)arg;
    for (int i = 0; i < count; i++) {
        pthread_mutex_lock(&cache_lock);
        if (cache_count > 0) {
            Record record = record_cache[--cache_count];
            printf("Read from cache: %d\n", record.value);
        } else {
            pthread_mutex_lock(&records_lock);
            Record record = records[rand() % NUM_RECORDS];
            pthread_mutex_unlock(&records_lock);

            pthread_mutex_lock(&cache_lock);
            if (cache_count < RECORD_CACHE_SIZE) {
                record_cache[cache_count++] = record;
            }
            printf("Read from memory: %d\n", record.value);
        }
        pthread_mutex_unlock(&cache_lock);
    }
    free(arg);
    return NULL;
}

void verify_records() {
    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < NUM_RECORDS; i++) {
        if (records[i].value == 0) {
            printf("Error: Record %d is not initialized\n", i);
        }
    }
    pthread_mutex_unlock(&records_lock);
}

int main() {
    srand(time(NULL));

    initialize_records(1, 100);

    pthread_t threads[8];
    int thread_args[8] = {1, 2, 3, 4, 5, 6, 7, 8};

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_writer, &thread_args[i]);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    verify_records();

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_reader, &thread_args[i]);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
