long customPRNG(long state) {
    return (state * 1664525 + 1013904223) % 2147483647;
}

record* initializeRecords(int numRecords, long initialState, int minValue, int maxValue) {
    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) return NULL;

    long state = initialState;
    for (int i = 0; i < numRecords; ++i) {
        state = customPRNG(state);
        records[i].value = minValue + (state % (maxValue - minValue + 1));
    }

    return records;
}

void freeRecords(record* records, int numRecords) {
    if (records) {
        free(records);
    }
}
