#define MAX_DATASETS 50000

typedef struct {
    int id;
    time_t timestamp;
    char payload[128];
    int sequenceNumber;
} DataSet;

DataSet *dataSets[MAX_DATASETS];
int datasetCount = 0;

void populateDataSets(int seed, int numDatasets) {
    srand(seed);

    for (int i = 0; i < numDatasets; i++) {
        DataSet *newDataset = (DataSet *)malloc(sizeof(DataSet));
        if (!newDataset) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        newDataset->id = rand() % MAX_DATASETS;
        newDataset->timestamp = time(NULL);
        snprintf(newDataset->payload, sizeof(newDataset->payload), "Data%04d", i);
        newDataset->sequenceNumber = rand() % 100;

        // Check for duplicates
        int duplicate = 0;
        for (int j = 0; j < datasetCount; j++) {
            if (dataSets[j]->id == newDataset->id) {
                free(newDataset);
                duplicate = 1;
                break;
            }
        }

        if (!duplicate) {
            dataSets[datasetCount++] = newDataset;
        } else {
            fprintf(stderr, "Duplicate dataset ID: %d\n", newDataset->id);
            free(newDataset);
        }
    }
}

int main() {
    srand(time(NULL));
    populateDataSets(12345, 100);

    // Simulate accessing datasets
    for (int i = 0; i < datasetCount; i++) {
        printf("ID: %d, Timestamp: %ld, Payload: %s, Sequence Number: %d\n",
               dataSets[i]->id, dataSets[i]->timestamp, dataSets[i]->payload, dataSets[i]->sequenceNumber);
    }

    // Free allocated memory
    for (int i = 0; i < datasetCount; i++) {
        free(dataSets[i]);
    }

    return 0;
}
