#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 10000

typedef struct {
    time_t timestamp;
    int identifier_index;
    float value;
    char buffer[256];
    long offset;
    int key;
} DataRecord;

typedef struct {
    DataRecord *records;
    int count;
    int capacity;
} RecordList;

RecordList* createRecordList() {
    RecordList *list = (RecordList*)malloc(sizeof(RecordList));
    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void freeRecordList(RecordList *list) {
    if (list->records != NULL) {
        free(list->records);
    }
    free(list);
}

int insertUniqueRecord(RecordList *list, DataRecord newRecord) {
    // Check for duplicates
    for (int i = 0; i < list->count; i++) {
        if (list->records[i].identifier_index == newRecord.identifier_index &&
            list->records[i].key == newRecord.key) {
            return -1; // Duplicate record
        }
    }

    // Resize the array if needed
    if (list->count >= list->capacity) {
        int newCapacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        DataRecord *newRecords = (DataRecord*)realloc(list->records, newCapacity * sizeof(DataRecord));
        if (newRecords == NULL) {
            return -1; // Memory allocation failed
        }
        list->records = newRecords;
        list->capacity = newCapacity;
    }

    // Insert the record
    memcpy(&list->records[list->count], &newRecord, sizeof(DataRecord));
    list->count++;
    return 0;
}

void generateUniqueDataRecords(RecordList *list, int seed) {
    srand(seed);
    for (int i = 0; i < MAX_RECORDS; i++) {
        DataRecord newRecord;
        newRecord.timestamp = time(NULL);
        newRecord.identifier_index = rand() % 100; // Example range
        newRecord.value = ((float)rand()) / RAND_MAX;
        snprintf(newRecord.buffer, sizeof(newRecord.buffer), "Record_%d", i);
        newRecord.offset = (long)i * 1024;
        newRecord.key = rand();

        insertUniqueRecord(list, newRecord);
    }
}
