#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int user_id;
    time_t timestamp;
    unsigned long session_key;
} Session;

typedef struct {
    time_t timestamp;
    unsigned int activity_id;
} Activity;

typedef struct {
    Session* sessions;
    Activity** activities;
    size_t num_sessions;
    size_t max_sessions;
    size_t num_activities;
    size_t max_activities;
    pthread_mutex_t lock;
} SystemManager;

void init_system_manager(SystemManager* manager, size_t initial_size) {
    manager->sessions = malloc(initial_size * sizeof(Session));
    manager->activities = malloc(initial_size * sizeof(Activity*));
    manager->num_sessions = 0;
    manager->max_sessions = initial_size;
    manager->num_activities = 0;
    manager->max_activities = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
}

void free_system_manager(SystemManager* manager) {
    for (size_t i = 0; i < manager->num_activities; ++i) {
        free(manager->activities[i]);
    }
    free(manager->sessions);
    free(manager->activities);
    pthread_mutex_destroy(&manager->lock);
}

void* generate_session_key(void* seed_ptr) {
    unsigned long* seed = (unsigned long*)seed_ptr;
    return (void*)((*seed * 1103515245U + 12345) % ULONG_MAX);
}

void add_session(SystemManager* manager, int user_id) {
    pthread_mutex_lock(&manager->lock);
    if (manager->num_sessions >= manager->max_sessions) {
        size_t new_size = manager->max_sessions * 2;
        Session* new_sessions = realloc(manager->sessions, new_size * sizeof(Session));
        Activity** new_activities = realloc(manager->activities, new_size * sizeof(Activity*));
        if (!new_sessions || !new_activities) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle memory allocation failure
        }
        manager->sessions = new_sessions;
        manager->activities = new_activities;
        manager->max_sessions = new_size;
    }

    time_t timestamp = time(NULL);
    unsigned long seed = timestamp * user_id;
    Session* session = (Session*)generate_session_key(&seed);
    session->user_id = user_id;
    session->timestamp = timestamp;
    session->session_key = *(unsigned long*)session;

    manager->sessions[manager->num_sessions] = *session;
    manager->num_sessions++;

    pthread_mutex_unlock(&manager->lock);
}

void* generate_activity_id(void* seed_ptr) {
    unsigned int* seed = (unsigned int*)seed_ptr;
    return (void*)((*seed * 1103515245U + 12345) % UINT_MAX);
}

void add_activity(SystemManager* manager, int user_id, unsigned int activity_range) {
    pthread_mutex_lock(&manager->lock);
    if (manager->num_activities >= manager->max_activities) {
        size_t new_size = manager->max_activities * 2;
        Activity** new_activities = realloc(manager->activities, new_size * sizeof(Activity*));
        if (!new_activities) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle memory allocation failure
        }
        manager->activities = new_activities;
        manager->max_activities = new_size;
    }

    time_t timestamp = time(NULL);
    unsigned int seed = (unsigned int)timestamp * user_id;
    Activity* activity = (Activity*)generate_activity_id(&seed);
    activity->timestamp = timestamp;
    activity->activity_id = *(unsigned int*)activity % activity_range;

    manager->activities[manager->num_activities] = activity;
    manager->num_activities++;

    pthread_mutex_unlock(&manager->lock);
}
