LogEntry** create_log_entries(int num_entries, time_t seed) {
    srand(seed);
    LogEntry** log_entries = (LogEntry**)malloc(num_entries * sizeof(LogEntry*));
    if (!log_entries) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        log_entries[i] = (LogEntry*)malloc(sizeof(LogEntry));
        if (!log_entries[i]) {
            perror("Memory allocation failed");
            // Free previously allocated entries
            for (int j = 0; j < i; ++j) {
                free(log_entries[j]);
            }
            free(log_entries);
            return NULL;
        }

        log_entries[i]->timestamp = time(NULL); // Use current time as timestamp
        log_entries[i]->key = rand() % 1000;   // Generate pseudo-random key

        uint64_t unique_value = ((uint64_t)rand()) << 32 | (uint64_t)rand();
        log_entries[i]->record.value = unique_value;
    }

    return log_entries;
}

void free_log_entries(LogEntry** log_entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(log_entries[i]);
    }
    free(log_entries);
}

int main() {
    const int num_entries = 1000;
    time_t seed = time(NULL); // Use current time as seed

    LogEntry** log_entries = create_log_entries(num_entries, seed);
    if (log_entries) {
        // Process log entries
        free_log_entries(log_entries, num_entries);
    }

    return 0;
}
