record* generate_records(int num_records, int min_key, int max_key) {
    if (num_records <= 0 || max_key - min_key + 1 < num_records) {
        return NULL; // Invalid input or insufficient range for unique keys
    }

    record* records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    int* key_set = calloc(max_key - min_key + 1, sizeof(int));
    if (key_set == NULL) {
        free(records);
        return NULL; // Memory allocation for key set failed
    }

    for (int i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (key_set[key - min_key] != 0);
        key_set[key - min_key] = 1;

        records[i].offset = i * sizeof(record);
        records[i].key = key;
        records[i].value = rand(); // Example value generation
    }

    free(key_set);
    return records;
}

int main() {
    int num_records = 1000;
    int min_key = 1;
    int max_key = 10000;

    record* records = generate_records(num_records, min_key, max_key);
    if (records == NULL) {
        printf("Failed to generate records.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Offset=%ld, Key=%d, Value=%d\n", i, records[i].offset, records[i].key, records[i].value);
    }

    free(records);
    return EXIT_SUCCESS;
}
