// Function to allocate and initialize arrays
void initializeArrays(size_t size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    unsigned char** dataBlocks = (unsigned char**)malloc(size * sizeof(unsigned char*));
    Record* records = (Record*)malloc(size * sizeof(Record));
    Metadata** metadata = (Metadata**)malloc(size * sizeof(Metadata*));

    if (!offsets || !keys || !dataBlocks || !records || !metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * 10;
        keys[i] = rand() % 100;

        dataBlocks[i] = (unsigned char*)malloc(64);
        if (!dataBlocks[i]) {
            fprintf(stderr, "Memory allocation failed for data block\n");
            exit(EXIT_FAILURE);
        }
        // Initialize data block with random values

        records[i].value = rand() % 1000;
        records[i].timestamp = time(NULL) - (rand() % 365 * 24 * 60 * 60);
        records[i].active = true;

        metadata[i] = (Metadata*)malloc(sizeof(Metadata));
        if (!metadata[i]) {
            fprintf(stderr, "Memory allocation failed for metadata\n");
            exit(EXIT_FAILURE);
        }
        metadata[i]->version = rand() % 10;
        snprintf(metadata[i]->source, sizeof(metadata[i]->source), "Source%d", i);

        // Clean up on failure
    }

    // Free allocated memory
    for (size_t i = 0; i < size; ++i) {
        free(dataBlocks[i]);
        free(metadata[i]);
    }
    free(offsets);
    free(keys);
    free(dataBlocks);
    free(records);
    free(metadata);
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    initializeArrays(10); // Initialize arrays with 10 elements
    return 0;
}
