#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 100000

typedef struct {
    int key;
    long offset;
} Record;

int compare_records(const void *a, const void *b) {
    return ((Record *)a)->key - ((Record *)b)->key;
}

void generate_random_records(Record **records, size_t *size) {
    srand(time(NULL));
    *records = malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    *size = MAX_RECORDS;
    for (size_t i = 0; i < *size; ++i) {
        (*records)[i].key = rand();
        (*records)[i].offset = rand() % 1000000000L;
    }
}

void sort_records(Record **records, size_t *size) {
    Record *temp = realloc(*records, *size * sizeof(Record));
    if (temp == NULL) {
        fprintf(stderr, "Memory reallocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    qsort(temp, *size, sizeof(Record), compare_records);
    *records = temp;
}

void manage_memory_efficiently() {
    Record *records = NULL;
    size_t size;

    generate_random_records(&records, &size);

    sort_records(&records, &size);

    // Assuming a logging function log_message is available
    log_message("Records sorted successfully.");

    free(records);
}
```

