typedef struct record {
    long offset;
    int key;
    long random_number;
} Record;

Record* create_records(int num_records, int use_cached_memory) {
    static Record* records = NULL;
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);
    if (use_cached_memory && records != NULL) {
        pthread_mutex_unlock(&lock);
        return records;
    }

    records = realloc(records, num_records * sizeof(Record));
    if (records == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand();
        records[i].key = rand() % INT_MAX;
        records[i].random_number = random();
    }

    pthread_mutex_unlock(&lock);
    return records;
}

void update_record_key(Record* records, int key, long new_random_value) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            records[i].random_number = new_random_value % RAND_MAX;
            return;
        }
    }
}

int main() {
    Record* records = create_records(100, 0);
    update_record_key(records, 42, random());

    // Additional code to demonstrate concurrent access and error handling

    return 0;
}
