    int seed = *(int*)arg;
    TransactionRecord* records = (TransactionRecord*)malloc(NUM_RECORDS * sizeof(TransactionRecord));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }

    srand(seed);

    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].value = rand() % 10000; // Random value between 0 and 9999
        records[i].timestamp = time(NULL) - (rand() % 86400); // Timestamp within the last 24 hours
        records[i].transaction_id = i + 1;
    }

    // Simulate fetching keys from an external data source
    int* keys = malloc(NUM_RECORDS * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(records);
        pthread_exit(NULL);
    }
    for (int i = 0; i < NUM_RECORDS; i++) {
        keys[i] = rand() % 100; // Simulated key
    }

    // Simulate fetching transaction descriptions from an external data source
    char** descriptions = malloc(NUM_RECORDS * sizeof(char*));
    if (!descriptions) {
        fprintf(stderr, "Memory allocation failed\n");
        free(records);
        free(keys);
        pthread_exit(NULL);
    }
    for (int i = 0; i < NUM_RECORDS; i++) {
        descriptions[i] = malloc(256 * sizeof(char));
        sprintf(descriptions[i], "Transaction %d", i + 1);
    }

    // Simulate thread-safe resource management
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < NUM_RECORDS; i++) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % 10000; // Random value between 0 and 9999
        pthread_mutex_unlock(&lock);
    }

    // Simulate performance profiling
    double start_time = clock();
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].timestamp = time(NULL) - (rand() % 86400); // Timestamp within the last 24 hours
    }
    double end_time = clock();

    printf("Time taken for timestamp updates: %f seconds\n", (end_time - start_time) / CLOCKS_PER_SEC);

    pthread_mutex_destroy(&lock);
    free(records);
    free(keys);
    for (int i = 0; i < NUM_RECORDS; i++) {
        free(descriptions[i]);
    }
    free(descriptions);

    pthread_exit(NULL);
}

int main() {
    pthread_t thread;
    int seed = time(NULL); // Use current time as the seed

    if (pthread_create(&thread, NULL, initialize_records, &seed) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Thread join failed\n");
        return 1;
    }

    printf("Initialization completed successfully\n");

    return 0;
}
