    if (num_records <= 0 || range_min > range_max) {
        return NULL; // Invalid input
    }

    srand(time(NULL)); // Seed the PRNG with system uptime

    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    record *records = (record *)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Memory allocation failed
    }

    int used_values[range_max - range_min + 1] = {0};
    for (int i = 0; i < num_records; i++) {
        int value;
        do {
            value = rand() % (range_max - range_min + 1) + range_min;
        } while (used_values[value - range_min]);
