record* initialize_records(long* offsets, int* keys, int num_elements, unsigned long seed) {
    if (seed == 0) {
        seed = time(NULL); // Use current time as default seed
    }

    record* records = malloc(num_elements * sizeof(record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    srand(seed);
    for (int i = 0; i < num_elements; ++i) {
        offsets[i] = rand();
        keys[i] = rand();

        records[i].value = rand();
        int str_len = rand() % 20 + 1; // Random string length between 1 and 20
        records[i].str = malloc(str_len * sizeof(char));
        if (!records[i].str) {
            free(records); // Free partially allocated memory on failure
            return NULL;
        }
        for (int j = 0; j < str_len - 1; ++j) {
            records[i].str[j] = 'a' + rand() % 26; // Random lowercase letter
        }
        records[i].str[str_len - 1] = '\0';
        records[i].score = (float)rand() / RAND_MAX;
    }

    return records;
}

void cleanup_records(record* records, int num_elements, long* offsets) {
    for (int i = 0; i < num_elements; ++i) {
        free(records[i].str);
    }
    free(records);
    free(offsets);
}
