unsigned int fastPRNG(unsigned int seed) {
    return seed * 1664525 + 1013904223;
}

void generateSessionTokens(int numTokens, int idRange, int valueRange, unsigned int seed, char **tokens, long *timestamps, int *keys, struct record *records, FILE **logBuffer) {
    if (numTokens <= 0 || idRange <= 0 || valueRange <= 0) {
        fprintf(stderr, "Invalid input values\n");
        return;
    }

    srand(seed); // Seed the PRNG

    for (int i = 0; i < numTokens; ++i) {
        // Generate unique tokens
        while (1) {
            int token = fastPRNG(i * seed);
            if (!isTokenUsed(token, tokens, i)) break;
        }
        sprintf(tokens[i], "%d", token);

        // Initialize timestamp array
        timestamps[i] = time(NULL);

        // Derive key from identifier
        keys[i] = deriveKey(timestamps[i]);

        // Generate random value for record
        records[i].value = fastPRNG(keys[i]) % (valueRange + 1);
    }

    // Log the generation process
    if (*logBuffer != NULL) {
        fprintf(*logBuffer, "Tokens generated: %d\n", numTokens);
    }
}

int isTokenUsed(int token, char **tokens, int count) {
    for (int i = 0; i < count; ++i) {
        if (atoi(tokens[i]) == token) return 1;
    }
    return 0;
}

int deriveKey(long timestamp) {
    // Simple key derivation logic
    return timestamp % 10000;
}

void initializeLogBuffer(FILE **logBuffer, size_t bufferSize) {
    *logBuffer = fopen("log_buffer.txt", "w");
    if (*logBuffer == NULL) {
        perror("Failed to open log buffer file");
        exit(EXIT_FAILURE);
    }
}

int main() {
