    scanf("%d", &numTokens);

    printf("Enter range for identifiers: ");
    scanf("%d", &idRange);

    printf("Enter range for values: ");
    scanf("%d", &valueRange);

    printf("Enter seed for PRNG: ");
    scanf("%u", &seed);

    // Allocate memory for arrays
    char **tokens = (char **)malloc(numTokens * sizeof(char *));
    long *timestamps = (long *)malloc(numTokens * sizeof(long));
    int *keys = (int *)malloc(numTokens * sizeof(int));
    struct record *records = (struct record *)malloc(numTokens * sizeof(struct record));

    if (tokens == NULL || timestamps == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Initialize log buffer
    FILE *logBuffer;
    initializeLogBuffer(&logBuffer, 1024);

    // Generate session tokens
    generateSessionTokens(numTokens, idRange, valueRange, seed, tokens, timestamps, keys, records, &logBuffer);

    // Clean up
    free(tokens);
    free(timestamps);
    free(keys);
    free(records);
