#define MAX_RECORDS 1000000
#define MEMORY_THRESHOLD 500 * 1024 * 1024 // 500MB

typedef struct {
    int value;
    long offset;
    int key;
    double weight;
} Record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* generate_records(void* arg) {
    int seed = *(int*)arg;
    srand(seed);

    Record records[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_lock(&mutex);
        records[i].value = rand() % 100; // Random value between 0 and 99
        records[i].offset = i * sizeof(Record);
        records[i].key = i;
        records[i].weight = (double)i / MAX_RECORDS;
        pthread_mutex_unlock(&mutex);

        if (i % 1000 == 0) {
            check_memory_usage();
        }
    }

    return NULL;
}

void check_memory_usage() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    long memory_used = usage.ru_maxrss * 1024; // Convert to bytes

    if (memory_used > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory usage exceeded threshold: %ldMB\n", memory_used / (1024 * 1024));
    }
}

void log_memory_event(char* status) {
    FILE* log_file = fopen("memory_log.txt", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - %s\n", ctime(&now), status);
        fclose(log_file);
    }
}

int main() {
    int seed = 12345;
    pthread_t thread;

    log_memory_event("Memory allocation started");
    if (pthread_create(&thread, NULL, generate_records, &seed) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    log_memory_event("Memory allocation completed");

    return EXIT_SUCCESS;
}
