#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_SIZE 1000000
#define MEM_LOG_FILE "memory_log.txt"
#define CPU_USAGE_THRESHOLD 80
#define MEM_USAGE_THRESHOLD 90

typedef struct {
    char* identifier;
    int id;
    float value;
    _Bool flag;
} CustomData;

CustomData** array;
int size = 0;
pthread_mutex_t mutex;

// PRNG function using Mersenne Twister algorithm for reproducibility
unsigned long mt[624];
int index = 625;

unsigned long gen_random(unsigned long seed) {
    if (index == 625) {
        mt[0] = seed;
        for (int i = 1; i < 624; i++) {
            mt[i] = (1812433253UL * (mt[i - 1] ^ (mt[i - 1] >> 30)) + i) % 0xFFFFFFFFUL;
        }
        index = 0;
    }

    unsigned long y = mt[index++];
    y ^= (y >> 11);
    y ^= (y << 7) & 2567483615UL;
    y ^= (y << 15) & 642735979UL;
    y ^= (y >> 18);

    return y % MAX_SIZE;
}

void init_array(unsigned long seed, int max_size) {
    array = (CustomData**)malloc(max_size * sizeof(CustomData*));
    if (!array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    size = 0;

    pthread_mutex_init(&mutex, NULL);

    srand(seed); // Seed for PRNG
}

void add_to_array(const char* identifier, float value, _Bool flag) {
    pthread_mutex_lock(&mutex);
    if (size >= MAX_SIZE) {
        printf("Array is full\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    CustomData* data = (CustomData*)malloc(sizeof(CustomData));
    if (!data) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return;
    }

    data->identifier = strdup(identifier);
    data->id = gen_random(time(NULL));
    data->value = value;
    data->flag = flag;

    array[size++] = data;
    pthread_mutex_unlock(&mutex);

    // Log memory allocation
    FILE* log_file = fopen(MEM_LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%ld - Allocation successful\n", time(NULL));
        fclose(log_file);
    }
}

void free_array() {
    for (int i = 0; i < size; i++) {
        free(array[i]->identifier);
        free(array[i]);
    }
    free(array);

    pthread_mutex_destroy(&mutex);

    // Log memory deallocation
    FILE* log_file = fopen(MEM_LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%ld - Deallocation successful\n", time(NULL));
        fclose(log_file);
    }
}
