    free(offsets);
    free(keys);
    for (int i = 0; i < array_size; i++) {
        free(records[i]);
    }
    free(records);
}

void* process_input(void* arg) {
    int stream_id = *(int*)arg;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        keys[stream_id] = atoi(buffer);
        offsets[stream_id]++;
        records[stream_id] = realloc(records[stream_id], offsets[stream_id] * sizeof(record));
        if (!records[stream_id]) {
            perror("Failed to reallocate memory");
            cleanup();
            exit(EXIT_FAILURE);
        }
        records[stream_id][offsets[stream_id] - 1].value = keys[stream_id];
    }
    pthread_exit(NULL);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <num_streams>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_streams = atoi(argv[1]);
    array_size = num_streams;

    offsets = malloc(num_streams * sizeof(long));
    keys = malloc(num_streams * sizeof(int));
    records = malloc(num_streams * sizeof(record*));

    if (!offsets || !keys || !records) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_streams; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        records[i] = NULL;
    }

    srand(time(NULL));

    pthread_t threads[num_streams];
    int thread_ids[num_streams];

    for (int i = 0; i < num_streams; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_input, &thread_ids[i]) != 0) {
            perror("Failed to create thread");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_streams; i++) {
        pthread_join(threads[i], NULL);
    }

    int max_value = keys[0];
    for (int i = 1; i < num_streams; i++) {
        if (keys[i] > max_value) {
            max_value = keys[i];
        }
    }

    printf("Maximum value: %d\n", max_value);

    cleanup();
    return EXIT_SUCCESS;
}
