#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEYS 10000
#define LOG_SIZE 100

typedef struct {
    int* keys;
    size_t count;
    pthread_mutex_t lock;
} KeyArray;

typedef struct {
    char buffer[LOG_SIZE][256];
    size_t head, tail;
    pthread_mutex_t lock;
} LogBuffer;

KeyArray key_array = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
LogBuffer log_buffer = {{"", 0}, 0, PTHREAD_MUTEX_INITIALIZER};

void log_event(const char* message) {
    pthread_mutex_lock(&log_buffer.lock);
    strcpy(log_buffer.buffer[log_buffer.head], message);
    log_buffer.head = (log_buffer.head + 1) % LOG_SIZE;
    if (log_buffer.tail == log_buffer.head) {
        log_buffer.tail = (log_buffer.tail + 1) % LOG_SIZE;
    }
    pthread_mutex_unlock(&log_buffer.lock);
}

void* generate_keys(void* arg) {
    size_t range_start, range_end, seed;
    sscanf((char*)arg, "%zu %zu %zu", &range_start, &range_end, &seed);

    srand(seed);
    key_array.keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!key_array.keys) {
        log_event("Failed to allocate memory for keys");
        pthread_exit(NULL);
    }

    size_t count = 0;
    while (count < MAX_KEYS && scanf("%d", &key_array.keys[count]) == 1) {
        count++;
    }
    key_array.count = count;

    for (size_t i = 0; i < count; i++) {
        key_array.keys[i] = rand() % (range_end - range_start + 1) + range_start;
    }

    log_event("Keys generated successfully");
    pthread_exit(NULL);
}

double find_median(int* array, size_t size) {
    if (size == 0) return 0.0;

    qsort(array, size, sizeof(int), (int (*)(const void *, const void *))strcmp);

    if (size % 2 == 0)
        return (array[size / 2 - 1] + array[size / 2]) / 2.0;
    else
        return array[size / 2];
}

void* print_median(void* arg) {
    pthread_mutex_lock(&key_array.lock);
    if (key_array.keys == NULL || key_array.count == 0) {
        log_event("No keys available to find median");
        pthread_exit(NULL);
    }

    double median = find_median(key_array.keys, key_array.count);
    printf("Median: %f\n", median);

    free(key_array.keys);
    key_array.keys = NULL;
    key_array.count = 0;

    log_event("Median printed successfully");
    pthread_exit(NULL);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <range_start> <range_end> <seed>\n", argv[0]);
        return 1;
    }

    size_t range_start, range_end, seed;
    sscanf(argv[1], "%zu", &range_start);
    sscanf(argv[2], "%zu", &range_end);
    sscanf(argv[3], "%zu", &seed);

    pthread_t key_thread, median_thread;

    if (pthread_create(&key_thread, NULL, generate_keys, argv + 1) != 0) {
        log_event("Failed to create key generation thread");
        return 1;
    }

    pthread_join(key_thread, NULL);
    pthread_create(&median_thread, NULL, print_median, NULL);

    pthread_join(median_thread, NULL);

    printf("Log Buffer:\n");
    for (size_t i = log_buffer.tail; i != log_buffer.head;) {
        printf("%s\n", log_buffer.buffer[i]);
        i = (i + 1) % LOG_SIZE;
    }

    return 0;
}
