#define MAX_USERS 100

typedef struct {
    int sessionId;
    time_t lastActivity;
} userSession;

int findLargestInteger(int *array, int size) {
    if (size <= 0) return -1; // Error handling for empty array
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void processAndConnect(int maxUsers) {
    srand(time(NULL)); // Seed the PRNG
    userSession *sessions = malloc(maxUsers * sizeof(userSession));
    if (sessions == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    int *userInputArray = malloc(maxUsers * sizeof(int));
    if (userInputArray == NULL) {
        free(sessions);
        printf("Memory allocation failed\n");
        return;
    }

    // Read user input for session IDs and timestamps
    for (int i = 0; i < maxUsers; i++) {
        scanf("%d %ld", &sessions[i].sessionId, &sessions[i].lastActivity);
    }

    // Find and print the largest integer from user input
    int size;
    printf("Enter number of elements: ");
    scanf("%d", &size);
    if (size > maxUsers) {
        printf("Size exceeds maximum allowed\n");
        free(sessions);
        free(userInputArray);
        return;
    }
    for (int i = 0; i < size; i++) {
        scanf("%d", &userInputArray[i]);
    }
    int largestInteger = findLargestInteger(userInputArray, size);
    printf("Largest integer: %d\n", largestInteger);

    // Clean up allocated memory
    free(sessions);
    free(userInputArray);
}

