#include <stdio.h>
#include <stdlib.h>

#define ARRAY_SIZE 1000

typedef struct {
    int value;
} record;

// Custom PRNG function that balances performance and predictability
unsigned long custom_prng(unsigned long seed) {
    return (seed * 214013 + 2531011) % 4294967296UL;
}

void initialize_arrays(long **offsets, int **keys, record **records, unsigned long seed, int range_min, int range_max) {
    if (!(*offsets = (long *)malloc(ARRAY_SIZE * sizeof(long)))) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }
    if (!(*keys = (int *)malloc(ARRAY_SIZE * sizeof(int)))) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }
    if (!(*records = (record *)malloc(ARRAY_SIZE * sizeof(record)))) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    unsigned long prng_seed = seed;
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        (*offsets)[i] = custom_prng(prng_seed++);
        (*keys)[i] = range_min + custom_prng(prng_seed++) % (range_max - range_min + 1);
        (*records)[i].value = range_min + custom_prng(prng_seed++) % (range_max - range_min + 1);
    }
}

void cleanup(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long *offsets;
    int *keys;
    record *records;

    unsigned long seed = 42; // Example seed value
    int range_min = -1000;
    int range_max = 1000;

    initialize_arrays(&offsets, &keys, &records, seed, range_min, range_max);

    // Use the arrays...

    cleanup(offsets, keys, records);
    return 0;
}
