#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SESSION_ID_RANGE 10000

typedef struct session {
    int id;
    struct session *next;
} session_t;

session_t* create_session() {
    session_t *new_session = (session_t *)malloc(sizeof(session_t));
    if (new_session == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_session->id = rand() % SESSION_ID_RANGE;
    new_session->next = NULL;
    return new_session;
}

void add_session(session_t **head) {
    session_t *new_session = create_session();
    if (*head == NULL) {
        *head = new_session;
    } else {
        session_t *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_session;
    }
}

void free_sessions(session_t **head) {
    session_t *current = *head;
    while (current != NULL) {
        session_t *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));
    session_t *head = NULL;

    // Add sessions to the list
    for (int i = 0; i < 5; ++i) {
        add_session(&head);
    }

    // Free all allocated memory
    free_sessions(&head);

    return 0;
}
