#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Task 1: Allocate memory for 'long' offset values and 'int' keys
void allocateArrays(size_t max_kb, size_t *offset_size, size_t *key_size) {
    size_t total_memory = 0;
    while (total_memory <= max_kb * 1024) {
        *offset_size += sizeof(long);
        *key_size += sizeof(int);
        total_memory = (*offset_size + *key_size);
    }
