// Define a class for managing individual data streams
class DataStream {
    constructor(id) {
        this.id = id;
        this.paused = false;
        this.dataBuffer = [];
        this.memoryUsage = 0;
        this.maxMemory = 1024; // Example memory limit in bytes
    }

    addData(data) {
        if (!this.paused) {
            this.dataBuffer.push(data);
            this.memoryUsage += data.length * 2; // Approximate memory usage based on byte size

            if (this.memoryUsage > this.maxMemory) {
                this.pause();
                console.warn(`Stream ${this.id} exceeded memory limit. Pausing.`);
            }
        }
    }

    pause() {
        this.paused = true;
    }

    resume() {
        this.paused = false;
        this.processData();
    }

    processData() {
        while (!this.paused && this.dataBuffer.length > 0) {
            const data = this.dataBuffer.shift();
            // Process data (e.g., send to messaging system)
            console.log(`Processing data from stream ${this.id}: ${data}`);
            this.memoryUsage -= data.length * 2;
        }
    }
}

// Define a class for managing the overall data ingestion system
class DataIngestionSystem {
    constructor(maxStreams) {
        this.maxStreams = maxStreams;
        this.streams = new Map();
        this.nextStreamId = 1;
        this.messagingService = new MessagingService();
    }

    addStream() {
        if (this.streams.size >= this.maxStreams) {
            console.warn("Maximum number of streams reached. Cannot add more.");
            return null;
        }
        const stream = new DataStream(this.nextStreamId);
        this.streams.set(this.nextStreamId++, stream);
        return stream;
    }

    ingestData(data, streamId) {
        if (this.streams.has(streamId)) {
            this.streams.get(streamId).addData(data);
        } else {
            console.warn(`No active stream with ID ${streamId}. Data not ingested.`);
        }
    }

    pauseStream(streamId) {
        const stream = this.streams.get(streamId);
        if (stream) stream.pause();
    }

    resumeStream(streamId) {
        const stream = this.streams.get(streamId);
        if (stream) stream.resume();
    }
}

// Define a simple messaging service class for demonstration
class MessagingService {
    constructor() {
        this.queue = [];
    }

    sendMessage(message) {
        return new Promise((resolve, reject) => {
            setTimeout(() => {
                // Simulate message delivery with possible failure
                if (Math.random() < 0.1) {
                    console.error("Message failed to deliver. Retrying...");
                    resolve(false);
                } else {
                    this.queue.push(message);
                    console.log(`Message delivered: ${message}`);
                    resolve(true);
                }
            }, Math.random() * 500); // Random delay simulating network latency
        });
    }

    async retryFailedMessages(maxRetries = 3) {
        for (let i = 0; i < maxRetries; i++) {
            const failedMessages = this.queue.filter(msg => !msg.delivered);
            if (failedMessages.length === 0) break;

            await Promise.all(failedMessages.map(msg => this.sendMessage(msg)));
        }
    }
}

// Example usage
const system = new DataIngestionSystem(10);

const stream1 = system.addStream();
system.ingestData("Data from stream 1", 1);
system.pauseStream(1);

setTimeout(() => {
    system.resumeStream(1);
}, 2000);

setInterval(() => {
    const randomMessage = `Random data at ${new Date().toISOString()}`;
    if (stream1 && !stream1.paused) {
        stream1.addData(randomMessage);
    }
}, 500);
```

This code provides a basic framework for a scalable data ingestion system in JavaScript. It includes classes for managing individual data streams, handling memory usage, and interacting with a messaging service. The example demonstrates adding streams, ingesting data, pausing and resuming streams, and simulating message delivery with retry logic.']

