class InputSource {
public:
    virtual ~InputSource() {}
    virtual bool read(char* buffer, size_t maxSize) = 0;
};

class StandardInputSource : public InputSource {
public:
    bool read(char* buffer, size_t maxSize) override {
        return std::cin.read(buffer, maxSize).gcount() > 0;
    }
};

class FileInputSource : public InputSource {
private:
    std::ifstream file;
public:
    FileInputSource(const std::string& filePath) : file(filePath) {}
    bool read(char* buffer, size_t maxSize) override {
        return file.read(buffer, maxSize).gcount() > 0;
    }
};

std::mutex logMutex;

void logCharacterRead(size_t characters) {
    std::lock_guard<std::mutex> lock(logMutex);
    std::cout << "Characters read: " << characters << std::endl;
}

std::string readFromSources(const std::vector<InputSource*>& sources, size_t maxChars) {
    std::string result;
    size_t totalRead = 0;

    for (auto& source : sources) {
        char buffer[1024];
        while (totalRead < maxChars && source->read(buffer, sizeof(buffer))) {
            size_t charsRead = std::cin.gcount();
            if (charsRead + result.size() > maxChars - totalRead) {
                charsRead = maxChars - totalRead;
            }
            result.append(buffer, charsRead);
            totalRead += charsRead;
            logCharacterRead(charsRead);
        }
    }

    return result;
}

int main() {
    std::vector<InputSource*> sources;
    sources.push_back(new StandardInputSource());
    sources.push_back(new FileInputSource("input.txt"));

    size_t maxChars = 1024 * 1024; // 1 MB
    std::string result = readFromSources(sources, maxChars);

    std::cout << "Final string: " << result << std::endl;

    for (auto& source : sources) {
        delete source;
    }

    return 0;
}
```

