function concatenateBuffers(buffers, startByte, endByte) {
    let totalLength = 0;
    for (let i = startByte; i < endByte; ++i) {
        totalLength += buffers[i].length;
    }

    const resultBuffer = Buffer.allocUnsafe(totalLength);
    let offset = 0;

    for (let i = startByte; i < endByte; ++i) {
        buffers[i].copy(resultBuffer, offset);
        offset += buffers[i].length;
    }

    return resultBuffer;
}
