// Define audit entry structure
typedef struct {
    char* description;
    size_t memory_size;
    unsigned seed_used;
    unsigned warnings;
    unsigned errors;
} AuditEntry;

// Custom PRNG state
unsigned long custom_prng_state = 0;

// Custom PRNG function (Mersenne Twister)
unsigned long custom_prng() {
    static const unsigned long MT_N = 624;
    static const unsigned long MT_M = 397;
    static const unsigned long MATRIX_A = 0x9908b0dfUL;
    static const unsigned long UPPER_MASK = 0x80000000UL;
    static const unsigned long LOWER_MASK = 0x7fffffffUL;

    if (custom_prng_state == 0) {
        custom_prng_state = time(NULL);
    }

    unsigned long x = custom_prng_state;
    x ^= (x >> 11);
    x ^= (x << 7) & MATRIX_A;
    x ^= (x << 15) & UPPER_MASK;
    x ^= (x >> 18);

    custom_prng_state = x;

    return x;
}

// Function to allocate and initialize arrays
int allocate_and_initialize(
    long** offsets,
    int** keys,
    Record** records,
    AuditEntry** audits,
    size_t size,
    unsigned seed) {

    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return -1;
    }

    *keys = malloc(size * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        return -1;
    }

    *records = malloc(size * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    *audits = malloc(size * sizeof(AuditEntry));
    if (*audits == NULL) {
        fprintf(stderr, "Memory allocation failed for audits\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    // Initialize PRNG seed
    custom_prng_state = seed;

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = custom_prng();
        (*keys)[i] = custom_prng() % 1000; // Random value in range [0, 999]

        time_t current_time;
        time(&current_time);
        (*records)[i].value = (*keys)[i];
        (*records)[i].creation_time = current_time;
        (*records)[i].flags = 0;

        snprintf((*audits)[i].description, 256, "Record %zu initialized", i);
        (*audits)[i].memory_size = sizeof(Record) * size;
        (*audits)[i].seed_used = seed;
        (*audits)[i].warnings = 0;
        (*audits)[i].errors = 0;
    }

    return 0;
}

// Example usage
int main() {
    const size_t size = 1000;
    unsigned seed = time(NULL);

    long* offsets;
    int* keys;
    Record* records;
    AuditEntry* audits;

    if (allocate_and_initialize(&offsets, &keys, &records, &audits, size, seed) == 0) {
        // Process data here
        free(offsets);
        free(keys);
        free(records);
        free(audits);
    }

    return 0;
}
