Record* create_record_array(size_t size, int min_value, int max_value) {
    if (RAND_status() != 1) {
        // Initialize the CSPRNG
        if (!RAND_poll()) {
            return NULL; // CSPRNG initialization failed
        }
    }

    Record* array = malloc(size * sizeof(Record));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < size; ++i) {
        array[i].offset = i * sizeof(Record);
        array[i].key = rand() % size;
        if (!RAND_bytes((unsigned char*)&array[i].value, sizeof(int))) {
            // Failed to generate random number
            free(array); // Free the allocated memory
            return NULL;
        }
        array[i].value %= (max_value - min_value + 1) + min_value; // Ensure value is within specified range
    }

    return array;
}

void destroy_record_array(Record* array, size_t size) {
    free(array); // Free the allocated memory for the record array
}
