#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

unsigned long xorshift128plus(unsigned long *state) {
    unsigned long x = state[0];
    unsigned long y = state[1];
    unsigned long z = state[2];
    unsigned long t;

    y ^= x;
    state[0] = x = (x << 24) | (x >> 8);
    state[1] = y;
    t = y ^ (y << 11);
    state[2] = y = (y << 19) | (y >> 13);
    state[3] = z;
    state[3] ^= x;
    return ((t << 8) | (t >> 24)) + z;
}

void generate_records(int size, int min_val, int max_val, unsigned long *prng_state) {
    if (size <= 0 || min_val > max_val) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (int i = 0; i < size; i++) {
        offsets[i] = xorshift128plus(prng_state) % (max_val - min_val + 1) + min_val;
        keys[i] = xorshift128plus(prng_state) % (max_val - min_val + 1) + min_val;
        records[i].value = i;
    }

    // Check for unique identifiers
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if ((offsets[i] << 32) | keys[i] == (offsets[j] << 32) | keys[j]) {
                fprintf(stderr, "Duplicate identifier found.\n");
                free(offsets);
                free(keys);
                free(records);
                return;
            }
        }
    }

    // Generate summary report
    FILE *report = fopen("records_report.csv", "w");
    if (report == NULL) {
        fprintf(stderr, "Failed to create report file.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    fprintf(report, "Offset,Key,Record Value\n");
    for (int i = 0; i < size; i++) {
        fprintf(report, "%ld,%d,%d\n", offsets[i], keys[i], records[i].value);
    }
    fclose(report);

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    unsigned long prng_state[] = {123456789UL, 987654321UL, 456789123UL};
    srand(time(NULL));
    xorshift128plus(prng_state);
    generate_records(100, 1, 1000, prng_state);

    return 0;
}
