#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

unsigned long custom_prng(unsigned long seed) {
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

int compare_records(const void *a, const void *b) {
    return ((record *)a)->value - ((record *)b)->value;
}

void initialize_records(long *offsets, int *keys, record **records, size_t size, unsigned long range_min, unsigned long range_max) {
    if (size == 0 || range_min > range_max) {
        fprintf(stderr, "Invalid input: size must be greater than 0 and range_min must be less than or equal to range_max\n");
        return;
    }

    offsets = (long *)malloc(size * sizeof(long));
    keys = (int *)malloc(size * sizeof(int));
    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed for offsets and/or keys\n");
        free(offsets);
        free(keys);
        return;
    }

    *records = (record *)malloc(size * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    unsigned long seed = time(NULL);
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = custom_prng(seed + i);
        keys[i] = custom_prng(seed + i * 2 + 1);
        (*records)[i].value = range_min + custom_prng(seed + i * 3 + 2) % (range_max - range_min + 1);
    }

    qsort(*records, size, sizeof(record), compare_records);

    free(offsets);
    free(keys);
}

int main() {
    size_t size = 100;
    unsigned long range_min = 0;
    unsigned long range_max = 1000;

    long *offsets;
    int *keys;
    record *records;

    initialize_records(&offsets, &keys, &records, size, range_min, range_max);

    if (records) {
        for (size_t i = 0; i < size; ++i) {
            printf("Record %zu: value=%d\n", i, records[i].value);
        }
        free(records);
    }

    return 0;
}
