entry* initialize_entries(size_t count, int prng_type, unsigned int key_range_start, unsigned int key_range_end, time_t seed) {
    if (count == 0 || key_range_start >= key_range_end) return NULL;

    entry* entries = malloc(count * sizeof(entry));
    if (!entries) return NULL;

    unsigned int* keys = malloc(count * sizeof(unsigned int));
    if (!keys) {
        free(entries);
        return NULL;
    }

    char** strings = malloc(count * sizeof(char*));
    if (!strings) {
        free(entries);
        free(keys);
        return NULL;
    }

    long* offsets = malloc(count * sizeof(long));
    if (!offsets) {
        free(entries);
        free(keys);
        free(strings);
        return NULL;
    }

    srand(seed);

    for (size_t i = 0; i < count; ) {
        unsigned int key = rand() % (key_range_end - key_range_start) + key_range_start;
        int is_unique = 1;

        for (size_t j = 0; j < i; j++) {
            if (keys[j] == key) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            keys[i] = key;

            char* string = malloc(rand() % 128 + 1);
            if (!string) {
                free(entries);
                free(keys);
                free(strings);
                free(offsets);
                for (size_t j = 0; j < i; j++) {
                    free(strings[j]);
                }
                return NULL;
            }

            strings[i] = string;

            size_t length = strlen(string);
            offsets[i] = rand();

            entries[i].key = key;
            entries[i].string = string;
            entries[i].length = length;
            entries[i].offset = offsets[i];

            i++;
        }
    }

    qsort(entries, count, sizeof(entry), (int (*)(const void*, const void*))compare_entries);

    return entries;
}

int compare_entries(const void* a, const void* b) {
    return ((entry*)a)->key - ((entry*)b)->key;
}
