#include <time.h>
#include <pthread.h>

#define BUFFER_SIZE 1024

typedef struct {
    char buffer[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

void initCircularBuffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
}

int isCircularBufferFull(CircularBuffer *cb) {
    return (cb->head + 1) % BUFFER_SIZE == cb->tail;
}

int isCircularBufferEmpty(CircularBuffer *cb) {
    return cb->head == cb->tail;
}

void writeToCircularBuffer(CircularBuffer *cb, const char *msg) {
    if (!isCircularBufferFull(cb)) {
        int index = (cb->head + 1) % BUFFER_SIZE;
        snprintf(cb->buffer[index], BUFFER_SIZE, msg);
        cb->head = index;
    }
}

void readFromCircularBuffer(CircularBuffer *cb, char *msg) {
    if (!isCircularBufferEmpty(cb)) {
        int index = (cb->tail + 1) % BUFFER_SIZE;
        snprintf(msg, BUFFER_SIZE, "%s", cb->buffer[index]);
        cb->tail = index;
    }
}

void *processDataAndRunTests(void *arg) {
    CircularBuffer logBuffer;
    initCircularBuffer(&logBuffer);

    // Simulate processing
    for (int i = 0; i < 1000; ++i) {
        writeToCircularBuffer(&logBuffer, "Processing data...\n");
        sleep(1);
    }

    // Clean up and exit
    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, processDataAndRunTests, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);
    return 0;
}
