// Define the record structure
typedef struct {
    int value;
} record;

// Function prototypes
void* safe_malloc(size_t size);
record* createRecords(int num_records, int seed, int range_start, int range_end);
int findLargest(int* arr, int size);
void processAndConnect();

int main() {
    // Call the function to process and connect
    processAndConnect();
    return 0;
}

// Function to safely allocate memory with error handling
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to create records with random values and initialize them
record* createRecords(int num_records, int seed, int range_start, int range_end) {
    srand(seed); // Seed the PRNG
    record* recs = safe_malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        recs[i].value = rand() % (range_end - range_start + 1) + range_start;
    }
    return recs;
}

// Function to find the largest integer in an array
int findLargest(int* arr, int size) {
    if (size == 0) return INT_MIN; // Handle empty array case
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Main function to process and connect
void processAndConnect() {
    // Example usage of the functions
    int num_records = 10;
    record* records = createRecords(num_records, time(NULL), -100, 100);

    int size = 5; // Size of the array to read from input
    int* arr = safe_malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    int largest = findLargest(arr, size);
    printf("Largest integer: %d\n", largest);

    // Free allocated memory
    free(records);
    free(arr);
}
