#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/rand.h>

#define TOKEN_LENGTH 32
#define LOG_BUFFER_SIZE 1024

typedef struct {
    long timestamp;
    char token[TOKEN_LENGTH];
} Session;

typedef struct {
    Session* sessions;
    int count;
    int capacity;
    pthread_mutex_t lock;
} SessionManager;

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t log_lock;
} Logger;

SessionManager* createSessionManager() {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->sessions = NULL;
    manager->count = 0;
    manager->capacity = 10;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroySessionManager(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        memset(manager->sessions[i].token, 0, TOKEN_LENGTH);
    }
    free(manager->sessions);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void addSessionToken(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        Session* new_sessions = (Session*)realloc(manager->sessions, manager->capacity * sizeof(Session));
        if (!new_sessions) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        manager->sessions = new_sessions;
    }
    manager->sessions[manager->count].timestamp = time(NULL);
    if (!RAND_bytes((unsigned char*)manager->sessions[manager->count].token, TOKEN_LENGTH)) {
        fprintf(stderr, "Failed to generate token\n");
        return;
    }
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void printMostRecentSession(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == 0) {
        printf("No sessions available\n");
    } else {
        int index = -1;
        for (int i = 0; i < manager->count; i++) {
            if (index == -1 || manager->sessions[i].timestamp > manager->sessions[index].timestamp) {
                index = i;
            }
        }
        printf("Most recent session: Timestamp=%ld, Token=%s\n", manager->sessions[index].timestamp, manager->sessions[index].token);
    }
    pthread_mutex_unlock(&manager->lock);
}

Logger* createLogger() {
    Logger* logger = (Logger*)malloc(sizeof(Logger));
    memset(logger->buffer, 0, LOG_BUFFER_SIZE);
    logger->head = 0;
    logger->tail = 0;
    logger->count = 0;
    pthread_mutex_init(&logger->log_lock, NULL);
    return logger;
}

void destroyLogger(Logger* logger) {
    pthread_mutex_lock(&logger->log_lock);
    memset(logger->buffer, 0, LOG_BUFFER_SIZE);
    logger->head = 0;
    logger->tail = 0;
    logger->count = 0;
    pthread_mutex_unlock(&logger->log_lock);
    pthread_mutex_destroy(&logger->log_lock);
    free(logger);
}

void logEvent(Logger* logger, const char* message) {
    pthread_mutex_lock(&logger->log_lock);
    if (logger->count == LOG_BUFFER_SIZE) {
        logger->head = (logger->head + 1) % LOG_BUFFER_SIZE;
    } else {
        logger->count++;
    }
    snprintf(logger->buffer + logger->tail * LOG_BUFFER_SIZE / logger->count, sizeof(char), "%s\n", message);
    logger->tail = (logger->tail + 1) % logger->count;
    pthread_mutex_unlock(&logger->log_lock);
}

void* generateSessionTokens(void* arg) {
    SessionManager* manager = (SessionManager*)arg;
    Logger* logger = createLogger();

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        long timestamp = atol(buffer);
        if (timestamp == 0 && feof(stdin)) break;

        addSessionToken(manager);
        logEvent(logger, "Session token generated");
    }

    printMostRecentSession(manager);
    destroyLogger(logger);

    return NULL;
}

int main() {
    SessionManager* manager = createSessionManager();
    pthread_t thread;
    pthread_create(&thread, NULL, generateSessionTokens, (void*)manager);

    // Simulate timeout mechanism
    sleep(10);
    pthread_cancel(thread);

    destroySessionManager(manager);
    return 0;
}
