#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <uuid/uuid.h>

// Function to generate a unique key using PRNG
uint64_t generateKey(uint64_t seed) {
    // Initialize PRNG with the seed
    srand(seed);
    // Generate and return a pseudo-random number as a key
    return (uint64_t)rand();
}

// Helper function to calculate median of an array
double findMedian(int* arr, int size) {
    qsort(arr, size, sizeof(int), (int (*)(const void *, const void *))strcmp);
    if (size % 2 != 0)
        return (double)arr[size / 2];
    else
        return (double)(arr[(size - 1) / 2] + arr[size / 2]) / 2.0;
}

// Function to log key generation details to a file
void logKeyGeneration(uint64_t* keys, uuid_t* uuids, int size, const char* filename) {
    FILE* logFile = fopen(filename, "w");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    for (int i = 0; i < size; i++) {
        fprintf(logFile, "Key: %" PRIu64 ", UUID: %s, Timestamp: %ld\n", keys[i], uuids[i], now);
    }
    fclose(logFile);
}

// Function to generate unique keys and log their details
void generateUniqueKeys(int numKeys, uint64_t seed) {
    uint64_t* keys = (uint64_t*)malloc(numKeys * sizeof(uint64_t));
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        return;
    }

    uuid_t* uuids = (uuid_t*)malloc(numKeys * sizeof(uuid_t));
    if (uuids == NULL) {
        perror("Failed to allocate memory for UUIDs");
        free(keys);
        return;
    }

    srand(seed);
    for (int i = 0; i < numKeys; i++) {
        keys[i] = generateKey(i); // Using index as a simple seed
        uuid_generate(uuids[i]);
    }

    int* intKeys = (int*)malloc(numKeys * sizeof(int));
    if (intKeys == NULL) {
        perror("Failed to allocate memory for integer keys");
        free(keys);
        free(uuids);
        return;
    }
    for (int i = 0; i < numKeys; i++) {
        intKeys[i] = (int)(keys[i] % 100); // Convert keys to integers in a simple way
    }

    double median = findMedian(intKeys, numKeys);
    printf("Median: %.2f\n", median);

    logKeyGeneration(keys, uuids, numKeys, "key_log.txt");

    free(keys);
    free(uuids);
    free(intKeys);
}

int main() {
    int numKeys;
    printf("Enter the number of keys to generate: ");
    scanf("%d", &numKeys);

    uint64_t seed;
    printf("Enter a seed value for PRNG: ");
    scanf("%lu", &seed);

    generateUniqueKeys(numKeys, seed);

    return 0;
}
