#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_MESSAGES 1000

typedef struct {
    time_t timestamp;
    int sequence_number;
    char data_payload[256];
} Message;

Message *messages[MAX_MESSAGES];
int message_count = 0;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

void seed_random_number_generator(unsigned int seed) {
    srand(seed);
}

int transmitMessages(int seed, int port) {
    seed_random_number_generator(seed);

    // Read messages from standard input and store them in the buffer
    while (message_count < MAX_MESSAGES && fgets(messages[message_count]->data_payload, 256, stdin)) {
        time(&messages[message_count]->timestamp);
        messages[message_count++]->sequence_number = rand();
    }

    pthread_t connection_thread;
    if (pthread_create(&connection_thread, NULL, send_messages_to_server, port) != 0) {
        perror("Failed to create connection thread");
        return -1;
    }

    pthread_join(connection_thread, NULL);
    return message_count;
}

void *send_messages_to_server(void *port_ptr) {
    int port = *(int *)port_ptr;
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        pthread_exit(NULL);
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to connect to server");
        close(sockfd);
        pthread_exit(NULL);
    }

    for (int i = 0; i < message_count; i++) {
        pthread_mutex_lock(&buffer_mutex);
        if (send(sockfd, messages[i], sizeof(Message), 0) < 0) {
            perror("Failed to send message");
            break;
        }
        pthread_mutex_unlock(&buffer_mutex);
    }

    close(sockfd);
    pthread_exit(NULL);
}
```

