    *count = 0;
    for (char *token = strtok(input, " "); token != NULL; token = strtok(NULL, " ")) {
        (*count)++;
    }

    int* numbers = (int*)malloc((*count) * sizeof(int));
    if (numbers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    int index = 0;
    for (char *token = strtok(input, " "); token != NULL; token = strtok(NULL, " ")) {
        numbers[index++] = atoi(token);
    }

    return numbers;
}

double findMedian(int* numbers, int count) {
    qsort(numbers, count, sizeof(int), (int (*)(const void *, const void *))strcmp);
    if (count % 2 == 0) {
        return (numbers[count / 2 - 1] + numbers[count / 2]) / 2.0;
    } else {
        return numbers[count / 2];
    }
}

session* generateSessionIDs(int count, unsigned long seed) {
    if (count > MAX_SESSIONS) {
        fprintf(stderr, "Input exceeds maximum allowed sessions\n");
        exit(1);
    }

    srand(seed);
    session* sessions = (session*)malloc(count * sizeof(session));
