typedef struct {
    int id;
    int priority;
    int status;
} Transaction;

Transaction* allocateTransactions(int initialCapacity, int *currentSize) {
    Transaction *transactions = (Transaction *)malloc(initialCapacity * sizeof(Transaction));
    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    *currentSize = 0;
    return transactions;
}

void resizeTransactions(Transaction **transactions, int *initialCapacity, int *currentSize) {
    *initialCapacity *= 2;
    Transaction *newTransactions = (Transaction *)realloc(*transactions, *initialCapacity * sizeof(Transaction));
    if (newTransactions == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }
    *transactions = newTransactions;
}

int generateRandomPriority(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void transactionProcessor(int seed) {
    srand(seed);
    int capacity = 10;
    Transaction *transactions = allocateTransactions(capacity, &capacity);
    int currentSize;

    // Simulate reading integers from standard input and processing transactions
    int value;
    while (scanf("%d", &value) != EOF) {
        if (currentSize == capacity) {
            resizeTransactions(&transactions, &capacity, &currentSize);
        }
        transactions[currentSize].id = currentSize + 1;
        transactions[currentSize].priority = generateRandomPriority(1, 10);
        transactions[currentSize].status = value % 2; // Example status code
        currentSize++;
    }

    // Example: Find the largest priority
    int maxPriority = 0;
    for (int i = 0; i < currentSize; i++) {
        if (transactions[i].priority > maxPriority) {
            maxPriority = transactions[i].priority;
        }
    }
    printf("Max Priority: %d\n", maxPriority);

    // Free allocated memory
    free(transactions);
}

int main() {
    int seed;
    printf("Enter a seed value for the random number generator: ");
    scanf("%d", &seed);
    transactionProcessor(seed);
    return 0;
}
