public class BankAccountService {
    private static final int MAX_ATTEMPTS = 5;
    private static final long RATE_LIMIT_INTERVAL = 60000; // in milliseconds (1 minute)
    private static final Map<String, Integer> attemptCounts = new ConcurrentHashMap<>();
    private static final Set<String> accountNumbers = Collections.synchronizedSet(new HashSet<>());
    private static final Logger logger = LoggerFactory.getLogger(BankAccountService.class);
    private AccountRepository accountRepository;

    public BankAccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    public synchronized boolean createBankAccount(String userId, String accountNumber, BigDecimal initialBalance, String authenticationToken) {
        if (!isValidAuthenticationToken(userId, authenticationToken)) {
            logAttemptFailure(userId);
            return false;
        }

        if (hasReachedRateLimit(userId)) {
            logger.warn("Rate limit exceeded for user: {}", userId);
            return false;
        }

        if (isDuplicateAccountNumber(accountNumber)) {
            logAttemptFailure(userId);
            return false;
        }

        try {
            validateInput(accountNumber, initialBalance);

            Account newAccount = new Account();
            newAccount.setUserId(userId);
            newAccount.setAccountNumber(accountNumber);
            newAccount.setBalance(initialBalance);

            accountRepository.save(newAccount);
            logger.info("New bank account created for user: {}", userId);
            return true;
        } catch (InvalidInputException e) {
            logAttemptFailure(userId);
            logger.error("Invalid input while creating bank account for user: {}", userId, e);
            return false;
        } finally {
            resetRateLimit(userId);
        }
    }

    private boolean isValidAuthenticationToken(String userId, String token) {
        // Implement authentication logic here
        return true; // Placeholder
    }

    private boolean hasReachedRateLimit(String userId) {
        attemptCounts.putIfAbsent(userId, 0);
        int count = attemptCounts.get(userId);

        if (count >= MAX_ATTEMPTS) {
            return true;
        } else {
            attemptCounts.put(userId, count + 1);
            return false;
        }
    }

    private void resetRateLimit(String userId) {
        attemptCounts.remove(userId);
    }

    private boolean isDuplicateAccountNumber(String accountNumber) {
        return !accountNumbers.add(accountNumber); // returns false if already exists
    }

    private void validateInput(String accountNumber, BigDecimal initialBalance) throws InvalidInputException {
        if (accountNumber == null || accountNumber.isEmpty()) {
            throw new InvalidInputException("Invalid account number");
        }
        if (initialBalance == null || initialBalance.compareTo(BigDecimal.ZERO) < 0) {
            throw new InvalidInputException("Invalid initial balance");
        }
    }

    private void logAttemptFailure(String userId) {
        logger.warn("Failed attempt to create bank account for user: {}", userId);
    }
}
