['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_TOKENS 1000
#define LOG_BUFFER_SIZE 100
#define CACHE_SIZE 50

typedef struct {
    char *token;
    time_t expiration_time;
} Token;

typedef struct {
    int head, tail;
    Token buffer[LOG_BUFFER_SIZE];
} LogBuffer;

typedef struct {
    int size, max_size;
    Token tokens[CACHE_SIZE];
    time_t last_accessed[CACHE_SIZE];
} TokenCache;

LogBuffer log_buffer;
TokenCache token_cache;
pthread_mutex_t cache_lock;

void initialize_log_buffer() {
    log_buffer.head = log_buffer.tail = 0;
}

void add_log_entry(const char *message) {
    pthread_mutex_lock(&cache_lock);
    int next_tail = (log_buffer.tail + 1) % LOG_BUFFER_SIZE;
    if (next_tail != log_buffer.head) {
        log_buffer.buffer[log_buffer.tail].token = strdup(message);
        log_buffer.tail = next_tail;
    }
    pthread_mutex_unlock(&cache_lock);
}

void initialize_token_cache() {
    token_cache.size = 0;
    token_cache.max_size = CACHE_SIZE;
    pthread_mutex_init(&cache_lock, NULL);
}

int get_cached_token(const char *key) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < token_cache.size; ++i) {
        if (strcmp(token_cache.tokens[i].token, key) == 0 && time(NULL) < token_cache.last_accessed[i]) {
            token_cache.last_accessed[i] = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return -1;
}

void cache_token(const char *key, const char *token, time_t expiration_time) {
    pthread_mutex_lock(&cache_lock);
    if (token_cache.size == token_cache.max_size) {
        int oldest_index = log_buffer.head;
        for (int i = 0; i < token_cache.size; ++i) {
            if (log_buffer.buffer[i].expiration_time < log_buffer.buffer[oldest_index].expiration_time) {
                oldest_index = i;
            }
        }
        free(log_buffer.buffer[oldest_index].token);
    } else {
        token_cache.size++;
    }
    int index = (log_buffer.tail + 1) % CACHE_SIZE;
    token_cache.tokens[index] = (Token){strdup(token), expiration_time};
    log_buffer.buffer[log_buffer.tail].token = strdup("Token cached");
    log_buffer.tail = (log_buffer.tail + 1) % LOG_BUFFER_SIZE;
    pthread_mutex_unlock(&cache_lock);
}

int generateSessionTokens(int num_tokens, size_t token_length, time_t seed, int timeout_seconds) {
    initialize_log_buffer();
    initialize_token_cache();

    srand(seed);

    for (int i = 0; i < num_tokens; ++i) {
        char *token = malloc(token_length + 1);
        if (!token) {
            add_log_entry("Memory allocation failed");
            return -1;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        time_t now = ts.tv_sec;

        for (size_t j = 0; j < token_length; ++j) {
            token[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        token[token_length] = '\0';

        if (!get_cached_token(token)) {
            time_t expiration_time = now + 3600; // Token valid for one hour
            cache_token(token, token, expiration_time);
            add_log_entry("Token generated: %s", token);
        } else {
            add_log_entry("Duplicate token detected");
            free(token);
        }

        if (i % 10 == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            time_t elapsed = ts.tv_sec - now;
            if (elapsed > timeout_seconds) {
                add_log_entry("Timeout occurred");
                return -1;
            }
        }
    }

    return 0;
}
