#include <time.h>
#include <string.h>
#include <pthread.h>

#define TOKEN_SIZE 32
#define MAX_LOG_ENTRIES 1000

typedef struct {
    char token[TOKEN_SIZE];
    time_t timestamp;
} SessionToken;

typedef struct {
    SessionToken tokens[MAX_LOG_ENTRIES];
    int head;
    int count;
    pthread_mutex_t lock;
} CircularBuffer;

void generateSessionTokens(int numTokens, uint64_t seed, CircularBuffer* log) {
    // Seed the PRNG
    srand(seed);

    for (int i = 0; i < numTokens; i++) {
        SessionToken token;
        // Generate a secure random token
        for (int j = 0; j < TOKEN_SIZE; j++) {
            token.token[j] = rand() % 256;
        }
        time_t now = time(NULL);
        token.timestamp = now;

        pthread_mutex_lock(&log->lock);
        if (log->count < MAX_LOG_ENTRIES) {
            log->tokens[log->head++] = token;
            log->head %= MAX_LOG_ENTRIES;
            log->count++;
        } else {
            // Overwrite the oldest entry
            log->tokens[log->head] = token;
            log->head = (log->head + 1) % MAX_LOG_ENTRIES;
        }
        pthread_mutex_unlock(&log->lock);
    }
}

int main() {
    CircularBuffer log;
    pthread_mutex_init(&log.lock, NULL);

    generateSessionTokens(5, time(NULL), &log);

    // Clean up
    pthread_mutex_destroy(&log.lock);

    return 0;
}
