}

int* initialize_key_array(FILE* input, int size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (keys == NULL) {
        perror("Failed to allocate memory for key array");
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), input) != NULL && size > 0) {
        keys[--size] = atoi(strtok(line, ","));
    }
    if (size > 0) {
        fprintf(stderr, "Not enough data in CSV file.\n");
        free(keys);
        return NULL;
    }

    // Sort the array for simplicity in finding smallest and second smallest
    qsort(keys, size, sizeof(int), (int(*)(const void*, const void*))strcmp);

    return keys;
}

record* initialize_record_array(int size, int min_val, int max_val, unsigned long seed) {
    record* records = (record*)malloc(size * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for record array");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < size; i++) {
        records[i].value = prng(rand());
        records[i].value %= max_val - min_val + 1;
        records[i].value += min_val;
    }

    return records;
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

unsigned long prng(unsigned long state) {
    // Simple linear congruential generator
    const unsigned long a = 1664525;
    const unsigned long c = 1013904223;
    return (a * state + c) % UINT_MAX;
}

void print_smallest_and_second_smallest(int* keys, int size) {
    if (size < 2) {
        fprintf(stderr, "Not enough elements to find smallest and second smallest.\n");
        return;
    }

    printf("Smallest: %d\n", keys[0]);
    printf("Second Smallest: %d\n", keys[1]);
}
