#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1024

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    long offset;
    int key;
} OffsetKey;

int* indexArray = NULL;
Record* recordArray = NULL;
OffsetKey* offsetKeyArray = NULL;
size_t arraySize = 0;

void initializeArrays(size_t size) {
    if (indexArray != NULL || recordArray != NULL || offsetKeyArray != NULL) {
        fprintf(stderr, "Arrays are already initialized.\n");
        return;
    }

    indexArray = (int*)malloc(size * sizeof(int));
    recordArray = (Record*)malloc(size * sizeof(Record));
    offsetKeyArray = (OffsetKey*)malloc(size * sizeof(OffsetKey));

    if (indexArray == NULL || recordArray == NULL || offsetKeyArray == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    arraySize = size;
}

void populateArrays() {
    srand(time(NULL)); // Seed the PRNG with current time for better randomness

    for (size_t i = 0; i < arraySize; ++i) {
        indexArray[i] = rand();

        recordArray[i].offset = rand();
        recordArray[i].key = rand();

        offsetKeyArray[i].offset = rand();
        offsetKeyArray[i].key = rand();
    }
}

void resizeArrays(size_t newSize) {
    if (newSize <= arraySize) {
        fprintf(stderr, "New size must be greater than current size.\n");
        return;
    }

    int* newIndexArray = (int*)realloc(indexArray, newSize * sizeof(int));
    Record* newRecordArray = (Record*)realloc(recordArray, newSize * sizeof(Record));
    OffsetKey* newOffsetKeyArray = (OffsetKey*)realloc(offsetKeyArray, newSize * sizeof(OffsetKey));

    if (newIndexArray == NULL || newRecordArray == NULL || newOffsetKeyArray == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(EXIT_FAILURE);
    }

    indexArray = newIndexArray;
    recordArray = newRecordArray;
    offsetKeyArray = newOffsetKeyArray;

    arraySize = newSize;
}

void cleanupArrays() {
    free(indexArray);
    free(recordArray);
    free(offsetKeyArray);
    indexArray = NULL;
    recordArray = NULL;
    offsetKeyArray = NULL;
    arraySize = 0;
}
```

This code provides a basic framework for managing memory for multiple data structures with random values. It initializes arrays, populates them with random data, resizes the arrays as needed, and cleans up the allocated memory when done. The use of `rand()` for PRNG is chosen for its simplicity and efficiency, which are typically sufficient for non-cryptographic purposes. For applications requiring higher security or more complex randomness, consider using cryptographic-grade libraries like OpenSSL's random number generator functions.']

