#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEM (1024 * 1024) // 1 MB

typedef struct {
    int value;
} record;

unsigned long xorshift(unsigned long x) {
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return x;
}

long get_time_ns() {
    static struct timespec start = {0, 0};
    if (start.tv_sec == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
    }
    struct timespec current;
    clock_gettime(CLOCK_MONOTONIC, &current);
    return (current.tv_sec - start.tv_sec) * 1000000000L + (current.tv_nsec - start.tv_nsec);
}

record* allocate_memory(size_t N, size_t M, int minVal, int maxVal) {
    unsigned long total_size = N * sizeof(long) + N * sizeof(int) + M * sizeof(record) + M * sizeof(timestamp);
    if (total_size > MAX_MEM) {
        return NULL;
    }

    long* offsets = malloc(N * sizeof(long));
    int* keys = malloc(N * sizeof(int));
    record* records = malloc(M * sizeof(record));
    timestamp* timestamps = malloc(M * sizeof(timestamp));

    if (!offsets || !keys || !records || !timestamps) {
        free(offsets);
        free(keys);
        free(records);
        free(timestamps);
        return NULL;
    }

    unsigned long seed = get_time_ns();
    for (size_t i = 0; i < N; ++i) {
        offsets[i] = xorshift(seed) % MAX_MEM;
        keys[i] = xorshift(seed++) % (maxVal - minVal + 1) + minVal;
    }

    for (size_t i = 0; i < M; ++i) {
        records[i].value = xorshift(seed++) % (maxVal - minVal + 1) + minVal;
        timestamps[i] = get_time_ns();
    }

    return records;
}

int main() {
    size_t N = 1024;
    size_t M = 512;
    int minVal = 1;
    int maxVal = 100;

    record* records = allocate_memory(N, M, minVal, maxVal);
    if (records) {
        printf("Memory allocation successful.\n");
        free(records);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
