typedef int64_t timestamp_t;
typedef enum { DEBUG, INFO, WARNING, ERROR } log_level_t;

typedef struct {
    timestamp_t *timestamp;
    log_level_t level;
    char *message;
} log_entry_t;

#define MAX_MEM 1024 * 1024 * 1024 // 1GB

void initialize_logging_system(size_t n, size_t N, size_t M, int64_t min_timestamp, int64_t max_timestamp) {
    timestamp_t *timestamps = (timestamp_t *)malloc(n * sizeof(timestamp_t));
    if (!timestamps) {
        // Handle memory allocation failure
        return;
    }

    log_level_t *log_levels = (log_level_t *)malloc(n * sizeof(log_level_t));
    if (!log_levels) {
        free(timestamps);
        return;
    }

    log_entry_t *log_entries = (log_entry_t *)malloc(n * sizeof(log_entry_t));
    if (!log_entries) {
        free(timestamps);
        free(log_levels);
        return;
    }

    long *int_offsets = (long *)malloc(N * sizeof(long));
    if (!int_offsets) {
        free(timestamps);
        free(log_levels);
        free(log_entries);
        return;
    }

    record_t *records = (record_t *)malloc(M * sizeof(record_t));
    if (!records) {
        free(timestamps);
        free(log_levels);
        free(log_entries);
        free(int_offsets);
        return;
    }

    // Initialize timestamp array with unique random timestamps
    for (size_t i = 0; i < n; ++i) {
        timestamps[i] = min_timestamp + rand() % (max_timestamp - min_timestamp + 1);
    }

    // Initialize log_level array with unique values, handling duplicates gracefully
    for (size_t i = 0; i < n; ++i) {
        log_levels[i] = (log_level_t)((i % 4) + DEBUG); // Example logic to avoid duplicates
    }

    // Initialize log_entry array and minimize cache misses
    for (size_t i = 0; i < n; ++i) {
        log_entries[i].timestamp = &timestamps[i];
        log_entries[i].level = log_levels[i];
        char message[128];
        snprintf(message, sizeof(message), "Log entry %zu", i);
        log_entries[i].message = strdup(message);
    }

    // Initialize int_offsets and records arrays
    for (size_t i = 0; i < N; ++i) {
        int_offsets[i] = rand() % M;
    }
    for (size_t i = 0; i < M; ++i) {
        records[i].value = rand();
    }

    // Free allocated memory when done
    free(timestamps);
    free(log_levels);
    for (size_t i = 0; i < n; ++i) {
        free((void *)log_entries[i].message); // Free dynamically allocated strings
    }
    free(log_entries);
    free(int_offsets);
    free(records);
}
