#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <semaphore.h>

#define MAX_IDS 10000
#define LOG_BUFFER_SIZE 256
#define CONFIG_FILE "config.txt"
#define TIMEOUT_SECONDS 60

typedef struct {
    int *ids;
    int count;
} IDSet;

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    sem_t semaphore;
} LogBuffer;

void initializeLogBuffer(LogBuffer *buffer) {
    sem_init(&buffer->semaphore, 0, 1);
    memset(buffer->buffer, 0, LOG_BUFFER_SIZE);
}

void logEvent(LogBuffer *buffer, const char *event) {
    sem_wait(&buffer->semaphore);
    time_t now = time(NULL);
    snprintf(buffer->buffer + strlen(buffer->buffer), LOG_BUFFER_SIZE - strlen(buffer->buffer),
             "%s: %s\n", ctime(&now), event);
    sem_post(&buffer->semaphore);
}

void processFileAndGenerateIDs(const char *inputFile, const char *outputFile, unsigned long seed) {
    FILE *input = fopen(inputFile, "r");
    if (!input) {
        perror("Failed to open input file");
        return;
    }

    IDSet existingIDs = {NULL, 0};
    IDSet newIDs = {malloc(sizeof(int) * MAX_IDS), 0};

    // Read existing IDs from file
    FILE *existingFile = fopen("existing_ids.txt", "r");
    if (existingFile) {
        int id;
        while (fscanf(existingFile, "%d", &id) == 1) {
            addID(&existingIDs, id);
        }
        fclose(existingFile);
    }

    // Initialize PRNG
    srand(seed);

    // Process transactions and generate new IDs
    char line[256];
    double totalAmount = 0;
    int transactionCount = 0;
    while (fgets(line, sizeof(line), input)) {
        // Extract user ID and amount from line
        int userID;
        double amount;
        sscanf(line, "%d %lf", &userID, &amount);
        totalAmount += amount;
        transactionCount++;

        // Check for duplicates
        if (!containsID(&existingIDs, userID)) {
            addID(&newIDs, userID);
        } else {
            logEvent(logBuffer, "Duplicate ID detected: UserID = %d", userID);
        }
    }

    fclose(input);

    // Calculate average amount per user
    double averageAmount = 0;
    if (transactionCount > 0) {
        averageAmount = totalAmount / transactionCount;
    }

    // Write results to file
    FILE *output = fopen(outputFile, "w");
    fprintf(output, "Total Amount: %.2f\n", totalAmount);
    fprintf(output, "Average Amount per User: %.2f\n", averageAmount);
    fclose(output);

    // Free allocated memory
    free(existingIDs.ids);
    free(newIDs.ids);

    logEvent(logBuffer, "Processing complete. Total IDs processed: %d", newIDs.count);
}

void addID(IDSet *set, int id) {
    if (set->count < MAX_IDS) {
        set->ids[set->count++] = id;
    } else {
        logEvent(logBuffer, "Warning: ID set overflow");
    }
}

int containsID(const IDSet *set, int id) {
    for (int i = 0; i < set->count; i++) {
        if (set->ids[i] == id) {
            return 1;
        }
    }
    return 0;
}
