        logError("Memory allocation failed");
        return -1;
    }

    seedPRNG(seed);
    fillCharArrayWithRandom(&container, 0.5);
    readDataFromFD(fd, &container);

    parseAndValidateConfig();

    if (!transmitDataOverSSL(ssl, &container)) {
        logError("Data transmission failed");
    }

    freeDataContainer(&container);
    return 0;
}
