    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, record** records, int** metadata, int* additional_metadata,
                      size_t N, size_t M, size_t P, unsigned int seed) {
    *offsets = safe_malloc(N * sizeof(long));
    *keys = safe_malloc(N * sizeof(int));
    *records = safe_malloc(M * sizeof(record));
    *metadata = safe_malloc(N * sizeof(int));
    *additional_metadata = safe_malloc(P * sizeof(int));

    srand(seed);
    for (size_t i = 0; i < N; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 1000; // Random key in the range [0, 999]
        (*metadata)[i] = rand() % 2; // Binary metadata
    }

    for (size_t i = 0; i < M; i++) {
        (*records)[i].value = rand() % 10000; // Random value in the range [0, 9999]
    }
}

void print_arrays(long* offsets, int* keys, record* records, int* metadata, int* additional_metadata,
