    int* keys;
    record* records;
    int* metadata;
    int* additional_metadata;

    initialize_arrays(&offsets, &keys, &records, &metadata, &additional_metadata, N, M, P, seed);

    print_arrays(offsets, keys, records, metadata, additional_metadata, N, M, P);

