Record* create_records(int count, int seed, long min_offset, long max_offset, int key_min, int key_max, int hex_id_length) {
    srand(seed);

    Record *records = (Record *)malloc(count * sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < count; ++i) {
        records[i].offset = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].key = rand() % (key_max - key_min + 1) + key_min;
        records[i].child = NULL;

        if (!(records[i].buffer = generate_hex_id(hex_id_length))) {
            // Handle error: failed to allocate memory for buffer
            free(records);
            return NULL;
        }
    }

    return records;
}

