        records[i].identifier = generate_unique_identifier(&identifiers);

        if (!records[i].identifier) {
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j].identifier);
            }
            free(records);
            free(identifiers);
