#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct MemoryPool {
    Record* records;
    size_t capacity;
    size_t size;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->records = (Record*)calloc(initial_capacity, sizeof(Record));
    pool->capacity = initial_capacity;
    pool->size = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->records);
    free(pool);
}

void initialize_records(MemoryPool* pool, int seed, int range_start, int range_end) {
    srand(seed);
    for (size_t i = 0; i < pool->capacity && i < pool->size; ++i) {
        pool->records[i].key = rand() % (range_end - range_start + 1) + range_start;
        // Initialize offset value as needed
    }
}

void resize_memory_pool(MemoryPool* pool, size_t new_capacity) {
    Record* new_records = (Record*)realloc(pool->records, new_capacity * sizeof(Record));
    if (new_records == NULL) {
        // Handle memory allocation failure
        return;
    }
    pool->records = new_records;
    pool->capacity = new_capacity;
}

void add_record(MemoryPool* pool, int key, long offset) {
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity == 0 ? 1 : pool->capacity * 2;
        resize_memory_pool(pool, new_capacity);
    }
    pool->records[pool->size].key = key;
    pool->records[pool->size].offset = offset;
    ++pool->size;
}

// Example usage
int main() {
    MemoryPool* pool = create_memory_pool(100);
    initialize_records(pool, time(NULL), 1, 1000);
    add_record(pool, 12345, 67890L);
    // Continue to use the pool as needed
    destroy_memory_pool(pool);
    return 0;
}
