typedef struct {
    int id;
    char name[50];
    char email[100];
    char password[100];
} User;

typedef enum { CREATE, UPDATE, DELETE } SubAction;

typedef struct {
    User user;
    SubAction sub_action;
} UserRequest;

void initialize_random_generator() {
    srand(time(NULL));
}

int generate_random_record(int min, int max) {
    return rand() % (max - min + 1) + min;
}

User create_user(UserRequest request) {
    User user = {0};
    if (request.user.id != 0) {
        // Update existing user
        user = request.user;
    } else {
        // Create new user
        strcpy(user.name, request.user.name);
        strcpy(user.email, request.user.email);
        strcpy(user.password, request.user.password);
        user.id = generate_random_record(1, MAX_USERS);
    }
    return user;
}

void manage_user_accounts(UserRequest request) {
    initialize_random_generator();
    User users[MAX_USERS] = {0};
    int user_count = 0;

    if (request.sub_action == CREATE || request.user.id != 0) {
        User new_user = create_user(request);
        int found = 0;
        for (int i = 0; i < user_count; ++i) {
            if (users[i].id == new_user.id) {
                users[i] = new_user;
                found = 1;
                break;
            }
        }
        if (!found) {
            users[user_count++] = new_user;
        }
    } else if (request.sub_action == DELETE) {
        for (int i = 0; i < user_count; ++i) {
            if (users[i].id == request.user.id) {
                memmove(&users[i], &users[i + 1], sizeof(User) * (user_count - i - 1));
                user_count--;
                break;
            }
        }
    }

    // Simulate JSON response
    printf("{\"message\": \"Operation successful\", \"user_count\": %d}\n", user_count);
}

int main() {
    UserRequest request = {{0, "John Doe", "john.doe@example.com", "password123"}, CREATE};
    manage_user_accounts(request);

    request.user.id = 1;
    manage_user_accounts(request);

    request.sub_action = DELETE;
    manage_user_accounts(request);

    return 0;
}
