User users[MAX_USERS];
int user_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Custom PRNG function for generating unique IDs
int generate_id() {
    static int id = 1; // Starting ID
    return id++;
}

// Function to create a new user account
json_object* create_user(const char *name, const char *email, const char *password, const char *sub_action) {
    pthread_mutex_lock(&mutex);
    if (user_count >= MAX_USERS) {
        json_object *result = json_object_new_object();
        json_object_object_add(result, "status", json_object_new_string("error"));
        json_object_object_add(result, "message", json_object_new_string("Max users reached"));
        pthread_mutex_unlock(&mutex);
        return result;
    }

    User *new_user = &users[user_count++];
    new_user->id = generate_id();
    new_user->name = strdup(name);
    new_user->email = strdup(email);
    new_user->password = strdup(password);
    new_user->sub_action = strdup(sub_action);

    json_object *result = json_object_new_object();
    json_object_object_add(result, "status", json_object_new_string("success"));
    json_object_object_add(result, "message", json_object_new_string("User created successfully"));
    json_object_object_add(result, "id", json_object_new_int(new_user->id));
    pthread_mutex_unlock(&mutex);
    return result;
}

// Function to update an existing user account
json_object* update_user(int id, const char *name, const char *email, const char *password, const char *sub_action) {
    pthread_mutex_lock(&mutex);
    User *user = NULL;
    for (int i = 0; i < user_count; i++) {
        if (users[i].id == id) {
            user = &users[i];
            break;
        }
    }

    if (!user) {
        json_object *result = json_object_new_object();
        json_object_object_add(result, "status", json_object_new_string("error"));
        json_object_object_add(result, "message", json_object_new_string("User not found"));
        pthread_mutex_unlock(&mutex);
        return result;
    }

    free(user->name);
    free(user->email);
    free(user->password);
    free(user->sub_action);

    user->name = strdup(name);
    user->email = strdup(email);
    user->password = strdup(password);
    user->sub_action = strdup(sub_action);

    json_object *result = json_object_new_object();
    json_object_object_add(result, "status", json_object_new_string("success"));
    json_object_object_add(result, "message", json_object_new_string("User updated successfully"));
    pthread_mutex_unlock(&mutex);
    return result;
}

// Function to delete a user account
json_object* delete_user(int id) {
    pthread_mutex_lock(&mutex);
    User *user = NULL;
    int index = -1;
    for (int i = 0; i < user_count; i++) {
        if (users[i].id == id) {
            user = &users[i];
            index = i;
            break;
        }
    }

    if (!user) {
        json_object *result = json_object_new_object();
        json_object_object_add(result, "status", json_object_new_string("error"));
        json_object_object_add(result, "message", json_object_new_string("User not found"));
        pthread_mutex_unlock(&mutex);
        return result;
    }

    free(user->name);
    free(user->email);
    free(user->password);
    free(user->sub_action);

    for (int i = index; i < user_count - 1; i++) {
        users[i] = users[i + 1];
    }
    user_count--;

    json_object *result = json_object_new_object();
    json_object_object_add(result, "status", json_object_new_string("success"));
    json_object_object_add(result, "message", json_object_new_string("User deleted successfully"));
    pthread_mutex_unlock(&mutex);
    return result;
}

