#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    double amount;
} TransactionRecord;

typedef struct {
    TransactionRecord* records;
    size_t count;
    size_t capacity;
    double* cachedAmounts;
    size_t cacheSize;
} TransactionList;

TransactionList* createTransactionList(size_t initialCapacity, size_t cacheSize) {
    TransactionList* list = (TransactionList*)malloc(sizeof(TransactionList));
    if (!list) return NULL;

    list->records = (TransactionRecord*)malloc(initialCapacity * sizeof(TransactionRecord));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initialCapacity;
    list->cachedAmounts = (double*)malloc(cacheSize * sizeof(double));
    if (!list->cachedAmounts) {
        free(list->records);
        free(list);
        return NULL;
    }

    list->cacheSize = cacheSize;

    for (size_t i = 0; i < cacheSize; ++i) {
        list->cachedAmounts[i] = -1.0; // Initialize to an invalid value
    }

    srand(time(NULL)); // Seed the PRNG

    return list;
}

void destroyTransactionList(TransactionList* list) {
    free(list->records);
    free(list->cachedAmounts);
    free(list);
}

int addTransaction(TransactionList* list, int id, time_t timestamp, double minAmount, double maxAmount) {
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        TransactionRecord* newRecords = (TransactionRecord*)realloc(list->records, newCapacity * sizeof(TransactionRecord));
        if (!newRecords) return -1;

        list->records = newRecords;
        list->capacity = newCapacity;
    }

    double cachedAmountIndex = id % list->cacheSize;
    if (list->cachedAmounts[cachedAmountIndex] == -1.0) {
        // Generate a new amount and cache it
        list->cachedAmounts[cachedAmountIndex] = minAmount + (maxAmount - minAmount) * ((double)rand() / RAND_MAX);
    }

    list->records[list->count].id = id;
    list->records[list->count].timestamp = timestamp;
    list->records[list->count].amount = list->cachedAmounts[cachedAmountIndex];

    ++list->count;

    return 0;
}

// Example usage
int main() {
    TransactionList* list = createTransactionList(10, 20);
    if (!list) {
        // Handle error
        return 1;
    }

    time_t now = time(NULL);

    for (int i = 0; i < 15; ++i) {
        if (addTransaction(list, i, now, 10.0, 1000.0) != 0) {
            // Handle error
            destroyTransactionList(list);
            return 1;
        }
    }

    // Process transactions...

    destroyTransactionList(list);

    return 0;
}
