void initializeDataStructures(long** offsets, int** keys, double** floats, Record** records, int size) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *floats = (double*)malloc(size * sizeof(double));
    *records = (Record*)malloc(size * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *floats == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for reproducibility
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = i * 10;
        (*keys)[i] = rand();
        (*floats)[i] = (double)rand() / RAND_MAX;

        (*records)[i].id = rand();
        (*records)[i].value = (double)rand() / RAND_MAX;
        (*records)[i].name = strdup("Sample");
    }
}

void readDataFromInput(long* offsets, int* keys, double* floats, Record* records, int size) {
    for (int i = 0; i < size; i++) {
        printf("Enter offset, key, float, id, value, name: ");
        scanf("%ld %d %lf %d %lf %s", &offsets[i], &keys[i], &floats[i], &records[i].id, &records[i].value, records[i].name);
    }
}

double findMaxFloat(double* floats, int size) {
    double max = -1;
    for (int i = 0; i < size; i++) {
        if (floats[i] > max) {
            max = floats[i];
        }
    }
    return max;
}

int findMaxInt(int* keys, int size) {
    int max = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (keys[i] > max) {
            max = keys[i];
        }
    }
    return max;
}

void freeMemory(long* offsets, int* keys, double* floats, Record* records, int size) {
    free(offsets);
    free(keys);
    free(floats);
    for (int i = 0; i < size; i++) {
        free(records[i].name);
    }
    free(records);
}

int main() {
    long* offsets;
    int* keys;
    double* floats;
    Record* records;
    int size;

    printf("Enter the number of records: ");
    scanf("%d", &size);

    initializeDataStructures(&offsets, &keys, &floats, &records, size);
    readDataFromInput(offsets, keys, floats, records, size);

    double maxFloat = findMaxFloat(floats, size);
    int maxInt = findMaxInt(keys, size);

    printf("Maximum float: %f\n", maxFloat);
    printf("Maximum integer: %d\n", maxInt);

    freeMemory(offsets, keys, floats, records, size);

    return 0;
}
