typedef struct {
    int value;
} record;

int compare(const void *a, const void *b) {
    return (*(record*)a).value - (*(record*)b).value;
}

void generate_records(long *offsets, int *keys, record **records, int num_records, int key_range) {
    srand(time(0));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1024; // Example offset calculation
        keys[i] = rand() % key_range;
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % 1024; // Example record value calculation
    }
}

void check_duplicates(int *keys, int num_records) {
    qsort(keys, num_records, sizeof(int), compare);
    for (int i = 1; i < num_records; i++) {
        if (keys[i] == keys[i - 1]) {
            fprintf(stderr, "Duplicate key detected: %d\n", keys[i]);
            exit(EXIT_FAILURE);
        }
    }
