#define LOG_BUFFER_SIZE 1024

typedef struct {
    long *ids;
    int *unique_ids;
    float *data_values;
    size_t size;
} LogEntry;

LogEntry* create_log_entry(size_t initial_size) {
    LogEntry *entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed for LogEntry\n");
        return NULL;
    }
    entry->ids = (long*)calloc(initial_size, sizeof(long));
    if (!entry->ids) {
        free(entry);
        fprintf(stderr, "Memory allocation failed for ids array\n");
        return NULL;
    }
    entry->unique_ids = (int*)calloc(initial_size, sizeof(int));
    if (!entry->unique_ids) {
        free(entry->ids);
        free(entry);
        fprintf(stderr, "Memory allocation failed for unique_ids array\n");
        return NULL;
    }
    entry->data_values = (float*)calloc(initial_size, sizeof(float));
    if (!entry->data_values) {
        free(entry->ids);
        free(entry->unique_ids);
        free(entry);
        fprintf(stderr, "Memory allocation failed for data_values array\n");
        return NULL;
    }
    entry->size = initial_size;
    return entry;
}

void free_log_entry(LogEntry *entry) {
    if (entry->ids) {
        free(entry->ids);
    }
    if (entry->unique_ids) {
        free(entry->unique_ids);
    }
    if (entry->data_values) {
        free(entry->data_values);
    }
    free(entry);
}

void log_entry(LogEntry *entry, long id, int unique_id) {
    if (entry->size <= entry->current_index) {
        // Resize the arrays
        size_t new_size = entry->size * 2;
        entry->ids = realloc(entry->ids, new_size * sizeof(long));
        entry->unique_ids = realloc(entry->unique_ids, new_size * sizeof(int));
        entry->data_values = realloc(entry->data_values, new_size * sizeof(float));
        if (!entry->ids || !entry->unique_ids || !entry->data_values) {
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        }
        entry->size = new_size;
    }
    entry->ids[entry->current_index] = id;
    entry->unique_ids[entry->current_index] = unique_id;
    entry->data_values[entry->current_index] = (float)rand() / RAND_MAX; // Non-cryptographically secure PRNG
    entry->current_index++;
}

int main() {
    srand(time(NULL)); // Seed the PRNG
    LogEntry *log = create_log_entry(LOG_BUFFER_SIZE);
    if (!log) {
        return 1;
    }

    for (size_t i = 0; i < 1000; i++) {
        log_entry(log, i, i % 10);
    }

    free_log_entry(log);
    return 0;
}
