#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LOG_ENTRIES 1000

typedef struct {
    long timestamp;
    int id;
    float data;
} logEntry;

typedef struct {
    logEntry *entries[MAX_LOG_ENTRIES];
    int count;
    int currentIndex;
    int gcThreshold;
} LogSystem;

LogSystem* createLogSystem(int gcThreshold) {
    LogSystem *logSys = (LogSystem *)malloc(sizeof(LogSystem));
    if (!logSys) {
        return NULL; // Memory allocation failed
    }
    logSys->count = 0;
    logSys->currentIndex = 0;
    logSys->gcThreshold = gcThreshold;
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        logSys->entries[i] = NULL;
    }
    return logSys;
}

void destroyLogSystem(LogSystem *logSys) {
    if (!logSys) return;

    for (int i = 0; i < logSys->count; i++) {
        free(logSys->entries[i]);
    }

    free(logSys);
}

logEntry* createLogEntry(long timestamp, int id, float data) {
    logEntry *entry = (logEntry *)malloc(sizeof(logEntry));
    if (!entry) return NULL; // Memory allocation failed

    entry->timestamp = timestamp;
    entry->id = id;
    entry->data = data;

    return entry;
}

void logEntryToBuffer(LogSystem *logSys, long timestamp, int id, float data) {
    if (logSys->count >= MAX_LOG_ENTRIES) {
        // Handle buffer overflow (e.g., discard oldest entry)
        free(logSys->entries[logSys->currentIndex]);
        logSys->currentIndex = (logSys->currentIndex + 1) % MAX_LOG_ENTRIES;
    }

    logEntry *entry = createLogEntry(timestamp, id, data);
    if (!entry) return; // Memory allocation failed

    logSys->entries[(logSys->currentIndex + logSys->count++) % MAX_LOG_ENTRIES] = entry;

    if (logSys->count > logSys->gcThreshold) {
        // Perform garbage collection
        for (int i = 0; i < logSys->currentIndex; i++) {
            free(logSys->entries[i]);
        }
        logSys->count -= logSys->currentIndex;
        logSys->currentIndex = 0;
    }
}

// Additional functions for thread safety, logging levels, and destination support can be implemented here
