#define MAX_INPUTS 1000

typedef struct {
    unsigned long offset;
} TimestampOffset;

typedef struct {
    double probability;
} ProbabilityRecord;

typedef struct {
    int value;
} Record;

double calculate_average(double *values, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return sum / count;
}

void generate_random_records(Record **records, int count, double min, double max, unsigned long seed) {
    srand(seed);
    for (int i = 0; i < count; i++) {
        (*records)[i].value = (int)((max - min + 1) * rand() / (RAND_MAX + 1.0) + min);
    }
}

void generate_time_based_records(Record **records, int count, time_t base_time) {
    for (int i = 0; i < count; i++) {
        (*records)[i].value = base_time + i;
    }
}

int read_and_validate_inputs(double *values, int max_count) {
    int count = 0;
    while (scanf("%lf", &values[count]) == 1 && count < max_count) {
        count++;
    }
    return count;
}

void free_all_memory(TimestampOffset *timestamp_offsets, ProbabilityRecord *probability_records, Record *records) {
    free(timestamp_offsets);
    free(probability_records);
    free(records);
}

int main() {
    int timestamp_offset_count = 100;
    int probability_record_count = 50;
    int record_count = 200;

    TimestampOffset *timestamp_offsets = (TimestampOffset *)malloc(timestamp_offset_count * sizeof(TimestampOffset));
    ProbabilityRecord *probability_records = (ProbabilityRecord *)malloc(probability_record_count * sizeof(ProbabilityRecord));
    Record *records = (Record *)malloc(record_count * sizeof(Record));

    if (!timestamp_offsets || !probability_records || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    time_t base_time = time(NULL);
    generate_random_records(&records[0], record_count / 2, 1.0, 100.0, 42); // Seed for reproducibility
    generate_time_based_records(&records[record_count / 2], record_count / 2, base_time);

    double input_values[MAX_INPUTS];
    int input_count = read_and_validate_inputs(input_values, MAX_INPUTS);
    if (input_count == 0) {
        fprintf(stderr, "No valid inputs provided\n");
        free_all_memory(timestamp_offsets, probability_records, records);
        return EXIT_FAILURE;
    }

    double average = calculate_average(input_values, input_count);
    printf("Average of inputs: %f\n", average);

    free_all_memory(timestamp_offsets, probability_records, records);
    return EXIT_SUCCESS;
}
