#include <time.h>

typedef struct {
    int value;
    long *offset;
} record;

typedef struct {
    void *data;
    size_t size;
    size_t capacity;
} dynamic_array;

void init_dynamic_array(dynamic_array *arr, size_t initial_capacity) {
    arr->data = malloc(initial_capacity * sizeof(void *));
    arr->size = 0;
    arr->capacity = initial_capacity;
}

void push_back(dynamic_array *arr, void *value) {
    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        arr->data = realloc(arr->data, arr->capacity * sizeof(void *));
    }
    ((void **)arr->data)[arr->size++] = value;
}

record* create_records(size_t count, int min_value, int max_value, unsigned long seed) {
    srand(seed);
    record *records = malloc(count * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = malloc(sizeof(long));
        if (!records[i].offset) {
            // Handle error
            for (size_t j = 0; j < i; ++j) free(records[j].offset);
            free(records);
            return NULL;
        }
    }

    return records;
}

void free_records(record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) free(records[i].offset);
    free(records);
}

int find_largest(dynamic_array *arr) {
    if (arr->size == 0) return INT_MIN;
    int largest = ((int *)arr->data)[0];
    for (size_t i = 1; i < arr->size; ++i) {
        if (((int *)arr->data)[i] > largest) largest = ((int *)arr->data)[i];
    }
    return largest;
}

void example_usage() {
    dynamic_array array;
    init_dynamic_array(&array, 10);

    push_back(&array, (void *)&array);
    // Add more elements as needed

    int largest = find_largest(&array);
    printf("Largest value: %d\n", largest);

    free(array.data);
}

int main() {
    example_usage();
    return 0;
}
