#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

// Custom pseudo-random number generator
unsigned long xorshift128plus(unsigned long *x, unsigned long *y) {
    *x ^= *y += *y << 23; // y = (y << 23) + y;
    return ((*x ^ (*x >> 17)) + (*y ^ (*y >> 19)));
}

// Function to allocate and initialize arrays
void allocate_and_initialize(int key_count, FILE *output_file) {
    if (key_count <= 0) {
        fprintf(stderr, "Error: Key count must be greater than zero.\n");
        return;
    }

    // Allocate memory for the long offset array
    long *offsets = malloc(10000 * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    // Allocate memory for the int key array
    int *keys = malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return;
    }

    // Allocate memory for the record array
    Record *records = malloc(10000 * key_count * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return;
    }

    // Initialize random seed and PRNG state
    unsigned long x = time(NULL), y = ~time(NULL);

    // Fill the arrays with random values
    for (int i = 0; i < 10000; i++) {
        offsets[i] = xorshift128plus(&x, &y) % 10001;
        for (int j = 0; j < key_count; j++) {
            keys[j] = rand() % 101;
            records[i * key_count + j].offset = offsets[i];
            records[i * key_count + j].key = keys[j];
            records[i * key_count + j].timestamp = (double)time(NULL);
        }
    }

    // Optionally, persist the records to a file
    if (output_file != NULL) {
        fwrite(records, sizeof(Record), 10000 * key_count, output_file);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int key_count = 100; // Example input size
    FILE *output_file = fopen("records.dat", "wb");

    if (output_file == NULL) {
        perror("Failed to open file for writing.");
        return EXIT_FAILURE;
    }

    allocate_and_initialize(key_count, output_file);
    fclose(output_file);

    return EXIT_SUCCESS;
}
```

This code snippet provides a function `allocate_and_initialize` that dynamically allocates memory for arrays of offsets and keys based on user input, initializes records with random values using a custom PRNG, and optionally persists the records to a file. The main function demonstrates how to use this function with an example key count and output file.']

