#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int offsetIndex;
} record;

record* allocate_and_initialize_records(int numOffsets, int numKeys, int minValue, int maxValue) {
    if (numOffsets <= 0 || numKeys <= 0 || minValue > maxValue) {
        return NULL;
    }

    // Seed the PRNG
    srand(time(NULL));

    long *offsets = malloc(numOffsets * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    // Initialize offsets with random values
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand();
    }

    int *keys = malloc(numKeys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize keys with unique random values
    for (int i = 0; i < numKeys; i++) {
        while (1) {
            int key = rand();
            int isUnique = 1;
            for (int j = 0; j < i; j++) {
                if (keys[j] == key) {
                    isUnique = 0;
                    break;
                }
            }
            if (isUnique) {
                keys[i] = key;
                break;
            }
        }
    }

    record *records = malloc(numKeys * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records with random values and valid offset indices
    for (int i = 0; i < numKeys; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        int index;
        do {
            index = rand() % numOffsets;
        } while (index >= numOffsets);
        records[i].offsetIndex = index;
    }

    // Verify integrity of offset indices
    for (int i = 0; i < numKeys; i++) {
        if (records[i].offsetIndex < 0 || records[i].offsetIndex >= numOffsets) {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    return records;
}
