    long* offsets = (long*)malloc(10 * sizeof(long));
    int* keys = (int*)malloc(10 * sizeof(int));
    record* records = (record*)malloc(10 * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        return NULL;
    }

    int seed = *(int*)arg;
    srand(seed);

    for (int i = 0; i < 10; i++) {
