// Define structures
typedef struct {
    float value;
    enum status { ACTIVE, INACTIVE };
} element;

typedef struct {
    element* record;
    struct metadata** attributes;
} data_structure;

// Function to initialize PRNG state
void init_prng_state(unsigned long seed) {
    srand(seed);
}

// Function to generate a random float
float generate_random_float() {
    return (float)rand() / RAND_MAX * 100.0f; // Random between 0 and 100
}

// Function to create data structures
data_structure* create_data_structures(int size, unsigned long seed) {
    if (size <= 0) {
        fprintf(stderr, "Size must be greater than zero.\n");
        return NULL;
    }

    init_prng_state(seed);

    data_structure* ds = malloc(size * sizeof(data_structure));
    if (!ds) {
        perror("Failed to allocate memory for data structures.");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        ds[i].record = malloc(sizeof(element));
        if (!ds[i].record) {
            fprintf(stderr, "Failed to allocate memory for element record.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(ds[j].record);
            }
            free(ds);
            return NULL;
        }

        ds[i].record->value = generate_random_float();
        ds[i].record->status = ACTIVE;

        ds[i].attributes = malloc(sizeof(struct metadata*));
        if (!ds[i].attributes) {
            fprintf(stderr, "Failed to allocate memory for attributes pointer.\n");
            // Free previously allocated memory
            free(ds[i].record);
            for (int j = 0; j < i; ++j) {
                free(ds[j].record);
                free(ds[j].attributes);
            }
            free(ds);
            return NULL;
        }

        *ds[i].attributes = malloc(sizeof(struct metadata));
        if (!(*ds[i].attributes)) {
            fprintf(stderr, "Failed to allocate memory for metadata.\n");
            // Free previously allocated memory
            free(ds[i].record);
            for (int j = 0; j < i; ++j) {
                free(ds[j].record);
                free(ds[j].attributes);
            }
            free(ds);
            return NULL;
        }

        // Initialize metadata here if needed
    }

    return ds;
}

// Function to free data structures
void free_data_structures(data_structure* ds, int size) {
    for (int i = 0; i < size; ++i) {
        free(ds[i].record);
        free(ds[i].attributes);
    }
    free(ds);
}
