#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1000

typedef struct {
    unsigned long timestamp;
    float temperature;
    double humidity;
} weather_record;

void seed_prng(unsigned long seed) {
    srand(seed);
}

weather_record* allocate_memory(size_t *size) {
    weather_record *records = (weather_record *)malloc(*size * sizeof(weather_record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return records;
}

void free_memory(weather_record *records) {
    free(records);
}

int is_valid_temperature(float temp) {
    // Define your temperature validation range here
    return (temp >= -40.0 && temp <= 50.0); // Example range
}

int is_valid_humidity(double hum) {
    // Define your humidity validation range here
    return (hum >= 0.0 && hum <= 100.0); // Example range
}

weather_record* read_weather_data(const char *filename, size_t *size, unsigned long seed) {
    seed_prng(seed);
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    weather_record *records = allocate_memory(size);
    size_t count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (count >= *size) {
            fprintf(stderr, "Too many records\n");
            free_memory(records);
            fclose(file);
            exit(EXIT_FAILURE);
        }

        sscanf(line, "%lu,%f,%lf", &records[count].timestamp, &records[count].temperature, &records[count].humidity);

        if (!is_valid_temperature(records[count].temperature) || !is_valid_humidity(records[count].humidity)) {
            fprintf(stderr, "Invalid data at line %zu\n", count + 2); // Assuming header is on first line
            free_memory(records);
            fclose(file);
            exit(EXIT_FAILURE);
        }

        count++;
    }

    *size = count;
    fclose(file);
    return records;
}

void calculate_and_print_averages(weather_record *records, size_t size) {
    float total_temp = 0.0;
    double total_humidity = 0.0;

    for (size_t i = 0; i < size; i++) {
        total_temp += records[i].temperature;
        total_humidity += records[i].humidity;
    }

    if (size > 0) {
        printf("Average Temperature: %.2f\n", total_temp / size);
        printf("Average Humidity: %.2f\n", total_humidity / size);
    } else {
        printf("No valid data available\n");
    }
}

int main() {
    const char *filename = "weather_data.csv";
    unsigned long seed = time(NULL); // Use current time as a seed for reproducibility
    size_t size = MAX_RECORDS;

    weather_record *records = read_weather_data(filename, &size, seed);
    calculate_and_print_averages(records, size);

    free_memory(records);
    return 0;
}
