#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    double value;
} record;

void* generateRandomData(void* arg) {
    long thread_id = (long)arg;
    record* data = (record*)malloc(sizeof(record));
    if (data == NULL) {
        perror("Memory allocation failed");
        pthread_exit(NULL);
    }

    // Simulate PRNG with time and thread ID
    srand(time(0) + thread_id);

    data->key = rand() % 100;  // Random key between 0 and 99
    data->offset = (long)(rand() * 1.0 / RAND_MAX * 1000L);  // Random offset between 0 and 1000
    data->value = (double)rand() / RAND_MAX * 100.0;  // Random value between 0.0 and 100.0

    pthread_exit((void*)data);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <num_threads>\n", argv[0]);
        return 1;
    }

    long num_threads = atol(argv[1]);
    pthread_t threads[num_threads];
    record* results[num_threads];

    for (long i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, generateRandomData, (void*)i) != 0) {
            perror("Thread creation failed");
            return 1;
        }
    }

    for (long i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], (void**)&results[i]);
        printf("Record %ld: Key=%d, Offset=%ld, Value=%.2f\n", i, results[i]->key, results[i]->offset, results[i]->value);
        free(results[i]);
    }

    return 0;
}
```

