    srand(time(NULL) + getpid());
    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % range_end;
        keys[i] = rand() % range_end;
        secure_record record;
        do {
            record.value = rand() % range_end;
        } while (!is_unique(record.value, *records, i));
        record.record_status = VALID; // Assuming all generated numbers are valid for now
        (*records)[i] = record;
    }
}

int is_unique(unsigned int value, secure_record *existing_records, size_t index) {
    for (size_t i = 0; i < index; ++i) {
        if (existing_records[i].value == value) {
            return 0;
        }
    }
    return 1;
}

