// Function to find the largest integer in an array
int findLargest(int arr[], int n) {
    if (n <= 0) return -1; // Handle edge case for empty array
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to dynamically allocate and initialize arrays using a PRNG
void dynamicAndScalableProcess(int seed, int range, int timeout, int healthCheckInterval) {
    srand(seed); // Seed the random number generator

    // Dynamically allocate memory for the arrays
    long *offsets = (long *)malloc(5 * sizeof(long));
    int *keys = (int *)malloc(5 * sizeof(int));
    Record *records = (Record *)malloc(5 * sizeof(Record));
    time_t *timestamps = (time_t *)malloc(5 * sizeof(time_t));
    int *inputArray;
    int inputSize;

    // Initialize the arrays using a PRNG
    for (int i = 0; i < 5; i++) {
        offsets[i] = rand();
        keys[i] = rand() % range;
        records[i].value = rand() % range;
        records[i].timestamp = time(NULL);
        timestamps[i] = time(NULL);
    }

    // Read input integers from standard input
    scanf("%d", &inputSize);
    inputArray = (int *)malloc(inputSize * sizeof(int));
    for (int i = 0; i < inputSize; i++) {
        scanf("%d", &inputArray[i]);
    }

    // Find and print the largest integer in the array
    int largest = findLargest(inputArray, inputSize);
    printf("The largest integer is: %d\n", largest);

    // Free dynamically allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
    free(inputArray);
}

int main() {
    int seed, range, timeout, healthCheckInterval;
    scanf("%d %d %d %d", &seed, &range, &timeout, &healthCheckInterval);
    dynamicAndScalableProcess(seed, range, timeout, healthCheckInterval);
    return 0;
}
