import hashlib
import os
import random
import string

class FileContentRetriever:
    def __init__(self, file_directory):
        self.file_directory = file_directory

    @staticmethod
    def generate_random_string(length, charset=string.ascii_letters + string.digits):
        return ''.join(random.choice(charset) for _ in range(length))

    @staticmethod
    def hash_password(password):
        return hashlib.sha256(password.encode()).hexdigest()

    def read_file_synchronously(self, filename):
        file_path = os.path.join(self.file_directory, filename)
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                return file.read()
        except FileNotFoundError:
            print(f"File '{filename}' not found.")
            return None
        except Exception as e:
            print(f"An error occurred while reading the file: {e}")
            return None

# Example usage:
if __name__ == "__main__":
    retriever = FileContentRetriever('/path/to/files')
    random_string = retriever.generate_random_string(10)
    hashed_password = retriever.hash_password("example_password")
    file_content = retriever.read_file_synchronously('example.txt')

    print(f"Random String: {random_string}")
    print(f"Hashed Password: {hashed_password}")
    print(f"File Content: {file_content}")
```

