    pthread_mutex_lock(&processor->mutex);

    // Apply filtering criteria
    if (packet.age > 5 || packet.size < 100) {
        pthread_mutex_unlock(&processor->mutex);
        return;
    }

    // Update metrics
    processor->metrics.average_size = ((processor->metrics.average_size * (processor->data_source->count - 1)) + packet.size) / processor->data_source->count;
    processor->metrics.frequency_last_minute++;

    if (packet.weighted_sum > processor->metrics.max_weighted_packet->weighted_sum) {
        processor->metrics.max_weighted_packet = &packet;
        processor->metrics.max_weighted_id = prng(processor->metrics.max_weighted_packet->id);
    }

    pthread_mutex_unlock(&processor->mutex);

    // Log packet processing statistics
    log_packet_stats(processor, packet);
}

