    processor->data_source = data_source;
    processor->metrics.average_size = 0;
    processor->metrics.frequency_last_minute = 0;
    processor->metrics.max_weighted_packet = NULL;
    processor->metrics.max_weighted_id = 0;
    pthread_mutex_init(&processor->mutex, NULL);
}

