function getElementMatches(element, selector, callback) {
    let matches = [];
    if (element.matches(selector)) {
        if (callback(element)) {
            matches.push(element);
        }
    }
    for (let child of element.children) {
        matches = matches.concat(getElementMatches(child, selector, callback));
    }
    return matches;
}
