void* processRecordsAndCommunicate(void* arg) {
    int* seeds = (int*)arg;
    int num_records = 10; // Example number of records
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize PRNG with user-provided seed
    srand(seeds[0]);

    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % seeds[1];
        records[i].value = rand() % seeds[2];
    }

    // Memory verification mechanism
    if (rand() % 2 == 0) {
        fprintf(stderr, "Memory integrity check failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Find and print the largest integer using a helper function
    int max_value = records[0].value;
    for (int i = 1; i < num_records; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    printf("Largest integer: %d\n", max_value);

    // Efficient deallocation strategies
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

void* connectToRemote(void* arg) {
    int* remote_address = (int*)arg;
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, processRecordsAndCommunicate, remote_address) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return NULL;
    }
    pthread_join(thread_id, NULL);
    return NULL;
}

int main() {
    int seeds[] = {12345, 100, 200}; // Example seed values
    int remote_address = 8080; // Example remote address

    processRecordsAndCommunicate(seeds);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, connectToRemote, &remote_address) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }
    pthread_join(thread_id, NULL);

    return EXIT_SUCCESS;
}
