#include <time.h>
#include <pthread.h>

#define MAX_OFFSETS_SIZE 1024 * 1024 // 1MB
#define MAX_KEYS_SIZE 512 * 1024 // 500KB
#define MAX_RECORDS_SIZE 2 * 1024 * 1024 // 2MB

typedef struct {
    int value;
} record;

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;
size_t num_offsets, num_keys, num_records;
pthread_mutex_t rng_lock = PTHREAD_MUTEX_INITIALIZER;

void init_memory() {
    offsets = (long*)malloc(MAX_OFFSETS_SIZE);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    keys = (int*)malloc(MAX_KEYS_SIZE);
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    records = (record*)malloc(MAX_RECORDS_SIZE);
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    num_offsets = MAX_OFFSETS_SIZE / sizeof(long);
    num_keys = MAX_KEYS_SIZE / sizeof(int);
    num_records = MAX_RECORDS_SIZE / sizeof(record);

    srand(time(NULL));
}

void reseed_rng() {
    pthread_mutex_lock(&rng_lock);
    srand(time(NULL));
    pthread_mutex_unlock(&rng_lock);
}

void set_record_values() {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100001;
    }
}

void calculate_and_print_sum() {
    long sum = 0;
    for (size_t i = 0; i < num_records; ++i) {
        sum += records[i].value;
    }

    printf("Sum of all integers in the records array: %ld\n", sum);

    if (sum > 10000000) {
        printf("Warning: Sum exceeds 10 million, potential inefficiencies.\n");
    } else if (sum < 5000000) {
        printf("Info: Dataset might be undersized.\n");
    }
}

void reset_data_structure() {
    free(offsets);
    offsets = NULL;
    free(keys);
    keys = NULL;
    free(records);
    records = NULL;

    init_memory();
    reseed_rng();
}

int main() {
    init_memory();
    set_record_values();
    calculate_and_print_sum();

    // Example of resetting the data structure
    reset_data_structure();

    return 0;
}
