#define RECORD_SIZE sizeof(struct record)
#define SEED_INTERVAL 60 // Re-seed every 60 seconds

typedef struct {
    int value;
} record;

int init_arrays(long **offsets, int **keys, record **records, size_t count) {
    static time_t last_seed_time = 0;
    if (time(NULL) - last_seed_time >= SEED_INTERVAL) {
        srand(time(NULL) ^ getpid());
        last_seed_time = time(NULL);
    }

    *offsets = realloc(*offsets, count * sizeof(long));
    *keys = realloc(*keys, count * sizeof(int));
    *records = realloc(*records, count * RECORD_SIZE);

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % INT_MAX;
        (*records)[i].value = rand() % 1000; // Random number between 0 and 999
    }

    return 0; // Success
}

