#define NUM_TOKENS 100

void generateTokensAndHandleRequests() {
    // Seed the PRNG with a user-provided value
    srand(time(NULL));

    // Dynamically allocate memory for tokens
    int* tokens = (int*)malloc(NUM_TOKENS * sizeof(int));
    if (tokens == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the PRNG with a seed value from user input
    unsigned int seed;
    printf("Enter a seed value for the PRNG: ");
    scanf("%u", &seed);
    srand(seed);

    // Generate tokens using the PRNG
    for (int i = 0; i < NUM_TOKENS; i++) {
        tokens[i] = rand();
    }

    // Verify memory correctness
    for (int i = 1; i < NUM_TOKENS; i++) {
        if (tokens[i] == tokens[i - 1]) {
            fprintf(stderr, "Memory initialization failed: Tokens are not unique\n");
            free(tokens);
            return;
        }
    }

    // Establish a connection to the remote server using Java Channel in a separate thread
    pthread_t serverThread;
    if (pthread_create(&serverThread, NULL, connectToServer, tokens) != 0) {
        fprintf(stderr, "Failed to create server thread\n");
        free(tokens);
        return;
    }

    // Wait for the server thread to complete
    pthread_join(serverThread, NULL);

    // Free allocated memory
    free(tokens);
}

void* connectToServer(void* arg) {
    int* tokens = (int*)arg;

    // Simulate connection establishment and data sending
    printf("Establishing connection to remote server...\n");
    for (int i = 0; i < NUM_TOKENS; i++) {
        printf("Sending token %d: %d\n", i, tokens[i]);
        // Simulate network delay
        sleep(1);
    }
    printf("Connection closed.\n");

    return NULL;
}

int main() {
    generateTokensAndHandleRequests();
    return 0;
}
