typedef struct {
    int id;
    char* value;
} metadata;

typedef struct record {
    int key;
    char* str;
    metadata meta;
    struct record* next;
} record;

typedef struct {
    record** records;
    long* offsets;
    int* keys;
    char*** strings;
    size_t count;
    size_t capacity;
} data_store;

data_store* create_data_store(size_t initial_capacity) {
    data_store* ds = (data_store*)malloc(sizeof(data_store));
    if (!ds) return NULL;

    ds->records = (record**)calloc(initial_capacity, sizeof(record*));
    ds->offsets = (long*)malloc(initial_capacity * sizeof(long));
    ds->keys = (int*)malloc(initial_capacity * sizeof(int));
    ds->strings = (char***)malloc(initial_capacity * sizeof(char***));

    if (!ds->records || !ds->offsets || !ds->keys || !ds->strings) {
        free(ds);
        return NULL;
    }

    ds->count = 0;
    ds->capacity = initial_capacity;

    srand(time(NULL)); // Seed for random number generation

    return ds;
}

void destroy_data_store(data_store* ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }

    free(ds->records);
    free(ds->offsets);
    free(ds->keys);
    free(ds->strings);

    free(ds);
}

record* create_record(int key, const char* str, long offset) {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) return NULL;

    rec->key = key;
    rec->str = strdup(str);
    rec->meta.id = rand() % 1000; // Example of a simple PRNG for demonstration
    rec->meta.value = strdup("example");
    rec->next = NULL;

    rec->meta.timestamp = time(NULL);
    rec->meta.reference_count = 1;

    return rec;
}

void insert_record(data_store* ds, int key, const char* str, long offset) {
    if (ds->count >= ds->capacity) {
        // Resize data store here
    }

    record* new_rec = create_record(key, str, offset);
    ds->records[ds->count] = new_rec;
    ds->keys[ds->count] = key;
    ds->strings[ds->count] = (char**)(new_rec->str); // Example of how to store strings
    ds->offsets[ds->count++] = offset;

    if (!new_rec) return;

    // Insert into linked list logic here
}

void remove_record(data_store* ds, int key) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->keys[i] == key) {
            record* temp = ds->records[i];
            free(temp->str);
            free(temp->meta.value);
            free(temp);
            // Remove from linked list logic here
            for (size_t j = i; j < ds->count - 1; ++j) {
                ds->records[j] = ds->records[j + 1];
                ds->keys[j] = ds->keys[j + 1];
                ds->strings[j] = ds->strings[j + 1];
                ds->offsets[j] = ds->offsets[j + 1];
            }
            --ds->count;
            break;
        }
    }
}

void update_record(data_store* ds, int key, const char* new_str) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->keys[i] == key) {
            free(ds->records[i]->str);
            ds->records[i]->str = strdup(new_str);
            // Update linked list logic here
            break;
        }
    }
}

