typedef struct {
    int value;
} Record;

void manage_memory() {
    long* file_offsets = malloc(MAX_FILE_OFFSETS);
    if (file_offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for file offsets.\n");
        return;
    }

    int* keys = (int*)calloc(MAX_INT_KEYS / sizeof(int), sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(file_offsets);
        return;
    }

    Record* records = (Record*)malloc(MAX_RECORD_SIZE);
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(file_offsets);
        free(keys);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_INT_KEYS / sizeof(int); ++i) {
        keys[i] = rand();
    }

    int sum = 0;
    for (int i = 0; i < MAX_RECORD_SIZE / sizeof(Record); ++i) {
        records[i].value = rand() % 10000000; // Random value between 0 and 9,999,999
        sum += records[i].value;
    }

    if (sum > 10 * 1024 * 1024) {
        printf("Warning: Sum exceeds 10 million, potential resource exhaustion or data integrity issues.\n");
    }

    free(file_offsets);
    free(keys);
    free(records);
}

int main() {
    manage_memory();
    return 0;
}
