#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a simple record structure
typedef struct {
    int value;
} Record;

// Function to generate pseudo-random numbers using a linear congruential generator (LCG)
unsigned long lcg(unsigned long seed) {
    return (seed * 1664525UL + 1013904223UL) % 4294967295UL;
}

// Function to initialize arrays and records
int init_arrays(long **offsets, int **keys, Record **records, int size) {
    // Seed the PRNG
    unsigned long seed = time(NULL);
    srand(seed);

    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (Record *)malloc(size * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < size; i++) {
        // Generate random values using the PRNG
        (*offsets)[i] = lcg(seed + i);
        (*keys)[i] = rand() % 1000; // Random int key between 0 and 999
        (*records)[i].value = rand() % 1000; // Record value between 0 and 999
    }

    return 0;
}

// Function to print the records
void print_records(Record *records, int size) {
    for (int i = 0; i < size; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }
}

int main() {
    const int array_size = 1000; // Example size
    long *offsets;
    int *keys;
    Record *records;

    if (init_arrays(&offsets, &keys, &records, array_size) == 0) {
        print_records(records, array_size);

        // Free allocated memory
        free(offsets);
        free(keys);
        free(records);
    }

    return 0;
}
```

### Notes:
1. **Memory Allocation and Error Handling**: The function checks if each allocation was successful before proceeding. If any allocation fails, it prints an error message and returns `-1`.
2. **Pseudo-Random Number Generator (PRNG)**: A simple linear congruential generator (LCG) is used for generating pseudo-random numbers. This is efficient and suitable for non-security-related applications.
3. **Record Structure**: Each record contains a single `int` value, which can be easily expanded if more fields are needed in the future.
4. **Memory Management**: The allocated memory is freed after use to prevent memory leaks.
5. **Scalability**: The function is designed to handle varying input sizes and can be easily adapted to larger datasets by changing the `array_size` variable.
6. **Performance Optimization**: The PRNG and memory management are optimized for performance, making it suitable for frequent calls in a performance-sensitive application.

This code provides a solid foundation that can be extended or modified as needed for different requirements or constraints.']

