#define SEED_RESEED_INTERVAL 60 // Re-seed PRNG every 60 seconds

typedef struct {
    int value;
} record;

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* create_records(long offsets[], int keys[], size_t size, int min_val, int max_val, pid_t pid, int *err_code) {
    static time_t last_reseed_time = 0;
    record *records = NULL;

    if (time(NULL) - last_reseed_time > SEED_RESEED_INTERVAL) {
        srand(time(NULL) ^ pid);
        last_reseed_time = time(NULL);
    }

    records = realloc(records, size * sizeof(record));
    if (!records) {
        *err_code = 1; // Memory allocation failed
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        keys[i] = offsets[i]; // Assuming offsets are unique and can be used as keys
        records[i].value = generate_random(min_val, max_val);
    }

    *err_code = 0;
    return records;
}

int main() {
    long offsets[] = {1, 2, 3};
    int keys[3];
    record *records;
    pid_t pid = getpid();
    int err_code;

    records = create_records(offsets, keys, sizeof(offsets) / sizeof(offsets[0]), 10, 100, pid, &err_code);

    if (err_code == 0) {
        for (size_t i = 0; i < sizeof(offsets) / sizeof(offsets[0]); i++) {
            printf("Key: %d, Record Value: %d\n", keys[i], records[i].value);
        }
        free(records);
    } else {
        printf("Failed to allocate memory for records.\n");
    }

    return 0;
}
