    size_t capacity;
    PRNG* prng;
    void (*reseedPRNG)(PRNG*);
    PRNGReseedStrategy reseedStrategy;
} MemoryManager;

MemoryManager* createMemoryManager(size_t initialCapacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->offsets = (long*)calloc(initialCapacity, sizeof(long));
    manager->keys = (int*)calloc(initialCapacity, sizeof(int));
    manager->records = (void**)calloc(initialCapacity, sizeof(void*));
    manager->size = 0;
    manager->capacity = initialCapacity;
    manager->prng = createPRNG(); // Assume PRNG creation function exists
    manager->reseedPRNG = reseedPRNGFunction; // Assume reseeding function exists
    manager->reseedStrategy = RERESEED_ON_HIGH_LOAD; // Assume enum for reseeding strategy
    return manager;
}

void resizeMemoryManager(MemoryManager* manager, size_t newCapacity) {
    long* newOffsets = (long*)realloc(manager->offsets, newCapacity * sizeof(long));
    int* newKeys = (int*)realloc(manager->keys, newCapacity * sizeof(int));
    void** newRecords = (void**)realloc(manager->records, newCapacity * sizeof(void*));

    if (!newOffsets || !newKeys || !newRecords) {
        // Handle memory allocation failure
        return;
    }

    manager->offsets = newOffsets;
    manager->keys = newKeys;
    manager->records = newRecords;
    manager->capacity = newCapacity;
}

void addRecord(MemoryManager* manager, Record record) {
    if (manager->size >= manager->capacity) {
        resizeMemoryManager(manager, manager->capacity * 2);
    }

    manager->records[manager->size] = malloc(sizeof(Record));
    *((Record*)manager->records[manager->size]) = record;
    manager->keys[manager->size] = record.intValue;
    manager->offsets[manager->size] = getUniqueOffset(); // Assume function to get unique offset
    manager->size++;
}

void addTransaction(MemoryManager* manager, Transaction transaction) {
    if (manager->size >= manager->capacity) {
        resizeMemoryManager(manager, manager->capacity * 2);
    }

    manager->records[manager->size] = malloc(sizeof(Transaction));
    *((Transaction*)manager->records[manager->size]) = transaction;
    manager->keys[manager->size] = transaction.intValue;
    manager->offsets[manager->size] = getUniqueOffset(); // Assume function to get unique offset
    manager->size++;
}

void freeMemoryManager(MemoryManager* manager) {
    for (size_t i = 0; i < manager->size; i++) {
        free(manager->records[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    freePRNG(manager->prng); // Assume PRNG cleanup function exists
    free(manager);
}

void reseedPRNGFunction(PRNG* prng) {
    reseedPRNG(prng, getCurrentTime() ^ getpid()); // Assume functions to get current time and process ID
}

