['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    long timestamp;
    double amount;
    char merchant[100];
} TransactionRecord;

typedef struct {
    int start_id;
    int num_records;
    long base_timestamp;
    double min_amount;
    double max_amount;
    char* merchants;
    pthread_mutex_t* mutex;
} ThreadData;

void* generate_transactions(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    for (int i = 0; i < data->num_records; ++i) {
        pthread_mutex_lock(data->mutex);
        TransactionRecord* record = malloc(sizeof(TransactionRecord));
        if (record == NULL) {
            // Handle memory allocation failure
            pthread_exit(NULL);
        }
        record->id = data->start_id + i;
        record->timestamp = data->base_timestamp + rand_r(&data->seed);
        record->amount = data->min_amount + (rand_r(&data->seed) / (RAND_MAX * 1.0)) * (data->max_amount - data->min_amount);
        strncpy(record->merchant, &data->merchants[rand_r(&data->seed) % strlen(data->merchants)], sizeof(record->merchant));
        // Process the transaction record
        pthread_mutex_unlock(data->mutex);
    }
    pthread_exit(NULL);
}

int main() {
    int num_threads = 4;
    int num_records_per_thread = 1000;
    long base_timestamp = 1633072800; // Example timestamp
    double min_amount = 1.0, max_amount = 1000.0;
    char merchants[] = "MerchantA\0MerchantB\0MerchantC";
    pthread_t threads[num_threads];
    ThreadData thread_data[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        thread_data[i].start_id = i * num_records_per_thread;
        thread_data[i].num_records = num_records_per_thread;
        thread_data[i].base_timestamp = base_timestamp + i * 86400; // Incremental timestamp
        thread_data[i].min_amount = min_amount;
        thread_data[i].max_amount = max_amount;
        thread_data[i].merchants = merchants;
        pthread_mutex_t mutex;
        pthread_mutex_init(&mutex, NULL);
        thread_data[i].mutex = &mutex;

        if (pthread_create(&threads[i], NULL, generate_transactions, &thread_data[i]) != 0) {
            // Handle thread creation failure
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

