    if (!timestamps) return NULL;

    short *identifiers = (short*)malloc(count * sizeof(short));
    if (!identifiers) {
        free(timestamps);
        return NULL;
    }

    float *float_data = (float*)malloc(count * sizeof(float));
    if (!float_data) {
        free(identifiers);
        free(timestamps);
        return NULL;
    }

