    if (!char_data) {
        free(float_data);
        free(identifiers);
        free(timestamps);
        return NULL;
    }

    event_t *events = (event_t*)malloc(count * sizeof(event_t));
    if (!events) {
        free(char_data);
        free(float_data);
        free(identifiers);
        free(timestamps);
        return NULL;
    }

    // Seed PRNG
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        timestamps[i] = rand(); // Random timestamp
        identifiers[i] = (short)(rand() % 100); // Identifier between 0 and 99
        float_data[i] = ((float)rand()) / RAND_MAX * 2.0f - 1.0f; // Float between -1.0 and 1.0
        char_data[i] = (char)(rand() % 256); // Random character

        events[i].id = identifiers[i];
        events[i].value = float_data[i];
        events[i].type = char_data[i];
    }

    return events;
}

