    int key;
    char log[256];
} AuditLog;

Record* init_records(int seed, long** offsets, AuditLog** logs) {
    srand(seed);
    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    *offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!*offsets) {
        perror("Failed to allocate memory for offsets");
        free(records);
        return NULL;
    }

    *logs = (AuditLog*)malloc(MAX_RECORDS * sizeof(AuditLog));
    if (!*logs) {
        perror("Failed to allocate memory for logs");
        free(*offsets);
        free(records);
        return NULL;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i].value = rand() % 1000 + 1; // Pseudo-random value between 1 and 1000
        records[i].offset = &(*offsets)[i];
        time_t current_time;
        time(&current_time);
        records[i].timestamp = current_time;

        sprintf((*logs)[i].log, "Record %d initialized at %ld", i, (long)records[i].offset);
    }

    return records;
}

void free_memory(Record* records, long* offsets, AuditLog* logs) {
    free(records);
    free(offsets);
    free(logs);
}

int main() {
    int seed = 42; // Example seed
    Record* records = init_records(seed, NULL, NULL);
    if (!records) return 1;

    long* offsets;
    AuditLog* logs;
    if (!(offsets = malloc(MAX_RECORDS * sizeof(long))) ||
        !(logs = malloc(MAX_RECORDS * sizeof(AuditLog)))) {
        free_memory(records, offsets, logs);
        perror("Failed to allocate memory for additional arrays");
        return 1;
    }

    // Read integers from standard input
    int num_ints;
    printf("Enter the number of integers: ");
    scanf("%d", &num_ints);

    int* numbers = (int*)malloc(num_ints * sizeof(int));
    if (!numbers) {
        free_memory(records, offsets, logs);
        perror("Failed to allocate memory for numbers");
        return 1;
    }

    printf("Enter the integers:\n");
    for (int i = 0; i < num_ints; ++i) {
        scanf("%d", &numbers[i]);
    }

    // Find and print the largest integer
    int max_value = numbers[0];
    for (int i = 1; i < num_ints; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", max_value);

    // Free all allocated memory
    free(numbers);
    free_memory(records, offsets, logs);

    return 0;
}
