typedef struct {
    int value;
} Record;

void seedRandomGenerator(unsigned long seed) {
    srand(seed);
}

Record* createRecords(int count, int minVal, int maxVal) {
    if (count <= 0 || minVal > maxVal) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    Record *records = malloc(count * sizeof(Record));
    if (records == NULL) {
        perror("Memory allocation failed.");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
    }

    return records;
}

void freeRecords(Record *records, int count) {
    if (records != NULL) {
        free(records);
    }
}

int* readIntegers(int *count) {
    char buffer[256];
    printf("Enter a list of integers separated by spaces: ");
    fgets(buffer, sizeof(buffer), stdin);

    *count = 0;
    int maxCount = 10; // Initial capacity
    int *numbers = malloc(maxCount * sizeof(int));
    if (numbers == NULL) {
        perror("Memory allocation failed.");
        return NULL;
    }

    char *token = strtok(buffer, " ");
    while (token != NULL && *count < maxCount) {
        numbers[(*count)++] = atoi(token);
        token = strtok(NULL, " ");
    }

    // Resize array if necessary
    int *resizedNumbers = realloc(numbers, (*count) * sizeof(int));
    if (resizedNumbers == NULL) {
        perror("Memory reallocation failed.");
        free(numbers);
        return NULL;
    }
    numbers = resizedNumbers;

    return numbers;
}

int findLargestInteger(const int *numbers, int count) {
    if (count <= 0) {
        fprintf(stderr, "Empty input array.\n");
        return INT_MIN;
    }

    int largest = INT_MIN;
    for (int i = 0; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    return largest;
}

void freeIntegers(int *numbers, int count) {
    if (numbers != NULL) {
        free(numbers);
    }
}
