int* readInput(int *size) {
    int capacity = 16;
    int *array = (int *)malloc(capacity * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int num;
    while (scanf("%d", &num) == 1) {
        if (*size >= capacity) {
            capacity *= 2;
            int *newArray = (int *)realloc(array, capacity * sizeof(int));
            if (!newArray) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(array);
                exit(EXIT_FAILURE);
            }
            array = newArray;
        }
        array[(*size)++] = num;
    }

    if (*size == 0) {
        fprintf(stderr, "No valid input provided\n");
        free(array);
        exit(EXIT_FAILURE);
    }

    int *newArray = (int *)realloc(array, *size * sizeof(int));
    if (!newArray) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(array);
        exit(EXIT_FAILURE);
    }
    return newArray;
}

void initializeArrays(long *offsets, int *keys, Record *records, int size, unsigned long seed, int rangeStart, int rangeEnd) {
    srand(seed);

    for (int i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
        records[i].value = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }
}

int findMax(int *array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array or empty\n");
        exit(EXIT_FAILURE);
    }

    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void cleanup(long *offsets, int *keys, Record *records, int size) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int size;
    int *inputArray = readInput(&size);

    long *offsets = (long *)malloc(size * sizeof(long));
    int *keys = (int *)malloc(size * sizeof(int));
    Record *records = (Record *)malloc(size * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(inputArray);
        exit(EXIT_FAILURE);
    }

    initializeArrays(offsets, keys, records, size, time(NULL), 0, 100);

    int max = findMax(inputArray, size);
    printf("Largest integer in input: %d\n", max);

    cleanup(offsets, keys, records, size);
    free(inputArray);

    return 0;
}
