typedef struct {
    int* keys;
    long* offsets;
} record;

typedef struct {
    unsigned long seed;
    time_t last_refresh;
} seed_manager;

record* initialize_records(int num_records, int key_range, int seed_refresh_rate, seed_manager** seed_manager_ptr) {
    // Allocate memory for records
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    // Initialize random number generator seed
    (*seed_manager_ptr)->seed = time(NULL);
    (*seed_manager_ptr)->last_refresh = (*seed_manager_ptr)->seed;

    for (int i = 0; i < num_records; ++i) {
        records[i].keys = (int*)malloc(sizeof(int));
        if (!records[i].keys) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(records[j].keys);
            free(records);
            return NULL;
        }
        *records[i].keys = rand_r(&(*seed_manager_ptr)->seed) % key_range;

        records[i].offsets = (long*)malloc(sizeof(long));
        if (!records[i].offsets) {
            // Handle memory allocation failure
            for (int j = 0; j <= i; ++j) {
                free(records[j].keys);
                free(records[j].offsets);
            }
            free(records);
            return NULL;
        }
        *records[i].offsets = rand_r(&(*seed_manager_ptr)->seed) % num_records;
    }

    // Refresh seed periodically
    if (time(NULL) - (*seed_manager_ptr)->last_refresh >= seed_refresh_rate) {
        (*seed_manager_ptr)->seed = time(NULL);
        (*seed_manager_ptr)->last_refresh = (*seed_manager_ptr)->seed;
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].keys);
        free(records[i].offsets);
    }
    free(records);
}
