typedef struct {
    long offset;
    int key;
    int transaction_id;
} record;

record* allocate_records(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    static unsigned long seed = time(NULL);
    if ((time(NULL) % SEED_INTERVAL) == 0) {
        srand(time(NULL));
        seed = rand();
    }

    for (int i = 0; i < count; i++) {
        records[i].offset = i * sizeof(record);
        records[i].key = i + 1;
        records[i].transaction_id = seed ^ (i * 7);
    }

    pthread_mutex_unlock(&mutex);

    return records;
}

void free_records(record* records) {
    free(records);
}
