    char* timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';
    snprintf(log_buffer.buffer[log_buffer.head], sizeof(log_buffer.buffer[log_buffer.head]), "[%s] %s", timestamp, message);
