#include <time.h>
#include <string.h>
#include <openssl/rand.h>

typedef struct {
    int value;
    time_t timestamp;
} Record;

void generate_data(long offset_count, int key_count, long seed) {
    if (!RAND_seed(&seed, sizeof(seed))) {
        // Handle error: PRNG seeding failed
        return;
    }

    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));
    Record* records = (Record*)malloc(key_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        // Handle error: Memory allocation failed
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (size_t i = 0; i < offset_count; ++i) {
        offsets[i] = i * seed; // Simple example of initializing offsets
    }

    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = rand() % INT_MAX;
        records[i].value = 0;
        records[i].timestamp = time(NULL);
    }

    // Initialize record values with cryptographically strong PRNG
    unsigned char buffer[sizeof(int)];
    for (size_t i = 0; i < key_count; ++i) {
        if (!RAND_bytes(buffer, sizeof(buffer))) {
            // Handle error: Failed to generate random bytes
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        memcpy(&records[i].value, buffer, sizeof(int));
    }

    // Verify data integrity using a simple checksum
    unsigned long checksum = 0;
    for (size_t i = 0; i < key_count; ++i) {
        checksum += records[i].value + keys[i] + offsets[i];
    }
    printf("Checksum: %lu\n", checksum);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
```

