#define MAX_THREADS 1000
#define MAX_RECORDS 1000000
#define RECORD_SIZE sizeof(int)
#define ARRAY_SIZE (1 * 1024 * 1024) // 1MB

typedef struct {
    int value;
} record;

int initialize_records(record **records, long **offsets, int *keys, int num_threads, int num_records, int range_start, int range_end) {
    size_t total_size = sizeof(record) * num_records + sizeof(long) * num_records + sizeof(int) * num_records;

    if (total_size > ARRAY_SIZE) {
        fprintf(stderr, "Error: Total memory allocation exceeds 1MB\n");
        return -1;
    }

    *records = (record *)aligned_alloc(64, total_size);
    if (!*records) {
        fprintf(stderr, "Error: Memory allocation failed for records\n");
        return -2;
    }

    *offsets = (long *)(*records + num_records);
    *keys = (int *)(*offsets + num_records);

    srand(time(0));

    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % (range_end - range_start + 1) + range_start;
    }

    return 0;
}

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;
    // Perform operations on records
    pthread_exit(NULL);
}

int main() {
    record *records;
    long *offsets;
    int *keys;
    int num_threads = MAX_THREADS;
    int num_records = MAX_RECORDS;

    if (initialize_records(&records, &offsets, keys, num_threads, num_records, 0, 1000) != 0) {
        fprintf(stderr, "Error: Failed to initialize records\n");
        return 1;
    }

    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]) != 0) {
            fprintf(stderr, "Error: Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Error: Failed to join thread %d\n", i);
            return 1;
        }
    }

    free(records);

    return 0;
}
