#include <openssl/rand.h>

typedef struct record {
    float f;
    char c;
    struct record *ptr;
} Record;

Record* create_records(size_t size, unsigned long seed) {
    if (RAND_seed(&seed, sizeof(seed)) != 1) {
        fprintf(stderr, "Failed to seed the PRNG\n");
        return NULL;
    }

    Record *records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        if (!RAND_bytes((unsigned char*)&records[i].f, sizeof(float))) {
            fprintf(stderr, "Failed to generate random float\n");
            free(records);
            return NULL;
        }
        records[i].c = (char)(rand() % 256); // Random character
        if (i < size - 1) {
            records[i].ptr = &records[i + 1];
        } else {
            records[i].ptr = NULL; // Last element points to NULL
        }
    }

    return records;
}

void free_records(Record *records, size_t size) {
    if (records) {
        free(records);
    }
}
