    Record *records = malloc(count * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    // Initialize records with pseudo-random values
    for (size_t i = 0; i < count; ++i) {
        records[i].id = rand();
        records[i].value = rand();
        records[i].ratio = ((double)rand()) / RAND_MAX;
    }
    return records;
