uint64_t generate_unique_id(uint64_t seed, uint64_t *id, uint64_t timeout) {
    // Implement a hash function with retry logic
    while (1) {
        uint64_t new_id = seed ^ time(NULL);
        if (new_id != *id) {
            *id = new_id;
            break;
        }
        usleep(timeout); // Retry after a short delay
    }
    return *id;
}

void export_records(Record *records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    // Write records in binary format
    size_t written = fwrite(records, sizeof(Record), count, file);
    if (written != count) {
        fprintf(stderr, "Error writing records to file.\n");
    }
    fclose(file);
}

