typedef struct {
    short value;
    uint64_t id;
    float precision;
} record;

uint64_t hash_function(uint64_t seed, int key) {
    return (seed * 31 + key) % UINT64_MAX;
}

void initialize_arrays(long **offsets, short **indices, uint64_t **ids1, uint64_t **ids2, record **records, uint64_t seed) {
    *offsets = malloc(ARRAY_SIZE * sizeof(long));
    *indices = malloc(ARRAY_SIZE * sizeof(short));
    *ids1 = malloc(ARRAY_SIZE * sizeof(uint64_t));
    *ids2 = malloc(ARRAY_SIZE * sizeof(uint64_t));
    *records = malloc(ARRAY_SIZE * sizeof(record));

    if (!*offsets || !*indices || !*ids1 || !*ids2 || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < ARRAY_SIZE; i++) {
        (*offsets)[i] = rand() % LONG_MAX;
        (*indices)[i] = rand() % SHRT_MAX;
        (*ids1)[i] = hash_function(seed, i);
        (*ids2)[i] = hash_function(seed + 1, i);

        while (i > 0 && (*ids1)[i] == (*ids1)[i - 1]) {
            (*ids1)[i] = hash_function(seed + i, i);
        }

        (*records)[i].value = rand() % SHRT_MAX;
        (*records)[i].id = (*ids1)[i];
        (*records)[i].precision = (float)rand() / RAND_MAX;
    }
}

void cleanup(long *offsets, short *indices, uint64_t *ids1, uint64_t *ids2, record *records) {
    free(offsets);
    free(indices);
    free(ids1);
    free(ids2);
    free(records);
}

