typedef struct {
    int id;
    uint64_t large_number;
    double value;
} record;

// Function to allocate memory for arrays and initialize records with secure random numbers
void init_records(int num_records, long *long_array, int *int_array, uint64_t *uint64_array, record **records) {
    // Allocate memory for the records array
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Seed the random number generator
    srand(time(NULL));

    // Initialize each record with secure random numbers
    for (int i = 0; i < num_records; i++) {
        (*records)[i].id = rand();
        RAND_bytes((unsigned char *)&((*records)[i].large_number), sizeof(uint64_t));
        (*records)[i].value = (double)rand() / RAND_MAX;
    }
}

// Function to free allocated memory
void cleanup_records(record *records, int num_records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    int num_records = 100;
    long *long_array = NULL;
    int *int_array = NULL;
    uint64_t *uint64_array = NULL;
    record *records = NULL;

    // Allocate and initialize records
    init_records(num_records, &long_array, &int_array, &uint64_array, &records);

    // Clean up allocated memory
    cleanup_records(records, num_records);

    return 0;
}
