#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

#define DEFAULT_RECORDS 10

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    unsigned int identifier;
    char* description;
    float value;
    double weight;
    short index;
} entry;

record* allocate_records(int num_records) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % INT_MAX;
        records[i].value = rand() % 1000 - 500; // Random int between -500 and 499
    }
    return records;
}

entry* allocate_entries(int num_entries, const char* seed) {
    srand(seed ? atoi(seed) : time(NULL)); // Seed for random number generation
    entry* entries = (entry*)malloc(num_entries * sizeof(entry));
    if (!entries) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_entries; ++i) {
        entries[i].identifier = rand() % UINT_MAX;
        entries[i].description = (char*)malloc(50 * sizeof(char));
        sprintf(entries[i].description, "Entry %d", i);
        entries[i].value = ((float)rand()) / RAND_MAX * 100.0f; // Random float between 0 and 100
        entries[i].weight = ((double)rand()) / RAND_MAX; // Random double between 0 and 1
        entries[i].index = rand() % SHRT_MAX;
    }
    return entries;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].description);
    }
    free(records);
}

void free_entries(entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].description);
    }
    free(entries);
}

int main(int argc, char** argv) {
    int num_records = DEFAULT_RECORDS;
    if (argc > 1) {
        num_records = atoi(argv[1]);
    }
    record* records = allocate_records(num_records);

    entry* entries = allocate_entries(num_records * 2, "12345"); // Example seed

    // Process the data...

    free_records(records, num_records);
    free_entries(entries, num_records * 2);

    return 0;
}
