        buffer->count++;
    }
    snprintf(buffer->logBuffer[buffer->tail], MAX_LOG_SIZE, "%s", message);
    buffer->tail = (buffer->tail + 1) % CIRCULAR_BUFFER_SIZE;
}

void executeCommand(const char* command, const char* args[], const char* directory) {
    FILE* input = popen(command, "r");
    if (!input) {
        perror("popen");
        return;
    }
    fclose(input);
}

int main() {
    LogBuffer logBuffer;
    logBuffer.head = 0;
    logBuffer.tail = 0;
    logBuffer.count = 0;

    IDArray* ids = generateUniqueIDs(time(NULL), 100);
    for (int i = 0; i < ids->size; i++) {
        printf("ID: %d\n", ids->ids[i]);
    }

    free(ids->ids);
    free(ids);

    logEvent(&logBuffer, "Identifier generation complete.");

    return 0;
}
