// Define record structure
struct Record {
    int attack;
};

// Function to simulate attack sequence
void simulateAttackSequence(int seed, int range, int cooldown) {
    // Seed the random number generator
    std::srand(seed);

    // Dynamically allocate memory for arrays
    long* offsets = new long[range];
    int* keys = new int[range];

    // Initialize arrays with cryptographically strong pseudo-random numbers
    for (int i = 0; i < range; ++i) {
        offsets[i] = std::rand() % 1000;
        keys[i] = std::rand() % 1000;
    }

    // Dynamically allocate memory for records
    Record* records = new Record[range];
    for (int i = 0; i < range; ++i) {
        records[i].attack = std::rand() % range + 1;
    }

    // Print attack numbers to the console
    for (int i = 0; i < range; ++i) {
        if (i > 0 && i % cooldown == 0) {
            std::this_thread::sleep_for(std::chrono::seconds(cooldown));
        }
        std::cout << records[i].attack << " ";
    }

    // Clean up allocated memory
    delete[] offsets;
    delete[] keys;
    delete[] records;
}

// Helper function to find the largest integer in an array
int findLargestInteger(const std::vector<int>& numbers) {
    return *std::max_element(numbers.begin(), numbers.end());
}

int main() {
    // Read integers from standard input
    std::vector<int> numbers;
    int number;
    while (std::cin >> number) {
        numbers.push_back(number);
    }

    // Find and print the largest integer
    std::cout << "Largest Integer: " << findLargestInteger(numbers) << std::endl;

    return 0;
}
