#include <iostream>
#include <vector>
#include <random>
#include <ctime>
#include <chrono>

struct record {
    int value;
};

void simulateAttackSequence(int cooldown, int max_attempts) {
    // Seed the random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1); // For choosing between two attacks

    long* timestamps = new long[max_attempts];
    int* keys = new int[max_attempts];
    record* records = new record[max_attempts];

    for (int i = 0; i < max_attempts; ++i) {
        timestamps[i] = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        keys[i] = dis(gen);
        records[i].value = dis(gen); // Assuming record value is an int
    }

    for (int i = 0; i < max_attempts; ++i) {
        std::this_thread::sleep_for(std::chrono::seconds(cooldown));
        if (dis(gen)) {
            std::cout << "Attack " << i % 2 + 1 << " chosen" << std::endl;
        }
    }

    delete[] timestamps;
    delete[] keys;
    delete[] records;
}

int findMaxInteger(const std::vector<int>& numbers) {
    if (numbers.empty()) {
        throw std::invalid_argument("The input vector is empty.");
    }

    int max_val = INT_MIN;
    for (int num : numbers) {
        if (num > max_val) {
            max_val = num;
        }
    }
    return max_val;
}

int main() {
    // Example usage
    simulateAttackSequence(9, 10);

    std::vector<int> input_numbers;
    int num;
    while (std::cin >> num) {
        input_numbers.push_back(num);
    }

    try {
        int max_num = findMaxInteger(input_numbers);
        std::cout << "The largest integer is: " << max_num << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
