import java.util.Scanner;
import java.util.LinkedList;
import java.util.Random;

public class TransactionProcessor {

    public static void processTransactionSequence(int seed) {
        Scanner scanner = new Scanner(System.in);
        int[] longArray = new int[100]; // Dynamically allocate memory for 'long' transaction IDs
        double[] doubleArray = new double[100]; // Dynamically allocate memory for 'double' transaction amounts

        LinkedList<Transaction> transactionList = new LinkedList<>(); // Allocate memory for linked list of 'transaction' objects

        Random prng = new Random(seed); // Seed the random number generator with a user-provided seed value

        try {
            while (true) {
                int id = prng.nextInt(10000); // Generate random transaction ID
                double amount = 0.01 + prng.nextDouble() * 999.99; // Generate random transaction amount within a specified range

                Transaction transaction = new Transaction(id, amount);
                transactionList.add(transaction);

                System.out.println("Transaction ID: " + id + ", Amount: " + amount); // Print the selected transaction's ID and amount to the console

                Thread.sleep(5000); // Ensure the process is efficient and minimizes overhead with a 5-second cooldown period
            }
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        scanner.close();

        freeMemory(longArray, doubleArray, transactionList); // Proper memory management to ensure all allocated memory is freed after execution
    }

    private static void freeMemory(int[] longArray, double[] doubleArray, LinkedList<Transaction> transactionList) {
        longArray = null; // Free memory for 'long' transaction IDs
        doubleArray = null; // Free memory for 'double' transaction amounts

        while (!transactionList.isEmpty()) {
            transactionList.removeFirst(); // Free memory for each 'transaction' object in the linked list
        }

        System.gc(); // Request the JVM to perform garbage collection
    }

    static class Transaction {
        int id;
        double amount;

        public Transaction(int id, double amount) {
            this.id = id;
            this.amount = amount;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter seed value: ");
        int seed = scanner.nextInt();
        processTransactionSequence(seed);
    }
}
