import os
import json
import logging
from functools import lru_cache

# Setup logging configuration
logging.basicConfig(level=logging.INFO)

def get_system_memory():
    # Simulate getting system memory
    return 16 * 1024 * 1024 * 1024  # 16GB

@lru_cache(maxsize=None)
def load_json_file(file_path):
    with open(file_path, 'r') as file:
        data = json.load(file)
    return data

def sort_user_records(users, sort_key='last_name'):
    return sorted(users, key=lambda x: x.get(sort_key, ''))

def extract_sequence_number(user_record):
    # Simulate extracting a sequence number
    return user_record.get('id', 0)

def generate_report(file_paths, filter_criteria=None, custom_sort_key=None):
    total_memory = get_system_memory()
    used_memory = 0
    report_data = []

    for file_path in file_paths:
        try:
            users = load_json_file(file_path)
            if filter_criteria:
                users = [user for user in users if all(user.get(key) == value for key, value in filter_criteria.items())]
            if custom_sort_key:
                users = sort_user_records(users, custom_sort_key)
            else:
                users = sort_user_records(users)

            sequence_numbers = [extract_sequence_number(user) for user in users]
            report_data.extend(sequence_numbers)

            # Update used memory
            file_size = os.path.getsize(file_path)
            used_memory += file_size

            if used_memory > total_memory * 0.8:  # Adjust cache size based on usage
                load_json_file.cache_clear()

        except Exception as e:
            logging.error(f"Error processing file {file_path}: {e}")

    return report_data
