typedef struct {
    unsigned long identifier;
    int index;
    byte *dataBuffer;
} keyRecord;

void generateAndProcessKeys(size_t numRecords, size_t bufferSize, unsigned long seed) {
    // Initialize OpenSSL
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    // Seed the random number generator
    srand(seed);

    // Allocate memory for key records
    keyRecord *records = (keyRecord *)malloc(numRecords * sizeof(keyRecord));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize key records and allocate data buffers
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].identifier = rand();
        records[i].index = rand() % numRecords;
        records[i].dataBuffer = (byte *)malloc(bufferSize);
        if (!records[i].dataBuffer) {
            fprintf(stderr, "Memory allocation failed\n");
            free(records);
            return;
        }
    }

    // Fill data buffers with random cryptographic data
    for (size_t i = 0; i < numRecords; ++i) {
        for (size_t j = 0; j < bufferSize; ++j) {
            records[i].dataBuffer[j] = rand() % 256;
        }
    }

    // Close OpenSSL
    EVP_cleanup();

    // Free allocated memory
    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i].dataBuffer);
    }
    free(records);

    // Find and print the largest key identifier
    unsigned long largestIdentifier = findLargestKeyIdentifier(numRecords, records);
    printf("Largest Key Identifier: %lu\n", largestIdentifier);
}

unsigned long findLargestKeyIdentifier(size_t numRecords, keyRecord *records) {
    if (numRecords == 0 || !records) {
        return 0;
    }
    unsigned long largest = records[0].identifier;
    for (size_t i = 1; i < numRecords; ++i) {
        if (records[i].identifier > largest) {
            largest = records[i].identifier;
        }
    }
    return largest;
}
