typedef struct {
    long *offsets;
    int *keys;
    struct record {
        int value;
    } **records;
} Session;

Session* create_session(int num_records, const char *extension) {
    if (num_records <= 0 || strlen(extension) > 128) {
        return NULL;
    }

    Session *session = (Session *)malloc(sizeof(Session));
    if (!session) {
        return NULL;
    }

    session->offsets = (long *)calloc(num_records, sizeof(long));
    session->keys = (int *)calloc(num_records, sizeof(int));
    session->records = (struct record **)calloc(num_records, sizeof(struct record *));
    if (!session->offsets || !session->keys || !session->records) {
        free(session);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        session->records[i] = (struct record *)malloc(sizeof(struct record));
        if (!session->records[i]) {
            for (int j = 0; j < i; j++) {
                free(session->records[j]);
            }
            free(session->records);
            free(session->keys);
            free(session->offsets);
            free(session);
            return NULL;
        }
    }

    srand(time(NULL));
    char new_filename[129];
    do {
        int length = sprintf(new_filename, "%s", extension);
        for (int i = 0; i < 10; i++) {
            new_filename[length++] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"[rand() % 52];
        }
        new_filename[length] = '\0';
        FILE *file = fopen(new_filename, "r");
    } while (file);

    return session;
}

void destroy_session(Session *session, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(session->records[i]);
    }
    free(session->records);
    free(session->keys);
    free(session->offsets);
    free(session);
}
