void manageSessionData(int seed, int numSessions) {
    srand(seed);
    Session* sessions = (Session*)malloc(numSessions * sizeof(Session));
    if (sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Seed custom PRNG with user-provided seed value
