    for (int i = 0; i < numSessions; i++) {
        sessions[i].timestamp = time(NULL);
        sessions[i].sessionID = rand_r(&prngSeed) % 1000000; // Generate a random session ID
        sessions[i].sessionToken = customPRNG(prngSeed); // Generate a unique session token
    }

    // Read timestamps from standard input and calculate average time spent per session
    double total_time = 0;
    for (int i = 0; i < numSessions; i++) {
        printf("Enter timestamp for session %d: ", i + 1);
        scanf("%ld", &sessions[i].timestamp);
        total_time += difftime(sessions[i].timestamp, sessions[0].timestamp);
    }

    double average_time = total_time / numSessions;
    printf("Average time spent per session: %.2f\n", average_time);

    // Free allocated memory
    free(sessions);
}

