    // Initialize variables and resources
    srand(time(NULL));  // Seed for cryptographically strong pseudo-random number generator

    // Create and initialize arrays
    long* offsets = (long*)malloc(10 * sizeof(long));
    int* keys = (int*)malloc(10 * sizeof(int));
    char** commands = (char**)malloc(10 * sizeof(char*));

    // Populate arrays with data
    for (int i = 0; i < 10; ++i) {
        offsets[i] = i * 100L;
        keys[i] = rand() % 100;
        commands[i] = "echo Test";
    }

    // Create and initialize thread pool
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, taskRunner, keys + i);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < 10; ++i) {
        free(commands[i]);
    }
    free(commands);

    return 0;
}

void* taskRunner(void* arg) {
    int* key = (int*)arg;

    // Perform task using the provided key
    logEvent("Starting task with key: %d", *key);
    char output[128];
    snprintf(output, sizeof(output), "Key processed: %d", *key);

    // Execute command and handle output
    FILE* pipe = popen(commands[*key], "r");
    if (!pipe) {
        logEvent("Error executing command for key: %d", *key);
        return NULL;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        printf("%s", buffer);
    }

    int status = pclose(pipe);
    if (status == -1) {
        logEvent("Error closing command output for key: %d", *key);
        return NULL;
    }

    // Log completion of task
    logEvent("Task completed with key: %d", *key);

    return NULL;
}

void logEvent(const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Implement timestamped logging to circular buffer here

    va_end(args);
}
