int* read_integers(int* count) {
    char buffer[256];
    *count = 0;
    printf("Enter integers (comma-separated): ");
    fgets(buffer, sizeof(buffer), stdin);
    char* token = strtok(buffer, ",");
    while (token != NULL) {
        (*count)++;
        token = strtok(NULL, ",");
    }
    int* integers = malloc(*count * sizeof(int));
    if (integers == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    token = strtok(buffer, ",");
    for (int i = 0; i < *count; i++) {
        integers[i] = atoi(token);
        token = strtok(NULL, ",");
    }
    return integers;
}

int find_largest(int* integers, int count) {
    if (count == 0) {
        fprintf(stderr, "No integers provided\n");
        exit(EXIT_FAILURE);
    }
    int largest = integers[0];
    for (int i = 1; i < count; i++) {
        if (integers[i] > largest) {
            largest = integers[i];
        }
    }
    return largest;
}

void generate_records(record* records, int size, long offset, int min_val, int max_val, unsigned seed) {
    srand(seed);
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void clean_up(record* records, long* offsets, int record_size, int offset_size) {
    free(records);
    free(offsets);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <record_size> <offset_size> <seed>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int record_size = atoi(argv[1]);
    int offset_size = atoi(argv[2]);
    unsigned seed = atoi(argv[3]);

    long* offsets = malloc(offset_size * sizeof(long));
    if (offsets == NULL) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    record* records = malloc(record_size * sizeof(record));
    if (records == NULL) {
        perror("Memory allocation failed");
        free(offsets);
        return EXIT_FAILURE;
    }

    generate_records(records, record_size, offsets[0], 1, 100, seed);

    int count;
    int* integers = read_integers(&count);
    int largest = find_largest(integers, count);

    printf("Largest integer: %d\n", largest);

    clean_up(records, offsets, record_size, offset_size);

    free(integers);
    return 0;
}
