use std::process::{Command, Stdio};
use rustc_driver::{catch_with_exit_code, early_error, run_compiler};
use rustc_session::{EarlyErrorHandler, Session};

fn get_resident_set_size() -> usize {
    unsafe { libc::sysconf(libc::_SC_PHYS_PAGES) as usize * libc::sysconf(libc::_SC_PAGE_SIZE) as usize }
}

fn compile_rust_with_logging() -> i32 {
    let start_time = std::time::Instant::now();
    let mut sess = Session::new(SessionKind::Normal);
    sess.err_handler().note("Compiling Rust code with custom logging");

    let args = vec!["rustc", "--crate-type=bin", "main.rs"];
    let exit_code = catch_with_exit_code(&args, |errors| {
        run_compiler(&sess, errors, args)
    });

    let end_time = std::time::Instant::now();
    sess.err_handler().note(format!("Compilation time: {:?}", end_time - start_time));
    sess.err_handler().note(format!("Resident set size before compilation: {}", get_resident_set_size()));
    sess.err_handler().note(format!("Resident set size after compilation: {}", get_resident_set_size()));

    exit_code
}

fn main() {
    let result = compile_rust_with_logging();
    println!("Exit code: {}", result);
}
