void* allocate_and_initialize_arrays(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL;
    }

    long* offset_values = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    unsigned long* timestamps = malloc(num_records * sizeof(unsigned long));

    if (!offset_values || !keys || !timestamps) {
        free(offset_values);
        free(keys);
        free(timestamps);
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        free(offset_values);
        free(keys);
        free(timestamps);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;

        pthread_mutex_lock(&timestamp_lock);
        timestamps[i] = global_counter++;
        pthread_mutex_unlock(&timestamp_lock);

        sprintf(records[i].identifier, "rec%d", i);
    }

    free(offset_values);
    free(timestamps);

    return records;
}

