use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime};
use getresrss::get_resident_set_size;

fn main() -> i32 {
    let start_time = Instant::now();

    let mut child = Command::new("rustc")
        .arg("--version")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to spawn subprocess");

    let (mut stdout, mut stderr) = (
        child.stdout.take().unwrap(),
        child.stderr.take().unwrap(),
    );

    let before_rss = get_resident_set_size().unwrap_or_default();
    let status = child.wait_with_output().expect("Failed to read output");
    let after_rss = get_resident_set_time().unwrap_or_default();

    println!("Compilation time: {:?}", start_time.elapsed());
    println!("Memory usage before compilation: {} bytes", before_rss);
    println!("Memory usage after compilation: {} bytes", after_rss);

    if !status.status.success() {
        let stderr_str = String::from_utf8_lossy(&stderr);
        eprintln!("Compilation failed:\n{}", stderr_str);
    }

    status.code().unwrap_or(1)
}
