        // Handle memory allocation failure
        perror("Failed to allocate key array");
        free(offsets); // Clean up previously allocated memory
        exit(EXIT_FAILURE);
    }
    return keys;
}

record* allocate_record_array(int size) {
    record* records = (record*)malloc(size * sizeof(record));
    if (records == NULL) {
        // Handle memory allocation failure
        perror("Failed to allocate record array");
        free(offsets); // Clean up previously allocated memory
