#include <time.h>
#include <stdint.h>
#include <openssl/sha.h> // Ensure OpenSSL is installed

typedef struct {
    int value;
    long timestamp;
    uint64_t hash;
} record;

record* init_records(int num_records, int min_value, int max_value, unsigned long seed) {
    srand(seed);
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    char key_str[100];
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            free(records);
            return NULL; // Handle system clock error
        }
        records[i].timestamp = current_time;

        snprintf(key_str, sizeof(key_str), "%d%ld", records[i].value, records[i].timestamp);

        SHA256_CTX sha256;
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, key_str, strlen(key_str));
        SHA256_Final(hash, &sha256);

        records[i].hash = *(uint64_t*)hash; // Assuming the first 8 bytes are sufficient
    }

    return records;
}

void free_records(record* records, int num_records) {
    free(records);
}
