#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1000
#define MIN_RECORD_SIZE 10
#define MAX_RECORD_SIZE 100

typedef struct {
    int id;
    time_t start_time;
    char user_id[256];
} SessionRecord;

typedef struct {
    int value;
    long timestamp;
    uint64_t hash;
} Record;

SessionRecord *sessions[MAX_SESSIONS];
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void seed_prng(uint32_t seed) {
    srand(seed);
}

uint32_t fast_prng() {
    return rand();
}

uint32_t secure_prng() {
    // Use a cryptographically strong PRNG here
    return arc4random();
}

uint64_t hash_record(const char *key, long timestamp) {
    uint64_t hash = 0;
    for (int i = 0; key[i] != '\0'; i++) {
        hash = (hash * 31) + key[i];
    }
    hash += timestamp;
    return hash;
}

SessionRecord* create_session(const char *user_id, int seed, int retry_count, struct timespec timeout) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < retry_count; i++) {
        if (sessions[i] == NULL) {
            sessions[i] = malloc(sizeof(SessionRecord));
            if (sessions[i] == NULL) {
                nanosleep(&timeout, NULL);
                continue;
            }
            seed_prng(seed + i * 17); // Unique seed for each attempt
            sessions[i]->id = fast_prng();
            sessions[i]->start_time = time(NULL);
            strncpy(sessions[i]->user_id, user_id, sizeof(sessions[i]->user_id) - 1);

            int record_size = rand() % (MAX_RECORD_SIZE - MIN_RECORD_SIZE + 1) + MIN_RECORD_SIZE;
            Record *records = malloc(record_size * sizeof(Record));
            if (records == NULL) {
                free(sessions[i]);
                sessions[i] = NULL;
                nanosleep(&timeout, NULL);
                continue;
            }

            for (int j = 0; j < record_size; j++) {
                records[j].value = secure_prng();
                records[j].timestamp = time(NULL);
                records[j].hash = hash_record(user_id, records[j].timestamp);
            }

            sessions[i]->records = records;
            pthread_mutex_unlock(&session_lock);
            return sessions[i];
        }
    }
    pthread_mutex_unlock(&session_lock);
    return NULL;
}

void free_session(SessionRecord *record) {
    pthread_mutex_lock(&session_lock);
    if (record != NULL) {
        free(record->records);
        free(record);
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (sessions[i] == record) {
                sessions[i] = NULL;
                break;
            }
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void log_session_creation(const char *user_id, int session_count) {
    FILE *log_file = fopen("session_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "User %s created %d sessions\n", user_id, session_count);
        fclose(log_file);
    }
}

void cleanup_sessions(void (*callback)(SessionRecord *)) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i] != NULL) {
            callback(sessions[i]);
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void *cleanup_thread(void *arg) {
    cleanup_sessions(free_session);
    return NULL;
}
