#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define USER_THRESHOLD 100
#define MEMORY_THRESHOLD 5000000

typedef struct {
    int id;
    float amount;
} Record;

Record* records = NULL;
long* offsets = NULL;
int* keys = NULL;

pthread_mutex_t memory_usage_lock;
long total_memory_used = 0;

void allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_usage_lock);
    if (total_memory_used + size > MEMORY_THRESHOLD) {
        printf("Memory usage threshold exceeded!\n");
        exit(1);
    }
    records = realloc(records, sizeof(Record) * MAX_RECORDS);
    offsets = realloc(offsets, sizeof(long) * USER_THRESHOLD);
    keys = realloc(keys, sizeof(int) * USER_THRESHOLD);
    total_memory_used += size;
    pthread_mutex_unlock(&memory_usage_lock);
}

void initialize_records() {
    allocate_memory(MAX_RECORDS * sizeof(Record));
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i].id = rand();
        records[i].amount = (float)(rand()) / RAND_MAX;
    }
}

void parse_csv(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Assuming CSV format: user_id,transaction_id,timestamp,amount
        int user_id, transaction_id;
        long timestamp;
        float amount;
        sscanf(buffer, "%d,%d,%ld,%f", &user_id, &transaction_id, &timestamp, &amount);
        if (user_id >= USER_THRESHOLD) continue;

        offsets[user_id] += amount;
    }
    fclose(file);
}

void* monitor_memory(void* arg) {
    while (1) {
        pthread_mutex_lock(&memory_usage_lock);
        printf("Current Memory Usage: %ld bytes\n", total_memory_used);
        if (total_memory_used > MEMORY_THRESHOLD * 0.8) {
            printf("Warning: Memory usage is high!\n");
        }
        pthread_mutex_unlock(&memory_usage_lock);
        sleep(1);
    }
}

int main() {
    pthread_t memory_monitor_thread;
    pthread_create(&memory_monitor_thread, NULL, monitor_memory, NULL);

    initialize_records();
    parse_csv("transactions.csv");

    pthread_join(memory_monitor_thread, NULL);

    free(records);
    free(offsets);
    free(keys);

    return 0;
}
