    LogEntry buffer[MAX_LOG_SIZE];
    size_t head, tail;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

ProcessedData processLine(const char *line) {
    // Dummy implementation for demonstration
    ProcessedData pd;
    pd.data = malloc(sizeof(int));
    pd.size = 1;
    *(pd.data) = atoi(line);
    return pd;
}

void logEntry(CircularBuffer *cb, const char *entry) {
    pthread_mutex_lock(&cb->mutex);
    while ((cb->tail + 1) % MAX_LOG_SIZE == cb->head) {
        pthread_cond_wait(&cb->not_full, &cb->mutex);
    }
    strcpy(cb->buffer[cb->tail].entry, entry);
    cb->buffer[cb->tail].timestamp = time(NULL);
    cb->tail = (cb->tail + 1) % MAX_LOG_SIZE;
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);
}

