    CircularBuffer logBuffer;

    logBuffer.head = logBuffer.tail = 0;
    pthread_mutex_init(&logBuffer.mutex, NULL);
    pthread_cond_init(&logBuffer.not_full, NULL);
    pthread_cond_init(&logBuffer.not_empty, NULL);

