    // Simulate processing time
    sleep(5);

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        return 1;
    }

    pthread_mutex_destroy(&logBuffer.mutex);
    pthread_cond_destroy(&logBuffer.not_full);
