    if (!entries) return NULL; // Handle memory allocation failure

    srand(time(NULL)); // Seed PRNG for consistent behavior across runs

    for (int i = 0; i < count; ++i) {
        entries[i] = (logEntry*)malloc(sizeof(logEntry));
        if (!entries[i]) {
            for (int j = 0; j < i; ++j) free(entries[j]);
            free(entries);
            return NULL; // Handle memory allocation failure
        }

        entries[i]->eventID = rand() % 1000 + 1; // Random event ID between 1 and 1000
        entries[i]->offset = rand() % 100000L; // Random offset between 0 and 99999
        entries[i]->value = (double)rand() / RAND_MAX * 100.0; // Random double value between 0 and 100
        entries[i]->identifier = (char*)malloc(20 * sizeof(char));
        if (!entries[i]->identifier) {
            for (int j = 0; j <= i; ++j) {
                free(entries[j]->identifier);
                free(entries[j]);
            }
            free(entries);
            return NULL; // Handle memory allocation failure
        }
        sprintf(entries[i]->identifier, "Entry%03d", i); // Simple identifier format
    }

    return entries;
}

void freeLogEntries(logEntry** entries, int count) {
    for (int i = 0; i < count; ++i) {
        free(entries[i]->identifier);
        free(entries[i]);
    }
    free(entries);
