void* prng_thread(void* arg) {
    long seed = *(long*)arg;
    srand(seed);

    // Simulate PRNG performance
    for (int i = 0; i < MAX_RECORDS; i++) {
        int random_value = rand();
        printf("Generated value: %d\n", random_value);
    }

    pthread_exit(NULL);
}

void read_and_print_largest() {
    int numbers[MAX_RECORDS];
    int count = 0;

    while (1) {
        int input;
        if (scanf("%d", &input) != 1 || input <= 0) {
            break;
        }
        if (count >= MAX_RECORDS) {
            printf("Error: List is too large.\n");
            return;
        }
        numbers[count++] = input;
    }

    if (count == 0) {
        printf("Error: List is empty or malformed.\n");
        return;
    }

    int largest = numbers[0];
    for (int i = 1; i < count; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest integer in the list: %d\n", largest);
}

int main() {
    pthread_t prng_thread_id;
    long seed = time(NULL);

    if (pthread_create(&prng_thread_id, NULL, prng_thread, &seed) != 0) {
        fprintf(stderr, "Error creating PRNG thread.\n");
        return EXIT_FAILURE;
    }

    read_and_print_largest();

    pthread_join(prng_thread_id, NULL);
    printf("PRNG thread completed.\n");

    return EXIT_SUCCESS;
}
