Transaction* create_transactions(int num_transactions, long offset_range[], int key_range[], char* labels[], unsigned int seed, const char* filename) {
    srand(seed);
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < num_transactions; i++) {
        fscanf(file, "%d %c", &transactions[i].value, &transactions[i].label);
        transactions[i].timestamp = time(NULL) + offset_range[rand() % (offset_range[1] - offset_range[0] + 1)] + key_range[rand() % (key_range[1] - key_range[0] + 1)];
    }

    fclose(file);
    return transactions;
}

void find_highest_value_transaction(Transaction* transactions, int num_transactions) {
    if (!transactions || num_transactions <= 0) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    Transaction* highest = transactions;
    for (int i = 1; i < num_transactions; i++) {
        if (transactions[i].value > highest->value) {
            highest = &transactions[i];
        }
    }

    printf("Transaction with the highest value:\nValue: %d\nLabel: %c\nTimestamp: %ld\n", highest->value, highest->label, highest->timestamp);
}

void free_transactions(Transaction* transactions) {
    if (transactions) {
        free(transactions);
    }
}
