double calculate_average_probability(Event* events, int count) {
    double total = 0.0;
    for (int i = 0; i < count; i++) {
        total += events[i].probability;
    }
    return count > 0 ? total / count : 0.0;
}

void free_event_data(Event** events, long* timestamps, int* eventIDs, double* probabilities, char* statuses) {
    free(*events);
    free(timestamps);
    free(eventIDs);
    free(probabilities);
    free(statuses);
}

int main() {
    Event* events = malloc(sizeof(Event) * MAX_EVENTS);
    long* timestamps = malloc(sizeof(long) * MAX_EVENTS);
    int* eventIDs = malloc(sizeof(int) * MAX_EVENTS);
    double* probabilities = malloc(sizeof(double) * MAX_EVENTS);
    char* statuses = malloc(sizeof(char) * MAX_EVENTS);

    if (!events || !timestamps || !eventIDs || !probabilities || !statuses) {
        perror("Memory allocation failed");
        free_event_data(&events, timestamps, eventIDs, probabilities, statuses);
        return 1;
    }

    int count = 0;
    while (count < MAX_EVENTS && scanf("%ld %d %lf %c", &timestamps[count], &eventIDs[count], &probabilities[count], &statuses[count]) == 4) {
        count++;
    }

    if (count == 0) {
        fprintf(stderr, "No valid events provided.\n");
        free_event_data(&events, timestamps, eventIDs, probabilities, statuses);
        return 1;
    }

    double average_probability = calculate_average_probability(events, count);
    printf("Average Probability: %.2f\n", average_probability);

    free_event_data(&events, timestamps, eventIDs, probabilities, statuses);
    return 0;
}
