    }

    int* key_array = malloc(NUM_RECORDS * sizeof(int));
    if (!key_array) {
        free(offset_array);
        perror("Failed to allocate memory for key array");
        return NULL;
    }

    Record* record_array = malloc(NUM_RECORDS * sizeof(Record));
    if (!record_array) {
        free(offset_array);
        free(key_array);
        perror("Failed to allocate memory for record array");
        return NULL;
    }

    pthread_mutex_lock(mutex);

    srand(time(NULL));
    for (int i = 0; i < NUM_RECORDS; ++i) {
        offset_array[i] = rand() % 1000L; // Random long value
        key_array[i] = rand() % CHAR_RANGE + 'a'; // Random int in the range of a-z

        record_array[i].id = i;
        snprintf(record_array[i].identifier, sizeof(record_array[i].identifier), "%c%c", key_array[i], (key_array[i] + 1) % CHAR_RANGE);
        record_array[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(mutex);

    // Free allocated memory if necessary
    free(offset_array);
    free(key_array);
    free(record_array);

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_mutex_t mutex;

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread, NULL, init_arrays, &mutex) != 0) {
        perror("Failed to create thread");
        pthread_mutex_destroy(&mutex);
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        pthread_mutex_destroy(&mutex);
        return EXIT_FAILURE;
    }

    pthread_mutex_destroy(&mutex);

    return EXIT_SUCCESS;
}
