typedef struct {
    int intValue;
    double doubleValue;
    char* stringValue;
} Record;

void* safeMalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initRecord(Record* record, int intValue, double doubleValue, const char* stringValue) {
    record->intValue = intValue;
    record->doubleValue = doubleValue;
    record->stringValue = (char*)safeMalloc(strlen(stringValue) + 1);
    strcpy(record->stringValue, stringValue);
}

void freeRecord(Record* record) {
    free(record->stringValue);
}

void initArrays(size_t size, long** offsetArray, int** keyArray, double** dataArray, Record** records, unsigned long seed) {
    srand(seed); // Seed the random number generator

    *offsetArray = (long*)safeMalloc(size * sizeof(long));
    *keyArray = (int*)safeMalloc(size * sizeof(int));
    *dataArray = (double*)safeMalloc(size * sizeof(double));

    *records = (Record*)safeMalloc(size * sizeof(Record));

    for (size_t i = 0; i < size; ++i) {
        (*offsetArray)[i] = rand();
        (*keyArray)[i] = rand();
        (*dataArray)[i] = ((double)rand() / RAND_MAX);

        char* randomString = (char*)safeMalloc(21); // Allocate space for 20 characters + null terminator
        for (int j = 0; j < 20; ++j) {
            randomString[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        randomString[20] = '\0';

        initRecord(&(*records)[i], rand(), (*dataArray)[i], randomString);
    }
}

void freeArrays(size_t size, long* offsetArray, int* keyArray, double* dataArray, Record* records) {
    for (size_t i = 0; i < size; ++i) {
        freeRecord(&records[i]);
    }

    free(records);
    free(dataArray);
    free(keyArray);
    free(offsetArray);
}
