    time_t expiration;
    bool active;
    struct Data data;
};

// Define the dynamic data structure
struct SessionManager {
    struct Session *sessions;
    size_t count;
    size_t capacity;
};

// Function to initialize the session manager
void initSessionManager(struct SessionManager *manager, size_t initial_capacity) {
    manager->sessions = (struct Session *)malloc(initial_capacity * sizeof(struct Session));
    if (manager->sessions == NULL) {
        // Handle memory allocation failure
        exit(1);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
}

// Function to add a new session
void addSession(struct SessionManager *manager, int id, time_t expiration, bool active) {
    if (manager->count >= manager->capacity) {
        // Reallocate memory or handle overflow
        exit(1);
    }
    struct Session *session = &manager->sessions[manager->count];
    session->id = id;
    session->expiration = expiration;
    session->active = active;
    session->data.value = (double)rand() / RAND_MAX; // Initialize with a random double between 0.0 and 1.0
    memset(session->data.buffer, 0, sizeof(session->data.buffer));
    memset(&session->data.record, 0, sizeof(struct Record));
    manager->count++;
}

// Function to free the session manager
void freeSessionManager(struct SessionManager *manager) {
    free(manager->sessions);
}
