#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RECORD_SIZE 16

typedef struct {
    long offset;
    int key;
    struct record *next;
} Record;

typedef struct {
    int value;
    char id[RECORD_SIZE];
} RecordData;

Record* allocate_records(int count, unsigned long seed) {
    srand(seed);
    Record* head = NULL;
    Record* current = NULL;

    for (int i = 0; i < count; i++) {
        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            printf("Memory allocation failed\n");
            // Free previously allocated records
            while (head != NULL) {
                Record* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_record->offset = rand();
        new_record->key = rand() % 100; // Assuming a range for demonstration
        new_record->next = NULL;

        if (i == 0) {
            head = new_record;
            current = new_record;
        } else {
            current->next = new_record;
            current = new_record;
        }

        RecordData* data = (RecordData*)malloc(sizeof(RecordData));
        if (!data) {
            printf("Memory allocation failed for record data\n");
            // Free previously allocated records and their data
            while (head != NULL) {
                Record* temp = head;
                free(temp->next);
                free(temp);
            }
            return NULL;
        }

        data->value = rand() % 100; // Assuming a range for demonstration
        snprintf(data->id, RECORD_SIZE, "%lx", ((unsigned long)data + i));

        new_record->data = data;
    }

    return head;
}

void free_records(Record* head) {
    while (head != NULL) {
        Record* temp = head;
        free(temp->data);
        head = head->next;
        free(temp);
    }
}

int main() {
    unsigned long seed = time(NULL); // Seed for the random number generator
    int count = 500; // Example count, can be adjusted based on system load

    Record* records = allocate_records(count, seed);
    if (records) {
        printf("Records allocated successfully\n");
        free_records(records);
        printf("Records freed successfully\n");
    }

    return 0;
}
