#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char id[10];
    time_t created;
} record;

enum eventType { INFO, WARNING, ERROR };
typedef struct {
    char* message;
    enum eventType type;
} event;

record** init_records(int count);
event** init_events(int count);
void free_records(record** records, int count);
void free_events(event** events, int count);

record** init_records(int count) {
    record** records = (record**)malloc(count * sizeof(record*));
    if (!records) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            free_records(records, i);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[i]->value = rand() % 1000; // Adjust range as needed
        sprintf(records[i]->id, "%d", rand() % 100); // Adjust format as needed
        records[i]->created = time(NULL);

        records[i]->ref_count = 1;
    }

    pthread_mutex_unlock(&lock);
    return records;
}

event** init_events(int count) {
    event** events = (event**)malloc(count * sizeof(event*));
    if (!events) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; i++) {
        events[i] = (event*)malloc(sizeof(event));
        if (!events[i]) {
            free_events(events, i);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        events[i]->message = strdup("Event message"); // Adjust as needed
        events[i]->type = rand() % 3; // Adjust range as needed

        events[i]->ref_count = 1;
    }

    pthread_mutex_unlock(&lock);
    return events;
}

void free_records(record** records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }
    free(records);
}

void free_events(event** events, int count) {
    for (int i = 0; i < count; i++) {
        if (events[i]) {
            free(events[i]->message);
            free(events[i]);
            events[i] = NULL;
        }
    }
    free(events);
}
