        (*records)[i].key = rand() % INT_MAX;
        (*records)[i].offset = ((long)rand() << 32) | rand();
        for (int j = 0; j < 64; ++j) {
            (*records)[i].data[j] = (unsigned char)(rand() & 0xFF);
        }
    }

    srand(seed2); // Seed the PRNG for integer keys
    return 0; // Success
}

void free_records(record *records, size_t num_records) {
    free(records);
}
