#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned long id;
    time_t timestamp;
    double amount;
} Transaction;

#define INITIAL_CAPACITY 1024

Transaction* init_transactions(size_t initial_capacity, size_t max_memory) {
    // Initialize pseudo-random number generator
    srand(time(NULL));

    // Allocate memory for the transactions array
    Transaction* transactions = malloc(initial_capacity * sizeof(Transaction));
    if (!transactions) {
        return NULL;
    }

    // Allocate memory for a pool of transaction IDs
    unsigned long* id_pool = malloc(max_memory * sizeof(unsigned long));
    if (!id_pool) {
        free(transactions);
        return NULL;
    }

    // Initialize the ID pool with unique, pseudo-randomly generated IDs
    for (size_t i = 0; i < max_memory; ++i) {
        id_pool[i] = rand();
    }

    // Return pointer to the first element of the transactions array
    return transactions;
}

void insert_transaction(Transaction* transactions, size_t* capacity, unsigned long* id_pool, size_t* index, unsigned long id, time_t timestamp, double amount) {
    if (*index >= *capacity) {
        // Double the capacity
        Transaction* new_transactions = realloc(transactions, 2 * *capacity * sizeof(Transaction));
        if (!new_transactions) {
            return;
        }
        transactions = new_transactions;
        *capacity *= 2;

        unsigned long* new_id_pool = realloc(id_pool, 2 * max_memory * sizeof(unsigned long));
        if (!new_id_pool) {
            free(transactions);
            return;
        }
        id_pool = new_id_pool;
        for (size_t i = 0; i < max_memory; ++i) {
            id_pool[i] = rand();
        }
    }

    transactions[*index].id = id;
    transactions[*index].timestamp = timestamp;
    transactions[*index].amount = amount;
    *index += 1;
}

void delete_transaction(Transaction* transactions, size_t* index, unsigned long id) {
    for (size_t i = 0; i < *index; ++i) {
        if (transactions[i].id == id) {
            // Shift the array to remove the element
            for (size_t j = i; j < *index - 1; ++j) {
                transactions[j] = transactions[j + 1];
            }
            *index -= 1;
            break;
        }
    }
}

void free_transactions(Transaction* transactions, unsigned long* id_pool) {
    free(transactions);
    free(id_pool);
}
```

This code provides a basic structure for managing financial transaction records with dynamic memory allocation and efficient management of pseudo-random IDs. The `init_transactions` function initializes the data structures, `insert_transaction` adds new records, `delete_transaction` removes records based on ID, and `free_transactions` cleans up allocated memory when no longer needed. This implementation assumes a single-threaded environment for simplicity; adding thread safety would involve additional synchronization mechanisms such as mutexes or atomic operations, which are beyond the scope of this task.']

