#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    long timestamp;
    int priority;
    int value;
} record;

record* create_records(size_t size, int priority_min, int priority_max, long memory_limit) {
    record* records = malloc(size * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed the non-cryptographic random number generator

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&mutex);
        records[i].offset = rand();
        records[i].key = rand();
        records[i].timestamp = rand() * time(NULL);

        // Generate priority within the specified range
        records[i].priority = priority_min + (rand() % (priority_max - priority_min + 1));
        records[i].value = rand();
        pthread_mutex_unlock(&mutex);

        // Check memory usage and stop if limit is reached
        if ((i + 1) * sizeof(record) > memory_limit) {
            free(records);
            fprintf(stderr, "Memory limit exceeded\n");
            return NULL;
        }
    }

    return records;
}
