#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define constants
#define MAX_MEASUREMENTS 1000
#define LOG_BUFFER_SIZE 100
#define TIMEOUT_SECONDS 60

// Define data structures
typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct {
    double measurements[MAX_MEASUREMENTS];
    char logs[LOG_BUFFER_SIZE][256];
    Node* linkedList;
    size_t measurementCount;
    time_t lastProcessingTime;
} DataStructures;

// Function declarations
void initializeDataStructures(DataStructures* ds, unsigned int seed);
void cleanUpDataStructures(DataStructures* ds);
int readSensorData(DataStructures* ds, const char* filename);
void processMeasurements(DataStructures* ds);
void logEvent(DataStructures* ds, const char* message);
double calculateMean(double* measurements, size_t count);
double calculateMedian(double* measurements, size_t count);
double calculateStandardDeviation(double* measurements, size_t count);

// Main function for demonstration
int main() {
    DataStructures ds;
    unsigned int seed = time(NULL); // Use current time as a default seed

    initializeDataStructures(&ds, seed);
    if (readSensorData(&ds, "sensor_data.txt") != 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return EXIT_FAILURE;
    }

    processMeasurements(&ds);

    cleanUpDataStructures(&ds);
    return EXIT_SUCCESS;
}

// Function definitions
void initializeDataStructures(DataStructures* ds, unsigned int seed) {
    // Initialize random number generator
    srand(seed);

    // Initialize arrays and linked list
    memset(ds->measurements, 0, sizeof(ds->measurements));
    memset(ds->logs, 0, sizeof(ds->logs));
    ds->linkedList = NULL;
    ds->measurementCount = 0;
    ds->lastProcessingTime = time(NULL);
}

void cleanUpDataStructures(DataStructures* ds) {
    // Free linked list
    Node* current = ds->linkedList;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    ds->linkedList = NULL;

    // Clear logs and reset other data structures as needed
}

int readSensorData(DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return -1;
    }

    double measurement;
    while (fscanf(file, "%lf", &measurement) == 1 && ds->measurementCount < MAX_MEASUREMENTS) {
        ds->measurements[ds->measurementCount++] = measurement;
    }

    fclose(file);
    return 0;
}

void processMeasurements(DataStructures* ds) {
    if (time(NULL) - ds->lastProcessingTime > TIMEOUT_SECONDS) {
        logEvent(ds, "Timeout occurred during data processing.");
        return;
    }

    double mean = calculateMean(ds->measurements, ds->measurementCount);
    double median = calculateMedian(ds->measurements, ds->measurementCount);
    double stdDev = calculateStandardDeviation(ds->measurements, ds->measurementCount);

    logEvent(ds, "Data processing complete.");
    printf("Mean: %.2f\n", mean);
    printf("Median: %.2f\n", median);
    printf("Standard Deviation: %.2f\n", stdDev);

    // Populate linked list with random integers
    Node* current = ds->linkedList;
    while (current != NULL) {
        free(current);
        current = current->next;
    }
    ds->linkedList = NULL;

    for (size_t i = 0; i < ds->measurementCount; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            logEvent(ds, "Memory allocation failed while populating linked list.");
            return;
        }
        newNode->value = rand() % 1000;
        newNode->next = ds->linkedList;
        ds->linkedList = newNode;
    }

    ds->lastProcessingTime = time(NULL);
}

void logEvent(DataStructures* ds, const char* message) {
    // Implement a simple circular buffer for logs
    size_t index = (ds->measurementCount % LOG_BUFFER_SIZE) * 256 / sizeof(char);
    snprintf(ds->logs[index], 256 - index, "[%s] %s\n", ctime(&time(NULL)), message);
}

double calculateMean(double* measurements, size_t count) {
    if (count == 0) return 0.0;
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += measurements[i];
    }
    return sum / count;
}

double calculateMedian(double* measurements, size_t count) {
    if (count == 0) return 0.0;
    qsort(measurements, count, sizeof(double), (int (*)(const void *, const void *))strcmp);
    if (count % 2 == 0) {
        return (measurements[count / 2 - 1] + measurements[count / 2]) / 2.0;
    } else {
        return measurements[count / 2];
    }
}

double calculateStandardDeviation(double* measurements, size_t count) {
    if (count <= 1) return 0.0;
    double mean = calculateMean(measurements, count);
    double sumOfSquares = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sumOfSquares += pow(measurements[i] - mean, 2);
    }
    return sqrt(sumOfSquares / (count - 1));
}
