        rec.hexString = malloc(RECORD_SIZE * sizeof(char));
        if (rec.hexString == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free(*records);
            return;
        }

        (*records)[i].data = rec;
    }
}

