    weatherRecord* records = initializeWeatherRecords(10);
    if (records) {
        for (size_t i = 0; i < 10; ++i) {
            printf("Record %zu: Temp=%.2f°C, Humidity=%d%%, Condition=%c\n", i, records[i].avgTemp, records[i].humidity, records[i].condition);
        }
        freeWeatherRecords(records, 10);
    }
    return 0;
}
