// Define record and context structures
typedef struct {
    int value;
} record;

typedef struct {
    record *rec_ptr;
} context;

// Function to initialize the arrays and structures
void init_structures(size_t num_elements, long min_offset, long max_offset, unsigned int seed) {
    // Allocate memory for offsets, keys, records, and contexts
    long *offsets = (long *)malloc(num_elements * sizeof(long));
    int *keys = (int *)malloc(num_elements * sizeof(int));
    record *records = (record *)malloc(num_elements * sizeof(record));
    context *contexts = (context *)malloc(num_elements * sizeof(context));

    // Initialize the PRNG with the provided seed
    srand(seed);

    // Populate records with random integers within the specified range
    for (size_t i = 0; i < num_elements; ++i) {
        records[i].value = rand() % (max_offset - min_offset + 1) + min_offset;
        contexts[i].rec_ptr = &records[i];
    }

    // Populate offsets and keys with random values
    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
    }

    // Free allocated memory after initialization is complete
    free(offsets);
    free(keys);
    free(records);
    free(contexts);
}

// Function to clean up and release resources
void cleanup_resources(size_t num_elements, long *offsets, int *keys, record *records, context *contexts) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
    if (contexts != NULL) {
        free(contexts);
    }
}

// Example usage in a multi-threaded environment
void *thread_function(void *arg) {
    size_t thread_id = *(size_t *)arg;
    // Perform initialization for this thread's portion of the data
    init_structures(1000, 0, 10000, (unsigned int)(thread_id * 12345));
    return NULL;
}

int main() {
    pthread_t threads[10];
    size_t thread_ids[10];

    // Create multiple threads to initialize data concurrently
    for (size_t i = 0; i < 10; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]) != 0) {
            perror("Thread creation failed");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < 10; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Thread join failed");
            return EXIT_FAILURE;
        }
    }

    // Cleanup resources after initialization is complete
    cleanup_resources(10000, NULL, NULL, NULL, NULL);

    return EXIT_SUCCESS;
}
