#define MAX_RECORDS 1000000

typedef struct {
    int value;
    char character;
} Record;

void generate_records(char* output_directory, char** file_names, int num_files, int seed) {
    FILE** files = (FILE**)malloc(num_files * sizeof(FILE*));
    if (!files) {
        fprintf(stderr, "Failed to allocate memory for file pointers.\n");
        return;
    }

    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        free(files);
        return;
    }

    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        free(offsets);
        free(files);
        return;
    }

    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        free(files);
        return;
    }

    srand(seed);

    // Open files
    for (int i = 0; i < num_files; i++) {
        char file_path[256];
        snprintf(file_path, sizeof(file_path), "%s/%s.csv", output_directory, file_names[i]);
        files[i] = fopen(file_path, "w");
        if (!files[i]) {
            fprintf(stderr, "Failed to open file %s for writing.\n", file_path);
            goto cleanup;
        }
    }

    // Generate records
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand();
        keys[i] = rand() % INT_MAX;
        records[i].value = rand() % INT_MAX;
        records[i].character = 'a' + rand() % 26;

        // Write record to file
        for (int j = 0; j < num_files; j++) {
            fprintf(files[j], "%d,%ld,%d,%c\n", keys[i], offsets[i], records[i].value, records[i].character);
        }
    }

cleanup:
    // Close files
    for (int i = 0; i < num_files; i++) {
        if (files[i]) fclose(files[i]);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(files);
}

int main() {
    char* output_directory = "./output";
    char* file_names[] = {"records1", "records2"};
    int num_files = 2;
    int seed = time(NULL);

    generate_records(output_directory, file_names, num_files, seed);

    return 0;
}
