#define MAX_RANDOM_VALUE 2147483647 // Maximum value for int

typedef struct {
    long* offsets;
    int* keys;
    size_t numOffsets;
    size_t maxNumOffsets;
} DynamicSet;

DynamicSet* create_dynamic_set(size_t maxNumOffsets, size_t numKeys, int maxValue) {
    if (maxNumOffsets == 0 || numKeys == 0 || maxValue <= 0) return NULL;

    DynamicSet* set = malloc(sizeof(DynamicSet));
    if (!set) return NULL;

    set->offsets = calloc(maxNumOffsets, sizeof(long));
    if (!set->offsets) {
        free(set);
        return NULL;
    }

    srand(time(NULL)); // Seed for non-cryptographic PRNG

    for (size_t i = 0; i < maxNumOffsets; ++i) {
        set->offsets[i] = rand() % (MAX_RANDOM_VALUE + 1);
    }

    set->keys = calloc(numKeys, sizeof(int));
    if (!set->keys) {
        free(set->offsets);
        free(set);
        return NULL;
    }

    bool* keyExists = calloc(maxValue, sizeof(bool));
    if (!keyExists) {
        free(set->offsets);
        free(set->keys);
        free(set);
        return NULL;
    }

    size_t uniqueKeys = 0;
    while (uniqueKeys < numKeys) {
        int key = rand() % maxValue;
        if (!keyExists[key]) {
            set->keys[uniqueKeys++] = key;
            keyExists[key] = true;
        }
    }

    free(keyExists);
    set->numOffsets = maxNumOffsets;
    set->maxNumOffsets = maxNumOffsets;

    return set;
}

void destroy_dynamic_set(DynamicSet* set) {
    if (set) {
        free(set->offsets);
        free(set->keys);
        free(set);
    }
}

bool is_valid_offset_index(const DynamicSet* set, size_t index) {
    return index < set->numOffsets;
}
