int* allocate_keys(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocate_records(int size) {
    return (record*)calloc(size, sizeof(record));
}

void initialize_keys(int* keys, int size) {
    for (int i = 0; i < size; ++i) {
        keys[i] = i + 1;
    }
}

void fill_records(record* records, int* keys, int size) {
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < size; ++i) {
        records[keys[i]].value = rand() % 2001 - 1000; // Range between -1000 and 1000
    }
}

void sort_records(record* records, int* keys, int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = 0; j < size - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                // Swap keys
                int temp_key = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = temp_key;

                // Swap records
                record temp_record = records[keys[j]];
                records[keys[j]] = records[keys[j + 1]];
                records[keys[j + 1]] = temp_record;
            }
        }
    }
}

record* manage_memory(int size) {
    long* offsets = allocate_offsets(size);
    int* keys = allocate_keys(size);
    record* records = allocate_records(size);

    initialize_keys(keys, size);
    fill_records(records, keys, size);
    sort_records(records, keys, size);

    // Free allocated memory
    free(offsets);
    free(keys);

    return records;
}
