#include <stdlib.h>
#include <time.h>

// Define a simple non-cryptographic PRNG
typedef struct {
    unsigned long seed;
} PRNGState;

void prng_init(PRNGState *state, unsigned long seed) {
    state->seed = seed;
}

unsigned long prng_next(PRNGState *state) {
    return (state->seed = state->seed * 1664525 + 1013904223) & 0xFFFFFFFFUL;
}

// Define a hash table entry
typedef struct {
    int key;
    long offsetIndex;
} HashTableEntry;

// Define a hash table
typedef struct {
    HashTableEntry *entries;
    unsigned int capacity;
    unsigned int size;
} HashTable;

// Initialize the hash table
HashTable* hash_table_init(unsigned int initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->capacity = initial_capacity;
    table->size = 0;
    table->entries = (HashTableEntry*)calloc(initial_capacity, sizeof(HashTableEntry));
    if (!table->entries) {
        free(table);
        return NULL;
    }
    return table;
}

// Hash function
unsigned int hash_function(int key, unsigned int capacity) {
    return abs(key) % capacity;
}

// Insert a key-offset pair into the hash table
int hash_table_insert(HashTable *table, int key, long offsetIndex) {
    if (table->size >= table->capacity / 2) {
        // Rehashing logic here
    }
    unsigned int index = hash_function(key, table->capacity);
    while (table->entries[index].key != 0) {
        index = (index + 1) % table->capacity;
    }
    table->entries[index] = (HashTableEntry){.key = key, .offsetIndex = offsetIndex};
    table->size++;
    return 0; // Return success
}

// Free the hash table
void hash_table_free(HashTable *table) {
    free(table->entries);
    free(table);
}

// Function to allocate and initialize memory for offsets array
long* allocate_and_initialize_offsets(unsigned long maxNumOffsets, unsigned long seed) {
    PRNGState prng;
    prng_init(&prng, seed);
    long *offsets = (long*)malloc(maxNumOffsets * sizeof(long));
    if (!offsets) return NULL;
    for (unsigned long i = 0; i < maxNumOffsets; i++) {
        offsets[i] = prng_next(&prng);
    }
    return offsets;
}

// Function to allocate and initialize keys array
int* allocate_and_initialize_keys(unsigned int numKeys, unsigned int maxKeyValue) {
    HashTable *table = hash_table_init(numKeys);
    if (!table) return NULL;
    int *keys = (int*)malloc(numKeys * sizeof(int));
    if (!keys) {
        hash_table_free(table);
        return NULL;
    }
    for (unsigned int i = 0; i < numKeys; ) {
        int key = rand() % (maxKeyValue + 1); // Using rand for simplicity
        if (hash_table_insert(table, key, i) == 0) {
            keys[i++] = key;
        }
    }
    hash_table_free(table);
    return keys;
}
