        memset(pool[i].buffer, 'A' + rand() % 26, buffer_size - 1); // Initialize random string
        pool[i].buffer[buffer_size - 1] = '\0'; // Null-terminate the string

        time_t now = time(NULL);
        pool[i].timestamp = now + (rand() % 2001) - 1000; // Adjust timestamp by random interval
    }

    return pool;
}

