    int* inputArray = NULL;
    size_t inputSize = 0;
    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;
        inputArray = realloc(inputArray, ++inputSize * sizeof(int));
        if (inputArray == NULL) {
