#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <semaphore.h>

typedef struct {
    float min;
    float max;
} Range;

typedef struct data_entry {
    int id;
    float value;
    time_t timestamp;
} DataEntry;

typedef struct {
    DataEntry* pool;
    size_t size;
    size_t count;
    sem_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->pool = (DataEntry*)malloc(initial_size * sizeof(DataEntry));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->size = initial_size;
    pool->count = 0;
    sem_init(&pool->mutex, 0, 1);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    sem_wait(&pool->mutex);
    free(pool->pool);
    sem_destroy(&pool->mutex);
    free(pool);
}

DataEntry* allocate_entry(MemoryPool* pool) {
    sem_wait(&pool->mutex);
    if (pool->count >= pool->size) {
        size_t new_size = pool->size * 2;
        DataEntry* new_pool = (DataEntry*)realloc(pool->pool, new_size * sizeof(DataEntry));
        if (!new_pool) {
            sem_post(&pool->mutex);
            return NULL;
        }
        pool->pool = new_pool;
        pool->size = new_size;
    }
    DataEntry* entry = &pool->pool[pool->count++];
    sem_post(&pool->mutex);
    return entry;
}

Range create_range(float min, float max) {
    Range range = {min, max};
    return range;
}

float generate_random_float(Range range) {
    return range.min + (rand() / (float)(RAND_MAX / (range.max - range.min)));
}

int generate_random_int(Range range) {
    return (int)(range.min + (rand() / (double)(RAND_MAX / (range.max - range.min + 1))));
}

void printf_range(Range range) {
    printf("Range: %f to %f\n", range.min, range.max);
}

void dataGenerator(const char* config_file) {
    // Read configuration from XML file
    // Initialize custom PRNG using user-provided seed

    MemoryPool pool = create_memory_pool(1024);
    if (!pool) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return;
    }

    Range float_range = create_range(-100.0, 100.0);
    Range int_range = create_range(1, 1000);

    for (int i = 0; i < 10000; i++) {
        DataEntry* entry = allocate_entry(&pool);
        if (!entry) {
            fprintf(stderr, "Failed to allocate memory for data entry\n");
            break;
        }
        entry->id = i + 1;
        entry->value = generate_random_float(float_range);
        entry->timestamp = time(NULL);

        printf("Entry %d: ID=%d, Value=%.2f, Timestamp=%ld\n", i + 1, entry->id, entry->value, entry->timestamp);
    }

    destroy_memory_pool(&pool);
}

int main() {
    srand(time(NULL)); // Seed the PRNG
    dataGenerator("config.xml");
    return 0;
}
