        return NULL; // Handle invalid input
    }

    Record* record = malloc(sizeof(Record));
    if (!record) {
        return NULL; // Memory allocation failed
    }

    record->int_ptr = malloc(count * sizeof(int));
    record->long_ptr = malloc(count * sizeof(long));
    record->double_ptr = malloc(count * sizeof(double));

    if (!record->int_ptr || !record->long_ptr || !record->double_ptr) {
        free(record);
        return NULL; // Memory allocation failed
    }

    srand(seed); // Initialize random seed

    for (size_t i = 0; i < count; ++i) {
        record->int_ptr[i] = rand();
        record->long_ptr[i] = (long)rand() * RAND_MAX + rand();
        record->double_ptr[i] = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
    }

    return record;
}

void free_record(Record* record) {
    if (!record) {
        return; // Handle invalid input
    }

    free(record->int_ptr);
    free(record->long_ptr);
    free(record->double_ptr);
