#define MAX_EVENT_DESCRIPTION_LEN 128
#define NUM_EVENTS 1000

typedef struct {
    time_t timestamp;
    int event_id;
    char *description;
} log_entry;

// High-performance PRNG (e.g., Xorshift)
unsigned long xorshift64star(unsigned long *state) {
    unsigned long x = (*state += UINT64_C(1812433253905205787));
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    return x * UINT64_C(2685821691112543129);
}

int init_log_entries(log_entry **entries, size_t num_entries, unsigned long seed) {
    const char *event_descriptions[] = {"INFO", "WARNING", "ERROR"};
    size_t event_count = sizeof(event_descriptions) / sizeof(event_descriptions[0]);

    *entries = (log_entry *)calloc(num_entries, sizeof(log_entry));
    if (*entries == NULL) {
        perror("Failed to allocate memory for log entries");
        return -1;
    }

    unsigned long state = seed;

    for (size_t i = 0; i < num_entries; ++i) {
        time((*entries)[i].timestamp);
        (*entries)[i].event_id = xorshift64star(&state) % event_count;
        (*entries)[i].description = strdup(event_descriptions[(*entries)[i].event_id]);
        if ((*entries)[i].description == NULL) {
            perror("Failed to allocate memory for event description");
            // Free previously allocated entries
            for (size_t j = 0; j < i; ++j) {
                free((*entries)[j].description);
            }
            free(*entries);
            *entries = NULL;
            return -1;
        }
    }

    return 0;
}

void free_log_entries(log_entry **entries, size_t num_entries) {
    if (*entries != NULL) {
        for (size_t i = 0; i < num_entries; ++i) {
            free((*entries)[i].description);
        }
        free(*entries);
        *entries = NULL;
    }
}

int main() {
    log_entry *log_entries = NULL;
    unsigned long seed = time(NULL);

    if (init_log_entries(&log_entries, NUM_EVENTS, seed) != 0) {
        fprintf(stderr, "Failed to initialize log entries\n");
        return EXIT_FAILURE;
    }

    // Process log entries...

    free_log_entries(&log_entries, NUM_EVENTS);

    return EXIT_SUCCESS;
}
