typedef struct {
    size_t total_memory;
    size_t used_memory;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager memory_manager = {0, 0, PTHREAD_MUTEX_INITIALIZER};

Record* allocate_record(int prng_type) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        return NULL;
    }
    pthread_mutex_lock(&memory_manager.lock);
    memory_manager.total_memory += sizeof(Record);
    memory_manager.used_memory += sizeof(Record);
    pthread_mutex_unlock(&memory_manager.lock);

    // Initialize PRNG based on type
    switch (prng_type) {
        case 0: // Default PRNG type
            srand(time(NULL));
            record->i = rand();
            record->l = rand() * RAND_MAX + rand();
            record->d = ((double)rand()) / RAND_MAX;
            break;
        // Add more PRNG types as needed
        default:
            fprintf(stderr, "Unsupported PRNG type\n");
            free(record);
            return NULL;
    }

    return record;
}

void free_record(Record* record) {
    pthread_mutex_lock(&memory_manager.lock);
    memory_manager.total_memory -= sizeof(Record);
    memory_manager.used_memory -= sizeof(Record);
    pthread_mutex_unlock(&memory_manager.lock);

    free(record);
}

void log_memory_usage() {
    printf("Total Memory: %zu bytes\n", memory_manager.total_memory);
    printf("Used Memory: %zu bytes\n", memory_manager.used_memory);
}

int serialize_record(const Record* record, char* buffer, size_t buffer_size) {
    if (buffer_size < sizeof(Record)) {
        return -1; // Not enough space in buffer
    }
    memcpy(buffer, record, sizeof(Record));
    return 0;
}

Record deserialize_record(const char* buffer) {
    Record record;
    memcpy(&record, buffer, sizeof(Record));
    return record;
}
