#include <time.h>

typedef struct {
    int data;
} Record;

// Custom PRNG algorithm
unsigned long xorshift128plus(unsigned long *x, unsigned long *y) {
    unsigned long s = (*x ^ (*y << 23));
    *x = (*y ^ (s >> 9));
    *y = (s ^ (*x << 12));
    return s + (*x);
}

void initialize_records(long timestamps[], int seeds[], Record records[], int size) {
    unsigned long x[2], y[2];
    srand(seeds[0]); // Seed PRNG with the first seed value
    x[0] = rand();
    y[0] = rand();

    for (int i = 0; i < size; ++i) {
        records[i].data = xorshift128plus(&x[0], &y[0]) % 1000000 + 1; // Generate a unique random number in the range [1, 1000000]
    }
}

int main() {
    int size = 100;
    long timestamps[size];
    int seeds[] = {42};
    Record records[size];

    initialize_records(timestamps, seeds, records, size);

    for (int i = 0; i < size; ++i) {
        printf("Record %d: Data = %d\n", i, records[i].data);
    }

    return 0;
}
```

