#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define LOG_BUFFER_SIZE 1024

typedef struct {
    char buffer[LOG_BUFFER_SIZE];
    int head, tail;
} LogBuffer;

void initLogBuffer(LogBuffer *log) {
    log->head = log->tail = 0;
}

int isLogFull(LogBuffer *log) {
    return (log->head + 1) % LOG_BUFFER_SIZE == log->tail;
}

int isLogEmpty(LogBuffer *log) {
    return log->head == log->tail;
}

void writeToLog(LogBuffer *log, const char *message) {
    if (!isLogFull(log)) {
        int pos = (log->head + 1) % LOG_BUFFER_SIZE;
        snprintf(log->buffer + pos * strlen(message), strlen(message) + 1, "%s", message);
        log->head = pos;
    }
}

void readFromLog(LogBuffer *log) {
    if (!isLogEmpty(log)) {
        printf("Log: %s\n", log->buffer + (log->tail * strlen(log->buffer / log->tail)));
        log->tail = (log->tail + 1) % LOG_BUFFER_SIZE;
    }
}

void executeCommandWithLoggingAndCleanup(char *label, void (*f)()) {
    // Initialize variables and resources
    LogBuffer log;
    initLogBuffer(&log);
    time_t start_time = time(NULL);
    pid_t pid;

    // Seed the random number generator with a user-provided seed value for reproducibility
    srand(time(NULL));

    // Allocate memory for arrays
    long *offsets = (long *)malloc(100 * sizeof(long));
    int *keys = (int *)malloc(100 * sizeof(int));
