    int* array = NULL;
    char line[1024];
    *size = 0;

    while (fgets(line, sizeof(line), stdin)) {
        int num;
        if (sscanf(line, "%d", &num) == 1) {
            *size += 1;
            array = realloc(array, *size * sizeof(int));
            if (array == NULL) {
                fprintf(stderr, "Memory allocation failed.\n");
                free(array);
                exit(EXIT_FAILURE);
            }
            array[*size - 1] = num;
        } else {
            break;
        }
    }

    return array;
}

