// Function to allocate and initialize arrays and records
void* allocate_and_initialize(int num_records, long offset_range) {
    // Allocate memory for 'long' offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) return NULL;

    // Allocate memory for 'int' key array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for 'record' structure array
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize the offset array with values from 0 to num_records-1
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i;
    }

    // Seed the PRNG using a secure method if available, otherwise use time-based seeding
    #ifdef SECURE_PRNG_AVAILABLE
    // Use the secure PRNG function from the cryptographic library
    // For example: secure_prng_seed();
    #else
    srand(time(NULL));
    #endif

    // Initialize the key and record arrays with random values within specified ranges
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % offset_range;
        records[i].value = rand();
    }

    // Return a pointer to all allocated arrays
    return (void*)records;
}

// Example usage
int main() {
    int num_records = 100;
    long offset_range = 1000;
    Record* records = (Record*)allocate_and_initialize(num_records, offset_range);
    if (records) {
        // Use the allocated arrays...
        free(records); // Remember to free all allocated memory
    }
    return 0;
}
