        transactions[i].amount = rand() % 100 + 1; // Range 1 to 100
        transactions[i].status = 'P'; // Pending status
    }

    // Process data concurrently using threads
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, processDataThread, &transactions[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return;
        }
