        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            // Handle memory allocation failure
            return;
        }

        int record_size = sizeof(Record);
        size_t string_length = rand() % 11 + 10; // Between 10 and 20 characters
        if ((total_memory_limit - record_size) < (string_length * sizeof(char))) {
            // Handle memory allocation failure due to exceeding total limit
            free_record(records[i]);
            return;
        }

        records[i]->value = rand() % (max_value - min_value + 1) + min_value;

        records[i]->string = generate_random_string(string_length);
        if (records[i]->string == NULL) {
            // Handle memory allocation failure for string
            free_record(records[i]);
            return;
        }

        total_memory_limit -= record_size + string_length * sizeof(char);
    }
}

void cleanup_records(Record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free_record(records[i]);
    }
    free(records);
}
