// Function to initialize an array of sessions with random IDs and current time as expiration
Session* initializeSessions(int numSessions, unsigned int seed) {
    if (numSessions <= 0 || seed < 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    // Allocate memory for the session array
    Session *sessions = malloc(numSessions * sizeof(Session));
    if (!sessions) {
        perror("Memory allocation failed.");
        return NULL;
    }

    // Seed the random number generator
    srand(seed);

    // Initialize each session with a unique random ID and current time as expiration
    for (int i = 0; i < numSessions; ++i) {
        sessions[i].sessionID = rand(); // Use rand() for simplicity, consider arc4random() for better performance
        snprintf(sessions[i].userName, sizeof(sessions[i].userName), "User%d", i);
        time_t now = time(NULL);
        sessions[i].expirationTime = now + 3600; // Expires in an hour
    }

    return sessions;
}

// Example usage of the function
int main() {
    int numSessions = 5;
    unsigned int seed = 42;

    Session *sessions = initializeSessions(numSessions, seed);
    if (sessions) {
        for (int i = 0; i < numSessions; ++i) {
            printf("Session ID: %u, User Name: %s, Expiration Time: %ld\n",
                   sessions[i].sessionID, sessions[i].userName, sessions[i].expirationTime);
        }
        free(sessions); // Free allocated memory
    }

    return 0;
}
