void* create_dynamic_array(size_t size, char type) {
    void* array = malloc(size * sizeof(type));
    if (array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    switch (type) {
        case 'l': // long
            // Initialize long values with a timestamp
            for (size_t i = 0; i < size; ++i) {
                ((long*)array)[i] = time(NULL);
            }
            break;
        case 'i': // int
            // Initialize int values with random numbers within a specified range
            srand(time(NULL));
            int min_val = -1000, max_val = 1000;
            for (size_t i = 0; i < size; ++i) {
                ((int*)array)[i] = rand() % (max_val - min_val + 1) + min_val;
            }
            break;
        case 'r': // Record
            // Initialize Record values with random numbers within a specified range
            srand(time(NULL));
            int record_min = 0, record_max = 100;
            for (size_t i = 0; i < size; ++i) {
                ((Record*)array)[i].value = rand() % (record_max - record_min + 1) + record_min;
            }
            break;
        case 'd': // double
            // Initialize double values with sensor readings
            for (size_t i = 0; i < size; ++i) {
                ((double*)array)[i] = (rand() / (double)RAND_MAX) * 360.0 - 180.0;
            }
            break;
        case 'w': // WeatherData
            // Initialize WeatherData values with temperature and humidity levels
            srand(time(NULL));
            for (size_t i = 0; i < size; ++i) {
                ((WeatherData*)array)[i].temperature = rand() % 100 - 30;
                ((WeatherData*)array)[i].humidity = (unsigned short)(rand() % 101);
            }
            break;
        default:
            free(array);
            return NULL;
    }

    return array;
}

void destroy_dynamic_array(void* array, char type) {
    if (array != NULL) {
        free(array);
    }
}
