int main() {
    // Read input data and initialize PRNG seed
    scanf("%d", &dataSize);
    data = (int*)malloc(dataSize * sizeof(int));
    for (int i = 0; i < dataSize; ++i) {
        scanf("%d", &data[i]);
    }

    // Initialize PRNG with user-provided seed and range
    int seed, minRange, maxRange;
    scanf("%d %d %d", &seed, &minRange, &maxRange);

    pthread_t threadID;
    if (pthread_create(&threadID, NULL, processThread, &seed) != 0) {
        fprintf(stderr, "Error creating thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(threadID, NULL);
    printf("Min: %d, Max: %d\n", minVal, maxVal);

    free(data);
    return EXIT_SUCCESS;
}

void* processThread(void* arg) {
    int seed = *(int*)arg;
    // Initialize PRNG with the provided seed

    for (int i = 0; i < dataSize; ++i) {
        int transformedValue = transformUsingPRNG(data[i], seed, minRange, maxRange);
        printf("%d ", transformedValue);
    }

    // Find and print min and max values using helper function
    findMinMax(data, dataSize, &minVal, &maxVal);

    pthread_exit(NULL);
}

int transformUsingPRNG(int value, int seed, int minRange, int maxRange) {
    // Implement custom PRNG transformation logic
    return (value * seed + minRange) % (maxRange - minRange + 1);
}

int findMinMax(int* array, int size, int* min, int* max) {
    *min = array[0];
    *max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] < *min) *min = array[i];
        if (array[i] > *max) *max = array[i];
    }
}
