#define RECORD_SIZE 1024

typedef struct Record {
    int key;
    char description[RECORD_SIZE];
} Record;

// Pseudo-random number generator function (simple example)
int prng(int seed) {
    return (seed * 1103515245 + 12345) % 2147483647;
}

// Function to initialize and manage records
void manageRecords(Record** records, int count, int seed) {
    if (!records || count <= 0) return;

    *records = (Record*)malloc(count * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand(seed);
    for (int i = 0; i < count; i++) {
        (*records)[i].key = prng(i); // Use PRNG to generate unique identifiers
        snprintf((*records)[i].description, RECORD_SIZE, "Record %d", (*records)[i].key);
    }
}

// Function to free records
void freeRecords(Record** records) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}

int main() {
    Record* records;
    int count = 10;
    int seed = time(NULL); // Use current timestamp as seed

    manageRecords(&records, count, seed);

    for (int i = 0; i < count; i++) {
        printf("Key: %d, Description: %s\n", records[i].key, records[i].description);
    }

    freeRecords(&records);

    return 0;
}
