        return NULL; // Invalid input
    }

    long* offsets = (long*)malloc(num_elements * sizeof(long));
    if (!offsets) {
        return NULL; // Memory allocation failed for offsets
    }

    int* keys = (int*)malloc(num_elements * sizeof(int));
    if (!keys) {
        free(offsets); // Clean up allocated offsets
        return NULL; // Memory allocation failed for keys
    }

    record* records = (record*)malloc(num_elements * sizeof(record));
    if (!records) {
        free(offsets); // Clean up allocated offsets
        free(keys);   // Clean up allocated keys
        return NULL; // Memory allocation failed for records
    }

    unsigned int* prng_state = (unsigned int*)malloc(sizeof(unsigned int));
    if (!prng_state) {
        free(offsets);  // Clean up allocated offsets
        free(keys);     // Clean up allocated keys
        free(records);  // Clean up allocated records
