        // Process each line of output
        log_buffer[log_index++] = buffer;
        if (log_index == MAX_LOG_ENTRIES) {
            log_index = 0; // Wrap around circular buffer
        }
    }

    pclose(fp);

    // Clean up allocated memory
    free(data->commands);
    free(data->offsets);
    free(data->keys);
    free(data);

