    node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
        new_node->next = new_node->prev = new_node;
    } else {
        node* last = (*head)->prev;
        new_node->next = *head;
        new_node->prev = last;
        last->next = new_node;
        (*head)->prev = new_node;
    }
    return new_node;
}

void delete_node(node** head, node* del) {
    if (*head == NULL || del == NULL) return;
    if (*head == del && (*head)->next == *head) {
