    config->seed = tv.tv_sec * 1000000 + tv.tv_usec;

    unsigned long prev_value = config->seed;
    for (int i = 0; i < num_entries; ++i) {
        timestamps[i] = custom_prng(config, prev_value);
        session_ids[i] = config->min_range + timestamps[i] % (config->max_range - config->min_range + 1);
