#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

unsigned long xorshift128plus(void) {
    static unsigned long state[4] = {0xdeadbeef, 0xbadc0ffee, 0xfaceb00c, 0xdeedface};
    unsigned long t = state[3];
    unsigned long const s = state[0];
    state[3] = state[2];
    state[2] = state[1];
    state[1] = s;
    t ^= t << 17; t ^= t >> 31; state[0] = t ^ s ^ (s << 9);
    return state[0] + ++t;
}

int* generate_random_keys(int count, int min, int max) {
    int* keys = malloc(count * sizeof(int));
    if (!keys) return NULL;
    for (int i = 0; i < count; ++i) {
        keys[i] = xorshift128plus() % (max - min + 1) + min;
    }
    return keys;
}

long* generate_offset_values(int count, long min, long max) {
    long* offsets = malloc(count * sizeof(long));
    if (!offsets) return NULL;
    for (int i = 0; i < count; ++i) {
        offsets[i] = xorshift128plus() % (max - min + 1) + min;
    }
    return offsets;
}

record* initialize_records(int count) {
    record* records = malloc(count * sizeof(record));
    if (!records) return NULL;
    for (int i = 0; i < count; ++i) {
        records[i].value = xorshift128plus() % 100; // Random value between 0 and 99
    }
    return records;
}

void free_memory(int* keys, long* offsets, record* records) {
    free(keys);
    free(offsets);
    free(records);
}

int main() {
    int count = 1000;
    int min_key = 1, max_key = 1000;
    long min_offset = 0, max_offset = 100000;

    int* keys = generate_random_keys(count, min_key, max_key);
    long* offsets = generate_offset_values(count, min_offset, max_offset);
    record* records = initialize_records(count);

    if (keys && offsets && records) {
        // Process the arrays and records
        printf("Random Key: %d\n", keys[0]);
        printf("Offset Value: %ld\n", offsets[0]);
        printf("Record Value: %d\n", records[0].value);
        free_memory(keys, offsets, records);
    } else {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    return 0;
}
