    // Memory allocation and initialization
    record* records = malloc(MAX_RECORDS * sizeof(record));
    if (records == NULL) {
        perror("Memory allocation failed");
        return;
    }

    srand(seed);
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % range;
        records[i].offset = (long)i * 1000;
        records[i].url = malloc(256 * sizeof(char));
        sprintf(records[i].url, "http://example.com/%d", i);
    }

    // Error handling for memory allocation failures
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].url == NULL) {
            perror("Memory allocation failed");
            goto cleanup;
        }
    }

    // Finding and printing the largest integer in an array
    int* numbers = malloc(10 * sizeof(int));
    if (numbers == NULL) {
        perror("Memory allocation failed");
        goto cleanup;
    }

    printf("Enter 10 integers: ");
    for (int i = 0; i < 10; i++) {
        scanf("%d", &numbers[i]);
    }

    int max = numbers[0];
    for (int i = 1; i < 10; i++) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }
    printf("Largest number: %d\n", max);

cleanup:
    // Cleaning up allocated memory
    free(numbers);
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i].url);
    }
    free(records);
}

int main() {
