class TimeBasedCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;
    private final long timeToLive;

    public TimeBasedCache(int capacity, long timeToLive) {
        super(capacity, 0.75f, true);
        this.capacity = capacity;
        this.timeToLive = timeToLive;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity || System.currentTimeMillis() - ((Record) eldest.getValue()).getLastAccessTime() > timeToLive;
    }
}

class CircularBuffer<T> {
    private T[] buffer;
    private int head = 0;
    private int tail = 0;

    @SuppressWarnings("unchecked")
    public CircularBuffer(int size) {
        this.buffer = (T[]) new Object[size];
    }

    public synchronized void add(T item) {
        buffer[tail] = item;
        tail = (tail + 1) % buffer.length;
        if (head == tail) {
            head = (head + 1) % buffer.length;
        }
    }

    public T get(int index) {
        int position = (head + index) % buffer.length;
        return buffer[position];
    }

    public int size() {
        if (tail >= head) {
            return tail - head;
        } else {
            return capacity - (head - tail);
        }
    }
}
