Transaction* readTransactionsFromFile(const char* filePath, size_t* transactionCount) {
    FILE* file = fopen(filePath, "r");
    if (!file) return NULL;

    // Determine the number of transactions
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    *transactionCount = fileSize / sizeof(Transaction);

    // Allocate memory for transactions
    Transaction* transactions = (Transaction*)malloc(*transactionCount * sizeof(Transaction));
    if (!transactions) return NULL;

    fread(transactions, sizeof(Transaction), *transactionCount, file);
    fclose(file);

    return transactions;
}

void processTransactions(const char* filePath, void (*f)(Transaction)) {
    size_t transactionCount;
    Transaction* transactions = readTransactionsFromFile(filePath, &transactionCount);

    if (!transactions) {
        fprintf(stderr, "Failed to load transactions from file.\n");
        return;
    }

    for (size_t i = 0; i < transactionCount; ++i) {
        f(transactions[i]);
    }

    free(transactions);
}

void* workerThread(void* arg) {
    // Worker thread implementation
    pthread_exit(NULL);
}

int main() {
    const char* filePath = "transactions.csv";

    // Initialize semaphore and other resources
    sem_t semaphore;
    sem_init(&semaphore, 0, MAX_THREADS);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, workerThread, NULL) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
            return 1;
        }
    }

    processTransactions(filePath, [](Transaction t) {
        // Process each transaction
    });

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);

    return 0;
}
