#define MAX_DATA_ENTRIES 1000

typedef struct {
    int id;
    float value;
    time_t timestamp;
} data_entry;

typedef struct {
    int min_value;
    int max_value;
} PRNG_struct;

PRNG_struct prng_init(int min, int max) {
    PRNG_struct prng = {min, max};
    return prng;
}

int prng_generate_integer(PRNG_struct *prng) {
    return rand() % (prng->max_value - prng->min_value + 1) + prng->min_value;
}

float prng_generate_float(PRNG_struct *prng) {
    return ((float)rand()) / RAND_MAX * (prng->max_value - prng->min_value) + prng->min_value;
}

void override_printf(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

data_entry* dataGenerator(char* xml_config, unsigned long seed) {
    sem_t lock;
    sem_init(&lock, 0, 1);

    PRNG_struct prng = prng_init(0, 100); // Example range
    srand(seed);

    data_entry *entries = (data_entry*)malloc(MAX_DATA_ENTRIES * sizeof(data_entry));
    if (entries == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < MAX_DATA_ENTRIES; i++) {
        sem_wait(&lock);
        entries[i].id = i + 1;
        entries[i].value = prng_generate_float(&prng);
        entries[i].timestamp = time(NULL);
        sem_post(&lock);
    }

    sem_destroy(&lock);

    return entries;
}

void cleanup(data_entry* entries) {
    free(entries);
}

int main() {
    unsigned long seed = time(NULL);
    data_entry* data = dataGenerator("config.xml", seed);
    if (data != NULL) {
        override_printf("Generated Data:\n");
        for (int i = 0; i < MAX_DATA_ENTRIES; i++) {
            override_printf("ID: %d, Value: %.2f, Timestamp: %ld\n", data[i].id, data[i].value, data[i].timestamp);
        }
        cleanup(data);
    }

    return 0;
}
