void processAndExecuteDynamicTask(const char* label, void (*f)(), int maxExecutionTime) {
    // Initialize arrays and variables
    long *offsets = malloc(100 * sizeof(long));
    int *keys = malloc(100 * sizeof(int));
    double *results = malloc(100 * sizeof(double));

    if (offsets == NULL || keys == NULL || results == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator
    unsigned int seed;
    printf("Enter a seed value: ");
    scanf("%u", &seed);

    if (!RAND_bytes((unsigned char *)&seed, sizeof(seed))) {
        fprintf(stderr, "Failed to seed PRNG\n");
        free(offsets);
        free(keys);
        free(results);
        exit(EXIT_FAILURE);
    }

    srand(seed);

    // Read integers from standard input and calculate average
    int count = 0;
    int sum = 0;
    int num;
    while (scanf("%d", &num) != EOF) {
        keys[count] = rand() % MAX_SEED;
        offsets[count] = num;
        sum += num;
        count++;
    }

    double average = (double)sum / count;

    // Execute the test function
    clock_t start = clock();
    f(label, averages);
    clock_t end = clock();

    if ((end - start) > maxExecutionTime * CLOCKS_PER_SEC) {
        fprintf(stderr, "Function execution exceeded maximum allowed time\n");
        free(offsets);
        free(keys);
        free(results);
        exit(EXIT_FAILURE);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(results);
}
