#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Transaction {
    int id;
    double amount;
    char description[256];
} Transaction;

typedef struct LogEntry {
    time_t timestamp;
    char message[1024];
} LogEntry;

#define MAX_LOG_ENTRIES 1000
#define BUFFER_SIZE 4096

LogEntry logBuffer[MAX_LOG_ENTRIES];
int logIndex = 0;
sem_t logSemaphore;

void logTransaction(const char* description, const char* status) {
    sem_wait(&logSemaphore);
    time_t now = time(NULL);
    snprintf(logBuffer[logIndex].message, sizeof(logBuffer[logIndex].message), "%s - %s", description, status);
    logBuffer[logIndex].timestamp = now;
    logIndex = (logIndex + 1) % MAX_LOG_ENTRIES;
    sem_post(&logSemaphore);
}

int processFinancialTransactions(
    const char* transactionStream,
    const LogEntry* logSchema,
    int prngSeed,
    int timeoutDuration,
    void (*dataProcessor)(const Transaction*)
) {
    srand(prngSeed);
    sem_init(&logSemaphore, 0, 1);

    FILE* stream = popen(transactionStream, "r");
    if (!stream) {
        logTransaction("transactionStream", "Failed to open");
        return -1;
    }

    clock_t startTime = clock();
    while (clock() < startTime + timeoutDuration * CLOCKS_PER_SEC) {
        char buffer[BUFFER_SIZE];
        if (fgets(buffer, BUFFER_SIZE, stream)) {
            Transaction transaction;
            sscanf(buffer, "%lf %[^\n]", &transaction.amount, transaction.description);
            transaction.id = rand();

            sem_wait(&logSemaphore);
            logTransaction(transaction.description, "Processed");
            sem_post(&logSemaphore);

            dataProcessor(&transaction);
        } else {
            break;
        }
    }

    pclose(stream);
    sem_destroy(&logSemaphore);
    return 0;
}
