#define MAX_LOG_ENTRIES 100
#define LOG_BUFFER_SIZE 256

typedef struct {
    char buffer[MAX_LOG_ENTRIES][LOG_BUFFER_SIZE];
    int index;
} LogBuffer;

void logEvent(LogBuffer *log, const char *message) {
    if (log->index >= MAX_LOG_ENTRIES) {
        log->index = 0; // Overwrite the oldest entry
    }
    snprintf(log->buffer[log->index], LOG_BUFFER_SIZE, "%s", message);
    log->index++;
}

void initializeLogBuffer(LogBuffer *log) {
    log->index = 0;
}

void printReport(double mean, double median, int mode) {
    printf("Mean: %.2f\n", mean);
    printf("Median: %.2f\n", median);
    printf("Mode: %d\n", mode);
}

double calculateMean(int *data, int count) {
    double sum = 0;
    for (int i = 0; i < count; i++) {
        sum += data[i];
    }
    return sum / count;
}

void findMedianAndMode(int *data, int count, double *median, int *mode) {
    qsort(data, count, sizeof(int), (int (*)(const void *, const void *))strcmp);
    *median = ((double)data[count / 2] + data[(count - 1) / 2]) / 2;
    *mode = data[0];
}

void processFileAndGenerateReport(const char *filename, int seed, int timeout, LogBuffer *log) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        logEvent(log, "Failed to open file.");
        return;
    }

    srand(seed);
    int dataCount = 0;
    int *data = (int *)malloc(1000 * sizeof(int)); // Initial allocation
    char line[256];

    clock_t start = clock();
    while ((fgets(line, sizeof(line), file)) != NULL && ((clock() - start) / CLOCKS_PER_SEC < timeout)) {
        data[dataCount++] = rand() % 1000; // Example range: 0-999
    }
    fclose(file);

    if (dataCount == 0) {
        logEvent(log, "No data found in the file.");
        free(data);
        return;
    }

    double mean = calculateMean(data, dataCount);
    int mode = data[0];
    double median;
    findMedianAndMode(data, dataCount, &median, &mode);

    printReport(mean, median, mode);

    // CSV generation (simplified example)
    FILE *csvFile = fopen("report.csv", "w");
    if (csvFile) {
        fprintf(csvFile, "Mean,Median,Mode\n");
        fprintf(csvFile, "%.2f,%.2f,%d\n", mean, median, mode);
        fclose(csvFile);
    }

    free(data);
    logEvent(log, "Report generated successfully.");
}

int main() {
    LogBuffer log;
    initializeLogBuffer(&log);

    processFileAndGenerateReport("data.txt", 12345, 60, &log); // Example parameters

    return 0;
}
