    free(res.keys);
}

void logEvent(CircularBuffer* buffer, const char* event) {
    int nextHead = (buffer->head + 1) % MAX_LOG_ENTRIES;
    if (nextHead == buffer->tail) {
        // Buffer is full, overwrite the oldest entry
        buffer->tail = (buffer->tail + 1) % MAX_LOG_ENTRIES;
    }
    buffer->buffer[buffer->head] = strdup(event);
    buffer->head = nextHead;
}

