#define MAX_RECORDS 10000
#define MAX_MEMORY_SIZE 1024 * 1024 * 5 // 5MB

typedef struct {
    int value;
    char log[64];
} record;

int* offsets;
int* keys;
record* records;
size_t allocated_size = 0;

void initialize_records(int start, int end) {
    if (allocated_size >= MAX_MEMORY_SIZE || (end - start + 1) > MAX_RECORDS) {
        fprintf(stderr, "Error: Insufficient memory or maximum records limit exceeded.\n");
        return;
    }

    offsets = realloc(offsets, sizeof(int) * (end - start + 1));
    keys = realloc(keys, sizeof(int) * (end - start + 1));
    records = realloc(records, sizeof(record) * (end - start + 1));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    allocated_size += sizeof(int) * 2 * (end - start + 1) + sizeof(record) * (end - start + 1);

    srand(time(NULL));
    for (int i = start; i <= end; ++i) {
        keys[i] = rand() % (end - start + 1);
        while (i > 0 && keys[i] == keys[i - 1]) {
            keys[i] = rand() % (end - start + 1);
        }
        records[i].value = rand();
        sprintf(records[i].log, "Record %d", i);
    }

    printf("Records initialized successfully.\n");
}

int main() {
    initialize_records(0, MAX_RECORDS - 1);
    // Further processing with offsets, keys, and records
    free(offsets);
    free(keys);
    free(records);
    return 0;
}
