#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define MAX_KEY 10000
#define LOG_FILE "memory_usage.log"

typedef struct {
    int value;
    char log[50];
} Record;

long *offsets;
int *keys;
Record *records;
size_t memory_limit = 1024 * 1024 * 10; // 10 MB
pthread_mutex_t lock;

void* initialize_records(void* arg) {
    pthread_mutex_lock(&lock);
    if (memory_used() > memory_limit) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    offsets = malloc(MAX_RECORDS * sizeof(long));
    keys = malloc(MAX_RECORDS * sizeof(int));
    records = malloc(MAX_RECORDS * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        offsets[i] = rand_r((unsigned int*)&arg);
        keys[i] = generate_unique_key(i, keys);
        records[i].value = rand_r((unsigned int*)&arg);
        snprintf(records[i].log, sizeof(records[i].log), "Record %d", i);
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

int generate_unique_key(int index, int *keys) {
    int key;
    do {
        key = rand_r((unsigned int*)&index);
    } while (find_existing_key(key, keys, index) != -1);
    return key;
}

int find_existing_key(int key, int *keys, int max_index) {
    for (int i = 0; i < max_index; ++i) {
        if (keys[i] == key) {
            return i;
        }
    }
    return -1;
}

size_t memory_used() {
    // Implement a function to calculate the current memory usage
    return sizeof(offsets) + sizeof(keys) + sizeof(records);
}

void log_memory_usage() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "Current memory usage: %zu bytes\n", memory_used());
        fclose(log_file);
    }
}

int main() {
    pthread_t thread;
    srand(time(NULL));

    pthread_mutex_init(&lock, NULL);
    if (pthread_create(&thread, NULL, initialize_records, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    log_memory_usage();
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
