typedef struct {
    long timestamp;
    int key;
    int priority;
    char log[256];
} record;

record* allocate_records(int num_records, unsigned long seed) {
    srand(seed);
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    long* timestamps = (long*)malloc(num_records * sizeof(long));
    if (!timestamps) {
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(timestamps);
        free(records);
        return NULL;
    }

    // Initialize timestamps, keys, and records
    for (int i = 0; i < num_records; i++) {
        timestamps[i] = rand() % 1000000L + time(NULL); // Random timestamp in the next million seconds
        do {
            keys[i] = rand();
        } while (i > 0 && keys[i] == keys[i - 1]); // Ensure no two records have the same key

        records[i].timestamp = timestamps[i];
        records[i].key = keys[i];
        records[i].priority = rand() % 10; // Random priority level
        snprintf(records[i].log, sizeof(records[i].log), "Log entry %d", i);
    }

    free(timestamps);
    free(keys);

    return records;
}

void free_records(record* records) {
    if (records) free(records);
}
